function machtileToggleAdminDrawer(open) {
  const drawer = $("#adminDrawer");
  const backdrop = $("#adminDrawerBackdrop");
  const button = $("#adminDrawerBtn");
  if (!drawer || !backdrop) return;
  const show = open ?? drawer.hidden;
  if (show) machtileRenderAdminDrawer();
  drawer.hidden = !show;
  backdrop.hidden = !show;
  drawer.classList.toggle("is-open", show);
  backdrop.classList.toggle("is-open", show);
  button?.setAttribute("aria-expanded", show ? "true" : "false");
}

function riskSuggestion(order) {
  const status = deriveOrderStatus(order);
  if (status === "overdue") {
    return "已進入交期風險。建議安排夜間或假日趕工，並提前通知客戶可能延後 1 天。";
  }
  if (status === "abnormal") {
    return "製程發生異常。建議先確認不良原因與可重工數量，再決定是否拆單到其他機台。";
  }
  if (status === "aiRisk") {
    return `目前完成 ${order.done}/${order.total}，進度低於交期節奏。建議今日加班 2 小時，或拆 30 件轉到可用機台。`;
  }
  if (status === "inspection") {
    return "加工已完成或接近完成，但卡在品檢。建議今日上午優先安排品檢，避免出貨延誤。";
  }
  if (status === "stale") {
    return "目前缺少現場回報。建議通知師傅更新狀態，避免主管用舊資料判斷交期。";
  }
  return "進度符合排程。維持正常回報節奏即可。";
}

function alertReason(order) {
  const status = primaryAlertStatus(order);
  if (status === "overdue") return order.workStatus === "abnormal" ? "尺寸超差需重做" : "剩餘製程不足以準時完成";
  if (status === "abnormal") return "製程異常待主管確認";
  if (status === "aiRisk") return `${order.machine || "機台"} 進度落後`;
  if (status === "inspection") return "品檢未排程或等待處理";
  if (status === "stale") return "現場未回報最新狀態";
  return "今日需完成";
}

function remainingProcesses(order) {
  const status = deriveOrderStatus(order);
  if (status === "inspection") return "品檢 · 包裝 · 出貨";
  if (status === "stale") return `${order.process || "首道製程"} · 待開工`;
  return `${order.process || "CNC 加工"} · 去毛邊 · 品檢`;
}

function processStageLabel(order) {
  const process = order.process || "目前製程";
  const status = String(order.processStatus || "").trim().toLowerCase();
  if (status === "waiting_inspection") return `${process} 已加工 · 待品檢`;
  if (status === "running" || status === "in_progress") return `${process} · 加工中`;
  if (status === "pending" || status === "not_started") return `${process} · 待開工`;
  if (status === "paused") return `${process} · 已暫停`;
  if (status === "abnormal") return `${process} · 異常處理中`;
  if (status === "completed") return `${process} · 已完成`;
  if (status === "skipped") return `${process} · 已略過`;
  return process;
}

function alertActions(order) {
  return machtileIsSchedulableOrder(order) ? ["調排程", "查看工單"] : ["查看工單"];
}

function machtileAttentionSourceKey(order) {
  return machtileAttentionCore?.sourceKey?.(order, primaryAlertStatus(order))
    || `work_order:${order?.workOrderId || order?.id || "unknown"}:${primaryAlertStatus(order)}:${order?.dueDate || "no-date"}`;
}

function machtileAttentionCaseForOrder(order) {
  const sourceKey = machtileAttentionSourceKey(order);
  const persisted = machtileAttentionState.casesBySourceKey.get(sourceKey) || null;
  return machtileAttentionCore?.mergeCase?.(order, primaryAlertStatus(order), persisted) || {
    sourceKey,
    status: persisted?.status || "unassigned",
    statusLabel: persisted?.status || "未指派",
    statusClassName: "attention-unassigned",
    assigneeName: persisted?.assignee_name || "尚未指派",
    assignedTo: persisted?.assigned_to || "",
    resolutionReason: persisted?.resolution_reason || "",
    updatedAt: persisted?.updated_at || "",
  };
}

function machtileAttentionMatchesWorkflow(order, filter = activeAttentionStatus) {
  const caseState = machtileAttentionCaseForOrder(order);
  return machtileAttentionCore?.matchesWorkflow?.(caseState, filter) ?? (caseState.status !== "closed");
}

function machtileAttentionCanWrite() {
  return machtileAttentionState.status === "ready"
    && machtileStrictMode()
    && machtileSessionActive()
    && ["admin", "manager"].includes(String(machtileAuthState.role || "").toLowerCase());
}

function machtileAttentionSeverity(order) {
  return ({ overdue: "critical", abnormal: "high", aiRisk: "high", inspection: "medium", stale: "low" })[primaryAlertStatus(order)] || "medium";
}

function machtileAttentionMutationItem(order) {
  const payload = {
    source_type: "work_order_risk",
    source_key: machtileAttentionSourceKey(order),
    title: `${order.id} · ${order.part}`,
    reason_summary: alertReason(order),
    severity: machtileAttentionSeverity(order),
    observed_at: new Date().toISOString(),
    source_snapshot: {
      work_order_no: order.id,
      part_name: order.part,
      customer: order.customer,
      process: order.process,
      machine: order.machine,
      due_date: order.dueDate,
      alert_status: primaryAlertStatus(order),
      categories: Array.from(alertCategories(order)),
      completed_qty: Number(order.done || 0),
      planned_qty: Number(order.total || 0),
    },
  };
  if (machtileUuidPattern.test(String(order.workOrderId || ""))) payload.work_order_id = order.workOrderId;
  if (machtileUuidPattern.test(String(order.processId || ""))) payload.process_id = order.processId;
  return payload;
}

function machtileAttentionOrdersForKeys(keys) {
  const keySet = new Set(keys);
  return state.workOrders.filter((order) => keySet.has(machtileAttentionSourceKey(order)));
}

function machtileAttentionWriteStatusMessage() {
  if (machtileAttentionState.status === "unavailable") return "等待 Production DB 契約";
  if (!machtileStrictMode() || !machtileSessionActive()) return "正式環境登入後可處理";
  if (!["admin", "manager"].includes(String(machtileAuthState.role || "").toLowerCase())) return "主管可指派與結案";
  return "載入處理狀態中";
}

function machtileAttentionPrimaryAction(caseState) {
  if (caseState.status === "unassigned") return { action: "assign", label: "指派負責人" };
  if (caseState.status === "closed") return { action: "reopen", label: "重新開啟" };
  return { action: "status", label: "更新處理狀態" };
}

function machtileOpenAttentionAction(keys, action) {
  const uniqueKeys = [...new Set(keys)].filter(Boolean);
  if (!uniqueKeys.length) return;
  if (!machtileAttentionCanWrite()) {
    showToast(machtileAttentionWriteStatusMessage());
    return;
  }
  machtileAttentionState.actionKeys = uniqueKeys;
  const orders = machtileAttentionOrdersForKeys(uniqueKeys);
  const firstCase = orders[0] ? machtileAttentionCaseForOrder(orders[0]) : null;
  const sheet = $("#attentionActionSheet");
  const assignee = $("#attentionAssigneeSelect");
  const status = $("#attentionStatusSelect");
  const reason = $("#attentionReasonInput");
  assignee.innerHTML = `<option value="">${action === "close" ? "結案者自動負責" : "請選擇負責人"}</option>`
    + machtileAttentionState.assignees.map((user) => `<option value="${escapeHtml(user.id)}">${escapeHtml(user.name)} · ${escapeHtml(user.role || "")}</option>`).join("");
  assignee.value = firstCase?.assignedTo || "";
  status.value = action === "close" ? "closed" : action === "reopen" || action === "assign" ? "in_progress" : (firstCase?.status || "in_progress");
  status.disabled = action === "close" || action === "assign" || action === "reopen";
  reason.value = "";
  $("#attentionActionTitle").textContent = action === "close" ? "結案待處理案件" : action === "assign" ? "指派負責人" : action === "reopen" ? "重新開啟案件" : "更新處理狀態";
  $("#attentionActionSummary").textContent = `${uniqueKeys.length} 筆案件；所有變更都會留下稽核紀錄`;
  $("#attentionActionSubmit").textContent = action === "close" ? "確認結案" : "確認更新";
  sheet.classList.add("is-open");
  sheet.setAttribute("aria-hidden", "false");
  window.setTimeout(() => (action === "close" ? reason : assignee).focus(), 50);
}

function machtileCloseAttentionAction() {
  const sheet = $("#attentionActionSheet");
  sheet?.classList.remove("is-open");
  sheet?.setAttribute("aria-hidden", "true");
  machtileAttentionState.actionKeys = [];
}

async function machtileSubmitAttentionAction() {
  if (machtileAttentionState.writePending) return;
  const orders = machtileAttentionOrdersForKeys(machtileAttentionState.actionKeys);
  const status = $("#attentionStatusSelect").value;
  const assignedTo = $("#attentionAssigneeSelect").value;
  const reason = $("#attentionReasonInput").value.trim();
  const validation = machtileAttentionCore?.validateMutation?.({ status, assignedTo, reason, itemCount: orders.length }) || { valid: Boolean(orders.length && reason), errors: ["請確認輸入資料"] };
  if (!validation.valid) {
    showToast(validation.errors[0]);
    return;
  }
  const idempotencyKey = globalThis.crypto?.randomUUID?.() || `attention-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  machtileAttentionState.writePending = true;
  $("#attentionActionSubmit").disabled = true;
  try {
    const payload = {
      status,
      reason,
      idempotency_key: idempotencyKey,
      items: orders.map(machtileAttentionMutationItem),
    };
    if (assignedTo) payload.assigned_to = assignedTo;
    const result = await supabaseFetch("rpc/attention_case_batch_update", {
      method: "POST",
      body: JSON.stringify({ p_payload: payload }),
    });
    await machtileLoadAttentionCenter();
    machtileAttentionState.selectedKeys.clear();
    machtileCloseAttentionAction();
    renderAlerts();
    showToast(`已更新 ${Number(result?.updated || 0)} 筆待處理案件`);
  } catch (error) {
    const message = String(error?.message || error || "");
    const mapped = message.includes("REASON_REQUIRED") ? "修改與結案原因至少需要 2 個字"
      : message.includes("ASSIGNEE_REQUIRED") ? "處理中或等待回覆必須指定負責人"
      : message.includes("FORBIDDEN") ? "此操作需要主管或管理員權限"
      : message.includes("ACTOR_NOT_FOUND") ? "登入帳號尚未對應到有效使用者"
      : "待處理案件更新失敗，請稍後重試";
    showToast(mapped);
  } finally {
    machtileAttentionState.writePending = false;
    $("#attentionActionSubmit").disabled = false;
  }
}

function renderStats() {
  const actualMachines = managedMachineList();
  const stats = [
    ["總機台", actualMachines.length, "risk-blue", "全部狀態"],
    ["加工中", actualMachines.filter((machine) => matchesStatusFilter(machine, "加工中")).length, "risk-blue", "加工中"],
    ["空閒", actualMachines.filter((machine) => matchesStatusFilter(machine, "空閒")).length, "risk-gray", "空閒"],
    ["暫停", actualMachines.filter((machine) => matchesStatusFilter(machine, "暫停")).length, "risk-amber", "暫停"],
    ["維修／停用", actualMachines.filter((machine) => matchesStatusFilter(machine, "維修／停用")).length, "risk-red", "維修／停用"],
  ];

  const todayFilterOn = Boolean(machtileTodayActiveFilterKeys());
  $("#statsGrid").innerHTML = stats.map(([label, value, riskClass, filter]) => `
    <button class="stat-card stat-button ${riskClass} ${!todayFilterOn && activeStatusFilter === filter ? "active" : ""}" data-stat-filter="${escapeHtml(filter)}" type="button">
      <span class="stat-label">${escapeHtml(label)}</span>
      <strong class="stat-value">${value}</strong>
    </button>
  `).join("") + machtileTodayTilesMarkup();
}

function renderFilters() {
  const available = machtileAvailableDepartments();
  if (!available.includes(activeDepartmentFilter)) activeDepartmentFilter = available[0] || "";
  $("#departmentChips").innerHTML = available.map((filter) => `
    <span class="department-filter-group ${activeDepartmentFilter === filter ? "is-active" : ""}">
      <button class="filter-chip department-chip ${activeDepartmentFilter === filter ? "active" : ""}" data-department="${escapeHtml(filter)}" type="button">
        ${escapeHtml(filter)}
      </button>
      ${filter === "銑床課" && activeDepartmentFilter === "銑床課" ? `
        <span class="milling-mode-chips" aria-label="銑床課報工模式">
          ${millingModeFilters.map((mode) => `
            <button class="filter-chip milling-mode-chip ${activeMillingModeFilter === mode ? "active" : ""}" data-milling-mode="${escapeHtml(mode)}" type="button">
              ${escapeHtml(mode)}
            </button>
          `).join("")}
        </span>
      ` : ""}
    </span>
  `).join("");

  if (machtileStrictMode() && available.length === 0) $("#departmentChips").innerHTML = `<p role="status">${machtileDepartmentAccess ? "此帳號沒有任何課別，請管理員設定" : "課別權限尚未取得，機台操作已停用"}</p>`;
  $("#statusChips").innerHTML = statusFilters.map((filter) => `
    <button class="filter-chip status-chip ${activeStatusFilter === filter ? "active" : ""}" data-status="${escapeHtml(filter)}" type="button">
      ${escapeHtml(filter)}${filter === "全部狀態" ? "" : ` <span class="filter-chip-count">${machinesForStatusFilter(filter).length}</span>`}
    </button>
  `).join("");
}

function matchesMillingModeFilter(machine) {
  if (activeDepartmentFilter !== "銑床課" || activeMillingModeFilter === "全部銑床") return true;
  const isHmc = isHmcMachine(machine);
  if (activeMillingModeFilter === "多盤多工件") return isHmc;
  if (activeMillingModeFilter === "單盤單工件") return !isHmc;
  return true;
}

function matchesStatusFilter(machine, filter = activeStatusFilter) {
  if (filter === "全部狀態") return true;
  if (filter === "加工中") return machine.status === "running";
  if (filter === "空閒") return machine.status === "idle";
  if (filter === "暫停") return machine.status === "paused";
  if (filter === "維修／停用") return ["maintenance", "offline"].includes(machine.status);
  const order = machine.order;
  if (filter === "可能延誤") return Boolean(order && alertCategories(order).has("可能延誤"));
  if (filter === "已延誤") return Boolean(order && alertCategories(order).has("已延誤"));
  if (filter === "異常") return Boolean(order && alertCategories(order).has("異常"));
  if (filter === "待品檢") return Boolean(order && alertCategories(order).has("待品檢"));
  if (filter === "今日到期") return Boolean(order && alertCategories(order).has("今日到期"));
  if (filter === "未排機") return Boolean(machine.isUnassignedBucket);
  if (filter === "未回報") return Boolean(order && alertCategories(order).has("未回報"));
  return true;
}

function machinesForStatusFilter(filter) {
  return state.machines
    .filter((machine) => activeDepartmentFilter === "全部" || machine.department === activeDepartmentFilter)
    .filter(matchesMillingModeFilter)
    .filter((machine) => matchesStatusFilter(machine, filter));
}

function visibleMachines() {
  // 總覽「今日未開工／未報工／可能加班」格子的篩選（owner 2026-10-02）：只顯示那幾台，不分課別／狀態
  const today = machtileTodayActiveFilterKeys();
  if (today) return managedMachineList().filter((machine) => today.has(machine.name));
  return machinesForStatusFilter(activeStatusFilter);
}

function renderWorkOrders() {
  const machines = visibleMachines();
  machtileRenderTodayFilterBar();
  const holder = $("#workOrderGrid");
  holder.innerHTML = machines.length
    ? machines.map(renderMachineCard).join("")
    : `<article class="empty-card"><strong>沒有符合條件的機台</strong><span>請調整課別或狀態篩選。</span></article>`;
  machtileRefreshDetailHmc();
}

function ensureHmcDashboardEntry() {
  const entry = $("#dashboardView [data-hmc-report-entry]");
  if (entry) entry.remove();
}

function machtileMonitorHmcRuntime(machine) {
  if (!isHmcMachine(machine) || !machtileHmcRuntimeCore) return "";
  let runtime = machtileHmcRuntimeMachine(machine);
  let preview = false;
  if (machtileHmcRuntimeState.status !== "ready" && state.source === "mock") {
    preview = true;
    const profile = machtileHmcRuntimeCore.machineProfile(machine.code || machine.name, config.hmcScheduleProfiles);
    runtime = machtileHmcRuntimeCore.normalizeSnapshot({
      machines: [{
        machine_code: profile.machineCode,
        pallets: Array.from({ length: profile.palletCount }, (_, index) => ({
          pallet_no: index + 1,
          state: index === 0 && machine.status === "running" ? "spindle" : index === 1 ? "external_preparing" : "waiting",
        })),
      }],
    }, config.hmcScheduleProfiles).machines.find((item) => item.machineCode === profile.machineCode);
  }
  if (!runtime || (machtileHmcRuntimeState.status !== "ready" && !preview)) {
    return `<section class="machine-hmc-runtime is-waiting"><div><strong>6 盤最近人工盤況</strong><span>等待 HMC runtime 契約</span></div></section>`;
  }
  const canWrite = !preview && machtileHmcRuntimeCanWrite();
  return `
    <section class="machine-hmc-runtime ${runtime.status === "stopped" ? "is-stopped" : ""}" data-no-detail>
      <div class="machine-hmc-runtime-head">
        <strong>${escapeHtml(runtime.palletCount)} 盤最近人工盤況</strong>
        <span title="目前沒有 IoT；只需在換料、開始加工、完成或異常時更新">人工回報 · ${runtime.status === "stopped" ? "停機・排程已凍結" : runtime.spindlePalletNo ? `主軸：第 ${runtime.spindlePalletNo} 盤` : "主軸空閒"}</span>
        ${runtime.pendingReplanCount ? `<em>${runtime.pendingReplanCount} 待重排</em>` : ""}
      </div>
      <div class="machine-hmc-runtime-grid">
        ${runtime.pallets.map((pallet) => canWrite ? `
          <button type="button" class="is-${escapeHtml(pallet.tone)}" data-hmc-runtime-pallet="${escapeHtml(pallet.palletNo)}" data-hmc-runtime-machine="${escapeHtml(runtime.machineCode)}" title="更新人工盤況：盤 ${escapeHtml(pallet.palletNo)} · ${escapeHtml(pallet.workOrderNo || pallet.fixtureName || pallet.stateLabel)}">
            <b>${escapeHtml(pallet.palletNo)}</b><small>${escapeHtml(pallet.stateLabel)}</small>
          </button>
        ` : `
          <span class="is-${escapeHtml(pallet.tone)}" title="${escapeHtml(pallet.workOrderNo || pallet.fixtureName || pallet.stateLabel)}">
            <b>${escapeHtml(pallet.palletNo)}</b><small>${escapeHtml(pallet.stateLabel)}</small>
          </span>
        `).join("")}
      </div>
      ${canWrite ? `<div class="machine-hmc-runtime-actions">
        <button type="button" class="${runtime.status === "stopped" ? "" : "is-risk"}" data-hmc-runtime-machine-action="${escapeHtml(runtime.machineCode)}" data-hmc-runtime-event="${runtime.status === "stopped" ? "machine_resume" : "machine_stop"}">${runtime.status === "stopped" ? "恢復機台" : "回報停機"}</button>
      </div>` : ""}
    </section>
  `;
}

// B01／B02 的「6 盤最近人工盤況」和「固定工件配置 · Staging」（owner 2026-10-02 從 Monitor 卡片搬到明細／完整單）。
// 內容、資料、按鈕（盤位、回報停機／恢復機台、固定工件盤位）都跟原本卡片上的一樣，只是換位置。
function machtileHmcMachineFor(machineName) {
  const key = String(machineName || "").trim();
  if (!key) return null;
  const upper = key.toUpperCase();
  const found = (state.machines || []).find((m) => m.name === key || String(m.code || "").toUpperCase() === upper || String(m.name || "").toUpperCase() === upper);
  if (found) return isHmcMachine(found) ? found : null;
  const master = (state.machineMasters || []).find((m) => String(m.code || m.name || "").toUpperCase() === upper);
  return master && isHmcMachine(master) ? master : null;
}

function machtileHmcDetailInner(machine) {
  let runtime = "";
  let fixed = "";
  try { runtime = machtileMonitorHmcRuntime(machine); } catch (error) { console.warn("HMC runtime block failed", error); }
  try { fixed = machtileHmcFixedEntries(machine); } catch (error) { console.warn("HMC fixed entries failed", error); }
  return `${runtime}${fixed}`;
}

function machtileHmcDetailSection(machine) {
  if (!machine || !isHmcMachine(machine)) return "";
  const code = String(machine.code || machine.name || "");
  const inner = machtileHmcDetailInner(machine);
  if (!inner.trim()) return "";
  return `
    <section class="detail-section detail-hmc-section" data-detail-hmc="${escapeHtml(code)}">
      <div class="detail-section-title">
        <h3>交換盤盤況</h3>
        <span>${escapeHtml(code)} · 臥式多盤</span>
      </div>
      <div data-detail-hmc-body>${inner}</div>
    </section>`;
}

// 盤況每 30 秒更新（或送出事件後）重畫卡片時，明細開著的話那一塊也跟著換
function machtileRefreshDetailHmc() {
  const sheet = document.getElementById("detailSheet");
  if (!sheet || !sheet.classList.contains("is-open")) return;
  const section = sheet.querySelector("[data-detail-hmc]");
  const body = section?.querySelector("[data-detail-hmc-body]");
  if (!section || !body) return;
  const machine = machtileHmcMachineFor(section.dataset.detailHmc);
  if (!machine) return;
  body.innerHTML = machtileHmcDetailInner(machine);
}

// 臥式機台沒有工單時，卡片「明細」只看這台的盤況
function machtileOpenHmcMachineDetail(machineCode) {
  const machine = machtileHmcMachineFor(machineCode);
  if (!machine) return;
  const code = String(machine.code || machine.name || "");
  $("#detailSheet").classList.remove("route-sheet");
  document.body.classList.remove("route-mode");
  $("#detailSheet").classList.add("is-open");
  $("#detailSheet").setAttribute("aria-hidden", "false");
  $("#detailContent").innerHTML = `
    <section class="detail-head">
      <div class="detail-head-order">
        <div class="detail-head-pills"><span class="machine-type-pill">${escapeHtml(machineTypeLabel(machine.type))}</span></div>
        <h3>${escapeHtml(code)}</h3>
        <p>${escapeHtml(machine.note || "目前沒有指派工單")}</p>
      </div>
    </section>
    ${machtileHmcDetailSection(machine) || '<p class="empty-note">目前沒有盤況資料。</p>'}`;
}

// ============================================================================================
// 機台卡片「開工／停工」回寫舊 MES（第 1 階段，owner 2026-10-07；合約與決策在 stationCommandCore.js 檔頭）。
//   旗標 config.stationCommandMachines 空＝完全不碰：不讀 station_commands、不出按鈕。
//   旗標開＋作業員或管理員（owner 2026-10-08 方案 C）→ 先試讀 station_commands（只讀一列）；讀不到（表不存在、沒權限、網路）→ 整個藏起來。
//   按鈕 → 確認卡（開卡時重讀這一道是否還在這台；大字：機台／工單號／料號＋品名／第幾道＋工序名；
//   「畫面資料（hh:mm）顯示…」）→ 確認才送 machtile_submit_station_command（command_uuid 由 App 產生，
//   重送同一筆不會重複；20 秒逾時）→ 一直輪詢到伺服器給 applied／rejected／expired（App 不自己判結果）。
//   第 1 階段不換單：「不是這張單」只叫作業員找生管。
// ============================================================================================
const machtileStationCmdCore = window.MachTileStationCommandCore || null;
const MACHTILE_STATION_CMD_PENDING_KEY = "machtile.stationCmdPending.v1";
const machtileStationCmd = {
  availability: "off",        // off（旗標關）／probing／ready／missing
  pending: {},                // 機台代號 → pendingRecord（等伺服器結果中）
  lastResult: {},             // 機台代號 → { view, at }（卡片上顯示最後一次結果）
  timers: {},                 // 機台代號 → 輪詢 timer
  sheet: null,                // 目前開著的確認卡
};

function machtileStationCmdFlag() {
  return machtileStationCmdCore ? machtileStationCmdCore.parseFlag(config.stationCommandMachines) : { all: false, machines: [] };
}

function machtileStationCmdRoleOk() {
  return Boolean(machtileStationCmdCore) && machtileStationCmdCore.roleAllowed(machtileFlowVisibilityRole(), machtileDepartmentAccess?.is_bridge === true);
}

// 這台現在有沒有開這個功能（旗標＋作業員或管理員＋表在）
function machtileStationCmdActiveFor(machineCode) {
  return Boolean(machtileStationCmdCore) && machtileStationCmd.availability === "ready" && machtileStationCmdRoleOk()
    && machtileStationCmdCore.enabledForMachine(machtileStationCmdFlag(), machineCode);
}

function machtileStationCmdSavePending() {
  const plain = {};
  Object.keys(machtileStationCmd.pending).forEach((code) => {
    const { view, emptyPolls, releasedShown, ...rest } = machtileStationCmd.pending[code];
    plain[code] = rest;
  });
  try { localStorage.setItem(MACHTILE_STATION_CMD_PENDING_KEY, JSON.stringify(plain)); } catch { /* 無痕視窗等：只是重新整理後不記得 */ }
}

function machtileStationCmdRestorePending() {
  if (!machtileStationCmdCore) return;
  let raw = null;
  try { raw = localStorage.getItem(MACHTILE_STATION_CMD_PENDING_KEY); } catch { raw = null; }
  const restored = machtileStationCmdCore.restorePending(raw, Date.now());
  const flag = machtileStationCmdFlag();
  Object.keys(restored).forEach((code) => {
    if (!machtileStationCmdCore.enabledForMachine(flag, code) || machtileStationCmd.pending[code]) return;
    machtileStationCmd.pending[code] = restored[code];
    machtileStationCmdPoll(code);
  });
  machtileStationCmdSavePending();
}

// loadFromSupabase 時呼叫（成功過就不再試）
async function machtileLoadStationCommandAvailability() {
  const flag = machtileStationCmdFlag();
  // 旗標關、或不是作業員／管理員帳號（橋接、manager、planner 都不行）→ 完全不讀
  if (!machtileStationCmdCore || !machtileStationCmdCore.flagIsOn(flag) || state.source !== "supabase" || !machtileStationCmdRoleOk()) {
    machtileStationCmd.availability = "off";
    return;
  }
  if (machtileStationCmd.availability === "ready") return;
  machtileStationCmd.availability = "probing";
  try {
    await supabaseFetch("station_commands?select=command_uuid&limit=1");
    machtileStationCmd.availability = "ready";
    machtileStationCmdRestorePending();
    machtileDailyStartResumeAll();
  } catch (error) {
    console.warn("station commands unavailable; start/stop buttons hidden", error);
    machtileStationCmd.availability = "missing";
  }
}

// 等待中的這筆是否已經可以讓作業員再按（本機 11 分鐘＋最後看到的伺服器狀態是 pending）
function machtileStationCmdUnlocked(rec) {
  const core = machtileStationCmdCore;
  return Boolean(core && rec && core.lockReleased(rec.startedAt, Date.now()) && core.releasedNote(rec.lastStatus).unlock);
}

function machtileStationCmdMachineCode(machine) {
  return String(machine?.code || machine?.name || "").trim().toUpperCase();
}

function machtileStationCmdRerender() {
  try { renderWorkOrders(); } catch { /* 畫面沒開也沒關係 */ }
}

// 卡片上的「開工／停工」（owner 2026-10-08：卡片太高）——按鈕併進卡片底部那排（明細｜報工｜開工｜停工），
// 狀態字改成底部正上方的一行小字。沒開這個功能的機台兩段都回空字串＝卡片 HTML 跟以前逐字相同。
function machtileStationCmdParts(machine) {
  const none = { status: "", buttons: "" };
  if (!machtileStationCmdCore) return none;
  const code = machtileStationCmdMachineCode(machine);
  const order = machine?.order || null;
  const gate = machtileStationCmdCore.eligibility({
    flag: machtileStationCmdFlag(), role: machtileFlowVisibilityRole(), isBridge: machtileDepartmentAccess?.is_bridge === true,
    availability: machtileStationCmd.availability, machineCode: code, order, isUnassignedBucket: machine?.isUnassignedBucket,
  });
  const pending = machtileStationCmd.pending[code];
  // 有一筆在等（例：重新整理後、卡片換了單）也要顯示，按鈕才有理由鎖住
  if (!gate.ok && !(pending && machtileStationCmdActiveFor(code))) return none;
  const last = machtileStationCmd.lastResult[code];
  const label = machtileStationCmdCore.TYPE_LABEL;
  const released = pending && machtileStationCmdCore.lockReleased(pending.startedAt, Date.now());
  const releaseNote = released ? machtileStationCmdCore.releasedNote(pending.lastStatus) : null;
  const locked = Boolean(pending) && !(releaseNote && releaseNote.unlock);
  let line = "";
  let retry = "";
  if (pending && pending.unconfirmed) {
    line = `<p class="station-cmd-status is-warn" data-station-cmd-status role="status">${escapeHtml(label[pending.commandType])}：上次送出時網路斷了，正在確認有沒有送到</p>`;
    retry = `<button type="button" class="station-cmd-retry" data-station-cmd-retry="${escapeHtml(code)}">用同一筆重送</button>`;
  } else if (pending) {
    const view = pending.view || machtileStationCmdCore.statusView({ status: "pending" }, pending.commandType, null);
    line = `<p class="station-cmd-status is-wait" data-station-cmd-status role="status">${escapeHtml(label[pending.commandType])}：${escapeHtml(view.title)}${view.late ? `　${escapeHtml(view.text)}` : ""}${releaseNote ? `　（${escapeHtml(releaseNote.text)}）` : ""}</p>`;
  } else if (last) {
    line = `<p class="station-cmd-status is-${escapeHtml(last.view.tone)}" data-station-cmd-status role="status">${escapeHtml(last.view.title)}${last.view.phase === "applied" ? "" : `：${escapeHtml(last.view.text)}`}</p>`;
  }
  // 「舊 MES」小標放在狀態字前面，免得「已開工」跟底部「今日尚未開工」（App 自己的開工紀錄）看起來打架
  const status = line ? `<div class="station-cmd-footline" data-no-detail data-station-cmd-footline="${escapeHtml(code)}"><span class="station-cmd-footlabel">舊 MES</span>${line}${retry}</div>
      ` : "";
  const buttons = gate.ok ? `
          <button type="button" class="station-cmd-button is-start" data-no-detail data-station-cmd="start" data-station-cmd-machine="${escapeHtml(code)}" title="舊 MES 開工（會先出確認卡）" ${locked ? "disabled" : ""}>開工</button>
          <button type="button" class="station-cmd-button is-stop" data-no-detail data-station-cmd="stop" data-station-cmd-machine="${escapeHtml(code)}" title="舊 MES 停工（會先出確認卡）" ${locked ? "disabled" : ""}>停工</button>` : "";
  return { status, buttons, active: true };
}

// 單台報工畫面：這台開了「舊 MES 開工／停工」→ 既有「今日開工」分頁標「只記錄（不改舊 MES）」
function machtileStationCmdLabelReportTab(machineName) {
  const tab = document.querySelector('.report-type-tab[data-report-type="dailyStart"]');
  if (!tab) return;
  tab.querySelector("[data-station-cmd-recordonly]")?.remove();
  if (!machineName || !machtileStationCmdActiveFor(machineName)) return;
  const note = document.createElement("small");
  note.className = "station-cmd-recordonly";
  note.dataset.stationCmdRecordonly = "";
  note.textContent = "只記錄（不改舊 MES）";
  tab.appendChild(note);
}

function machtileStationCmdMachineByCode(code) {
  const key = String(code || "").trim().toUpperCase();
  return (state.machines || []).find((m) => machtileStationCmdMachineCode(m) === key) || null;
}

function machtileStationCmdCloseSheet() {
  const sheet = machtileStationCmd.sheet;
  if (sheet && sheet.phase === "sending") return;
  // 確認卡上停在「重送今日開工」等他按 → 關掉後改成自動用同一筆重送
  if (sheet && sheet.dailyStart && sheet.dailyStart.state === "absent") setTimeout(() => machtileDailyStartKick(String(sheet.uuid), 0), 0);
  document.getElementById("machtileStationCmdSheet")?.remove();
  machtileStationCmd.sheet = null;
  if (!sheet) return;
  // 焦點回到原本按的按鈕（卡片重畫過就找同一台同一顆）
  let target = sheet.returnFocus && sheet.returnFocus.isConnected ? sheet.returnFocus : null;
  if (!target) target = document.querySelector(`#workOrderGrid [data-station-cmd="${sheet.type}"][data-station-cmd-machine="${sheet.code}"]`)
    || document.querySelector(`#workOrderGrid [data-station-cmd-retry="${sheet.code}"]`);
  try { target?.focus(); } catch { /* ignore */ }
}

function machtileStationCmdFocusables() {
  const panel = document.querySelector("#machtileStationCmdSheet .station-cmd-panel");
  return panel ? [...panel.querySelectorAll("input:not([disabled]), button:not([disabled]), [href], [tabindex]:not([tabindex='-1'])")] : [];
}

function machtileStationCmdRenderSheet(focus) {
  const sheet = machtileStationCmd.sheet;
  const holder = document.getElementById("machtileStationCmdSheet");
  if (!sheet || !holder) return;
  const core = machtileStationCmdCore;
  const model = sheet.model;
  const field = (label, value, attr) => `<div class="station-cmd-field"><span>${escapeHtml(label)}</span><strong ${attr}>${escapeHtml(value || "—")}</strong></div>`;
  let body = "";
  let actions = "";
  if (sheet.phase === "notThis") {
    body = `<p class="station-cmd-notice is-warn" data-station-cmd-notthis>${escapeHtml(model.notThisOrder)}</p>`;
    actions = `<button type="button" class="station-cmd-secondary" data-station-cmd-close>知道了</button>`;
  } else if (sheet.phase === "confirm" || sheet.phase === "sending" || sheet.phase === "sendError") {
    const sending = sheet.phase === "sending";
    const freshBad = !sheet.loading && sheet.fresh && !sheet.fresh.ok;
    const canSend = !sending && !sheet.loading && !freshBad && (sheet.phase !== "sendError" || sheet.canRetry);
    const adminLines = Array.isArray(model.adminLines) ? model.adminLines : [];
    body = `
      ${adminLines.length ? `<div class="station-cmd-notice is-warn" role="note" data-station-cmd-admin>${adminLines.map((line, i) => `<p style="margin:${i ? "4px" : "0"} 0 0" data-station-cmd-admin-line="${i}">${i === 0 ? `<strong>${escapeHtml(line)}</strong>` : escapeHtml(line)}</p>`).join("")}</div>` : ""}
      <div class="station-cmd-fields">
        ${field("機台", model.machine, "data-station-cmd-field=\"machine\"")}
        ${field("工單號", model.workOrderNo, "data-station-cmd-field=\"order\"")}
        ${field("料號／品名", sheet.loading ? "讀取中…" : [model.partNoDisplay, model.partName].filter(Boolean).join("　"), "data-station-cmd-field=\"part\"")}
        ${field("第幾道／工序", [model.stepLabel, model.operationName].filter(Boolean).join("　"), "data-station-cmd-field=\"step\"")}
      </div>
      ${machtileStationCmdDailyStartHtml(sheet)}
      ${sheet.isRetry ? "" : `<section class="station-cmd-legacy" data-station-cmd-legacy>
        <h3>舊 MES 現況（派工橋同步的畫面資料）</h3>
        ${sheet.loading ? "<p>讀取中…</p>" : `<ul>${model.legacyLines.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul>`}
      </section>`}
      ${freshBad ? `<p class="station-cmd-notice is-bad" role="alert" data-station-cmd-stale>${escapeHtml(sheet.fresh.text)}</p>` : ""}
      ${model.otherOrders && !sheet.isRetry ? `<p class="station-cmd-notice is-warn" data-station-cmd-others>${escapeHtml(model.otherOrders)}；請確認你現在做的就是上面這張。</p>` : ""}
      ${sheet.phase === "sendError" ? `<p class="station-cmd-notice is-bad" role="alert" data-station-cmd-error>${escapeHtml(sheet.errorText)}</p>` : ""}`;
    actions = `
      <button type="button" class="station-cmd-confirm is-${escapeHtml(sheet.type)}" data-station-cmd-confirm ${canSend ? "" : "disabled"}>${sending ? "送出中…" : sheet.phase === "sendError" && sheet.canRetry ? "重送" : escapeHtml(model.confirmLabel)}</button>
      ${sheet.isRetry ? "" : `<button type="button" class="station-cmd-secondary" data-station-cmd-notthis-open ${sending ? "disabled" : ""}>不是這張單</button>`}
      <button type="button" class="station-cmd-secondary" data-station-cmd-close ${sending ? "disabled" : ""}>取消</button>`;
  } else {
    const view = sheet.view || core.statusView({ status: "pending" }, sheet.type, null);
    body = `
      <div class="station-cmd-fields is-compact">
        ${field("機台", model.machine, "")}
        ${field("工單號", model.workOrderNo, "")}
        ${field("第幾道", model.stepLabel, "")}
      </div>
      <section class="station-cmd-result is-${escapeHtml(view.tone)}" data-station-cmd-result="${escapeHtml(view.phase)}"${view.late ? " data-station-cmd-late" : ""} role="status">
        <strong>${escapeHtml(view.title)}</strong>
        <p>${escapeHtml(view.text)}</p>
        ${view.detail ? `<small>工廠說明：${escapeHtml(view.detail)}</small>` : ""}
        ${view.code && view.phase === "rejected" ? `<small>代碼 ${escapeHtml(view.code)}</small>` : ""}
      </section>
      ${machtileStationCmdDailyStartHtml(sheet)}`;
    actions = `<button type="button" class="station-cmd-secondary" data-station-cmd-close>${view.terminal ? "關閉" : "先關掉（結果會顯示在卡片上）"}</button>`;
  }
  const hadFocusInside = holder.contains(document.activeElement);
  const qtyHadFocus = Boolean(document.activeElement?.matches?.("[data-station-cmd-daily-qty]"));
  holder.innerHTML = `
    <section class="station-cmd-panel is-${escapeHtml(sheet.type)}" role="dialog" aria-modal="true" aria-labelledby="stationCmdTitle">
      <header><h2 id="stationCmdTitle">${escapeHtml(model.title)}</h2></header>
      ${body}
      <footer class="station-cmd-actions">${actions}</footer>
    </section>`;
  // 初始焦點放「取消」（不是確認，免得桌機按 Enter 直接送出）；重畫時焦點留在卡片裡
  if (focus || hadFocusInside) {
    // 正在打今日開工數量時（例：讀完資料重畫一次）焦點留在那一格
    const qty = qtyHadFocus ? holder.querySelector("[data-station-cmd-daily-qty]") : null;
    const target = qty || holder.querySelector("[data-station-cmd-close]:not([disabled])") || machtileStationCmdFocusables()[0] || holder.querySelector("h2");
    try { target?.focus(); } catch { /* ignore */ }
  }
}

function machtileStationCmdNewSheet(fields) {
  machtileStationCmdCloseSheet();
  machtileStationCmd.sheet = fields;
  const holder = document.createElement("div");
  holder.id = "machtileStationCmdSheet";
  holder.className = "station-cmd-overlay";
  document.body.appendChild(holder);
  machtileStationCmdRenderSheet(true);
}

async function machtileStationCmdOpen(type, code, returnFocus) {
  const core = machtileStationCmdCore;
  if (!core || !core.COMMAND_TYPES.includes(type)) return;
  const machine = machtileStationCmdMachineByCode(code);
  const order = machine?.order || null;
  const gate = core.eligibility({ flag: machtileStationCmdFlag(), role: machtileFlowVisibilityRole(), isBridge: machtileDepartmentAccess?.is_bridge === true,
    availability: machtileStationCmd.availability, machineCode: code, order, isUnassignedBucket: machine?.isUnassignedBucket });
  const pending = machtileStationCmd.pending[code];
  if (!gate.ok || (pending && !machtileStationCmdUnlocked(pending))) return;
  let uuid;
  try { uuid = core.newUuid(window.crypto); } catch (error) { showToast("這台平板太舊，不能用 App 開工／停工，請改用電子紙"); return; }
  const others = Number(machine?.cardOtherCount || 0);
  const isAdmin = core.isAdminActor(machtileFlowVisibilityRole(), machtileDepartmentAccess?.is_bridge === true);
  const actorRole = isAdmin ? "admin" : "operator";
  const actorName = () => machtileAuthState.appUserName || machtileAccountDisplay(machtileAuthState.email) || "";
  const sheet = {
    code, type, order, uuid, phase: "confirm", loading: true, fresh: null, attempts: 0, returnFocus: returnFocus || null,
    fields: { orderNo: order.id, step: order.stationStep, manufactureIiId: order.manufactureIiId || null, partNo: null },
    model: core.confirmModel({ commandType: type, machineCode: code, order, otherOrderCount: others, actorRole, actorName: actorName() }),
    // 開工時一起填今日開工數量（owner 2026-10-08）：作業員＋開工＋今天這道還沒有今日開工紀錄才問；管理員不問
    dailyStart: machtileStationCmdAskDailyStart(type, order) ? { state: "ask", value: "", error: "", qty: null } : null,
  };
  machtileStationCmdNewSheet(sheet);
  let legacy = null;
  let legacyError = false;
  let fresh = null;
  await Promise.all([
    (async () => {
      try {
        const rows = await supabaseFetch(`work_order_processes?select=id,process_order,process_name,status,off_station_at,work_orders!inner(work_order_no,part_no,part_name,status),machines!work_order_processes_machine_id_fkey(machine_code)&id=eq.${encodeURIComponent(order.processId)}`);
        fresh = core.freshCheck({ order, machineCode: code, row: Array.isArray(rows) ? rows[0] : null });
      } catch (error) {
        console.warn("station command: work_order_processes re-read failed", error);
        fresh = { ok: false, reason: "read_failed", text: "讀不到最新的工單資料，請重新整理畫面再按。" };
      }
    })(),
    (async () => {
      try {
        const wo = `"${encodeURIComponent(String(order.id).replace(/"/g, ""))}"`;
        const rows = await supabaseFetch(`legacy_station_progress?select=work_order_no,machine_code,process_order,legacy_output,legacy_fail,legacy_updated_at,legacy_snapshot_at&work_order_no=in.(${wo})`);
        legacy = core.legacyRowFor(rows, { workOrderNo: order.id, machineCode: code, step: order.stationStep });
      } catch (error) {
        console.warn("station command: legacy_station_progress unavailable", error);
        legacyError = true;
      }
    })(),
    // 管理員：確認卡要寫出「你是管理員 <名字>」→ 讀一次 app_users 名字（已讀過就不再讀）
    isAdmin ? machtileResolveAppUserId().catch(() => "") : Promise.resolve(""),
    // 要問今日開工數量時，重讀一次今天的紀錄（卡片的那份最多 2 分鐘前）：別台平板剛記過 → 不再問；讀不到 → 照卡片那份
    sheet.dailyStart ? machtileStationCmdRecheckDailyStart(order) : Promise.resolve(true),
  ]).then((results) => {
    if (results[3] === false && sheet.dailyStart && sheet.dailyStart.state === "ask") sheet.dailyStart = null;
  });
  if (machtileStationCmd.sheet !== sheet) return;
  sheet.loading = false;
  sheet.fresh = fresh;
  if (fresh && fresh.ok) sheet.fields.partNo = fresh.partNo;
  sheet.model = core.confirmModel({ commandType: type, machineCode: code, order, fresh, legacy, legacyError, otherOrderCount: others, nowMs: Date.now(), actorRole, actorName: actorName() });
  machtileStationCmdRenderSheet();
}

// 重新整理後「上次送出不確定」→ 從卡片直接用同一個 uuid 重送
function machtileStationCmdOpenRetry(code, returnFocus) {
  const core = machtileStationCmdCore;
  const rec = machtileStationCmd.pending[code];
  if (!core || !rec || !rec.unconfirmed) return;
  const order = { id: rec.orderNo, stationStep: rec.step, part: rec.partName, process: rec.operationName, manufactureIiId: rec.manufactureIiId };
  const fresh = { ok: true, partNo: rec.partNo, partName: rec.partName, operationName: rec.operationName };
  machtileStationCmdNewSheet({
    code, type: rec.commandType, order, uuid: rec.commandUuid, phase: "sendError", loading: false, fresh, attempts: 1, isRetry: true,
    returnFocus: returnFocus || null, canRetry: true,
    errorText: "上次送出時網路斷了，不知道有沒有送到。按「重送」會用同一筆指令，不會重複。",
    fields: { orderNo: rec.orderNo, step: rec.step, manufactureIiId: rec.manufactureIiId, partNo: rec.partNo },
    model: core.confirmModel({ commandType: rec.commandType, machineCode: code, order, fresh,
      actorRole: core.isAdminActor(machtileFlowVisibilityRole(), machtileDepartmentAccess?.is_bridge === true) ? "admin" : "operator",
      actorName: machtileAuthState.appUserName || machtileAccountDisplay(machtileAuthState.email) || "" }),
  });
}

// ---- 開工時一起填「今日開工」數量（owner 2026-10-08「按開工時，順便請他填計數器數字，一次做完」）----
// 只有作業員按「開工」、而且今天這道工序還沒有今日開工紀錄（伺服器或 outbox 待送都算有）才在確認卡多一格必填數量。
// 開工指令被伺服器接受才寫今日開工（L3 P1）；送出時網路斷 → 數量跟著那筆等確認的指令存（localStorage），之後查到指令被接受
// （確認卡還開著、關掉、或重新整理後的輪詢）才寫一次，被拒／過期就丟掉（owner「先修」）。寫之前一律重讀：今天已有就不寫。
// 今日開工走報工→今日開工同一條路（submitReport → outbox field_report_upsert，outbox 不能用時直接寫 production_reports）。
function machtileStationCmdAskDailyStart(type, order) {
  const core = machtileStationCmdCore;
  if (!core || typeof core.askDailyStart !== "function" || !order) return false;
  return core.askDailyStart({
    commandType: type, role: machtileFlowVisibilityRole(), isBridge: machtileDepartmentAccess?.is_bridge === true,
    todayStatus: machtileCardState.todayStatus, rows: machtileCardState.todayRows, processId: order.processId,
  });
}

// outbox 裡還沒送到（待送／送出中）的今日開工：同一道、今天 → { qty }；沒有、outbox 不能用 → null
async function machtileOutboxPendingDailyStart(processId) {
  if (!processId || !machtileOutboxEnabled()) return null;
  try {
    const box = await machtileGetOutbox();
    if (!box) return null;
    const ecore = machtileCardEstimateCore();
    const since = ecore ? Date.parse(ecore.todayStartIso()) : NaN;
    const items = await box.outbox.list();
    const hit = (Array.isArray(items) ? items : []).find((it) => {
      const pl = it && it.payload;
      if (!pl || !["pending", "sending"].includes(it.status)) return false;
      if (pl.report_type !== "dailyStart" || String(pl.process_id) !== String(processId)) return false;
      const at = Date.parse(pl.ended_at || "") || Number(it.created_at) || 0;
      return !Number.isFinite(since) || at >= since;
    });
    return hit ? { qty: hit.payload.report_payload?.machine_qty ?? null } : null;
  } catch (error) {
    console.warn("outbox dailyStart lookup failed", error);
    return null;
  }
}

// 今天這道有沒有今日開工：重讀伺服器（卡片底部同一支查詢）或 outbox 待送 → "server"／"outbox"；都沒有 → ""。
// 伺服器讀不到 → 只看 outbox（卡片那份資料已經判過一次「還沒有」）。
// 今天這道有沒有今日開工 →
//   "pending"＝這台平板還有一筆等送達的今日開工（machtileDailyStartQueue）、"server"＝伺服器今天已有、
//   "outbox"＝outbox 有待送、""＝伺服器確認沒有、"unknown"＝伺服器讀不到（L3：讀不到就不能當作沒有）
async function machtileDailyStartExistsToday(processId) {
  if (!processId) return "unknown";
  if (machtileDailyStartQueueFor(processId)) return "pending";
  const ecore = machtileCardEstimateCore();
  let read = false;
  if (ecore) {
    try {
      const rows = await machtileCardFetch(machtileCardTodayPath(ecore));
      if (!Array.isArray(rows)) throw new Error("production_reports returned no rows array");
      read = true;
      if (machtileStationCmdCore.dailyStartRecordedToday(rows, processId)) return "server";
    } catch (error) {
      console.warn("station command: today dailyStart re-read failed", error);
    }
  }
  if (await machtileOutboxPendingDailyStart(processId)) return "outbox";
  return read ? "" : "unknown";
}

// 開確認卡時要不要問數量：回 false＝今天已有（伺服器、outbox、這台等送達的）→ 不問；讀不到 → 照卡片那份資料
async function machtileStationCmdRecheckDailyStart(order) {
  const where = await machtileDailyStartExistsToday(order.processId);
  return where === "" || where === "unknown";
}

function machtileStationCmdDailyStartHtml(sheet) {
  const core = machtileStationCmdCore;
  const ds = sheet && sheet.dailyStart;
  if (!core || !ds) return "";
  if (ds.state === "ask") {
    if (!["confirm", "sendError"].includes(sheet.phase)) return "";
    return `<section class="station-cmd-daily" data-station-cmd-daily>
        <label for="stationCmdDailyQty">${escapeHtml(core.DAILY_START_FIELD_LABEL)} <small>必填</small></label>
        <input id="stationCmdDailyQty" type="number" inputmode="numeric" min="0" step="1" required aria-required="true"${ds.error ? ' aria-invalid="true" aria-describedby="stationCmdDailyErr"' : ""} data-station-cmd-daily-qty value="${escapeHtml(ds.value)}" autocomplete="off">
        <p>今天這台還沒記今日開工：照機台計數器填，按確認會一起記下來（只記錄，不改舊 MES）。</p>
        ${ds.error ? `<p class="station-cmd-notice" id="stationCmdDailyErr" role="alert" data-station-cmd-daily-error>${escapeHtml(ds.error)}</p>` : ""}
      </section>`;
  }
  if (ds.state === "failed") return `<p class="station-cmd-notice is-bad" role="alert" data-station-cmd-daily-state="failed">${escapeHtml(core.DAILY_START_FAILED_TEXT)}</p>`;
  if (ds.state === "queued") return `<p class="station-cmd-daily-line is-wait" role="status" data-station-cmd-daily-state="queued">${escapeHtml(core.DAILY_START_QUEUED_TEXT)}</p>`;
  if (ds.state === "exists") return `<p class="station-cmd-daily-line is-wait" role="status" data-station-cmd-daily-state="exists">${escapeHtml(core.DAILY_START_EXISTS_TEXT)}</p>`;
  if (ds.state === "retrying") return `<p class="station-cmd-daily-line is-wait" role="status" data-station-cmd-daily-state="retrying">${escapeHtml(core.DAILY_START_RETRY_TEXT)}</p>`;
  if (ds.state === "unconfirmed") return `<p class="station-cmd-daily-line is-wait" role="status" data-station-cmd-daily-state="unconfirmed">${escapeHtml(core.DAILY_START_UNCONFIRMED_TEXT)}</p>`;
  if (ds.state === "absent") {
    return `<div class="station-cmd-notice is-warn" role="alert" data-station-cmd-daily-state="absent">
        <p style="margin:0">${escapeHtml(core.DAILY_START_ABSENT_TEXT)}</p>
        <button type="button" class="station-cmd-secondary" style="margin-top:8px;min-height:48px;width:100%" data-station-cmd-daily-resend>重送今日開工（數量 ${escapeHtml(String(ds.qty))}）</button>
      </div>`;
  }
  const text = ds.state === "saving" || ds.state === "awaitAck" ? "儲存中…" : "已記錄";
  const tone = ds.state === "saved" ? "is-ok" : "is-wait";
  return `<p class="station-cmd-daily-line ${tone}" role="status" data-station-cmd-daily-state="${escapeHtml(ds.state)}">今日開工數量 ${escapeHtml(String(ds.qty))}：${escapeHtml(text)}</p>`;
}

// 要寫的今日開工（數量＋那道工序＋固定的 report_uuid）。report_uuid 由（租戶、機台、工序、台灣日期、開工指令 uuid）算出，
// 重送／補寫永遠同一個 → 伺服器 UNIQUE(tenant_id, report_uuid) 保證最多一列。壞資料 → null
function machtileStationCmdDailyStartSnapshot(order, qty, commandUuid, machineCode, atMs) {
  const core = machtileStationCmdCore;
  return core.pendingDailyStart({
    qty, processId: order?.processId, workOrderId: order?.workOrderId, tenantId: order?.tenantId, processStatus: order?.processStatus,
    reportUuid: core.dailyStartReportUuid({ tenantId: order?.tenantId, machineCode, processId: order?.processId, commandUuid, day: core.taiwanDay(atMs ?? Date.now()) }),
  });
}

// ---- 等送達的今日開工（L3 複審 fa1db2fb）----
// 開工指令被接受後，要寫的今日開工（數量、工序、固定 report_uuid）先存進 localStorage（machtileDailyStartQueue），
// 直到「重讀伺服器看到今天這道有今日開工」或「伺服器明確拒絕」才刪；排入 outbox 待送、結果不確定、讀不到都不刪。
// 每一輪：先重讀伺服器（讀不到 → 不寫，退避後再試）→ 有了 → 完成；沒有 → outbox 有這筆待送就等、否則用同一個
// report_uuid 送出（伺服器 UNIQUE(tenant_id, report_uuid) 去重）。重新整理後、連線恢復時自動接著做。
const MACHTILE_DAILY_START_QUEUE_KEY = "machtile.stationCmdDailyStart.v1";
const MACHTILE_DAILY_START_MAX_TRIES = 10;          // 每次開頁最多試幾輪（之後等重新整理／連線恢復）
const MACHTILE_DAILY_START_KEEP_MS = 24 * 60 * 60 * 1000;
const machtileDailyStartRun = { timers: {}, running: {}, tries: {}, ui: {}, notified: {} };

function machtileDailyStartQueueRead() {
  let obj = {};
  try { obj = JSON.parse(localStorage.getItem(MACHTILE_DAILY_START_QUEUE_KEY) || "{}") || {}; } catch { obj = {}; }
  const out = {};
  Object.keys(obj).forEach((key) => {
    const it = obj[key];
    const snap = it && machtileStationCmdCore.pendingDailyStart(it.snap);
    if (!snap || !snap.reportUuid || Date.now() - Number(it.createdAt || 0) > MACHTILE_DAILY_START_KEEP_MS) return;
    out[key] = { snap, machineCode: String(it.machineCode || ""), createdAt: Number(it.createdAt), wrote: it.wrote === true, absentChecks: Number(it.absentChecks) || 0 };
  });
  return out;
}

function machtileDailyStartQueueWrite(queue) {
  try { localStorage.setItem(MACHTILE_DAILY_START_QUEUE_KEY, JSON.stringify(queue)); } catch { /* 無痕視窗：只是重新整理後不記得 */ }
}

function machtileDailyStartQueueFor(processId) {
  const queue = machtileDailyStartQueueRead();
  const key = Object.keys(queue).find((k) => String(queue[k].snap.processId) === String(processId));
  return key ? { key, ...queue[key] } : null;
}

function machtileDailyStartQueueUpdate(key, patch) {
  const queue = machtileDailyStartQueueRead();
  if (!queue[key]) return;
  queue[key] = { ...queue[key], ...patch };
  machtileDailyStartQueueWrite(queue);
}

function machtileDailyStartQueueRemove(key) {
  const queue = machtileDailyStartQueueRead();
  delete queue[key];
  machtileDailyStartQueueWrite(queue);
  clearTimeout(machtileDailyStartRun.timers[key]);
  delete machtileDailyStartRun.timers[key];
  delete machtileDailyStartRun.tries[key];
  delete machtileDailyStartRun.notified[key];
}

// 加一筆（key＝開工指令 uuid；同一筆再加不會蓋掉進度）並開始處理。ui＝{ sheet, ds }（確認卡）或 null
function machtileDailyStartEnqueue(commandUuid, machineCode, snap, ui) {
  const key = String(commandUuid);
  const queue = machtileDailyStartQueueRead();
  if (!queue[key]) queue[key] = { snap, machineCode: String(machineCode || ""), createdAt: Date.now(), wrote: false, absentChecks: 0 };
  machtileDailyStartQueueWrite(queue);
  if (ui) machtileDailyStartRun.ui[key] = ui;
  machtileDailyStartKick(key, 0);
}

function machtileDailyStartKick(key, delayMs) {
  clearTimeout(machtileDailyStartRun.timers[key]);
  machtileDailyStartRun.timers[key] = setTimeout(() => { machtileDailyStartResolve(key); }, Math.max(0, delayMs || 0));
}

function machtileDailyStartBackoff(tries) {
  const base = Number(config.stationCmdDailyStartVerifyMs) > 0 ? Number(config.stationCmdDailyStartVerifyMs) : 5000;
  return Math.min(base * 2 ** Math.max(0, tries - 1), 60000);
}

// 開頁（功能可用時）、連線恢復時：接著處理還沒送達的
function machtileDailyStartResumeAll() {
  Object.keys(machtileDailyStartQueueRead()).forEach((key) => {
    machtileDailyStartRun.tries[key] = 0;
    machtileDailyStartKick(key, 0);
  });
}

// 確認卡上的狀態＋提示（同一個狀態只提示一次）
function machtileDailyStartShow(key, state, qty) {
  const core = machtileStationCmdCore;
  const ui = machtileDailyStartRun.ui[key];
  if (ui && ui.ds) {
    ui.ds.state = state;
    ui.ds.qty = qty;
    if (machtileStationCmd.sheet === ui.sheet) machtileStationCmdRenderSheet();
  }
  const toast = { failed: core.DAILY_START_FAILED_TEXT, queued: core.DAILY_START_QUEUED_TEXT, unconfirmed: core.DAILY_START_UNCONFIRMED_TEXT,
    retrying: core.DAILY_START_RETRY_TEXT }[state];
  if (toast && machtileDailyStartRun.notified[key] !== state) {
    machtileDailyStartRun.notified[key] = state;
    showToast(toast);
  }
}

function machtileDailyStartUiOpen(key) {
  const ui = machtileDailyStartRun.ui[key];
  return Boolean(ui && ui.ds && machtileStationCmd.sheet === ui.sheet);
}

// 處理一筆（同一筆同時只跑一個）
async function machtileDailyStartResolve(key, { force = false } = {}) {
  const core = machtileStationCmdCore;
  if (!core || machtileDailyStartRun.running[key]) return;
  const item = machtileDailyStartQueueRead()[key];
  if (!item) return;
  machtileDailyStartRun.running[key] = true;
  const snap = item.snap;
  const again = (state) => {
    machtileDailyStartShow(key, state, snap.qty);
    const tries = (machtileDailyStartRun.tries[key] || 0) + 1;
    machtileDailyStartRun.tries[key] = tries;
    if (tries < MACHTILE_DAILY_START_MAX_TRIES) machtileDailyStartKick(key, machtileDailyStartBackoff(tries));
  };
  const done = async (state) => {
    machtileDailyStartQueueRemove(key);
    machtileDailyStartShow(key, state, snap.qty);
    if (state === "saved" || state === "exists") await machtileStationCmdRefreshToday();
  };
  try {
    // 1. 重讀伺服器今天的報工：讀不到 → 不寫
    const ecore = machtileCardEstimateCore();
    let rows = null;
    try {
      rows = ecore ? await machtileCardFetch(machtileCardTodayPath(ecore)) : null;
      if (!Array.isArray(rows)) rows = null;
    } catch (error) {
      console.warn("dailyStart queue: today re-read failed; will retry", error);
    }
    if (!rows) { again(item.wrote ? "unconfirmed" : "retrying"); return; }
    if (core.dailyStartRecordedToday(rows, snap.processId)) { await done(item.wrote ? "saved" : "exists"); return; }
    // 2. 伺服器確認沒有：outbox 已有這筆（同一個 report_uuid）待送 → 等它送
    const outboxItem = await machtileOutboxItemByUuid(snap.reportUuid);
    if (outboxItem && ["pending", "sending"].includes(outboxItem.status)) { again("queued"); return; }
    // 這台 outbox 裡有別筆今天這道的今日開工待送（例：報工畫面送的）→ 不再寫
    if (!outboxItem && await machtileOutboxPendingDailyStart(snap.processId)) { await done("queued"); return; }
    // 3. 送過但結果不確定、伺服器還沒看到：再查兩次；確認卡開著 → 出重送鈕等他按，關著 → 自動用同一筆重送
    if (item.wrote && !force && item.absentChecks < 2) {
      machtileDailyStartQueueUpdate(key, { absentChecks: item.absentChecks + 1 });
      again("unconfirmed");
      return;
    }
    if (item.wrote && !force && machtileDailyStartUiOpen(key)) { machtileDailyStartShow(key, "absent", snap.qty); return; }
    // 4. 送出（同一個 report_uuid）
    machtileDailyStartQueueUpdate(key, { wrote: true, absentChecks: 0 });
    machtileDailyStartShow(key, "saving", snap.qty);
    const outcome = await machtileDailyStartSubmit(snap);
    if (outcome === "failed") { await done("failed"); return; }          // 伺服器明確拒絕：沒寫進去，提示補填
    if (outcome === "saved") {                                            // 回了列 → 馬上重讀確認
      machtileDailyStartRun.running[key] = false;
      machtileDailyStartKick(key, 0);
      return;
    }
    again(outcome);                                                       // queued／unconfirmed：留著，之後再查
  } finally {
    machtileDailyStartRun.running[key] = false;
  }
}

async function machtileOutboxItemByUuid(reportUuid) {
  if (!reportUuid || !machtileOutboxEnabled()) return null;
  try {
    const box = await machtileGetOutbox();
    return box ? (await box.outbox.get(reportUuid)) || null : null;
  } catch {
    return null;
  }
}

// 用固定的 report_uuid 送一筆今日開工。回 saved（伺服器回了列）／queued（outbox 待送）／
// unconfirmed（201 沒回列、網路斷、逾時、5xx、409…）／failed（伺服器明確拒絕：4xx、dead-letter）
async function machtileDailyStartSubmit(snap) {
  try {
    const actorId = await machtileResolveAppUserId();
    const result = await submitReport(0, 0, buildDailyStartCounterRemark(snap.qty), "dailyStart", {
      order: snap,
      reportPayload: buildDailyStartCounterPayload(snap.qty),
      operators: actorId ? [actorId] : [],
      noFiles: true,
      requireStructured: true,
      reportUuid: snap.reportUuid,
    });
    if (!result || !result.wroteCloud || result.deadLetter) return "failed";
    if (result.queuedOffline) return "queued";
    return result.reportId != null && String(result.reportId) !== "" ? "saved" : "unconfirmed";
  } catch (error) {
    console.warn("station command: dailyStart save failed", error);
    const status = Number((String(error?.message || "").match(/^(\d{3})\b/) || [])[1]);
    return status >= 400 && status < 500 && ![408, 409, 429].includes(status) ? "failed" : "unconfirmed";
  }
}

// 等確認的開工指令（送出時網路斷）在伺服器查到：被接受 → 數量搬進「等送達的今日開工」（先存那邊、再從指令紀錄拿掉）；
// rejected／expired → 丟掉（卡片照舊顯示被拒／過期）。
function machtileStationCmdDelayedDailyStart(code, record, row) {
  const core = machtileStationCmdCore;
  const saved = record && record.dailyStart;
  if (!core || !saved) return;
  const action = core.delayedDailyStartAction(row && row.status);
  if (action === "wait") return;
  if (action === "write") {
    const snap = saved.reportUuid ? saved : { ...saved,
      reportUuid: core.dailyStartReportUuid({ tenantId: saved.tenantId, machineCode: code, processId: saved.processId, commandUuid: record.commandUuid, day: core.taiwanDay(record.startedAt) }) };
    const sheet = machtileStationCmd.sheet;
    const ds = sheet && String(sheet.uuid) === String(record.commandUuid) && sheet.dailyStart ? sheet.dailyStart : null;
    if (ds) { ds.snap = snap; ds.qty = snap.qty; }
    machtileDailyStartEnqueue(record.commandUuid, code, snap, ds ? { sheet, ds } : null);
  }
  record.dailyStart = null;
  machtileStationCmdSavePending();
}

// 送出失敗、要記成「等確認」時，跟著存的今日開工：確認卡剛送的那個數量，或（從卡片重送時）上一筆紀錄裡存的
function machtileStationCmdCarriedDailyStart(sheet, existing) {
  const ds = sheet && sheet.dailyStart;
  if (ds && ds.state === "awaitAck") return machtileStationCmdDailyStartSnapshot(sheet.order, ds.qty, sheet.uuid, sheet.code);
  return existing && existing.commandUuid === sheet.uuid ? existing.dailyStart || null : null;
}

// 確認卡上「確認開工」：有今日開工那一格 → 先檢查數量（不合格就不送任何東西）→ 開工指令照舊送 →
// 伺服器「接受」這筆開工指令（machtile_submit_station_command 回了「同一個 command_uuid」的指令列，新建或冪等重送都算）才寫今日開工。
// 送出被拒／送出時網路斷（沒收到回覆）／按鈕鎖住／回應不是這筆 → 不寫今日開工（2026-10-08 L3 P1／P3）。
// 之後工廠套用舊 MES 的結果（applied／rejected／expired）不影響已寫的今日開工：計數器數字是事實。
function machtileStationCmdConfirm() {
  const core = machtileStationCmdCore;
  const sheet = machtileStationCmd.sheet;
  const ds = sheet && sheet.dailyStart;
  if (core && ds && ds.state === "ask") {
    if (!machtileStationCmdCanSubmit(sheet)) return;
    const input = document.querySelector("#machtileStationCmdSheet [data-station-cmd-daily-qty]");
    const raw = input ? input.value : ds.value;
    const check = core.dailyStartQtyCheck(raw);
    if (!check.ok) {
      ds.value = raw;
      ds.error = check.text;
      machtileStationCmdRenderSheet();
      try { document.querySelector("#machtileStationCmdSheet [data-station-cmd-daily-qty]")?.focus(); } catch { /* ignore */ }
      return;
    }
    ds.value = raw;
    ds.qty = check.value;
    ds.error = "";
    ds.state = "awaitAck";   // 等開工指令被接受；送出被拒會改回 ask（數量還在）
  }
  machtileStationCmdSubmit();
}

// 伺服器回的是不是「這一筆」指令列（L3 P3：沒有 command_uuid 或不同 → 不算）
function machtileStationCmdRowIsThis(row, uuid) {
  return Boolean(row && row.command_uuid != null && String(row.command_uuid).toLowerCase() === String(uuid).toLowerCase());
}

// machtileStationCmdSubmit 的兩個出口呼叫：accepted＝RPC 有回應（沒丟錯）
function machtileStationCmdDailyStartAfterSubmit(sheet, accepted, row) {
  const ds = sheet && sheet.dailyStart;
  if (!ds || ds.state !== "awaitAck") return;
  if (!accepted) { ds.state = "ask"; return; }   // 開工沒送成 → 不寫，欄位連同數字回到確認卡
  if (!machtileStationCmdRowIsThis(row, sheet.uuid)) {
    // 回應裡不是這筆指令：不能確定開工有被接受 → 不寫（沒有任何今日開工被送出，補填不會重複）
    ds.state = "failed";
    showToast(machtileStationCmdCore.DAILY_START_FAILED_TEXT);
    return;
  }
  const snap = machtileStationCmdDailyStartSnapshot(sheet.order, ds.qty, sheet.uuid, sheet.code);
  if (!snap) { ds.state = "failed"; showToast(machtileStationCmdCore.DAILY_START_FAILED_TEXT); return; }
  ds.state = "saving";   // 同步改掉：之後再按、重送開工指令都不會再送今日開工
  ds.snap = snap;
  machtileDailyStartEnqueue(sheet.uuid, sheet.code, snap, { sheet, ds });
}

// 確認卡「重送今日開工」（查過伺服器確定沒有那一筆）：同一個 report_uuid 再送一次
function machtileStationCmdResendDailyStart() {
  const sheet = machtileStationCmd.sheet;
  const ds = sheet && sheet.dailyStart;
  if (!ds || ds.state !== "absent" || !ds.snap) return;
  ds.state = "saving";   // 同步：連按只送一次
  machtileStationCmdRenderSheet();
  machtileDailyStartResolve(String(sheet.uuid), { force: true });
}

// 今日開工存好 → 重讀今天的紀錄（卡片底部「今日已開工…」、總覽三格同一份），不用等每 2 分鐘的重讀
async function machtileStationCmdRefreshToday() {
  const ecore = machtileCardEstimateCore();
  if (!ecore || state.source !== "supabase") return;
  try {
    machtileApplyCardTodayRows(ecore, await machtileCardFetch(machtileCardTodayPath(ecore)));
  } catch (error) {
    console.warn("station command: today reports refresh failed; the 2-minute refresh will pick it up", error);
    return;
  }
  try { renderStats(); } catch { /* 總覽沒開也沒關係 */ }
  machtileStationCmdRerender();
}

window.addEventListener("online", () => { if (machtileStationCmd.availability === "ready") machtileDailyStartResumeAll(); });

document.addEventListener("input", (event) => {
  const input = event.target;
  if (!(input instanceof HTMLElement) || !input.matches("[data-station-cmd-daily-qty]")) return;
  const ds = machtileStationCmd.sheet && machtileStationCmd.sheet.dailyStart;
  if (!ds || ds.state !== "ask") return;
  ds.value = input.value;
  // 改了數字 → 上一次的提示收起來（不整張重畫，游標不跳）
  if (ds.error) {
    ds.error = "";
    input.removeAttribute("aria-invalid");
    input.removeAttribute("aria-describedby");
    document.querySelector("#machtileStationCmdSheet [data-station-cmd-daily-error]")?.remove();
  }
});

// 送得出開工指令嗎（確認鈕的同一套條件；machtileStationCmdSubmit 也用這個）
function machtileStationCmdCanSubmit(sheet) {
  const core = machtileStationCmdCore;
  if (!core || !sheet || sheet.phase === "sending" || sheet.loading) return false;
  if (!["confirm", "sendError"].includes(sheet.phase)) return false;
  if (sheet.phase === "sendError" && !sheet.canRetry) return false;
  if (!sheet.fresh || !sheet.fresh.ok) return false;
  const existing = machtileStationCmd.pending[sheet.code];
  if (existing && existing.commandUuid !== sheet.uuid && !machtileStationCmdUnlocked(existing)) return false;
  return true;
}

function machtileStationCmdRecordFor(sheet, extra) {
  return machtileStationCmdCore.pendingRecord({
    commandUuid: sheet.uuid, commandType: sheet.type, machineCode: sheet.code,
    orderNo: sheet.fields.orderNo, step: sheet.fields.step, partNo: sheet.fields.partNo, manufactureIiId: sheet.fields.manufactureIiId,
    partName: sheet.model.partName, operationName: sheet.model.operationName,
    startedAt: machtileStationCmd.pending[sheet.code]?.commandUuid === sheet.uuid ? machtileStationCmd.pending[sheet.code].startedAt : Date.now(),
    ...extra,
  });
}

async function machtileStationCmdSubmit() {
  const core = machtileStationCmdCore;
  const sheet = machtileStationCmd.sheet;
  if (!machtileStationCmdCanSubmit(sheet)) return;
  const existing = machtileStationCmd.pending[sheet.code];
  sheet.phase = "sending";
  sheet.attempts += 1;
  machtileStationCmdRenderSheet();
  const startedAt = existing?.commandUuid === sheet.uuid ? existing.startedAt : Date.now();
  let row = null;
  const controller = typeof AbortController === "function" ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(new Error("timeout")), core.SUBMIT_TIMEOUT_MS) : null;
  try {
    const payload = core.submitPayload({ commandUuid: sheet.uuid, commandType: sheet.type, machineCode: sheet.code, ...sheet.fields });
    const result = await supabaseFetch(`rpc/${core.SUBMIT_RPC}`, { method: "POST", body: JSON.stringify(payload), ...(controller ? { signal: controller.signal } : {}) });
    row = Array.isArray(result) ? result[0] : result;
  } catch (error) {
    if (timer) clearTimeout(timer);
    const carried = machtileStationCmdCarriedDailyStart(sheet, existing);
    machtileStationCmdDailyStartAfterSubmit(sheet, false, null);
    if (machtileStationCmd.sheet !== sheet) return;
    const info = core.submitErrorText(error);
    if (info.missing) machtileStationCmd.availability = "missing";
    sheet.phase = "sendError";
    sheet.errorText = info.text;
    sheet.canRetry = info.retry;
    if (info.retry) {
      // 不知道有沒有送到：記下來（重新整理後也記得），一面查這個 uuid，一面讓他立刻用同一個 uuid 重送
      // 今日開工數量跟著這筆存：之後查到指令被接受才寫（作業員關掉確認卡、重新整理也一樣）
      machtileStationCmd.pending[sheet.code] = { ...machtileStationCmdRecordFor(sheet, { unconfirmed: true, serverOffset: null, dailyStart: carried }), startedAt };
      machtileStationCmdSavePending();
      machtileStationCmdPoll(sheet.code);
    } else if (machtileStationCmd.pending[sheet.code]?.commandUuid === sheet.uuid) {
      // 伺服器明確拒絕了這次請求 → 這個 uuid 沒有建成指令，解鎖
      delete machtileStationCmd.pending[sheet.code];
      machtileStationCmdSavePending();
    }
    machtileStationCmdRenderSheet();
    machtileStationCmdRerender();
    return;
  }
  if (timer) clearTimeout(timer);
  // 上一次送出網路斷時存的數量（從卡片「用同一筆重送」）；確認卡這次自己有填 → 由確認卡寫，存的那份丟掉
  const carriedDs = existing?.commandUuid === sheet.uuid ? existing.dailyStart || null : null;
  const sheetAwaitsAck = sheet.dailyStart?.state === "awaitAck";
  machtileStationCmdDailyStartAfterSubmit(sheet, true, row);
  const now = Date.now();
  // 伺服器時鐘差：只有第一次送出（新建的列）才準；重送拿到的可能是舊列 → 不算
  const offset = sheet.attempts === 1 && row ? core.serverOffset(row.requested_at, now) : (existing?.commandUuid === sheet.uuid ? existing.serverOffset : null);
  const record = { ...machtileStationCmdRecordFor(sheet, { unconfirmed: false, serverOffset: offset }), startedAt };
  machtileStationCmd.pending[sheet.code] = record;
  delete machtileStationCmd.lastResult[sheet.code];
  const view = core.statusView(row || { status: "pending" }, sheet.type, core.ageForHint(record, row?.requested_at, now));
  record.view = view;
  record.lastStatus = String(row?.status || "pending");
  if (carriedDs && !sheetAwaitsAck) record.dailyStart = carriedDs;
  machtileStationCmdSavePending();
  if (machtileStationCmd.sheet === sheet) {
    sheet.phase = "status";
    sheet.view = view;
    machtileStationCmdRenderSheet();
  }
  if (record.dailyStart && machtileStationCmdRowIsThis(row, sheet.uuid)) machtileStationCmdDelayedDailyStart(sheet.code, record, row);
  if (view.terminal) machtileStationCmdFinish(sheet.code, view);
  else machtileStationCmdPoll(sheet.code);
  machtileStationCmdRerender();
}

// 只有伺服器給了結果（applied／rejected／expired）才會走到這裡
function machtileStationCmdFinish(code, view) {
  const record = machtileStationCmd.pending[code];
  if (!record) return;
  clearTimeout(machtileStationCmd.timers[code]);
  delete machtileStationCmd.timers[code];
  delete machtileStationCmd.pending[code];
  machtileStationCmdSavePending();
  machtileStationCmd.lastResult[code] = { view, at: Date.now() };
  const sheet = machtileStationCmd.sheet;
  if (sheet && sheet.code === code && sheet.uuid === record.commandUuid) {
    sheet.phase = "status";
    sheet.view = view;
    machtileStationCmdRenderSheet();
  }
  machtileStationCmdRerender();
  if (view.phase === "applied") showToast(`${code} ${view.title}（舊 MES）`);
}

function machtileStationCmdPoll(code) {
  const core = machtileStationCmdCore;
  const record = machtileStationCmd.pending[code];
  if (!core || !record) return;
  clearTimeout(machtileStationCmd.timers[code]);
  const elapsed = Date.now() - record.startedAt;
  machtileStationCmd.timers[code] = setTimeout(async () => {
    const current = machtileStationCmd.pending[code];
    if (!current || current.commandUuid !== record.commandUuid) return;
    try {
      const rows = await supabaseFetch(`station_commands?select=command_uuid,command_type,status,requested_at,claimed_at,reject_code,reject_message,applied_at&command_uuid=eq.${current.commandUuid}`);
      const row = Array.isArray(rows) ? rows[0] : null;
      if (machtileStationCmd.pending[code] !== current) return;
      if (row) {
        if (current.dailyStart) machtileStationCmdDelayedDailyStart(code, current, row);
        const wasUnconfirmed = current.unconfirmed;
        current.unconfirmed = false;
        const view = core.statusView(row, current.commandType, core.ageForHint(current, row.requested_at, Date.now()));
        if (view.terminal) { machtileStationCmdFinish(code, view); return; }
        const changed = !current.view || current.view.title !== view.title || current.view.late !== view.late || wasUnconfirmed;
        current.view = view;
        const statusChanged = current.lastStatus !== String(row.status || "");
        current.lastStatus = String(row.status || "");
        if (wasUnconfirmed || statusChanged) machtileStationCmdSavePending();
        const sheet = machtileStationCmd.sheet;
        if (sheet && sheet.code === code && sheet.uuid === current.commandUuid) {
          if (sheet.phase === "sendError") sheet.phase = "status";
          if (sheet.phase === "status") { sheet.view = view; machtileStationCmdRenderSheet(); }
        }
        if (changed) machtileStationCmdRerender();
      } else if (current.unconfirmed) {
        current.emptyPolls = (current.emptyPolls || 0) + 1;
        if (core.unconfirmedNotSent(current, Date.now())) {
          // 送出時網路斷、伺服器連續查不到這筆＝沒送到 → 解鎖（同一個 uuid 之後重送也沒問題）
          delete machtileStationCmd.timers[code];
          delete machtileStationCmd.pending[code];
          machtileStationCmdSavePending();
          const sheet = machtileStationCmd.sheet;
          if (sheet && sheet.code === code && sheet.uuid === current.commandUuid && sheet.phase === "sendError") {
            sheet.errorText = "目前查不到這筆（已等 30 秒、查了 3 次）。可以按「重送」，會用同一筆指令，不會重複。";
            sheet.canRetry = true;
            machtileStationCmdRenderSheet();
          }
          machtileStationCmdRerender();
          return;
        }
      }
    } catch (error) {
      if (core.isMissingResourceError(error)) {
        // 表不見了：停止輪詢；不宣稱結果
        machtileStationCmd.availability = "missing";
        clearTimeout(machtileStationCmd.timers[code]);
        delete machtileStationCmd.timers[code];
        delete machtileStationCmd.pending[code];
        machtileStationCmdSavePending();
        machtileStationCmdRerender();
        return;
      }
      console.warn("station command poll failed; will retry", error);
    }
    // 剛過解鎖時間 → 卡片重畫一次（按鈕解鎖、輪詢照舊）
    if (!current.releasedShown && core.lockReleased(current.startedAt, Date.now())) { current.releasedShown = true; machtileStationCmdRerender(); }
    machtileStationCmdPoll(code);
  }, core.pollDelay(elapsed));
}

// 卡片按鈕與確認卡的點擊（document 層代理，於卡片「明細」判斷之前處理）
function machtileStationCmdHandleClick(event) {
  const open = event.target.closest("[data-station-cmd]");
  if (open) { machtileStationCmdOpen(open.dataset.stationCmd, open.dataset.stationCmdMachine, open); return true; }
  const retry = event.target.closest("[data-station-cmd-retry]");
  if (retry) { machtileStationCmdOpenRetry(retry.dataset.stationCmdRetry, retry); return true; }
  if (!event.target.closest("#machtileStationCmdSheet")) return false;
  if (event.target.closest("[data-station-cmd-confirm]")) { machtileStationCmdConfirm(); return true; }
  if (event.target.closest("[data-station-cmd-daily-resend]")) { machtileStationCmdResendDailyStart(); return true; }
  if (event.target.closest("[data-station-cmd-notthis-open]")) {
    const sheet = machtileStationCmd.sheet;
    if (sheet && sheet.phase !== "sending") { sheet.phase = "notThis"; machtileStationCmdRenderSheet(true); }
    return true;
  }
  if (event.target.closest("[data-station-cmd-close]")) { machtileStationCmdCloseSheet(); return true; }
  return true;
}

// Esc 關閉；Tab 只在確認卡裡面轉（focus trap）
document.addEventListener("keydown", (event) => {
  if (!machtileStationCmd.sheet || !document.getElementById("machtileStationCmdSheet")) return;
  if (event.key === "Escape") {
    event.preventDefault();
    machtileStationCmdCloseSheet();
    return;
  }
  if (event.key !== "Tab") return;
  const items = machtileStationCmdFocusables();
  if (!items.length) { event.preventDefault(); return; }
  const first = items[0];
  const last = items[items.length - 1];
  const inside = items.includes(document.activeElement);
  if (event.shiftKey && (document.activeElement === first || !inside)) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && (document.activeElement === last || !inside)) { event.preventDefault(); first.focus(); }
});

function renderMachineCard(machine) {
  const order = machine.order;
  const status = statusMeta[machine.status] || statusMeta.idle;
  const orderRiskKey = order ? deriveOrderStatus(order) : "";
  const orderRisk = order ? (statusMeta[orderRiskKey] || statusMeta.normal) : null;
  const due = order ? dueInfo(order) : { label: machine.status === "maintenance" ? "維修中" : "空閒", date: "-", diffDays: 999 };
  const percent = order ? pct(order) : 0;
  // 超量（已報良品 ≥ 訂單數量）仍在站：百分比照實（例 128%）、進度條滿格改紅色、加「超量 +N」標籤
  const overInfo = order ? machtileOverQtyInfo(order) : null;
  const isOver = Boolean(overInfo?.full);
  const percentText = isOver ? overInfo.percent : percent;
  const barPercent = isOver ? 100 : percent;
  const profile = order ? getProgramProfile(order) : null;
  const delta = profile ? cycleDelta(profile) : null;
  const dailyQty = profile ? dailyPureCapacity(profile) : null;
  const detailAttr = order ? `data-detail="${escapeHtml(order.id)}"` : "";
  const isHmc = isHmcMachine(machine);
  const hmcUrl = isHmc ? hmcReportRouteUrl(machine) : "";
  const canReport = isReportableMachineName(machine.name) && (!order || isOrderReportable(order));
  const reportAttr = order && canReport ? `data-report="${escapeHtml(order.id)}" data-report-machine="${escapeHtml(machine.name)}" data-report-process="${escapeHtml(order.processId || "")}"` : "";
  const reportUrl = canReport ? machineReportUrl(machine) : "";
  const qrReportUrl = reportUrl ? publicReportUrlOnLocalhost(reportUrl) : "";
  const reportLinkText = isHmc
    ? `${machine.code || machine.name} · 多盤多工件每日盤點`
    : order
    ? `${machine.code || machine.name} · 已帶 ${order.id} 報工連結`
    : `${machine.code || machine.name} · ${qrReportUrl}`;
  const detailUrl = order ? workOrderDetailUrl(order.id) : "";
  const flowLevel = machtileFlowVisibilityLevel();
  const dept = normalizedMachineDepartment(machine);
  const deptTone = dept === "車床課" ? "machine-dept-lathe" : dept === "銑床課" ? "machine-dept-mill" : "";
  const stationCmd = machtileStationCmdParts(machine);

  return `
    <article class="machine-tile-card ${status.className} ${deptTone}" ${detailAttr}>
      <header class="machine-tile-header">
        <div>
          <div class="machine-title-line">
            <span class="machine-symbol" aria-hidden="true"></span>
            <h2>${escapeHtml(machine.name)}${machine.location ? ` <span class="machine-alias">${escapeHtml(machine.location)}</span>` : ""}</h2>
          </div>
          <span class="machine-type-pill">${escapeHtml(machineTypeLabel(machine.type))}</span>
          ${dept === "車床課" || dept === "銑床課" ? `<span class="machine-dept-pill ${deptTone}">${escapeHtml(dept)}</span>` : ""}
          ${dept === "未設定課別" ? '<span class="machine-dept-pill">未設定課別</span>' : ""}
        </div>
        <div class="machine-header-actions">
          <span class="status-pill ${escapeHtml(status.className)}">機台 · ${escapeHtml(status.label)}</span>
          ${orderRisk && !["running", "normal"].includes(orderRiskKey) ? `<span class="status-pill ${escapeHtml(orderRisk.className)}">工單 · ${escapeHtml(orderRisk.label)}</span>` : ""}
          ${order ? `<a class="machine-open-link" data-no-detail ${flowLevel === "full" ? `data-flow-open="${escapeHtml(order.id)}" data-flow-current="${escapeHtml(order.processId || '')}" ` : ""}href="${escapeHtml(detailUrl)}" target="_blank" rel="noopener">完整單</a>` : ""}
        </div>
      </header>

      <div class="machine-job-strip">
        <span>目前工單</span>
        ${order ? `
          <strong class="job-order-highlight">${escapeHtml(order.id)} · ${escapeHtml(order.part)}</strong>${isOver ? machtileOverQtyTag(order) : ""}
          <small class="job-order-subline">${escapeHtml(order.customer)} · ${escapeHtml(machtileOperationLabel(order))}</small>
        ` : `
          <strong>${escapeHtml(machine.note || "無工單指派中")}</strong>
          <small>${machine.status === "idle" ? "可安排新工單" : "請確認機台狀態"}</small>
        `}
      </div>
      ${"" /* 原本中段「舊 MES 開工／停工」區塊的位置：已移到卡片底部（保留這一行，沒開功能的機台卡片 HTML 才會跟以前逐字相同） */}
      ${machtileCardOrdersMarkup(machine)}
      ${machtileProcessFlowMarkup(order, { level: flowLevel, machine })}
      ${!machine.isUnassignedBucket && machtileCanEditSchedule() && machtileCanAssignToMachine(machine.code || machine.name)
        ? `<button type="button" class="card-select-entry" data-no-detail data-card-select-open="${escapeHtml(machine.code || machine.name)}">選擇工單</button>` : ""}
      ${machtileCardPoolEntryMarkup(machine)}

      ${order ? `
        <div class="program-strip">
          <span>CNC 程式</span>
          <strong>${escapeHtml(profile.programName)}</strong>
          <small>
            ${escapeHtml(profile.programVersion)}
            ${profile.previousVersion && profile.previousVersion !== profile.programVersion ? ` · 較 ${escapeHtml(profile.previousVersion)} 有差異` : " · 與上版相同"}
          </small>
        </div>
      ` : ""}

      <div class="machine-metrics">
        <div>
          <span>完成進度</span>
          <strong${isOver ? ` class="card-progress-over"` : ""}>${order ? `${order.done}/${order.total}` : "-"}</strong>
          ${order ? `
            <small class="card-progress-pct${isOver ? " is-over" : ""}">${percentText}%</small>
            <div class="progress-track card-progress-track${isOver ? " is-over" : ""}" aria-label="完成進度 ${percentText}%">
              <div class="progress-fill" style="width:${barPercent}%"></div>
            </div>
          ` : "<small>未派工</small>"}
          ${order ? machtileCardProgressNote(order) : ""}
        </div>
        <div>
          <span>交期</span>
          <strong>${escapeHtml(due.label)}</strong>
          <small>${escapeHtml(due.date)}</small>
        </div>
      </div>

      ${order ? machtileCardCycleGrid(machine, order, profile, delta, dailyQty) : ""}

      <details class="machine-card-more" data-no-detail>
        <summary>${canReport ? "報工入口與建議" : "指派說明"}</summary>
        ${canReport ? `
          <a class="machine-qr-card" data-no-detail href="${escapeHtml(qrReportUrl)}" target="_blank" rel="noopener" aria-label="${escapeHtml(machine.name)} 開啟現場回報">
            <span class="qr-placeholder" aria-hidden="true">↗</span>
            <span>
              <strong>${isHmc ? "多盤多工件每日盤點" : "開啟報工頁"}</strong>
              <small>${escapeHtml(reportLinkText)}</small>
            </span>
          </a>
        ` : `
          <div class="machine-qr-card machine-qr-card-disabled" aria-label="未排機不產生 QR">
            <span class="qr-placeholder">--</span>
            <span><strong>未排機</strong><small>請先指派實際機台，指派後才會產生報工 QR</small></span>
          </div>
        `}
        <section class="machine-advice">
          <div class="advice-title"><span></span>處理建議</div>
          <p>${escapeHtml(order ? riskSuggestion(order) : machine.status === "idle" ? "目前空閒，可安排新工單。" : "請先確認機台狀態，再調整派工順序。")}</p>
        </section>
      </details>

      ${stationCmd.status}<footer class="machine-tile-footer${stationCmd.active ? " has-station-cmd" : ""}">
        ${machtileCardFooterStatus(order, machine)}
        <div class="machine-tile-actions">
          ${order
            ? `<button class="machine-detail-button" type="button" data-detail="${escapeHtml(order.id)}">明細</button>`
            : isHmc
              ? `<button class="machine-detail-button" type="button" data-no-detail data-hmc-machine-detail="${escapeHtml(machine.code || machine.name)}">明細</button>`
              : ""}
          ${isHmc
            ? `<a class="machine-hmc-report-link" data-no-detail href="${escapeHtml(hmcUrl)}">多盤多工件每日盤點</a>`
            : order
              ? canReport
                ? `<button type="button" class="machine-report-button" ${reportAttr}>報工</button>`
                : `<button type="button" data-no-detail data-schedule-open="${escapeHtml(machine.code || machine.name)}">前往指派</button>`
              : `<button type="button" data-no-detail data-schedule-open="${escapeHtml(machine.code || machine.name)}" ${["maintenance", "offline"].includes(machine.status) ? "disabled" : ""}>${["maintenance", "offline"].includes(machine.status) ? "不可指派" : "指派機台"}</button>`}${stationCmd.buttons}
        </div>
      </footer>
    </article>
  `;
}

function alertOrders() {
  return state.workOrders
    .filter((order) => {
      const categories = alertCategories(order);
      const categoryMatches = activeAlertFilter === "全部"
        ? categories.size > 0 && deriveOrderStatus(order) !== "normal"
        : categories.has(activeAlertFilter);
      return categoryMatches && machtileAttentionMatchesWorkflow(order);
    })
    .sort((a, b) => {
      const rank = { overdue: 0, abnormal: 1, aiRisk: 2, inspection: 3, stale: 4, running: 5, normal: 6 };
      return (rank[primaryAlertStatus(a)] ?? 9) - (rank[primaryAlertStatus(b)] ?? 9);
    });
}

function renderAlerts() {
  const counts = Object.fromEntries(alertFilters.map((filter) => [filter, 0]));
  state.workOrders.forEach((order) => {
    if (!machtileAttentionMatchesWorkflow(order)) return;
    const categories = alertCategories(order);
    if (categories.size > 0 && deriveOrderStatus(order) !== "normal") counts["全部"] += 1;
    categories.forEach((category) => {
      if (category in counts) counts[category] += 1;
    });
  });

  $("#alertChips").innerHTML = alertFilters.map((filter) => `
    <button class="filter-chip alert-chip ${activeAlertFilter === filter ? "active" : ""}" data-alert-filter="${escapeHtml(filter)}" type="button">
      ${escapeHtml(filter)} <span>${counts[filter] || 0}</span>
    </button>
  `).join("");

  const workflowCounts = Object.fromEntries(attentionWorkflowFilters.map((filter) => [filter, 0]));
  state.workOrders.forEach((order) => {
    if (alertCategories(order).size === 0 || deriveOrderStatus(order) === "normal") return;
    attentionWorkflowFilters.forEach((filter) => {
      if (machtileAttentionMatchesWorkflow(order, filter)) workflowCounts[filter] += 1;
    });
  });
  $("#attentionWorkflowChips").innerHTML = attentionWorkflowFilters.map((filter) => `
    <button class="filter-chip attention-workflow-chip ${activeAttentionStatus === filter ? "active" : ""}" data-attention-filter="${escapeHtml(filter)}" type="button">
      ${escapeHtml(filter)} <span>${workflowCounts[filter] || 0}</span>
    </button>
  `).join("");

  const alerts = alertOrders();
  $("#alertList").innerHTML = alerts.length
    ? alerts.map(renderAlertCard).join("")
    : `<article class="empty-card"><strong>目前沒有待處理警報</strong><span>所有工單都在可控範圍內。</span></article>`;

  const visibleKeys = new Set(alerts.map(machtileAttentionSourceKey));
  [...machtileAttentionState.selectedKeys].forEach((key) => {
    if (!visibleKeys.has(key)) machtileAttentionState.selectedKeys.delete(key);
  });
  const batchBar = $("#attentionBatchBar");
  const selectedCount = machtileAttentionState.selectedKeys.size;
  batchBar.hidden = selectedCount === 0;
  $("#attentionSelectedCount").textContent = String(selectedCount);
  batchBar.querySelectorAll("[data-attention-batch]").forEach((button) => { button.disabled = !machtileAttentionCanWrite(); });
  machtileRenderAttentionAudit();

  if (machtileStrictMode() && machtileSessionActive()) machtileRenderNotifyLog().catch(() => {});
}

function machtileRenderAttentionAudit() {
  const panel = $("#attentionAuditPanel");
  const list = $("#attentionAuditList");
  if (!panel || !list) return;
  const rows = machtileAttentionState.history.slice(0, 12);
  panel.hidden = rows.length === 0;
  if (!rows.length) {
    list.innerHTML = "";
    return;
  }
  const actionLabels = { created: "建立", assigned: "指派", status_changed: "更新狀態", closed: "結案", reopened: "重新開啟" };
  list.innerHTML = rows.map((row) => `
    <article>
      <div><strong>${escapeHtml(row.case_title || row.source_key || "待處理案件")}</strong><span>${escapeHtml(actionLabels[row.action] || row.action || "更新")}</span></div>
      <p>${escapeHtml(row.reason || "-")}</p>
      <small>${escapeHtml(row.actor_name || "系統")} · ${escapeHtml(machtileFormatAuditTime(row.created_at))}</small>
    </article>
  `).join("");
}

// H3 通知紀錄（strict）：警報頁尾顯示 LINE 已推播內容，與群組看到的一致。
async function machtileRenderNotifyLog() {
  const list = $("#alertList");
  if (!list || document.getElementById("machtileNotifyLog")) return;
  try {
    const rows = await supabaseFetch("line_notification_log?select=rule_key,message,sent_at&order=sent_at.desc&limit=20");
    const section = document.createElement("section");
    section.id = "machtileNotifyLog";
    section.className = "machtile-notify-log";
    section.innerHTML = `
      <div class="panel-title"><h2>LINE 通知紀錄</h2><span>近 ${(rows || []).length} 則</span></div>
      ${(rows || []).length ? rows.map((row) => `
        <div class="machtile-notify-log-row">
          <span>${escapeHtml((row.message || row.rule_key || "").slice(0, 90))}</span>
          <time>${escapeHtml(machtileFormatAuditTime(row.sent_at))}</time>
        </div>
      `).join("") : '<p class="empty-note">還沒有推播過通知。</p>'}
    `;
    list.parentElement.appendChild(section);
  } catch (error) {
    console.warn("notify log render failed", error);
  }
}

function renderAlertCard(order) {
  const status = statusMeta[primaryAlertStatus(order)] || statusMeta.normal;
  const due = dueInfo(order);
  const percent = pct(order);
  const categories = Array.from(alertCategories(order));
  const actions = alertActions(order);
  const primaryAction = actions[0];
  const secondaryActions = actions.slice(1);
  const caseState = machtileAttentionCaseForOrder(order);
  const attentionAction = machtileAttentionPrimaryAction(caseState);
  const attentionWritable = machtileAttentionCanWrite();
  const sourceKey = caseState.sourceKey;
  const selected = machtileAttentionState.selectedKeys.has(sourceKey);

  return `
    <article class="alert-card ${status.className} ${caseState.status === "closed" ? "is-attention-closed" : ""}">
      <header class="alert-card-header">
        <div class="alert-title-group">
          <label class="attention-select-control" title="選取後可批次指派或結案">
            <input type="checkbox" data-attention-select="${escapeHtml(sourceKey)}" ${selected ? "checked" : ""}>
            <span>選取</span>
          </label>
          <span class="status-pill">${escapeHtml(status.label)}</span>
          <code>${escapeHtml(order.id)}</code>
          <strong>${escapeHtml(order.part)}</strong>
          <span>${escapeHtml(order.customer)}</span>
          ${order.priority === "urgent" ? '<b class="urgent-mark">急</b>' : ""}
        </div>
        <div class="alert-score">
          <span>交期</span>
          <strong>${escapeHtml(due.label)}</strong>
          <small>${escapeHtml(due.date)}</small>
        </div>
      </header>

      <div class="attention-workflow-strip ${escapeHtml(caseState.statusClassName)}">
        <div><span>處理狀態</span><strong>${escapeHtml(caseState.statusLabel)}</strong></div>
        <div><span>負責人</span><strong>${escapeHtml(caseState.assigneeName)}</strong></div>
        <div><span>已等待</span><strong>${escapeHtml(order.lastReport || "尚未回報")}</strong></div>
        ${caseState.resolutionReason ? `<div><span>結案原因</span><strong>${escapeHtml(caseState.resolutionReason)}</strong></div>` : ""}
      </div>

      <div class="alert-meta-grid">
        <div>
          <span>剩餘製程</span>
          <strong>${escapeHtml(remainingProcesses(order))}</strong>
        </div>
        <div>
          <span>最近回報</span>
          <strong>${escapeHtml(order.lastReport)} · ${order.done}/${order.total}</strong>
        </div>
        <div>
          <span>風險原因</span>
          <strong>${escapeHtml(alertReason(order))}</strong>
        </div>
        <div>
          <span>分類</span>
          <strong>${escapeHtml(categories.join(" / "))}</strong>
        </div>
      </div>

      <div class="alert-progress">
        <div class="alert-progress-copy">
          <strong>加工數量 ${order.done}/${order.total}</strong>
          <small>製程階段 · ${escapeHtml(processStageLabel(order))}</small>
        </div>
        <div class="alert-progress-meter">
          <div class="progress-track" aria-label="加工數量 ${order.done}/${order.total}，${percent}%">
            <div class="progress-fill" style="width:${percent}%"></div>
          </div>
          <span>${percent}%</span>
        </div>
      </div>

      <section class="alert-ai-box">
        <strong>AI 建議：</strong>${escapeHtml(riskSuggestion(order))}
      </section>

      <div class="alert-actions">
        <button type="button" data-attention-open="${escapeHtml(attentionAction.action)}" data-attention-key="${escapeHtml(sourceKey)}" ${attentionWritable ? "" : `disabled title="${escapeHtml(machtileAttentionWriteStatusMessage())}"`}>${escapeHtml(attentionWritable ? attentionAction.label : machtileAttentionWriteStatusMessage())}</button>
        <details class="alert-more">
          <summary>更多操作</summary>
          <div>
            <button type="button" data-alert-action="${escapeHtml(primaryAction)}" data-alert-order="${escapeHtml(order.id)}">${escapeHtml(primaryAction)}</button>
            ${secondaryActions.map((action) => `
              <button type="button" data-alert-action="${escapeHtml(action)}" data-alert-order="${escapeHtml(order.id)}">${escapeHtml(action)}</button>
            `).join("")}
            <button type="button" data-detail="${escapeHtml(order.id)}">查看明細</button>
          </div>
        </details>
      </div>
    </article>
  `;
}

function inspectionItems() {
  const mapped = state.workOrders
    .filter((order) => alertCategories(order).has("待品檢") || order.done >= order.total)
    .map((order) => ({
      id: order.id,
      part: order.part,
      drawing: order.drawing,
      customer: order.customer,
      quantity: order.total,
      dueDate: order.dueDate,
      priority: priorityLabel(order.priority),
      status: alertCategories(order).has("今日到期") ? "今日交期" : alertCategories(order).has("待品檢") ? "卡關" : "待檢",
      wait: alertCategories(order).has("待品檢") ? "16h" : "2h",
      real: true,
    }));

  const demos = [
    { id: "WO-20260429-019", part: "滾珠螺桿支座", drawing: "BS-MNT-447", customer: "永承精密", quantity: 25, dueDate: new Date().toISOString().slice(0, 10), priority: "最高", status: "今日交期", wait: "急" },
    { id: "WO-20260427-009", part: "法蘭盤", drawing: "FL-DSK-201", customer: "三達精密", quantity: 30, dueDate: "2026-05-03", priority: "中", status: "已", wait: "2h" },
    { id: "WO-20260428-013", part: "軸承擋圈", drawing: "BR-RING-088", customer: "大同重工", quantity: 120, dueDate: "2026-05-05", priority: "中", status: "已", wait: "1h" },
  ];

  const existingIds = new Set(mapped.map((item) => item.id));
  return [...mapped, ...demos.filter((item) => !existingIds.has(item.id))].slice(0, 4);
}

// 今日品檢打卡板（2026-07-14 owner 鎖定：時間制——早上首件檢＋下午下班前檢）。
// strict 取代示範用「待品檢」佇列；每機台每時段一格，合格/異常（異常必填原因）。
const machtileQcEditSet = new Set();

async function machtileRenderQcBoard() {
  const holder = $("#inspectionQueue");
  if (!holder) return;
  const title = $("#inspectionQueueTitle");
  if (title) title.textContent = "今日品檢";
  try {
    const today = hmcTodayDateIso();
    const punches = await supabaseFetch(`quality_checks?select=check_type,machine_code,result,note,checked_at&check_date=eq.${today}`);
    const punchMap = new Map((Array.isArray(punches) ? punches : []).map((p) => [`${p.check_type}|${p.machine_code}`, p]));
    const machines = state.machines.filter((machine) => !machine.isUnassignedBucket);
    const slot = (type, label, emoji) => `
      <div class="machtile-qc-slot">
        <p class="machtile-qc-slot-title">${emoji} ${escapeHtml(label)}</p>
        ${machines.map((machine) => {
          const punch = machtileQcEditSet.has(`${type}|${machine.name}`) ? null : punchMap.get(`${type}|${machine.name}`);
          const orderInfo = machine.order ? `${escapeHtml(machine.order.id)}・${escapeHtml(machine.part || "")}` : "目前沒有工單";
          if (punch) {
            const time = machtileFormatAuditTime(punch.checked_at).slice(-5);
            return `
              <div class="machtile-qc-row ${punch.result === "fail" ? "is-fail" : "is-pass"}">
                <strong>${escapeHtml(machtileMachineDisplay(machine.name))}</strong>
                <span>${orderInfo}</span>
                <em>${punch.result === "fail" ? `✗ 異常 ${time}｜${escapeHtml(punch.note || "")}` : `✓ 合格 ${time}`}</em>
                <button type="button" data-qc-redo="${escapeHtml(type)}" data-qc-machine="${escapeHtml(machine.name)}">改判</button>
              </div>`;
          }
          return `
            <div class="machtile-qc-row" data-qc-slot="${escapeHtml(type)}" data-qc-machine="${escapeHtml(machine.name)}" data-qc-wo="${escapeHtml(machine.order?.id || "")}" data-qc-part="${escapeHtml(machine.part || "")}">
              <strong>${escapeHtml(machtileMachineDisplay(machine.name))}</strong>
              <span>${orderInfo}</span>
              <span class="machtile-qc-actions">
                <button type="button" class="is-pass" data-qc-punch="pass">合格</button>
                <button type="button" class="is-fail" data-qc-punch="fail">異常</button>
              </span>
              <span class="machtile-qc-note" hidden>
                <input type="text" maxlength="200" placeholder="異常原因（必填）">
                <button type="button" data-qc-punch-confirm="fail">確認異常</button>
              </span>
            </div>`;
        }).join("")}
      </div>
    `;
    holder.innerHTML = slot("first_article", "首件檢查（早上）", "🌅") + slot("afternoon", "下班前檢查", "🕓");
  } catch (error) {
    holder.innerHTML = `<p class="admin-module-note">品檢資料載入失敗：${escapeHtml(String(error?.message || ""))}</p>`;
  }
}

async function machtileQcPunch(row, result, note) {
  const payload = {
    check_type: row.dataset.qcSlot,
    machine_code: row.dataset.qcMachine,
    result,
    note: note || null,
    work_order_no: row.dataset.qcWo || null,
    part_name: row.dataset.qcPart || null,
  };
  await supabaseFetch("rpc/quality_check_record", {
    method: "POST",
    body: JSON.stringify({ p_payload: payload }),
  });
  machtileQcEditSet.delete(`${payload.check_type}|${payload.machine_code}`);
  showToast(`${payload.machine_code} ${result === "pass" ? "品檢合格" : "品檢異常已記錄"}`);
  machtileRenderQcBoard().catch(() => {});
}

function renderInspectionQueue() {
  if (machtileStrictMode() && machtileSessionActive()) {
    machtileRenderQcBoard().catch(() => {});
    return;
  }
  const items = inspectionItems();
  $("#inspectionQueue").innerHTML = items.map((item) => {
    const due = dueInfo({ dueDate: item.dueDate });
    const isUrgent = item.status === "今日交期" || due.diffDays <= 0;
    const riskClass = isUrgent ? "risk-red" : item.status === "卡關" ? "risk-amber" : "risk-gray";
    return `
      <article class="inspection-card ${riskClass}">
        <header>
          <code>${escapeHtml(item.id)}</code>
          <span class="status-pill">${escapeHtml(item.status)} ${escapeHtml(item.wait)}</span>
        </header>
        <h3>${escapeHtml(item.part)}</h3>
        <p>${escapeHtml(item.drawing)} · ${escapeHtml(item.customer)}</p>
        <div class="inspection-info">
          <div><span>數量</span><strong>${Number(item.quantity || 0)}</strong></div>
          <div><span>交期</span><strong>${escapeHtml(due.label)}</strong></div>
          <div><span>優先</span><strong>${escapeHtml(item.priority)}</strong></div>
        </div>
        <div class="inspection-actions">
          ${machtileStrictMode() && machtileSessionActive()
            ? `<button type="button" data-alert-action="查看工單" ${item.real ? `data-alert-order="${escapeHtml(item.id)}"` : ""}>查看工單</button>`
            : `<button type="button" data-alert-action="開始品檢" ${item.real ? `data-alert-order="${escapeHtml(item.id)}"` : ""}>開始品檢</button>
          <button type="button" data-alert-action="品檢通過" ${item.real ? `data-alert-order="${escapeHtml(item.id)}"` : ""}>通過</button>
          <button type="button" data-alert-action="品檢異常" ${item.real ? `data-alert-order="${escapeHtml(item.id)}"` : ""}>異常</button>`}
        </div>
      </article>
    `;
  }).join("");
}

function notificationItems() {
  const riskyOrders = state.workOrders.filter((order) => alertCategories(order).size > 0);
  const items = riskyOrders.map((order) => {
    const status = primaryAlertStatus(order);
    const meta = statusMeta[status] || statusMeta.normal;
    return {
      id: order.id,
      status,
      title: meta.label,
      time: order.lastReport || "剛剛",
      body: status === "stale"
        ? `${order.machine || order.id} 尚未更新回報，目前進度不明。`
        : `${order.id} ${order.part} ${alertReason(order)}。${riskSuggestion(order)}`,
      actions: alertActions(order).slice(0, 3),
    };
  });

  items.push({
    id: "WO-20260427-009",
    status: "normal",
    title: "已處理",
    time: "昨日",
    body: "WO-20260427-009 法蘭盤已通過品檢並出貨。",
    actions: [],
  });

  return items.slice(0, 5);
}

function renderNotificationCenter() {
  const items = notificationItems();
  const unresolvedCount = items.filter((item) => item.status !== "normal").length;
  $("#notificationCount").textContent = unresolvedCount;
  $("#notificationCenter").innerHTML = items.map((item) => {
    const status = statusMeta[item.status] || statusMeta.normal;
    return `
      <article class="notification-row ${status.className}">
        <span class="notification-dot"></span>
        <div class="notification-icon">${item.status === "aiRisk" ? "AI" : item.status === "normal" ? "✓" : "!"}</div>
        <div>
          <div class="notification-head">
            <strong>${escapeHtml(item.title)}</strong>
            <time>${escapeHtml(item.time)}</time>
          </div>
          <p>${escapeHtml(item.body)}</p>
          ${item.actions.length ? `
            <div class="notification-actions">
              ${item.actions.map((action) => `<button type="button" data-alert-action="${escapeHtml(action)}" data-alert-order="${escapeHtml(item.id)}">${escapeHtml(action)}</button>`).join("")}
            </div>
          ` : ""}
        </div>
      </article>
    `;
  }).join("");
}

const historyTabs = ["全部", "生產事件", "系統操作"];
let machtileHistoryRealRows = null;

function historyRows() {
  const reportRows = state.workOrders
    .filter((order) => Number(order.done || 0) > 0)
    .map((order) => ({
      category: "生產事件",
      recordType: "報工",
      tone: "risk-blue",
      orderId: order.id,
      part: order.part,
      machine: order.machine ? machtileMachineDisplay(order.machine) : "未排機",
      title: `${order.machine ? machtileMachineDisplay(order.machine) : "未排機"} 回報 ${order.done}/${order.total}`,
      detail: `${order.id} · ${order.part} · 加工數量 ${order.done}/${order.total}`,
      time: order.lastReport || "未提供",
      eventTime: order.lastReport || "未提供",
      writtenAt: "未提供",
      operator: "未提供",
      modifier: "-",
      beforeAfter: "-",
      reason: "-",
      source: state.source === "mock" ? "MachTile 示範工單摘要" : "MachTile 工單卡讀模型",
    }));
  const abnormalRows = state.workOrders
    .filter((order) => alertCategories(order).has("異常"))
    .map((order) => ({
      category: "生產事件",
      recordType: "異常",
      tone: "risk-red",
      orderId: order.id,
      part: order.part,
      machine: order.machine ? machtileMachineDisplay(order.machine) : "未排機",
      title: alertReason(order),
      detail: `${order.id} · ${order.part} · ${order.machine ? machtileMachineDisplay(order.machine) : "未排機"}`,
      time: order.lastReport || "未提供",
      eventTime: order.lastReport || "未提供",
      writtenAt: "未提供",
      operator: "未提供",
      modifier: "-",
      beforeAfter: "加工中 → 異常",
      reason: alertReason(order),
      source: state.source === "mock" ? "MachTile 示範工單摘要" : "MachTile 工單卡讀模型",
    }));
  const programRows = state.workOrders
    .filter((order) => getProgramProfile(order).programName !== "待上傳")
    .map((order) => {
      const profile = getProgramProfile(order);
      const delta = cycleDelta(profile);
      return {
        category: "生產事件",
        recordType: "加工履歷",
        tone: delta !== null && delta > 8 ? "risk-amber" : "risk-blue",
        orderId: order.id,
        part: order.part,
        machine: order.machine ? machtileMachineDisplay(order.machine) : "未排機",
        title: `${order.drawing} · ${profile.programName}`,
        detail: `${order.part} · 做過 ${Number(profile.historyRuns || 0)} 次 · 純加工 ${formatSeconds(profile.pureCycleSec)} · ${delta === null ? "無基準" : `較基準 ${delta > 0 ? "+" : ""}${delta}%`}`,
        time: profile.lastRunDate || "未提供",
        eventTime: profile.lastRunDate || "未提供",
        writtenAt: "未提供",
        operator: "未提供",
        modifier: "-",
        beforeAfter: "-",
        reason: "-",
        source: "MachTile CNC 加工履歷",
      };
    });
  const scheduleAuditRows = machtileScheduleState.auditEvents.map((event) => ({
    category: "系統操作",
    recordType: "排程工時修正",
    tone: "risk-purple",
    orderId: event.orderId,
    part: event.part,
    machine: event.machine,
    title: `${event.title} · ${event.orderId}`,
    detail: `${event.beforeValue} → ${event.afterValue} · 原因 ${event.reason}`,
    time: machtileFormatAuditTime(event.eventTime),
    eventTime: machtileFormatAuditTime(event.eventTime),
    writtenAt: machtileFormatAuditTime(event.writtenAt),
    operator: "-",
    modifier: event.operator,
    beforeAfter: `${event.beforeValue} → ${event.afterValue}`,
    reason: event.reason,
    source: event.source,
  }));
  const productionRows = Array.isArray(machtileHistoryRealRows)
    ? machtileHistoryRealRows
    : [...reportRows, ...abnormalRows, ...programRows];
  return [...scheduleAuditRows, ...productionRows];
}

function filteredHistoryRows() {
  const query = historySearchQuery.trim().toLocaleLowerCase("zh-TW");
  return historyRows().filter((row) => {
    if (activeHistoryTab !== "全部" && row.category !== activeHistoryTab) return false;
    if (!query) return true;
    return [row.category, row.recordType, row.orderId, row.part, row.machine, row.title, row.detail, row.time, row.operator, row.modifier, row.source, row.reason]
      .some((value) => String(value || "").toLocaleLowerCase("zh-TW").includes(query));
  });
}

function renderHistoryTimeline() {
  const rows = filteredHistoryRows();
  const count = $("#historyResultCount");
  if (count) count.textContent = `${rows.length} 筆`;
  const timeline = $("#historyTimeline");
  if (!timeline) return;
  timeline.innerHTML = rows.length ? rows.map((row) => `
    <button class="history-row ${row.tone}" type="button" data-detail="${escapeHtml(row.orderId)}">
      <span class="timeline-dot"></span>
      <div>
        <span class="history-kind ${row.category === "系統操作" ? "is-system" : ""}">${escapeHtml(row.category)} · ${escapeHtml(row.recordType)}</span>
        <strong>${escapeHtml(row.title)}</strong>
        <small>${escapeHtml(row.detail)}</small>
        <small class="history-event-meta">事件 ${escapeHtml(row.eventTime || row.time || "未提供")} · 寫入 ${escapeHtml(row.writtenAt || "未提供")} · 現場 ${escapeHtml(row.operator || "未提供")} · 修改人 ${escapeHtml(row.modifier || "-")} · 來源 ${escapeHtml(row.source || "未提供")}</small>
      </div>
      <time>${escapeHtml(row.time)}</time>
    </button>
  `).join("") : `<p class="empty-note">${activeHistoryTab === "系統操作" ? "目前沒有系統修改事件；不以生產摘要冒充稽核紀錄。" : "目前篩選條件沒有紀錄。"}</p>`;
}

function renderHistory() {
  $("#historyContent").innerHTML = `
    <section class="history-tools">
      <label class="history-search">
        <span>搜尋紀錄</span>
        <input id="historySearch" type="search" value="${escapeHtml(historySearchQuery)}" placeholder="工單、品號、機台或關鍵字" autocomplete="off">
      </label>
      <p>單一時間線保留生產事件與系統操作兩種類型。舊資料缺事件時間、寫入時間或操作員時會明確顯示「未提供」，不以推測值補齊。</p>
      <div class="history-tabs" role="tablist" aria-label="紀錄類型">
        ${historyTabs.map((tab) => `<button type="button" role="tab" aria-selected="${tab === activeHistoryTab}" class="${tab === activeHistoryTab ? "active" : ""}" data-history-tab="${escapeHtml(tab)}">${escapeHtml(tab)}</button>`).join("")}
      </div>
    </section>
    <section class="history-panel history-timeline-panel">
      <div class="panel-title"><h2>${escapeHtml(activeHistoryTab === "全部" ? "全部紀錄" : activeHistoryTab)}</h2><span id="historyResultCount">0 筆</span></div>
      <div id="historyTimeline"></div>
    </section>
  `;
  $("#historySearch")?.addEventListener("input", (event) => {
    historySearchQuery = event.target.value;
    renderHistoryTimeline();
  });
  renderHistoryTimeline();
  if (machtileStrictMode() && machtileSessionActive()) machtileRenderUnifiedHistoryReal().catch(() => {});
}

let machtileUnifiedHistoryRequest = 0;

function machtileHistoryDataSummary(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return "-";
  const labels = {
    setup_seconds: "架機秒數",
    standard_unit_seconds: "單件秒數",
    handling_seconds: "上下料秒數",
    effective_minutes: "有效分鐘",
    completed_qty: "良品",
    defect_qty: "不良",
    cycle_time_seconds: "單件秒數",
    held: "停等",
    hold_type: "停等類型",
    status: "狀態",
    severity: "嚴重度",
  };
  const text = Object.entries(value).slice(0, 6).map(([key, item]) => {
    const shown = item && typeof item === "object" ? JSON.stringify(item) : String(item ?? "-");
    return `${labels[key] || key} ${shown.length > 80 ? `${shown.slice(0, 77)}…` : shown}`;
  }).join("、");
  return text || "-";
}

function machtileUnifiedEventRow(item, userNames) {
  const order = state.workOrders.find((candidate) => String(candidate.workOrderId) === String(item.work_order_id)
    || String(candidate.processId) === String(item.process_id));
  const machine = state.machineMasters.find((candidate) => String(candidate.id) === String(item.machine_id));
  const typeLabels = {
    workStart: "開工",
    dailyStart: "今日開工",
    noon: "中午盤點",
    afternoonCheck: "下午盤點",
    finish: "完工",
    abnormal: "異常",
    pause: "暫停",
    abnormal_event: "異常事件",
    schedule_input_changed: "標準工時更新",
    schedule_override_set: "主管修正工時",
    schedule_override_clear: "撤銷工時修正",
    schedule_hold_set: "排程停等",
    schedule_hold_release: "解除排程停等",
  };
  const eventType = typeLabels[item.event_type] || item.event_type || "事件";
  const isSystem = item.event_kind === "system_audit";
  const isAbnormal = ["abnormal", "abnormal_event"].includes(item.event_type);
  const beforeValue = machtileHistoryDataSummary(item.before_data);
  const afterValue = machtileHistoryDataSummary(item.after_data);
  const machineName = machine?.code || machine?.name || order?.machine || "未提供";
  const actorName = userNames.get(String(item.actor_user_id)) || "未提供";
  const operatorName = userNames.get(String(item.operator_user_id)) || "未提供";
  return {
    category: isSystem ? "系統操作" : "生產事件",
    recordType: eventType,
    tone: isSystem ? "risk-purple" : isAbnormal ? "risk-red" : item.event_type === "schedule_hold_set" ? "risk-amber" : "risk-blue",
    orderId: order?.id || "-",
    part: order?.part || "-",
    machine: machtileMachineDisplay(machineName),
    title: item.summary || `${eventType}${order?.id ? ` · ${order.id}` : ""}`,
    detail: [order?.part, machineName !== "未提供" ? machtileMachineDisplay(machineName) : "", item.reason].filter(Boolean).join(" · ") || "未提供摘要",
    time: machtileFormatAuditTime(item.event_at),
    eventTime: machtileFormatAuditTime(item.event_at),
    writtenAt: machtileFormatAuditTime(item.written_at),
    operator: operatorName,
    modifier: isSystem ? actorName : (item.actor_user_id && item.actor_user_id !== item.operator_user_id ? actorName : "-"),
    beforeAfter: beforeValue === "-" && afterValue === "-" ? "-" : `${beforeValue} → ${afterValue}`,
    reason: item.reason || "-",
    source: [item.source_system || "未提供", item.source_event_id || ""].filter(Boolean).join(" · "),
  };
}

async function machtileRenderUnifiedHistoryReal() {
  const requestId = ++machtileUnifiedHistoryRequest;
  try {
    const eventKind = activeHistoryTab === "生產事件"
      ? "production_event"
      : activeHistoryTab === "系統操作"
        ? "system_audit"
        : undefined;
    const payload = { limit: 300 };
    if (eventKind) payload.event_kind = eventKind;
    const [result, users] = await Promise.all([
      supabaseFetch("rpc/unified_event_list", {
        method: "POST",
        body: JSON.stringify({ p_payload: payload }),
      }),
      machtileFetchOperatorList(),
    ]);
    if (requestId !== machtileUnifiedHistoryRequest) return;
    const userNames = new Map((Array.isArray(users) ? users : []).map((user) => [String(user.id), user.name || "未提供"]));
    machtileHistoryRealRows = (Array.isArray(result?.items) ? result.items : []).map((item) => machtileUnifiedEventRow(item, userNames));
    renderHistoryTimeline();
  } catch (error) {
    if (requestId !== machtileUnifiedHistoryRequest) return;
    console.warn("unified history RPC failed", error);
    machtileHistoryRealRows = [];
    renderHistoryTimeline();
    showToast(machtileScheduleErrorMessage(error, "紀錄時間線讀取失敗"));
  }
}

// H2 歷史真做（2026-07-14）：strict 模式下報工/異常/加工履歷三面板改吃真資料；
// 工件加工履歷＝每次加工的（機台×程式版本×單件時間），同工件落差 >15% 標紅。
async function machtileRenderHistoryReal() {
  const holder = $("#historyContent");
  if (!holder) return;
  try {
    const [reports, runs, jevByReport] = await Promise.all([
      supabaseFetch("production_reports?select=report_uuid,report_date,report_type,completed_qty,defect_qty,cycle_time_seconds,remark,created_at,machine_id,work_orders(work_order_no,part_name)&order=created_at.desc&limit=20"),
      supabaseFetch("cnc_machining_runs?select=run_date,qty_good,qty_defect,pure_cutting_seconds,machine_id,created_at,work_orders(work_order_no,part_name,part_no),cnc_program_versions(version_no)&order=created_at.desc&limit=500"),
      machtileJevSuggestionsByReport(),
    ]);
    const machineNames = new Map();
    try {
      (await supabaseFetch("machines?select=id,machine_code")).forEach((m) => machineNames.set(String(m.id), m.machine_code));
    } catch (error) { /* 顯示未知機台 */ }
    const machineOf = (id) => machineNames.get(String(id)) || "未知機台";
    // 進料檢驗（I-Reporter 唯讀橋）：同品號的近期檢驗記錄掛進工件履歷卡
    let irRecords = [];
    try {
      irRecords = await machtileInspectionFetch("op=records");
    } catch (error) { /* 橋未部署時安靜略過 */ }
    const typeLabel = { workStart: "開工", dailyStart: "今日開工", noon: "中午盤點", afternoonCheck: "下午盤點", finish: "完工", abnormal: "異常", pause: "暫停", batch: "批次報工" };

    const abnormalRows = (Array.isArray(reports) ? reports : []).filter((row) => row.report_type === "abnormal");

    // 工件履歷：以品名分組 →（機台×版本）分組平均 → 對最佳組標落差
    const byPart = new Map();
    (Array.isArray(runs) ? runs : []).forEach((run) => {
      const part = run.work_orders?.part_name || "未命名工件";
      if (!byPart.has(part)) byPart.set(part, []);
      byPart.get(part).push(run);
    });
    const partSections = [...byPart.entries()].map(([part, list]) => {
      const groups = new Map();
      list.forEach((run) => {
        if (run.pure_cutting_seconds == null) return;
        const key = `${machtileMachineDisplay(machineOf(run.machine_id))}｜${run.cnc_program_versions?.version_no || "無程式版"}`;
        const slot = groups.get(key) || { sum: 0, count: 0, qty: 0, lastDate: "" };
        slot.sum += Number(run.pure_cutting_seconds) || 0;
        slot.count += 1;
        slot.qty += Number(run.qty_good) || 0;
        if (String(run.run_date) > slot.lastDate) slot.lastDate = String(run.run_date);
        groups.set(key, slot);
      });
      if (!groups.size) return "";
      const partNos = new Set(list.map((run) => run.work_orders?.part_no).filter(Boolean));
      const irMatches = (Array.isArray(irRecords) ? irRecords : []).filter((record) => {
        const code = record.inspection_workpieces?.workpiece_code;
        return code && (partNos.has(code) || record.inspection_workpieces?.workpiece_name === part);
      }).slice(0, 3);
      const best = Math.min(...[...groups.values()].map((g) => g.sum / g.count));
      const rows = [...groups.entries()].map(([key, g]) => {
        const avg = g.sum / g.count;
        const delta = best > 0 ? Math.round(((avg - best) / best) * 100) : 0;
        const slow = delta > 15;
        return `<tr class="${slow ? "machtile-history-slow" : ""}"><td>${escapeHtml(key.split("｜")[0])}</td><td>${escapeHtml(key.split("｜")[1])}</td><td>${Math.round(avg)} 秒</td><td>${slow ? `<strong>+${delta}%</strong>` : delta > 0 ? `+${delta}%` : "最佳"}</td><td>${g.count}</td><td>${g.qty}</td><td>${escapeHtml(g.lastDate)}</td></tr>`;
      }).join("");
      return `
        <div class="machtile-part-history">
          <strong>${escapeHtml(part)}</strong>
          <div class="machtile-stats-table-wrap">
            <table class="machtile-stats-table">
              <thead><tr><th>機台</th><th>程式版</th><th>平均單件</th><th>vs 最佳</th><th>次數</th><th>累計良品</th><th>最近加工</th></tr></thead>
              <tbody>${rows}</tbody>
            </table>
          </div>
          ${irMatches.length ? `<p class="machtile-ir-inline">🔬 進料檢驗：${irMatches.map((record) => `<span class="cnc-chip">${escapeHtml(record.lot_number)}・${escapeHtml(machtileIrStatusLabel[record.status] || record.status || "")}</span>`).join(" ")}（明細在管理抽屜 → 進料檢驗）</p>` : ""}
        </div>
      `;
    }).filter(Boolean).join("");

    holder.innerHTML = `
      <section class="history-panel">
        <div class="panel-title"><h2>報工紀錄（真資料）</h2><span>${(reports || []).length} 筆</span></div>
        ${(reports || []).length ? reports.map((row) => `
          <div class="history-row risk-blue">
            <span class="timeline-dot"></span>
            <div>
              <strong>${escapeHtml(machtileMachineDisplay(machineOf(row.machine_id)))} · ${escapeHtml(typeLabel[row.report_type] || row.report_type || "報工")} · ${row.completed_qty}/${row.defect_qty} 件</strong>
              <small>${escapeHtml(row.work_orders?.work_order_no || "-")} · ${escapeHtml(row.work_orders?.part_name || "")}${row.cycle_time_seconds != null ? ` · 單件 ${row.cycle_time_seconds} 秒` : ""}</small>
            </div>
            <time>${escapeHtml(machtileFormatAuditTime(row.created_at))}</time>
          </div>
        `).join("") : '<p class="empty-note">還沒有報工紀錄。</p>'}
      </section>

      <section class="history-panel">
        <div class="panel-title"><h2>異常紀錄（真資料）</h2><span>${abnormalRows.length} 筆</span></div>
        ${abnormalRows.length ? abnormalRows.map((row) => `
          <div class="history-row risk-red">
            <span class="timeline-dot"></span>
            <div>
              <strong>${escapeHtml(machtileMachineDisplay(machineOf(row.machine_id)))} · ${escapeHtml(row.work_orders?.work_order_no || "-")}</strong>
              <small>${escapeHtml(row.remark || "未填異常說明")}</small>
              ${machtileJevChip(jevByReport.get(String(row.report_uuid)))}
            </div>
            <time>${escapeHtml(machtileFormatAuditTime(row.created_at))}</time>
          </div>
        `).join("") : '<p class="empty-note">近期沒有異常報工。</p>'}
      </section>

      <section class="history-panel machtile-part-history-panel">
        <div class="panel-title"><h2>工件加工履歷（真資料）</h2><span>${byPart.size} 個工件</span></div>
        <p class="admin-module-note">同一工件在不同機台或不同程式版本的平均單件時間；比最佳組合慢超過 15% 的標紅。資料來自每筆帶單件時間的報工，自動累積。</p>
        ${partSections || '<p class="empty-note">還沒有加工履歷；現場報工填「單件時間」後會自動累積。</p>'}
      </section>
    `;
  } catch (error) {
    console.warn("history real render failed", error);
  }
}

// ---- 營運分析：稼動率／實際 vs 估算／交期風險（owner 2026-10-02，純邏輯在 analyticsCore.js）----
// 規則：數字只來自真實報工；估算一律標「估算」並寫公式；資料不足就寫原因，不補 0。讀取失敗顯示錯誤，不顯示假資料。
// 讀取（全部 SELECT）：
//   1. production_reports 近 7 天（台灣 00:00 起，created_at 下限，最多 5000 筆）
//   2. machines（id → 機台代碼）
//   3. 這些工序歷次填過的機台加工時間（cycle_time_seconds 不是 null；算「當時的機台加工時間」）
// 卡片已經載入的資料直接用：目前工單、已報（舊 MES＋待回寫）、卡片機台加工時間、每日估算。
const machtileAnalyticsCore = () => (typeof window === "undefined" ? null : window.MachTileAnalyticsCore);
const MACHTILE_ANALYTICS_STALE_MS = 2 * 60 * 1000;
const MACHTILE_ANALYTICS_REPORT_LIMIT = 5000;
const MACHTILE_ANALYTICS_RANGE_KEY = "machtile-analytics-range";
const machtileAnalyticsState = {
  status: "idle",        // idle | loading | ok | error | demo
  error: "",
  cycleError: "",
  loadedAt: 0,
  reports: [],
  cycleRows: [],
  unknownMachine: 0,
  truncated: false,
  promise: null,
  range: (() => { try { return localStorage.getItem(MACHTILE_ANALYTICS_RANGE_KEY) === "7d" ? "7d" : "today"; } catch { return "today"; } })(),
  legacyOpen: false,
};

function machtileReportsViewActive() {
  return Boolean(document.getElementById("reportsView")?.classList.contains("is-active"));
}

function machtileAnalyticsRerender() {
  const holder = document.getElementById("machtileAnalytics");
  if (holder) holder.innerHTML = machtileAnalyticsHtml();
}

async function machtileLoadAnalytics(force = false) {
  const core = machtileAnalyticsCore();
  const st = machtileAnalyticsState;
  if (!core) return;
  if (state.source !== "supabase") {
    st.status = "demo";
    machtileAnalyticsRerender();
    return;
  }
  if (!force && st.status === "ok" && Date.now() - st.loadedAt < MACHTILE_ANALYTICS_STALE_MS) return;
  if (st.promise) return st.promise;
  if (st.status !== "ok") { st.status = "loading"; machtileAnalyticsRerender(); }
  st.promise = (async () => {
    try {
      const nowMs = Date.now();
      const since = core.windowStartIso(nowMs);
      const [reports, machines] = await Promise.all([
        supabaseFetch(`production_reports?select=id,process_id,machine_id,report_type,started_at,ended_at,completed_qty,defect_qty,cycle_time_seconds,created_at,overtime_plan:report_payload->>overtime_plan,work_order_processes(machine_id)&created_at=gte.${encodeURIComponent(since)}&order=created_at.asc&limit=${MACHTILE_ANALYTICS_REPORT_LIMIT}`),
        supabaseFetch("machines?select=id,machine_code").catch((error) => { console.warn("analytics: machines lookup failed", error); return []; }),
      ]);
      if (!Array.isArray(reports)) throw new Error("報工資料格式不對");
      const codeByMachineId = new Map();
      (state.machineMasters || []).forEach((m) => { if (m.id && m.code) codeByMachineId.set(String(m.id), m.code); });
      (Array.isArray(machines) ? machines : []).forEach((m) => { if (m?.id && m.machine_code) codeByMachineId.set(String(m.id), m.machine_code); });
      const codeByProcessId = new Map();
      machtileCardOrders().forEach((o) => { if (o?.processId && o.machine) codeByProcessId.set(String(o.processId), o.machine); });
      const attached = core.attachMachineCodes(reports, { codeByMachineId, codeByProcessId });
      // 當時的機台加工時間：報工裡的工序＋畫面上的工序，歷次填過的值
      const pids = [...new Set([...reports.map((r) => String(r?.process_id || "")), ...machtileCardOrders().map((o) => String(o?.processId || ""))].filter(isUuid))];
      const cycleRows = [];
      let cycleError = "";
      for (let i = 0; i < pids.length; i += 80) {
        const chunk = pids.slice(i, i + 80).map(encodeURIComponent).join(",");
        try {
          const got = await supabaseFetch(`production_reports?select=process_id,cycle_time_seconds,created_at&process_id=in.(${chunk})&cycle_time_seconds=not.is.null&order=created_at.desc&limit=1000`);
          if (Array.isArray(got)) cycleRows.push(...got);
        } catch (error) {
          cycleError = String(error?.message || error || "");
        }
      }
      st.reports = attached.rows;
      st.unknownMachine = attached.unknown;
      st.truncated = reports.length >= MACHTILE_ANALYTICS_REPORT_LIMIT;
      st.cycleRows = cycleRows;
      st.cycleError = cycleError;
      st.error = "";
      st.status = "ok";
      st.loadedAt = Date.now();
    } catch (error) {
      console.warn("analytics load failed", error);
      st.status = "error";
      st.error = String(error?.message || error || "未知錯誤");
      st.reports = [];
      st.cycleRows = [];
    } finally {
      st.promise = null;
      machtileAnalyticsRerender();
    }
  })();
  return st.promise;
}

function machtileBindAnalyticsEvents() {
  const holder = document.getElementById("reportsContent");
  if (!holder || holder.dataset.analyticsBound === "1") return;
  holder.dataset.analyticsBound = "1";
  holder.addEventListener("click", (event) => {
    const rangeButton = event.target.closest("[data-analytics-range]");
    if (rangeButton) {
      machtileAnalyticsState.range = rangeButton.dataset.analyticsRange === "7d" ? "7d" : "today";
      try { localStorage.setItem(MACHTILE_ANALYTICS_RANGE_KEY, machtileAnalyticsState.range); } catch { /* 只是記住選項 */ }
      machtileAnalyticsRerender();
      return;
    }
    if (event.target.closest("[data-analytics-retry]")) machtileLoadAnalytics(true).catch(() => {});
  });
}

function machtileAnalyticsMachines() {
  return managedMachineList().map((machine) => ({ machine, code: String(machine.code || machine.name || "").trim().toUpperCase(), label: machtileMachineDisplay(machine.name) }));
}

function machtileAnalyticsOrderEstimate(order) {
  if (!order) return { estimate: null, reason: "沒有目前工單" };
  const profile = getProgramProfile(order);
  if (!(Number(profile?.pureCycleSec) > 0)) return { estimate: null, reason: "未填機台加工時間" };
  const qty = dailyPureCapacity(profile);
  return qty ? { estimate: qty, reason: "" } : { estimate: null, reason: "估算缺值" };
}

function machtileAnalyticsMd(date) {
  const [, m, d] = String(date || "").split("-");
  return m && d ? `${m}/${d}` : "-";
}

function machtileAnalyticsSigned(n) {
  const v = Math.round(Number(n) || 0);
  return v > 0 ? `+${v}` : v < 0 ? `−${Math.abs(v)}` : "0";
}

function machtileAnalyticsHtml() {
  const core = machtileAnalyticsCore();
  const st = machtileAnalyticsState;
  if (!core) return '<p class="admin-module-note">分析元件沒有載入，請重新整理頁面。</p>';
  const range = st.range === "7d" ? "7d" : "today";
  const nowMs = Date.now();
  const rangeLabel = range === "7d" ? `近 7 天（${machtileAnalyticsMd(core.windowDates(nowMs)[0])}–${machtileAnalyticsMd(core.taipeiDate(nowMs))}）` : `今天 ${machtileAnalyticsMd(core.taipeiDate(nowMs))}`;
  const toggle = `
    <div class="analytics-toolbar">
      <div class="analytics-range" role="group" aria-label="期間">
        <button type="button" data-analytics-range="today" aria-pressed="${range === "today"}">今天</button>
        <button type="button" data-analytics-range="7d" aria-pressed="${range === "7d"}">近 7 天</button>
      </div>
      <small class="analytics-asof">${st.status === "ok" ? `資料讀取於 ${escapeHtml(core.hhmm(st.loadedAt))}（台灣時間）` : ""}</small>
    </div>`;
  if (st.status === "demo") {
    return `${toggle}<section class="report-panel analytics-panel"><p class="analytics-reason" data-analytics-state="demo">示範資料模式沒有真實報工，分析不顯示（不拿示範資料冒充實績）。</p></section>`;
  }
  if (st.status === "error") {
    return `${toggle}<section class="report-panel analytics-panel analytics-error" data-analytics-state="error" role="alert">
      <div class="panel-title"><h2>營運分析</h2><span>讀取失敗</span></div>
      <p>真資料讀取失敗，以下三個分析都不顯示（不顯示假資料）：${escapeHtml(st.error)}</p>
      <button type="button" class="secondary-button" data-analytics-retry>重新讀取</button>
    </section>`;
  }
  if (st.status !== "ok") {
    return `${toggle}<section class="report-panel analytics-panel" data-analytics-state="loading"><p class="admin-module-note">正在讀取報工資料（近 7 天）…</p></section>`;
  }
  const machines = machtileAnalyticsMachines();
  const warnings = [];
  if (st.truncated) warnings.push(`近 7 天報工超過 ${MACHTILE_ANALYTICS_REPORT_LIMIT} 筆，只讀到前 ${MACHTILE_ANALYTICS_REPORT_LIMIT} 筆，數字可能偏低。`);
  if (st.unknownMachine) warnings.push(`${st.unknownMachine} 筆報工對不到機台，沒有算進去。`);
  const warnHtml = warnings.length ? `<p class="analytics-warning">${warnings.map(escapeHtml).join("<br>")}</p>` : "";
  return `${toggle}${warnHtml}
    ${machtileAnalyticsUtilHtml(core, machines, range, rangeLabel, nowMs)}
    ${machtileAnalyticsOutputHtml(core, machines, range, rangeLabel, nowMs)}
    ${machtileAnalyticsRiskHtml(core, nowMs)}`;
}

function machtileAnalyticsUtilHtml(core, machines, range, rangeLabel, nowMs) {
  const st = machtileAnalyticsState;
  const title = `<div class="panel-title"><h2>機台稼動率</h2><span>${escapeHtml(rangeLabel)}・由低到高</span></div>`;
  if (st.cycleError) {
    return `<section class="report-panel analytics-panel analytics-error" data-analytics-section="utilization" role="alert">${title}<p>機台加工時間讀取失敗，稼動率不顯示：${escapeHtml(st.cycleError)}</p></section>`;
  }
  const cardSecondsByProcess = new Map();
  machtileCardOrders().forEach((o) => { if (o?.processId && Number(o.pureCycleSec) > 0) cardSecondsByProcess.set(String(o.processId), Number(o.pureCycleSec)); });
  const result = core.machineUtilization({ machines: machines.map((m) => ({ code: m.code, label: m.label })), reports: st.reports, cycleRows: st.cycleRows, cardSecondsByProcess, nowMs, range });
  const rows = result.rows.map((r) => {
    const has = r.utilization !== null;
    const pct = has ? Math.round(r.utilization * 100) : null;
    const width = has ? Math.max(0, Math.min(100, pct)) : 0;
    const tone = !has ? "is-na" : r.lowest ? "is-lowest" : "";
    const detail = has
      ? `純加工 ${escapeHtml(core.formatHours(r.pureSec))}／在班 ${escapeHtml(core.formatHours(r.shiftSec))}${range === "7d" ? `（${r.days} 天）` : ""}・報工覆蓋 ${escapeHtml(core.formatPercent(r.coverage))}`
      : r.coverage !== null && r.shiftSec > 0 ? `在班 ${escapeHtml(core.formatHours(r.shiftSec))}・報工覆蓋 ${escapeHtml(core.formatPercent(r.coverage))}` : "";
    const notes = [r.status === "partial" ? r.reason : "", ...r.notes].filter(Boolean);
    return `
      <div class="analytics-util-row ${tone}" data-util-machine="${escapeHtml(r.code)}" data-util-status="${escapeHtml(r.status)}">
        <div class="analytics-row-head">
          <strong>${escapeHtml(r.label)}</strong>
          ${r.lowest ? '<span class="analytics-badge is-low">最低</span>' : ""}
          <b class="analytics-value" data-util-value>${has ? `${r.status === "partial" ? "≥" : ""}${pct}%` : "—"}</b>
        </div>
        ${has ? `<div class="analytics-bar" aria-hidden="true"><i style="width:${width}%"></i></div>` : `<p class="analytics-reason" data-util-reason>${escapeHtml(r.reason)}</p>`}
        ${detail ? `<small class="analytics-detail">${detail}</small>` : ""}
        ${notes.length ? `<small class="analytics-note">${notes.map(escapeHtml).join("；")}</small>` : ""}
      </div>`;
  }).join("");
  return `
    <section class="report-panel analytics-panel" data-analytics-section="utilization">
      ${title}
      ${result.valuedCount ? "" : `<p class="analytics-empty" data-analytics-empty>資料不足：${range === "7d" ? "近 7 天" : "今天"}沒有任何一台同時有開工、數量報工和機台加工時間，算不出稼動率。</p>`}
      <div class="analytics-rows">${rows}</div>
      <details class="analytics-formula">
        <summary>公式與口徑</summary>
        <p>稼動率 ＝ 純加工時間 ÷ 在班時間。</p>
        <p>純加工時間 ＝ Σ（報工良品＋不良）× 當時的機台加工時間（這道工序在那筆報工以前最新一次填的值；沒有就用卡片上最新的值，並註明）。</p>
        <p>在班時間 ＝ 當天第一筆「今日開工」到最後一筆「收工」。還沒收工：今天算到現在，但不超過下班時間（17:00；當天報工選了加班 17:30／20:30 就算到那時）；以前的日子沒收工算到下班時間。近 7 天＝有開工的天加總。</p>
        <p>報工覆蓋 ＝ 有報工的時段（每筆報工 開始～結束 的聯集）÷ 在班時間。覆蓋低＝中間有一段時間沒有報工，稼動率可能偏低。</p>
        <p>沒開工、沒數量、沒填機台加工時間的機台不給數字，寫出原因。「≥」＝有部分數量沒有機台加工時間、沒算進去。</p>
      </details>
    </section>`;
}

function machtileAnalyticsOutputHtml(core, machines, range, rangeLabel, nowMs) {
  const st = machtileAnalyticsState;
  const input = machines.map((m) => {
    const est = machtileAnalyticsOrderEstimate(m.machine.order);
    return { code: m.code, label: m.label, estimate: est.estimate, estimateReason: est.reason };
  });
  const result = core.dailyOutput({ machines: input, reports: st.reports, nowMs, range });
  const anyActual = result.rows.some((r) => r.actual !== null);
  const rows = result.rows.map((r) => {
    const behind = r.diff !== null && r.diff < 0;
    const cell = (label, value, cls = "") => `<div class="${cls}"><dt>${label}</dt><dd>${value}</dd></div>`;
    return `
      <div class="analytics-out-row ${r.status !== "ok" ? "is-na" : behind ? "is-behind" : "is-ahead"}" data-out-machine="${escapeHtml(r.code)}" data-out-status="${escapeHtml(r.status)}">
        <div class="analytics-row-head">
          <strong>${escapeHtml(r.label)}</strong>
          ${r.status === "noEstimate" ? '<span class="analytics-badge is-warn">估算缺值</span>' : ""}
          ${r.status === "ok" ? `<b class="analytics-value" data-out-rate>${escapeHtml(core.formatPercent(r.rate))}</b>` : ""}
        </div>
        ${r.status === "notOpened" ? `<p class="analytics-reason" data-out-reason>${escapeHtml(r.reason)}</p><small class="analytics-detail">實際良品 —・估算 ${r.estimatePerDay ? `${r.estimatePerDay} 件／天` : `缺值（${escapeHtml(r.estimateReason)}）`}</small>` : `<dl class="analytics-out-grid">
          ${cell("實際良品", r.actual === null ? "—" : `${r.actual} 件`)}
          ${cell("估算", r.estimate !== null ? `${Math.round(r.estimate)} 件` : r.estimatePerDay ? `${r.estimatePerDay} 件／天` : "缺值", r.estimate === null && !r.estimatePerDay ? "is-missing" : "")}
          ${cell("差額", r.diff === null ? "—" : `${machtileAnalyticsSigned(r.diff)} 件`, behind ? "is-bad" : "")}
          ${cell("達成率", r.rate === null ? "—" : escapeHtml(core.formatPercent(r.rate)))}
        </dl>`}
        ${r.status === "noEstimate" ? `<p class="analytics-reason" data-out-reason>${escapeHtml(r.status === "noEstimate" ? `估算缺值：${r.reason}` : r.reason)}</p>` : ""}
        ${r.status === "ok" && range === "7d" ? `<small class="analytics-detail">開工 ${r.openedDays} 天 × 每日估算 ${r.estimatePerDay} 件</small>` : ""}
      </div>`;
  }).join("");
  const totals = range === "7d" ? `
      <div class="analytics-day-totals" data-out-totals>
        <strong>每天 App 報工良品合計</strong>
        <ul>${result.dailyTotals.map((t) => `<li><span>${machtileAnalyticsMd(t.date)}</span><b>${t.good + t.bad > 0 ? `${t.good} 件` : "無報工"}</b></li>`).join("")}</ul>
      </div>` : "";
  return `
    <section class="report-panel analytics-panel" data-analytics-section="output">
      <div class="panel-title"><h2>產量：實際 vs 估算</h2><span>${escapeHtml(rangeLabel)}・落後最多的在前</span></div>
      ${anyActual ? "" : `<p class="analytics-empty" data-analytics-empty>資料不足：${range === "7d" ? "近 7 天" : "今天"}沒有任何一台在 App 報工，沒有實際產量可以比較。</p>`}
      ${totals}
      <div class="analytics-rows">${rows}</div>
      <details class="analytics-formula">
        <summary>公式與口徑</summary>
        <p>實際 ＝ 這段期間 App 報工的良品合計（不良另計，不算進實際）。只算 App 報工；舊 MES 沒有逐日紀錄（只有累計），所以不列，累計請看卡片上「含舊 MES」的完成數。</p>
        <p><strong>估算</strong> ＝ 卡片上的每日估算 ＝ 430 分 ÷（機台加工時間＋上下料時間），照這台目前的工單算；近 7 天 ＝ 每日估算 × 有開工的天數。</p>
        <p>差額 ＝ 實際 − 估算；達成率 ＝ 實際 ÷ 估算。今天還沒收工時，達成率會隨時間往上走。</p>
      </details>
    </section>`;
}

function machtileAnalyticsRiskHtml(core, nowMs) {
  const st = machtileAnalyticsState;
  const seen = new Set();
  const orders = machtileCardOrders().filter((o) => {
    if (!o || !o.processId || o.offStation === true || !isReportableMachineName(o.machine)) return false;
    if (["completed", "cancelled"].includes(String(o.processStatus || ""))) return false;
    if (["completed", "shipped", "cancelled"].includes(String(o.workStatus || "").toLowerCase())) return false;
    if (seen.has(String(o.processId))) return false;
    seen.add(String(o.processId));
    return true;
  }).map((o) => ({
    processId: o.processId, workOrderNo: o.id, machine: o.machine, part: o.part, process: o.process,
    total: Number(o.total || 0), done: Number(o.done || 0), doneLabel: o.progressSource?.label || "", dueDate: o.dueDate,
    estimateDaily: machtileAnalyticsOrderEstimate(o).estimate,
  }));
  const result = core.dueRisk({ orders, reports: st.reports, nowMs });
  const levelClass = { overdue: "is-overdue", late: "is-late", tight: "is-tight" };
  const rows = result.risks.map((r) => `
      <div class="analytics-risk-row ${levelClass[r.level]}" data-risk-wo="${escapeHtml(r.workOrderNo)}" data-risk-level="${r.level}">
        <div class="analytics-row-head">
          <span class="analytics-risk-badge">${escapeHtml(core.riskLabel(r))}</span>
          <strong>${escapeHtml(r.workOrderNo)}</strong>
          <span class="analytics-risk-machine">${escapeHtml(machtileMachineDisplay(r.machine))}</span>
        </div>
        <small class="analytics-detail">${escapeHtml(r.part || "")}${r.process ? `・${escapeHtml(r.process)}` : ""}</small>
        <dl class="analytics-risk-grid">
          <div><dt>剩餘</dt><dd>${r.remaining} 件<small>已報 ${r.done}/${r.total}${r.doneLabel ? `・${escapeHtml(r.doneLabel)}` : ""}</small></dd></div>
          <div><dt>每日速度</dt><dd data-risk-basis="${escapeHtml(r.basis || "none")}">${r.speed ? `${Math.round(r.speed * 10) / 10} 件／天<small>${r.basis === "actual" ? "實際" : "估算"}：${escapeHtml(r.speedNote)}</small>` : "—<small>沒有速度資料</small>"}</dd></div>
          <div><dt>預計完成</dt><dd>${r.projected ? `${machtileAnalyticsMd(r.projected)}<small>${r.basis === "estimate" ? "估算・" : ""}還要 ${r.daysNeeded} 個工作天</small>` : "—"}</dd></div>
          <div><dt>交期</dt><dd>${machtileAnalyticsMd(r.dueDate)}</dd></div>
        </dl>
      </div>`).join("");
  const insufficient = result.insufficient.length ? `
      <details class="analytics-insufficient" data-risk-insufficient="${result.insufficient.length}">
        <summary>資料不足、無法判斷：${result.insufficient.length} 張</summary>
        <ul>${result.insufficient.map((r) => `<li><strong>${escapeHtml(r.workOrderNo)}</strong> ${escapeHtml(machtileMachineDisplay(r.machine))}・${escapeHtml(r.reason)}</li>`).join("")}</ul>
      </details>` : "";
  const count = (level) => result.risks.filter((r) => r.level === level).length;
  return `
    <section class="report-panel analytics-panel" data-analytics-section="risk">
      <div class="panel-title"><h2>交期風險</h2><span>在站未完工 ${orders.length} 張・只列有風險的</span></div>
      <p class="analytics-summary" data-risk-summary>有風險 ${result.risks.length} 張（逾期 ${count("overdue")}、會延誤 ${count("late")}、緊 ${count("tight")}）；OK ${result.okCount} 張；已報滿／超量 ${result.excludedOver} 張不列；資料不足 ${result.insufficient.length} 張。</p>
      ${rows ? `<div class="analytics-rows">${rows}</div>` : '<p class="analytics-empty">目前沒有判斷得出來的風險工單。</p>'}
      ${insufficient}
      <details class="analytics-formula">
        <summary>公式與口徑</summary>
        <p>剩餘 ＝ 訂單數量 − 已報（跟卡片同一個口徑：有舊 MES 資料＝舊 MES 已報＋待回寫；沒有＝App 累計）。剩餘 ≤ 0（已報滿或超量）不列。</p>
        <p>每日速度：優先用<strong>實際</strong>＝近 7 天這道工序 App 報工良品 ÷ 有報工的天數；沒有實際就用<strong>估算</strong>＝卡片每日估算（430 分 ÷（機台加工時間＋上下料））。</p>
        <p>預計完成日 ＝ 從今天起（含今天）第「剩餘 ÷ 每日速度（無條件進位）」個工作天；工作天＝週一到週五，週六、週日不算。</p>
        <p>已逾期＝交期已過還沒做完；會延誤 N 天＝預計完成日比交期晚 N 天；緊＝預計完成日離交期只剩 ${core.TIGHT_DAYS} 天以內。</p>
      </details>
    </section>`;
}

function renderReports() {
  const activeOrders = state.workOrders.filter((order) => !["completed", "shipped", "cancelled"].includes(String(order.workStatus || "").toLowerCase()));
  const total = activeOrders.length || 1;
  const overdue = activeOrders.filter((order) => alertCategories(order).has("已延誤")).length;
  const abnormal = activeOrders.filter((order) => alertCategories(order).has("異常")).length;
  const completedQty = state.workOrders.reduce((sum, order) => sum + Number(order.done || 0), 0);
  const totalQty = state.workOrders.reduce((sum, order) => sum + Number(order.total || 0), 0) || 1;
  const managedMachines = managedMachineList();
  const assignedMachineCount = managedMachines.filter((machine) => machine.order).length;
  const assignedMachineRate = Math.round((assignedMachineCount / Math.max(1, managedMachines.length)) * 100);
  const currentNotOverdueRate = Math.max(0, Math.round(((total - overdue) / total) * 100));
  const abnormalOrderRate = Math.round((abnormal / total) * 1000) / 10;
  const programOrders = state.workOrders.filter((order) => getProgramProfile(order).programName !== "待上傳");
  const deltas = programOrders.map((order) => cycleDelta(getProgramProfile(order))).filter((value) => value !== null);
  const avgDelta = deltas.length ? Math.round(deltas.reduce((sum, value) => sum + value, 0) / deltas.length) : 0;
  const historyRuns = programOrders.reduce((sum, order) => sum + Number(getProgramProfile(order).historyRuns || 0), 0);

  const reportCards = [
    { title: "在製未逾期占比", value: `${currentNotOverdueRate}%`, meta: `目前未結工單；非準交率`, status: currentNotOverdueRate >= 90 ? "risk-green" : "risk-amber" },
    { title: "在製逾期工單", value: overdue, meta: "目前未結且已逾期", status: overdue ? "risk-red" : "risk-green" },
    { title: "已排工機台占比", value: `${assignedMachineRate}%`, meta: `${assignedMachineCount}/${managedMachines.length} 台有目前工單；非稼動率`, status: "risk-blue" },
    { title: "異常工單占比", value: `${abnormalOrderRate}%`, meta: `${abnormal}/${total} 張；非正式不良率`, status: abnormal ? "risk-amber" : "risk-green" },
    { title: "加工時間偏差", value: `${avgDelta > 0 ? "+" : ""}${avgDelta}%`, meta: "與標準純加工時間比", status: avgDelta > 8 ? "risk-amber" : "risk-green" },
    { title: "歷史加工次數", value: historyRuns, meta: `${programOrders.length} 個工件已有程式履歷`, status: "risk-purple" },
  ];

  // owner 2026-10-02：上方換成三個有意義的分析（稼動率、實際 vs 估算、交期風險，見 analyticsCore.js）；
  // 原本的內容一字不改收進下方摺疊（打開才載入營運追蹤／加工時間統計，不打開不查）。
  const realSession = machtileStrictMode() && machtileSessionActive();
  const legacyOpen = machtileAnalyticsState.legacyOpen === true;
  $("#reportsContent").innerHTML = `
    <div id="machtileAnalytics" class="analytics-root">${machtileAnalyticsHtml()}</div>

    <details id="reportsLegacy" class="analytics-legacy"${legacyOpen ? " open" : ""}>
      <summary>原本的分析內容（營運追蹤、工單進度、加工時間統計…）</summary>
      <div class="analytics-legacy-body">
    ${realSession ? '<div id="machtileOperationalTracking"><p class="admin-module-note">正在載入營運追蹤（真資料）...</p></div>' : ""}

    <div class="report-card-grid">
      ${reportCards.map((card) => `
        <article class="report-card ${card.status}">
          <span>${escapeHtml(card.title)}</span>
          <strong>${escapeHtml(card.value)}</strong>
          <small>${escapeHtml(card.meta)}</small>
        </article>
      `).join("")}
    </div>

    <section class="report-panel">
      <div class="panel-title">
        <h2>各機台目前工單進度</h2>
        <span>長條＝完成數／總數；逾期最多的排最上面；非產能／稼動率</span>
      </div>
      <div class="load-list load-list-progress">
        ${(() => {
          // owner 2026-09-20: the old "has a current order" bar was binary and read as 11
          // identical lines. Show what differs between machines instead — how far the
          // current order is and how late it runs — from the same loaded state.
          const rows = managedMachines.map((machine) => {
            const order = machine.order;
            const total = Number(order?.total || 0);
            const done = Number(order?.done || 0);
            const pct = order && total > 0 ? Math.max(0, Math.min(100, Math.round((done / total) * 100))) : 0;
            const due = order ? dueInfo(order) : null;
            return { machine, order, total, done, pct, due };
          });
          rows.sort((a, b) => {
            if (!a.order !== !b.order) return a.order ? -1 : 1; // idle machines last
            return (a.due?.diffDays ?? 999) - (b.due?.diffDays ?? 999) || a.pct - b.pct;
          });
          return rows.map(({ machine, order, total, done, pct, due }) => {
            const tone = !order ? "is-idle" : due.diffDays < 0 ? "is-late" : due.diffDays <= 3 ? "is-soon" : "";
            return `
              <div class="load-row ${tone}">
                <span>${escapeHtml(machtileMachineDisplay(machine.name))}</span>
                <div class="load-track" aria-label="${order ? `${done}/${total} 件` : "無工單"}"><i style="width:${pct}%"></i></div>
                <strong>${order ? `${done}/${total}` : "無工單"}</strong>
                <small>${order ? `${escapeHtml(due.label)} · ${escapeHtml(due.date)}` : "—"}</small>
              </div>
            `;
          }).join("");
        })()}
      </div>
    </section>

    <section class="report-panel">
      <div class="panel-title">
        <h2>目前資料摘要</h2>
        <span>${completedQty}/${totalQty} 件</span>
      </div>
      <p class="report-copy">本頁目前是即時在製快照，不是「本週」統計。準交率需以實際交貨日對承諾交期計算；不良率需使用正式良品／不良品數；稼動率與產能負載需先確認班表、停機與標準工時。</p>
    </section>

    <section class="report-panel">
      <div class="panel-title">
        <h2>加工時間履歷</h2>
        <span>不含上下料</span>
      </div>
      <div class="program-history-table">
        ${programOrders.map((order) => {
          const profile = getProgramProfile(order);
          const delta = cycleDelta(profile);
          return `
            <button type="button" data-detail="${escapeHtml(order.id)}">
              <span>${escapeHtml(order.drawing)}</span>
              <strong>${escapeHtml(formatSeconds(profile.pureCycleSec))}</strong>
              <small>${delta === null ? "無基準" : `${delta > 0 ? "+" : ""}${delta}%`} · ${profile.historyRuns} 次</small>
            </button>
          `;
        }).join("")}
      </div>
    </section>

    ${realSession ? '<div id="machtileTimeStats"><p class="admin-module-note">正在載入加工時間統計（真資料）...</p></div>' : ""}
      </div>
    </details>
  `;
  machtileBindAnalyticsEvents();
  const legacy = document.getElementById("reportsLegacy");
  legacy?.addEventListener("toggle", () => {
    machtileAnalyticsState.legacyOpen = legacy.open;
    if (legacy.open) machtileLoadReportsLegacy();
  });
  if (legacyOpen) machtileLoadReportsLegacy();
  // 分析頁正開著才重讀（資料超過 2 分鐘）；沒開著不查
  if (machtileReportsViewActive()) machtileLoadAnalytics().catch(() => {});
}

function machtileLoadReportsLegacy() {
  if (!(machtileStrictMode() && machtileSessionActive())) return;
  machtileRenderOperationalTracking(30).catch(() => {});
  machtileRenderTimeStats().catch(() => {});
}

function machtileTrackingPercent(value, signed = false) {
  if (!Number.isFinite(value)) return "—";
  return `${signed && value > 0 ? "+" : ""}${Number(value).toFixed(1)}%`;
}

function machtileTrackingDelay(minutes) {
  const value = Math.max(0, Number(minutes) || 0);
  const days = Math.floor(value / 1440);
  const hours = Math.floor((value % 1440) / 60);
  const remaining = Math.floor(value % 60);
  if (days) return `${days} 天 ${hours} 小時`;
  if (hours) return `${hours} 小時 ${remaining} 分`;
  return `${remaining} 分`;
}

async function machtileRenderOperationalTracking(days = 30) {
  const holder = document.getElementById("machtileOperationalTracking");
  const core = globalThis.MachTileOperationalTrackingCore;
  if (!holder || !core) return;
  const safeDays = [7, 30, 90].includes(Number(days)) ? Number(days) : 30;
  holder.innerHTML = '<p class="admin-module-note">正在載入營運追蹤（真資料）...</p>';
  const from = new Date(Date.now() - (safeDays - 1) * 86400000);
  from.setHours(0, 0, 0, 0);
  const fromDate = from.toISOString().slice(0, 10);
  const nowIso = new Date().toISOString();

  try {
    const [runs, calibrationSnapshot, reservations, replans, quoteSnapshot] = await Promise.all([
      supabaseFetch(`cnc_machining_runs?select=id,run_date,pure_cutting_seconds,machine_id,program_id,program_version_id,created_at,work_orders(part_name),cnc_program_versions(version_no,estimated_seconds),machines(machine_code)&run_date=gte.${fromDate}&order=run_date.desc&limit=2000`),
      supabaseFetch("rpc/cnc_calibration_snapshot", { method: "POST", body: JSON.stringify({ p_payload: {} }) }),
      supabaseFetch(`schedule_reservations?select=process_id,machine_id,resource_kind,starts_at,ends_at,is_active,machines(machine_code)&is_active=eq.true&resource_kind=eq.machine_spindle&ends_at=lt.${encodeURIComponent(nowIso)}&order=ends_at.asc&limit=2000`),
      supabaseFetch(`schedule_replan_requests?select=machine_code,trigger_type,reason,status,requested_at&requested_at=gte.${encodeURIComponent(from.toISOString())}&order=requested_at.desc&limit=2000`),
      config.enableManufacturingQuoteTracking === true ? machtileFormalQuoteRpc("manufacturing_quote_tracking_snapshot", {}) : Promise.resolve({ versions: [], links: [], finals: [] }),
    ]);
    const processIds = [...new Set((reservations || []).map((row) => String(row.process_id || "")).filter(machtileValidProcessId))];
    const processChunks = machtileScheduleChunks(processIds, 200);
    const [processGroups, holdGroups] = processChunks.length ? await Promise.all([
      Promise.all(processChunks.map((chunk) => supabaseFetch(`work_order_processes?select=id,status,process_name,work_order_id,work_orders(work_order_no,part_name)&id=in.(${chunk.join(",")})`))),
      Promise.all(processChunks.map((chunk) => supabaseFetch(`process_schedule_holds?select=process_id,hold_type,reason,held_at,released_at&released_at=is.null&process_id=in.(${chunk.join(",")})&order=held_at.desc`))),
    ]) : [[], []];
    const processes = processGroups.flat();
    const holds = holdGroups.flat();
    const excludedIds = (calibrationSnapshot?.sample_decisions || [])
      .filter((decision) => decision.excluded)
      .map((decision) => decision.machining_run_id);
    const accuracy = core.summarizeEstimateAccuracy(runs, { from: from.toISOString(), excludedIds });
    const schedule = core.summarizeScheduleDelay({ reservations, processes, holds, replans, from: from.toISOString(), now: nowIso });
    const quoteLinks = new Map((quoteSnapshot?.links || []).map((link) => [String(link.work_order_id), link]));
    const quoteVariance = core.summarizeQuoteVariance((quoteSnapshot?.finals || []).map((item) => ({ ...item, ...(quoteLinks.get(String(item.work_order_id)) || {}) })));
    const accuracyTone = accuracy.averageAbsolutePct == null ? "risk-blue" : accuracy.averageAbsolutePct <= 20 ? "risk-green" : accuracy.averageAbsolutePct <= 30 ? "risk-amber" : "risk-red";
    const direction = accuracy.averageSignedPct == null
      ? "尚無可比樣本"
      : accuracy.averageSignedPct > 0
        ? `實際平均比預估多 ${machtileTrackingPercent(accuracy.averageSignedPct)}`
        : accuracy.averageSignedPct < 0
          ? `實際平均比預估少 ${machtileTrackingPercent(Math.abs(accuracy.averageSignedPct))}`
          : "實際與預估平均相同";
    const accuracyRows = accuracy.samples.slice(0, 20).map((sample) => `
      <tr>
        <td>${escapeHtml(String(sample.runDate || "").slice(0, 10) || "-")}</td>
        <td>${escapeHtml(machtileMachineDisplay(sample.machineLabel))}</td>
        <td>${escapeHtml(sample.programLabel)}・${escapeHtml(sample.versionLabel)}</td>
        <td>${escapeHtml(machtileFormatDuration(Math.round(sample.estimatedSeconds)))}</td>
        <td>${escapeHtml(machtileFormatDuration(Math.round(sample.actualSeconds)))}</td>
        <td class="${Math.abs(sample.signedPct) <= 20 ? "tracking-good" : "tracking-bad"}">${escapeHtml(machtileTrackingPercent(sample.signedPct, true))}</td>
      </tr>
    `).join("");
    const delayRows = schedule.overdue.slice(0, 20).map((item) => `
      <tr>
        <td>${escapeHtml(item.workOrderNo)}</td>
        <td>${escapeHtml(item.partName || "-")}</td>
        <td>${escapeHtml(item.processName)}</td>
        <td>${escapeHtml(machtileMachineDisplay(item.machineLabel))}</td>
        <td>${escapeHtml(machtileFormatAuditTime(item.plannedEndAt))}</td>
        <td class="tracking-bad">${escapeHtml(machtileTrackingDelay(item.delayMinutes))}</td>
        <td>${escapeHtml(item.reason)}</td>
      </tr>
    `).join("");
    const reasonRows = schedule.replanReasons.slice(0, 10).map((item) => `<li><span>${escapeHtml(item.reason)}</span><strong>${item.count} 次</strong></li>`).join("");
    const quoteRows = quoteVariance.rows.slice(0, 20).map((item) => `<tr><td>${escapeHtml(item.workOrderNo)}</td><td>${escapeHtml(item.partName || "-")}</td><td>${escapeHtml(machtileFormatScheduleMinutes(item.quotedMinutes))}</td><td>${escapeHtml(machtileFormatScheduleMinutes(item.actualMinutes))}</td><td class="${item.signedPct > 0 ? "tracking-bad" : "tracking-good"}">${escapeHtml(machtileTrackingPercent(item.signedPct, true))}</td><td>${item.actualQuantity} 件／${item.machiningRunCount} 筆</td><td>${escapeHtml(item.reason)}</td></tr>`).join("");
    const quoteDirection = quoteVariance.averageSignedPct == null ? "尚無完工確認" : quoteVariance.averageSignedPct > 0 ? `實際平均超出 ${machtileTrackingPercent(quoteVariance.averageSignedPct)}` : `實際平均低於 ${machtileTrackingPercent(Math.abs(quoteVariance.averageSignedPct))}`;

    holder.innerHTML = `
      <section class="report-panel operational-tracking-panel">
        <div class="panel-title operational-tracking-title">
          <div><h2>營運追蹤</h2><small>只使用真實加工履歷與已發布排程；更新至 ${escapeHtml(machtileFormatAuditTime(nowIso))}</small></div>
          <label><span>觀察期間</span><select id="machtileTrackingPeriod"><option value="7" ${safeDays === 7 ? "selected" : ""}>近 7 天</option><option value="30" ${safeDays === 30 ? "selected" : ""}>近 30 天</option><option value="90" ${safeDays === 90 ? "selected" : ""}>近 90 天</option></select></label>
        </div>
        <div class="operational-kpi-grid">
          <article class="report-card ${accuracyTone}"><span>平均絕對估時誤差</span><strong>${machtileTrackingPercent(accuracy.averageAbsolutePct)}</strong><small>${accuracy.sampleCount} 筆有效樣本；${escapeHtml(direction)}</small></article>
          <article class="report-card ${accuracy.within20Rate == null ? "risk-blue" : accuracy.within20Rate >= 80 ? "risk-green" : "risk-amber"}"><span>誤差在 ±20% 內</span><strong>${machtileTrackingPercent(accuracy.within20Rate)}</strong><small>${accuracy.within20Count}/${accuracy.sampleCount} 筆</small></article>
          <article class="report-card ${schedule.overdueCount ? "risk-red" : "risk-green"}"><span>目前排程落後</span><strong>${schedule.overdueCount}</strong><small>預定結束已過且工序未完成</small></article>
          <article class="report-card ${schedule.pendingReplanCount ? "risk-amber" : "risk-green"}"><span>待處理重排</span><strong>${schedule.pendingReplanCount}</strong><small>近 ${safeDays} 天共 ${schedule.replanCount} 次重排觸發</small></article>
          <article class="report-card ${quoteVariance.comparisonCount ? quoteVariance.averageAbsolutePct <= 20 ? "risk-green" : "risk-amber" : "risk-blue"} operational-quote-gap"><span>估價與最終工時差異</span><strong>${quoteVariance.comparisonCount ? machtileTrackingPercent(quoteVariance.averageAbsolutePct) : "尚無資料"}</strong><small>${quoteVariance.comparisonCount} 張已完工工單；${escapeHtml(quoteDirection)}</small></article>
        </div>
        <p class="operational-definition">定義：估時誤差＝平均 |實際純加工秒數－程式版原估秒數| ÷ 原估秒數；已由主管排除的樣本不計。排程落後只計已發布且仍有效的主軸排程，預定結束已過而工序未完成。</p>
      </section>

      <section class="report-panel">
        <div class="panel-title"><h2>預估與實際誤差</h2><span>近 ${safeDays} 天・${accuracy.sampleCount} 筆</span></div>
        ${accuracyRows ? `<div class="machtile-stats-table-wrap"><table class="machtile-stats-table"><thead><tr><th>加工日</th><th>機台</th><th>程式／版本</th><th>原估時</th><th>實際</th><th>差異</th></tr></thead><tbody>${accuracyRows}</tbody></table></div>` : '<p class="admin-module-note">這段期間沒有同時具備原估時與實際純加工時間的有效樣本。</p>'}
        <p class="operational-footnote">未納入：主管排除 ${accuracy.rejected.excluded} 筆、缺實際時間 ${accuracy.rejected.missingActual} 筆、缺原估時 ${accuracy.rejected.missingEstimate} 筆。只顯示最近 20 筆。</p>
      </section>

      <section class="report-panel">
        <div class="panel-title"><h2>排程落後原因</h2><span>${schedule.overdueCount} 個目前落後工序</span></div>
        ${delayRows ? `<div class="machtile-stats-table-wrap"><table class="machtile-stats-table"><thead><tr><th>工單</th><th>品名</th><th>工序</th><th>機台</th><th>預定結束</th><th>已落後</th><th>原因</th></tr></thead><tbody>${delayRows}</tbody></table></div>` : '<p class="admin-module-note">目前沒有「預定結束已過且工序未完成」的有效排程。</p>'}
        <div class="operational-replan-summary"><div><strong>近 ${safeDays} 天重排原因</strong><small>停機、缺料、恢復等正式重排請求</small></div>${reasonRows ? `<ol>${reasonRows}</ol>` : '<p class="admin-module-note">這段期間沒有重排請求。</p>'}</div>
      </section>

      <section class="report-panel ${quoteRows ? "" : "operational-data-gap"}">
        <div class="panel-title"><h2>估價與最終工時差異</h2><span>${quoteVariance.comparisonCount} 張已確認</span></div>
        ${quoteRows ? `<div class="machtile-stats-table-wrap"><table class="machtile-stats-table"><thead><tr><th>工單</th><th>品名</th><th>報價總工時</th><th>實際總工時</th><th>差異</th><th>證據</th><th>確認原因</th></tr></thead><tbody>${quoteRows}</tbody></table></div>` : '<p>正式估價契約已啟用；完成「建立版本 → 主管核准 → 連結工單 → 工單完工 → 確認最終工時」後，這裡會顯示差異。</p>'}
      </section>
    `;
    document.getElementById("machtileTrackingPeriod")?.addEventListener("change", (event) => {
      machtileRenderOperationalTracking(Number(event.target.value)).catch(() => {});
    });
  } catch (error) {
    holder.innerHTML = `<section class="report-panel"><div class="panel-title"><h2>營運追蹤</h2><span>載入失敗</span></div><p class="admin-module-note">真資料讀取失敗：${escapeHtml(String(error?.message || error || ""))}</p></section>`;
  }
}

// D 加工時間統計（2026-07-14 夜間 sprint）：strict-only 真資料區塊——
// 近 14 天每日產量（報工＋已確認盤點）＋工單單件時間統計，附 CSV 匯出。
async function machtileRenderTimeStats() {
  const holder = document.getElementById("machtileTimeStats");
  if (!holder) return;
  try {
    const fromDate = new Date(Date.now() - 13 * 24 * 3600000).toISOString().slice(0, 10);
    const [reports, checks] = await Promise.all([
      supabaseFetch(`production_reports?select=report_date,completed_qty,defect_qty,cycle_time_seconds,report_type,machine_id,work_orders(work_order_no,part_name)&report_date=gte.${fromDate}&order=report_date.desc&limit=2000`),
      supabaseFetch(`hmc_daily_worklist_item_quantities?select=work_date,machine_code,completed_qty,defect_qty&daily_check_status=in.(confirmed,converted)&work_date=gte.${fromDate}&limit=2000`),
    ]);
    const machineNameById = new Map(state.machineMasters.map((m) => [String(m.dbRowId || ""), m.code || m.name]));
    // fallback：view 沒帶 id 時就用 machines REST 補
    if (![...machineNameById.keys()].some(Boolean)) {
      try {
        const machines = await supabaseFetch("machines?select=id,machine_code");
        machines.forEach((m) => machineNameById.set(String(m.id), m.machine_code));
      } catch (error) { /* 名稱缺就顯示未知機台 */ }
    }

    // 每日產量：日期×機台
    const daily = new Map();
    (Array.isArray(reports) ? reports : []).forEach((row) => {
      const machine = machineNameById.get(String(row.machine_id)) || "未知機台";
      const key = `${row.report_date}|${machine}`;
      const slot = daily.get(key) || { date: row.report_date, machine, reportDone: 0, reportDefect: 0, reportCount: 0, cycleSum: 0, cycleCount: 0, checkDone: 0, checkDefect: 0 };
      slot.reportDone += Number(row.completed_qty) || 0;
      slot.reportDefect += Number(row.defect_qty) || 0;
      slot.reportCount += 1;
      if (row.cycle_time_seconds != null) {
        slot.cycleSum += Number(row.cycle_time_seconds) || 0;
        slot.cycleCount += 1;
      }
      daily.set(key, slot);
    });
    (Array.isArray(checks) ? checks : []).forEach((row) => {
      const key = `${row.work_date}|${row.machine_code}`;
      const slot = daily.get(key) || { date: row.work_date, machine: row.machine_code, reportDone: 0, reportDefect: 0, reportCount: 0, cycleSum: 0, cycleCount: 0, checkDone: 0, checkDefect: 0 };
      slot.checkDone += Number(row.completed_qty) || 0;
      slot.checkDefect += Number(row.defect_qty) || 0;
      daily.set(key, slot);
    });
    const dailyRows = [...daily.values()].sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : a.machine.localeCompare(b.machine)));

    // 工單單件時間統計
    const perOrder = new Map();
    (Array.isArray(reports) ? reports : []).forEach((row) => {
      const wo = row.work_orders;
      if (!wo || row.cycle_time_seconds == null) return;
      const key = wo.work_order_no || "-";
      const slot = perOrder.get(key) || { workOrderNo: key, partName: wo.part_name || "", cycleSum: 0, cycleCount: 0, cycleMin: Infinity, cycleMax: 0, done: 0 };
      const cycle = Number(row.cycle_time_seconds) || 0;
      slot.cycleSum += cycle;
      slot.cycleCount += 1;
      slot.cycleMin = Math.min(slot.cycleMin, cycle);
      slot.cycleMax = Math.max(slot.cycleMax, cycle);
      slot.done += Number(row.completed_qty) || 0;
      perOrder.set(key, slot);
    });
    const orderRows = [...perOrder.values()].sort((a, b) => b.cycleCount - a.cycleCount).slice(0, 20);

    const avg = (slot) => (slot.cycleCount ? Math.round(slot.cycleSum / slot.cycleCount) : null);
    holder.innerHTML = `
      <section class="report-panel">
        <div class="panel-title">
          <h2>每日產量（近 14 天・真資料）</h2>
          <span>${dailyRows.length} 列</span>
        </div>
        ${dailyRows.length ? `
        <div class="machtile-stats-table-wrap">
          <table class="machtile-stats-table">
            <thead><tr><th>日期</th><th>機台</th><th>報工完成</th><th>報工不良</th><th>盤點完成</th><th>盤點不良</th><th>報工筆數</th><th>平均單件</th></tr></thead>
            <tbody>
              ${dailyRows.map((row) => `<tr><td>${escapeHtml(row.date)}</td><td>${escapeHtml(machtileMachineDisplay(row.machine))}</td><td>${row.reportDone}</td><td>${row.reportDefect}</td><td>${row.checkDone}</td><td>${row.checkDefect}</td><td>${row.reportCount}</td><td>${avg(row) != null ? `${avg(row)} 秒` : "—"}</td></tr>`).join("")}
            </tbody>
          </table>
        </div>
        <button type="button" class="hmc-secondary-action" data-machtile-timestats-csv="daily">匯出每日產量 CSV</button>
        ` : '<p class="admin-module-note">近 14 天還沒有報工或已確認盤點資料。</p>'}
      </section>
      <section class="report-panel">
        <div class="panel-title">
          <h2>工單單件時間（真資料）</h2>
          <span>${orderRows.length} 張</span>
        </div>
        ${orderRows.length ? `
        <div class="machtile-stats-table-wrap">
          <table class="machtile-stats-table">
            <thead><tr><th>工單號</th><th>品名</th><th>平均單件</th><th>最快</th><th>最慢</th><th>樣本數</th><th>累計完成</th></tr></thead>
            <tbody>
              ${orderRows.map((row) => `<tr><td>${escapeHtml(row.workOrderNo)}</td><td>${escapeHtml(row.partName)}</td><td>${avg(row)} 秒</td><td>${row.cycleMin} 秒</td><td>${row.cycleMax} 秒</td><td>${row.cycleCount}</td><td>${row.done}</td></tr>`).join("")}
            </tbody>
          </table>
        </div>
        ` : '<p class="admin-module-note">還沒有帶單件時間的報工（現場報工填「單件時間」後這裡就會有統計）。</p>'}
      </section>
    `;
    const csvButton = holder.querySelector("[data-machtile-timestats-csv]");
    if (csvButton) {
      csvButton.addEventListener("click", () => {
        machtileCsvDownload(
          `MachTile_每日產量_近14天.csv`,
          ["日期", "機台", "報工完成", "報工不良", "盤點完成", "盤點不良", "報工筆數", "平均單件秒數"],
          dailyRows.map((row) => [row.date, row.machine, row.reportDone, row.reportDefect, row.checkDone, row.checkDefect, row.reportCount, avg(row) ?? ""]),
        );
      });
    }
  } catch (error) {
    holder.innerHTML = `<p class="admin-module-note">加工時間統計載入失敗：${escapeHtml(String(error?.message || error || ""))}</p>`;
  }
}

