// 工單清單（owner 2026-10-02：加來源欄＋清單優化）。只讀：work_orders＋work_order_processes、建立者名字（app_users）、
// 完成數（rpc/batch_report_progress，跟 Monitor 卡片同一套 cardProgress 口徑）。純邏輯在 workOrderListCore.js。
const machtileWoListState = { rows: [], byNo: new Map(), query: "", filter: "all", loaded: false };
const MACHTILE_WO_LIST_LIMIT = 500;
const machtileWoListCore = () => (typeof window === "undefined" ? null : window.MachTileWorkOrderListCore);

let machtileWoMachinesCache = null;

function machtileWoMachineLabel(machine) {
  const code = String(machine.machine_code || "");
  // The machine cards display the shop-floor alias from location, not name.
  const alias = typeof machine.location === "string" ? machine.location.trim() : "";
  const name = alias || (typeof machine.name === "string" ? machine.name.trim() : "");
  const alreadyLabeled = name.startsWith(code) && /^\s/.test(name.slice(code.length));
  return name && name !== code ? (alreadyLabeled ? name : `${code} ${name}`) : code;
}

async function machtileWoMachines() {
  if (machtileWoMachinesCache) return machtileWoMachinesCache;
  const rows = await supabaseFetch("machines?select=id,machine_code,name,location&order=machine_code");
  if (!Array.isArray(rows) || !rows.length || rows.some(m => !m.id || !m.machine_code)) throw new Error("機台清單讀取失敗，暫不能送出；請重新開啟工單管理。");
  machtileWoMachinesCache = rows;
  return machtileWoMachinesCache;
}

// 依單號取全部真實工序；不再把第一道當成建單表單的唯一工序。
async function machtileWoFetchByNo(workOrderNo) {
  const rows = await supabaseFetch(
    `work_orders?select=id,work_order_no,part_no,part_name,quantity,due_date,work_order_processes(id,machine_id,process_name,process_order,process_type,status,qty_completed,qty_defect)&work_order_no=eq.${encodeURIComponent(workOrderNo)}&limit=1`
  );
  const row = (rows || [])[0];
  if (!row) return null;
  const procs = (row.work_order_processes || [])
    .slice()
    .sort((a, b) => Number(a.process_order || 0) - Number(b.process_order || 0));
  const machines = await machtileWoMachines();
  const codeById = new Map(machines.map((m) => [m.id, m.machine_code]));
  const departmentById = new Map((state.machineMasters || []).map(m => [m.id, m.department]));
  if (procs.some(p => p.machine_id && !codeById.has(p.machine_id))) throw new Error("工序原機台不在清單中，暫不能送出；請重新開啟工單管理。");
  const progressById = new Map();
  const ids = procs.map(p => p.id).filter(isUuid);
  for (let i = 0; i < ids.length; i += MACHTILE_CARD_PROGRESS_CHUNK) {
    const progress = await supabaseFetch("rpc/batch_report_progress", {
      method: "POST", body: JSON.stringify({ p_process_ids: ids.slice(i, i + MACHTILE_CARD_PROGRESS_CHUNK), p_pending_since: config.batchReportPendingSince || null }),
    });
    if (!Array.isArray(progress)) throw new Error("工序報工資料未驗證，暫不能改派");
    progress.forEach(p => progressById.set(p.process_id, p));
  }
  return {
    work_order_no: row.work_order_no,
    part_no: row.part_no,
    part_name: row.part_name,
    quantity: row.quantity,
    due_date: row.due_date,
    process_name: "",
    machine_code: "",
    processes: procs.map(p => {
      const progress = progressById.get(p.id);
      const done = progress && window.MachTileBatchReportCore?.cardProgress
        ? window.MachTileBatchReportCore.cardProgress(Number(p.qty_completed || 0), progress, Date.now()).done : null;
      return { ...p, machine_department: p.machine_id ? departmentById.get(p.machine_id) || null : null,
        machine_code: p.machine_id ? codeById.get(p.machine_id) || "" : "",
        reported: done, progressVerified: Boolean(progress),
        hasReports: Boolean(progress?.last_report_at || Number(progress?.legacy_output) > 0 || Number(p.qty_completed) > 0 || Number(p.qty_defect) > 0) };
    }),
  };
}

// 讓人「選」而不是「照抄 16 碼」。label 帶品號品名，才認得出是哪一張。
async function machtileWoPopulateNoDatalist() {
  const list = document.getElementById("machtileWoNoList");
  if (!list) return;
  try {
    const rows = await supabaseFetch(
      "work_orders?select=work_order_no,part_no,part_name&order=created_at.desc&limit=50"
    );
    list.innerHTML = (rows || [])
      .filter((r) => r.work_order_no)
      .map((r) => {
        const desc = [r.part_no, r.part_name].filter(Boolean).join(" ");
        return `<option value="${escapeHtml(r.work_order_no)}"${desc ? ` label="${escapeHtml(desc)}"` : ""}></option>`;
      })
      .join("");
  } catch (error) {
    console.warn("work order datalist failed", error);
  }
}

// 來源欄位（source_system 等）是後來加的；萬一某個環境還沒有，退回只取舊欄位（來源就照 created_by 判斷）。
const MACHTILE_WO_LIST_SELECT_FULL = "id,work_order_no,part_no,part_name,quantity,due_date,status,created_by,source_system,legacy_mes_source,legacy_work_order_no,work_order_processes(id,machine_id,process_order,qty_completed,off_station_at)";
const MACHTILE_WO_LIST_SELECT_BASIC = "id,work_order_no,part_no,part_name,quantity,due_date,status,created_by,work_order_processes(id,machine_id,process_order,qty_completed,off_station_at)";

async function machtileWoFetchListRows() {
  const tail = `&order=due_date.asc.nullslast,work_order_no.asc&limit=${MACHTILE_WO_LIST_LIMIT}`;
  try {
    return await supabaseFetch(`work_orders?select=${MACHTILE_WO_LIST_SELECT_FULL}${tail}`);
  } catch (error) {
    console.warn("work order list: source columns unavailable, retrying basic select", error);
    return supabaseFetch(`work_orders?select=${MACHTILE_WO_LIST_SELECT_BASIC}${tail}`);
  }
}

// 建立者名字（created_by → app_users.name）。讀不到就只顯示「App 手動」，不擋清單。
async function machtileWoFetchCreatorNames(ids) {
  const list = [...new Set(ids.filter((v) => isUuid(String(v || ""))))];
  if (!list.length) return new Map();
  try {
    const rows = await supabaseFetch(`app_users?select=id,name&id=in.(${list.join(",")})`);
    return new Map((rows || []).map((r) => [r.id, r.name || ""]));
  } catch (error) {
    console.warn("work order creator lookup failed", error);
    return new Map();
  }
}

// 完成數：跟 Monitor 卡片同一套（batchReportCore.cardProgress：有舊 MES 結算＝舊 MES 已報＋待回寫，否則 App 累計）。
// rpc/batch_report_progress 是唯讀查詢（卡片牆載入時也是同一支）。
async function machtileWoFetchProgress(processIds) {
  const byProcess = new Map();
  const ids = [...new Set(processIds.map(String).filter(isUuid))];
  const chunks = [];
  for (let i = 0; i < ids.length; i += MACHTILE_CARD_PROGRESS_CHUNK) chunks.push(ids.slice(i, i + MACHTILE_CARD_PROGRESS_CHUNK));
  await Promise.all(chunks.map(async (chunk) => {
    try {
      const rows = await supabaseFetch("rpc/batch_report_progress", {
        method: "POST",
        body: JSON.stringify({ p_process_ids: chunk, p_pending_since: config.batchReportPendingSince || null }),
      });
      (Array.isArray(rows) ? rows : []).forEach((row) => { if (row && row.process_id) byProcess.set(String(row.process_id), row); });
    } catch (error) {
      console.warn("batch_report_progress unavailable for work order list; using App-only completion", error);
    }
  }));
  return byProcess;
}

function machtileWoSortedProcesses(order) {
  return (order.work_order_processes || []).slice()
    .sort((a, b) => Number(a.process_order || 0) - Number(b.process_order || 0));
}

// 一張單的代表工序：還在站上的（off_station_at 為 null）照 process_order 取第一道；都離站了就取第一道。
function machtileWoRepresentativeProcess(order) {
  const procs = machtileWoSortedProcesses(order);
  return procs.find((p) => !p.off_station_at) || procs[0] || null;
}

function machtileWoBuildRow(order, { labelById, codeById, creatorById, progressByProcess, core, batchCore }) {
  const procs = machtileWoSortedProcesses(order);
  const onStation = procs.filter((p) => !p.off_station_at && p.machine_id);
  const labels = [...new Set(onStation.map((p) => labelById.get(p.machine_id) || "?"))];
  let machineText = labels.join("、");
  let machineNote = "";
  if (!machineText) {
    const assigned = procs.find((p) => p.machine_id);
    if (assigned) { machineText = labelById.get(assigned.machine_id) || "?"; machineNote = "已離站"; }
    else machineText = "未指派";
  }
  const rep = machtileWoRepresentativeProcess(order);
  const appDone = Number(rep?.qty_completed || 0);
  let progress = { done: appDone, label: "", source: "app" };
  if (batchCore && typeof batchCore.cardProgress === "function") {
    try { progress = batchCore.cardProgress(appDone, rep ? progressByProcess.get(String(rep.id)) || null : null, Date.now()); }
    catch (error) { console.warn("work order progress failed", error); }
  }
  const source = core.sourceOf(order);
  return {
    ...order,
    source,
    creatorName: source.createdBy ? (creatorById.get(source.createdBy) || "") : "",
    machineText,
    machineNote,
    // 建單表單（work_order_upsert）改的是第一道工序的機台；改派確認拿這個比
    firstMachineCode: procs[0] && procs[0].machine_id ? (codeById.get(procs[0].machine_id) || "") : "",
    done: Number(progress.done || 0),
    progressLabel: progress.label || "",
    progressSource: progress.source || "app",
  };
}

async function machtileRefreshWorkOrderList() {
  const holder = document.getElementById("machtileWoList");
  if (!holder) return;
  const core = machtileWoListCore();
  if (!core) {
    holder.innerHTML = '<p class="admin-module-note">工單清單元件沒有載入，請重新整理頁面。</p>';
    return;
  }
  try {
    const [orders, machines] = await Promise.all([machtileWoFetchListRows(), machtileWoMachines()]);
    const list = Array.isArray(orders) ? orders : [];
    const labelById = new Map(machines.map((m) => [m.id, machtileWoMachineLabel(m)]));
    const codeById = new Map(machines.map((m) => [m.id, m.machine_code]));
    const repIds = list.map((o) => machtileWoRepresentativeProcess(o)?.id).filter(Boolean);
    const [creatorById, progressByProcess] = await Promise.all([
      machtileWoFetchCreatorNames(list.map((o) => core.sourceOf(o).createdBy).filter(Boolean)),
      machtileWoFetchProgress(repIds),
    ]);
    const ctx = { labelById, codeById, creatorById, progressByProcess, core, batchCore: machtileBatchCore() };
    machtileWoListState.rows = list.map((o) => machtileWoBuildRow(o, ctx));
    machtileWoListState.byNo = new Map(machtileWoListState.rows.map((r) => [r.work_order_no, r]));
    machtileWoListState.loaded = true;
    machtileRenderWorkOrderRows();
  } catch (error) {
    holder.innerHTML = `<p class="admin-module-note">工單清單載入失敗：${escapeHtml(error.message || "")}</p>`;
  }
}

function machtileWoSourceBadge(row) {
  const isApp = row.source.kind === "app";
  const by = isApp ? `<small class="wo-source-by">${escapeHtml(row.creatorName ? `建立者：${row.creatorName}` : "建立者不明")}</small>` : "";
  return `<span class="wo-source-badge ${isApp ? "is-app" : "is-legacy"}" data-wo-source="${escapeHtml(row.source.kind)}">${escapeHtml(row.source.label)}</span>${by}`;
}

function machtileRenderWorkOrderRows() {
  const holder = document.getElementById("machtileWoList");
  const core = machtileWoListCore();
  if (!holder || !core) return;
  const today = core.localToday(new Date());
  const all = machtileWoListState.rows;
  const counts = core.counts(all, today);
  document.querySelectorAll("[data-wo-filter-count]").forEach((el) => {
    const n = counts[el.dataset.woFilterCount];
    el.textContent = Number.isFinite(n) ? String(n) : "";
  });
  const shown = core.filterRows(all, { query: machtileWoListState.query, filter: machtileWoListState.filter, today });
  const head = `
    <li class="wo-row wo-row-head" aria-hidden="true">
      <span>單號</span><span>品名</span><span>數量（已報／訂單）</span><span>交期</span><span>機台</span><span>來源</span>
    </li>`;
  const body = shown.map((row) => {
    const due = core.dueState(row, today);
    const dueNote = due === "closed" ? "已結案" : core.dueNote(row, today);
    const pct = core.progressPercent(row.done, row.quantity);
    const over = Number(row.quantity) > 0 && row.done > Number(row.quantity);
    return `
      <li class="wo-row" data-wo-row="${escapeHtml(row.work_order_no)}" data-wo-due-state="${escapeHtml(due)}">
        <div class="wo-cell wo-no"><button type="button" class="wo-no-button" data-wo-edit="${escapeHtml(row.work_order_no)}" title="帶入下方表單">${escapeHtml(row.work_order_no)}</button></div>
        <div class="wo-cell wo-part"><strong>${escapeHtml(row.part_name || "-")}</strong>${row.part_no ? `<small>${escapeHtml(row.part_no)}</small>` : ""}</div>
        <div class="wo-cell wo-qty">
          <span class="wo-qty-text"><b>${escapeHtml(String(row.done))}</b> / ${escapeHtml(String(row.quantity ?? "-"))}</span>
          <span class="wo-progress${over ? " is-over" : ""}" role="progressbar" aria-label="完成進度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></span>
          ${row.progressLabel ? `<small class="wo-progress-source${row.progressSource === "legacy" ? "" : " is-missing"}">${escapeHtml(row.progressLabel)}</small>` : ""}
        </div>
        <div class="wo-cell wo-due is-${escapeHtml(due)}"><span>${escapeHtml(row.due_date || "-")}</span>${dueNote ? `<small>${escapeHtml(dueNote)}</small>` : ""}</div>
        <div class="wo-cell wo-machine"><span>${escapeHtml(row.machineText)}</span>${row.machineNote ? `<small>${escapeHtml(row.machineNote)}</small>` : ""}</div>
        <div class="wo-cell wo-source">${machtileWoSourceBadge(row)}</div>
      </li>`;
  }).join("");
  const empty = !all.length ? "尚無工單" : "沒有符合的工單";
  const limitNote = all.length >= MACHTILE_WO_LIST_LIMIT ? `<p class="admin-module-note">只顯示前 ${MACHTILE_WO_LIST_LIMIT} 張（依交期）。</p>` : "";
  holder.innerHTML = `
    <p class="wo-list-summary">共 ${shown.length} 張${shown.length !== all.length ? `（全部 ${all.length} 張）` : ""}・依交期排序，最急的在最上面・點單號帶入下方表單</p>
    <ul class="wo-list">${head}${body || `<li class="wo-row wo-row-empty">${empty}</li>`}</ul>
    ${limitNote}`;
}

function machtileWoBindListControls() {
  const search = document.getElementById("machtileWoSearch");
  if (search) {
    search.addEventListener("input", () => {
      machtileWoListState.query = search.value;
      machtileRenderWorkOrderRows();
    });
  }
  document.querySelectorAll("[data-wo-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      machtileWoListState.filter = button.dataset.woFilter;
      document.querySelectorAll("[data-wo-filter]").forEach((b) => {
        const on = b.dataset.woFilter === machtileWoListState.filter;
        b.classList.toggle("is-active", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      machtileRenderWorkOrderRows();
    });
  });
}

// 送出前查「這張單現在是什麼來源、第一道工序掛哪台」：先用清單快取，沒有（例：超過清單上限）再唯讀查一次。
// 查不到＝新單（不跳確認）。查詢失敗時當作舊 MES 單、機台未知 → 會跳確認（寧可多問一次）。
async function machtileWoExistingForConfirm(workOrderNo, selectedProcess = null) {
  const core = machtileWoListCore();
  if (!core || !workOrderNo) return null;
  const cached = machtileWoListState.byNo.get(workOrderNo);
  if (cached) return { source: cached.source, machine_code: selectedProcess?.machine_code ?? cached.firstMachineCode ?? "" };
  try {
    const no = encodeURIComponent(workOrderNo);
    let rows;
    try {
      rows = await supabaseFetch(`work_orders?select=created_by,source_system,legacy_mes_source,legacy_work_order_no&work_order_no=eq.${no}&limit=1`);
    } catch (error) {
      rows = await supabaseFetch(`work_orders?select=created_by&work_order_no=eq.${no}&limit=1`);
    }
    const row = (rows || [])[0];
    if (!row) return null;
    const record = await machtileWoFetchByNo(workOrderNo);
    return { source: core.sourceOf(row), machine_code: selectedProcess?.machine_code ?? record?.machine_code ?? "" };
  } catch (error) {
    console.warn("work order source lookup failed; asking for confirmation anyway", error);
    return { source: core.sourceOf({}), machine_code: "（讀取失敗）" };
  }
}

function machtileWoErrorText(error) {
  const msg = String(error?.message || error || "");
  if (msg.includes("PROCESS_ORDER_REQUIRED")) return "這張工單有多道工序，請先選擇要更新哪一道。";
  if (msg.includes("PROCESS_HAS_REPORTS")) return "這道工序已有報工（含舊 MES 數量），不能改機台或步序；報工數量已保留。";
  if (msg.includes("PROCESS_NOT_FOUND")) return "所選工序不存在或不屬於這張工單，請重新查詢並選擇。";
  if (msg.includes("PROCESS_ORDER_CONFLICT")) return "目標步序已有另一道工序，不可覆蓋。";
  if (msg.includes("MACHINE_UNAVAILABLE")) return "維修或停用機台不可接受派工。";
  if (msg.includes("FORBIDDEN")) return "此帳號沒有建單權限（需排程以上）。";
  if (msg.includes("machine_code not found")) return "找不到這台機台，請重新選擇。";
  if (msg.includes("quantity must be")) return "數量必須大於 0。";
  return msg;
}

async function machtileInitWorkOrderModule() {
  const form = document.getElementById("machtileWoForm");
  if (!form) return;
  let machines;
  try { machines = await machtileWoMachines(); }
  catch (error) {
    if (!form.isConnected) return;
    form.querySelectorAll('button[type="submit"], select').forEach(el => { el.disabled = true; });
    document.getElementById('machtileWoSteps').textContent = `機台清單讀取失敗，無法確認原指派：${machtileWoErrorText(error)}`;
    const note = document.getElementById('machtileWoPrefillNote');
    if (note) { note.textContent = '送出已停用，請重新開啟工單管理重試。'; note.hidden = false; }
    return;
  }
  if (!form.isConnected) return;
  const select = document.getElementById("machtileWoMachine");
  if (select) {
    select.innerHTML = `<option value="">暫不指派</option>` +
      machines.map((m) => `<option value="${escapeHtml(m.machine_code)}">${escapeHtml(machtileWoMachineLabel(m))}</option>`).join("");
  }
  machtileWoBindListControls();
  machtileRefreshWorkOrderList();

  // --- ISSUE-007：貼單號 → 其餘欄位自動帶出 ---
  // 派工橋早就把這些值同步進 work_orders 了；先前要人逐格照抄，16 碼抄錯一碼
  // 不會當場報錯，要到現場掃碼被拒才發現。決策邏輯在 workOrderPrefillCore.js。
  const prefillFieldIds = {
    partNo: "machtileWoPartNo",
    partName: "machtileWoPartName",
    qty: "machtileWoQty",
    due: "machtileWoDue",
    process: "machtileWoProcess",
    machine: "machtileWoMachine",
  };
  const prefillEdited = {};
  const prefillNoteEl = document.getElementById("machtileWoPrefillNote");
  const prefillCore = () => (typeof window === "undefined" ? null : window.MachTileWorkOrderPrefillCore);

  // 只有真人打字／選單才算「手動改過」。程式帶入時直接設 .value、不發事件，
  // 所以不會把自己的帶入誤記成使用者的修改。
  for (const [field, id] of Object.entries(prefillFieldIds)) {
    const el = document.getElementById(id);
    if (!el) continue;
    const mark = () => { prefillEdited[field] = true; };
    el.addEventListener("input", mark);
    el.addEventListener("change", mark);
  }

  const showPrefillNote = (text) => {
    if (!prefillNoteEl) return;
    prefillNoteEl.textContent = text || "";
    prefillNoteEl.hidden = !text;
  };

  const readPrefillCurrent = () => {
    const out = {};
    for (const [field, id] of Object.entries(prefillFieldIds)) {
      out[field] = document.getElementById(id)?.value ?? "";
    }
    return out;
  };

  const applyPrefill = (plan) => {
    const skippedMachine = [];
    for (const [field, value] of Object.entries(plan.fill)) {
      const el = document.getElementById(prefillFieldIds[field]);
      if (!el) continue;
      // 下拉沒有這個選項就別硬塞（塞了會靜默變成「暫不指派」，比不填更誤導）。
      if (el.tagName === "SELECT" && !Array.from(el.options).some((o) => o.value === value)) {
        skippedMachine.push(value);
        continue;
      }
      el.value = value;
    }
    const note = prefillCore().prefillNote(plan);
    showPrefillNote(skippedMachine.length
      ? `${note}；機台 ${skippedMachine.join("、")} 不在可選清單，未帶入`
      : note);
  };

  const noInput = document.getElementById("machtileWoNo");
  const stepSelect = document.getElementById("machtileWoStep");
  let stepRecord = null;
  let stepRecordNo = "";
  let stepsLoaded = false;
  let lookupFailed = false;
  const renderSteps = (record, normalized) => {
    stepRecord = record;
    stepRecordNo = normalized;
    stepsLoaded = true;
    lookupFailed = false;
    form.querySelector('button[type="submit"]').disabled = false;
    const procs = record?.processes || [];
    const isNew = !record || procs.length === 0;
    stepSelect.disabled = isNew;
    stepSelect.required = !isNew;
    stepSelect.innerHTML = '<option value="">請選擇要更新哪一道</option>' + procs.map(p =>
      `<option value="${escapeHtml(p.id)}">${escapeHtml(machtileOperationLabel(p))}</option>`).join("");
    document.getElementById("machtileWoNewStepField").hidden = !isNew;
    document.getElementById("machtileWoNewStep").required = isNew;
    document.getElementById("machtileWoSteps").innerHTML = isNew
      ? "沒有現有工序；新增時請明確指定步序，不推測舊 MES 路線。"
      : window.MachTileProcessFlow.render(record.displayProcesses || procs, {quantity: record.quantity,
          ...machtileProcessFlowOptions(normalized,machtileProcessFlows.get(normalized)?.auditAvailable)});
    select.disabled = !isNew;
    document.getElementById("machtileWoProcess").value = "";
  };
  stepSelect.addEventListener("change", () => {
    const p = stepRecord?.processes?.find(p => p.id === stepSelect.value);
    select.value = p?.machine_code || "";
    select.disabled = !p || p.hasReports || !p.progressVerified;
    document.getElementById("machtileWoProcess").value = p?.process_name || "";
    if (p?.hasReports) showPrefillNote(`N${p.process_order} 已報工，機台／步序鎖定；仍可更新工單表頭。`);
  });
  select.disabled = true;
  let prefillSeq = 0;
  let prefillTimer = null;
  const lookupAndPrefill = async () => {
    const core = prefillCore();
    if (!core || !noInput) return;
    const normalized = core.normalizeWorkOrderNo(noInput.value);
    if (normalized !== noInput.value) noInput.value = normalized;
    if (normalized.length < 4) { showPrefillNote(""); return; }
    const seq = ++prefillSeq;
    showPrefillNote("查詢中…");
    try {
      const record = await machtileWoFetchByNo(normalized);
      const displayRoutes = await machtileReadRouteSteps([normalized]);
      if (record) {
        try { record.displayProcesses=window.MachTileProcessFlow.mergeRoute(displayRoutes,record.processes,normalized); }
        catch(error) { console.warn('management route fallback',error);record.displayProcesses=record.processes; }
      }
      if (seq !== prefillSeq || !form.isConnected) return;   // 舊單號或已關閉的表單不能覆寫新表單
      applyPrefill(core.planPrefill({ record, current: readPrefillCurrent(), edited: prefillEdited }));
      renderSteps(record, normalized);
    } catch (error) {
      if (seq !== prefillSeq || !form.isConnected) return;
      stepsLoaded = false;
      lookupFailed = true;
      form.querySelector('button[type="submit"]').disabled = true;
      select.disabled = true;
      stepSelect.innerHTML = '<option value="">讀取失敗，請重新查詢</option>';
      document.getElementById('machtileWoSteps').textContent = `工序／機台資料讀取失敗：${machtileWoErrorText(error)}；不能確認原指派，送出已停用。`;
      showPrefillNote(`帶入失敗，送出已停用：${machtileWoErrorText(error)}`);
    }
  };
  if (noInput) {
    noInput.addEventListener("input", () => {
      stepsLoaded = false;
      select.disabled = true;
      stepSelect.value = "";
      clearTimeout(prefillTimer);
      prefillTimer = setTimeout(lookupAndPrefill, 400);
    });
    // 回傳 promise：瀏覽器不理回傳值，但讓測試（與未來的呼叫端）等得到查詢完成。
    noInput.addEventListener("change", () => {
      clearTimeout(prefillTimer);
      return lookupAndPrefill();
    });
  }
  machtileWoPopulateNoDatalist();

  // 清單點單號 → 帶入下方表單（走同一套「貼單號自動帶出」），捲到表單。只帶入、不送出。
  const listHolder = document.getElementById("machtileWoList");
  if (listHolder && noInput) {
    listHolder.addEventListener("click", (event) => {
      const button = event.target.closest("[data-wo-edit]");
      if (!button) return;
      // 換一張單＝整張重帶：清掉上一張的手動修改記號和欄位值，否則「手動改過的欄位不覆蓋」會把上一張的機台留下來。
      for (const [field, fieldId] of Object.entries(prefillFieldIds)) {
        delete prefillEdited[field];
        const el = document.getElementById(fieldId);
        if (el) el.value = "";
      }
      noInput.value = button.dataset.woEdit;
      clearTimeout(prefillTimer);
      lookupAndPrefill();
      document.getElementById("machtileWoFormSection")?.scrollIntoView({ behavior: "smooth", block: "start" });
      noInput.focus({ preventScroll: true });
    });
  }

  // --- ISSUE-007 第 2 條：數字／文字欄位記「最近使用值」，點選帶入 ---
  // 存在瀏覽器 localStorage（每台平板各自的），只是方便，不是資料來源；
  // 讀寫失敗（隱私模式／配額）一律靜默——絕不能因為記不住上次的值而擋住建單。
  const RECENT_STORAGE_KEY = "machtile.wo.recent.v1";
  const recentFields = {
    partNo: "machtileWoRecentPartNo",
    partName: "machtileWoRecentPartName",
    qty: "machtileWoRecentQty",
    process: "machtileWoRecentProcess",
  };
  const readRecentAll = () => {
    const core = prefillCore();
    let raw = "";
    try { raw = window.localStorage.getItem(RECENT_STORAGE_KEY) || ""; } catch (error) { raw = ""; }
    let obj = {};
    try { obj = JSON.parse(raw || "{}") || {}; } catch (error) { obj = {}; }
    const out = {};
    for (const field of Object.keys(recentFields)) {
      out[field] = core ? core.parseRecent(JSON.stringify(obj[field] || [])) : [];
    }
    return out;
  };
  const renderRecentLists = (all) => {
    for (const [field, listId] of Object.entries(recentFields)) {
      const list = document.getElementById(listId);
      if (!list) continue;
      list.innerHTML = (all[field] || []).map((v) => `<option value="${escapeHtml(v)}"></option>`).join("");
    }
  };
  const rememberRecentFromForm = () => {
    const core = prefillCore();
    if (!core) return;
    const all = readRecentAll();
    const cur = readPrefillCurrent();
    const next = {};
    for (const field of Object.keys(recentFields)) {
      next[field] = Array.from(core.rememberRecent(all[field], cur[field]));
    }
    try { window.localStorage.setItem(RECENT_STORAGE_KEY, JSON.stringify(next)); } catch (error) { /* 記不住就算了 */ }
    renderRecentLists(next);
  };
  renderRecentLists(readRecentAll());

  // --- ISSUE-007 第 5 條：Enter 逐欄跳轉，最後一格 Enter＝送出 ---
  // 不用滑鼠也能整張填完。跳轉順序＝表單裡的視覺順序。
  const enterOrder = [
    "machtileWoNo", "machtileWoPartNo", "machtileWoPartName", "machtileWoQty",
    "machtileWoDue", "machtileWoStep", "machtileWoMachine", "machtileWoProcess",
  ];
  enterOrder.forEach((id, index) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" || event.isComposing) return;   // 中文輸入法選字中的 Enter 不算
      event.preventDefault();
      const core = prefillCore();
      const nextIndex = core ? core.nextFieldIndex(enterOrder, index) : -1;
      if (nextIndex >= 0) {
        document.getElementById(enterOrder[nextIndex])?.focus();
      } else {
        form.requestSubmit ? form.requestSubmit() : form.querySelector("button[type=submit]")?.click();
      }
    });
  });

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const button = form.querySelector("button[type=submit]");
    button.disabled = true;
    try {
      const requestedNo = prefillCore().normalizeWorkOrderNo(document.getElementById("machtileWoNo").value);
      if (!stepsLoaded || stepRecordNo !== requestedNo) await lookupAndPrefill();
      if (!stepsLoaded || stepRecordNo !== requestedNo) throw new Error("工序資料未確認，請重新查詢工單。");
      const selectedProcess = stepRecord?.processes?.find(p => p.id === stepSelect.value) || null;
      if (stepRecord?.processes?.length && !selectedProcess) throw new Error("請先選擇要更新哪一道工序。");
      if (selectedProcess && !selectedProcess.progressVerified) throw new Error("這道工序報工資料無法讀取，暫不能更新。");
      const processOrder = selectedProcess ? Number(selectedProcess.process_order) : Number(document.getElementById("machtileWoNewStep").value);
      if (!Number.isInteger(processOrder) || processOrder < 1) throw new Error("請填寫大於 0 的整數步序。");
      const payload = {
        work_order_no: document.getElementById("machtileWoNo").value.trim(),
        part_no: document.getElementById("machtileWoPartNo").value.trim(),
        part_name: document.getElementById("machtileWoPartName").value.trim(),
        quantity: Number(document.getElementById("machtileWoQty").value),
        due_date: document.getElementById("machtileWoDue").value,
        machine_code: document.getElementById("machtileWoMachine").value || null,
        process_name: document.getElementById("machtileWoProcess").value.trim() || selectedProcess?.process_name || null,
        process_order: processOrder,
        ...(selectedProcess ? { process_id: selectedProcess.id } : {}),
      };
      // 舊 MES 派工來的單要改派機台 → 先講清楚會被同步蓋回去；按取消就不送。
      const existing = await machtileWoExistingForConfirm(payload.work_order_no, selectedProcess);
      if (machtileWoListCore()?.needsReassignConfirm(existing, payload.machine_code || "")) {
        const from = existing.machine_code || "未指派";
        const to = payload.machine_code || "暫不指派";
        const okToSend = window.confirm(
          `${payload.work_order_no} 是「舊 MES 派工」自動同步的工單。\n\n`
          + `這裡把機台從 ${from} 改成 ${to}，下一輪派工同步（約每 5 分鐘）可能被舊 MES 覆蓋回去。\n`
          + `要長久改派，請在舊 MES 派工。\n\n確定仍要在這裡改派嗎？`
        );
        if (!okToSend) {
          showToast("已取消改派，工單沒有變更");
          return;
        }
      }
      const result = await supabaseFetch("rpc/work_order_upsert", {
        method: "POST",
        body: JSON.stringify({ p_payload: payload }),
      });
      const machineText = result?.machine_code ? `，指派 ${result.machine_code}` : "（未指派）";
      showToast(`${result?.action === "created" ? "已建立" : "已更新"}工單 ${payload.work_order_no}${machineText}`);
      rememberRecentFromForm();
      machtileRefreshWorkOrderList();
      // card wall picks up the new/assigned order on next data load
      loadFromSupabase().then(renderAll).catch(() => {});
    } catch (error) {
      showToast(`工單儲存失敗：${machtileWoErrorText(error)}`);
    } finally {
      button.disabled = lookupFailed;
    }
  });
}

