// ---- Strict account management module (AM3; Edge Functions from AM2) ----

const amRoleLabels = {
  admin: "管理者",
  manager: "主管",
  planner: "排程",
  operator: "作業員",
  inspector: "品檢",
};

const amCreatableRoles = ["manager", "planner", "operator", "inspector"];

const amErrorMessages = {
  AUTH_REQUIRED: "請先登入正式環境帳號。",
  FORBIDDEN: "此帳號沒有執行這項操作的權限。",
  INVALID_PAYLOAD: "輸入內容不完整或格式錯誤（密碼至少 8 碼）。",
  ROLE_NOT_ALLOWED: "不能建立管理者帳號（管理者由平台管理）。",
  EMAIL_EXISTS: "這個 Email 已經有帳號了。",
  USER_NOT_FOUND: "找不到這個使用者。",
  SELF_TARGET: "不能對自己的帳號執行這項操作。",
  TENANT_EXISTS: "已經有同名的租戶了。",
  NOT_DELETABLE: "伺服器再次檢查後判定不能刪除，帳號沒有變動。",
  CONFIRM_MISMATCH: "輸入的帳號名稱不對，沒有刪除。",
  INTERNAL: "伺服器處理失敗，請稍後再試。",
};

const amUsersState = {
  status: "idle",
  users: [],
  message: "",
  messageKind: "",
  expandedResetId: "",
  expandedEditId: "",
  confirmStateId: "",
  // 2026-09-29 帳號管理 UI：伺服器使用紀錄（可不可以刪、人臉登記張數）。
  // null＝沒載入（功能未開或查詢失敗）→ 畫面不出現刪除與張數。
  usageById: null,
  usageNote: "",
  inactiveOpen: false,
  specialOpen: false,
  deleteOpenId: "",
  // 修改紀錄（am-list-user-audit）：展開中的帳號，與每個帳號最近 20 筆的載入結果。
  auditOpenId: "",
  auditById: {},
  // 所屬課別（owner 2026-10-06）：SQL RPC machine_departments_admin_list 的結果，key=auth_user_id。
  // deptStatus: idle｜ready｜missing（RPC 尚未部署→藏起課別區）｜error。
  deptById: {},
  deptStatus: "idle",
  deptSavingId: "",
};

// Pure rules (sorting / delete verdict / face entry) live in accountAdminCore.js.
const amAccountCore = typeof globalThis !== "undefined" ? globalThis.MachTileAccountAdminCore : null;

function amErrorText(code, fallback) {
  return amErrorMessages[code] || fallback || "操作失敗，請稍後再試。";
}

// Function-call result → message. A 403 from the manager scope gate carries `reason`
// (supabase/functions/_shared/accountPolicy.ts) which has its own plain-language text.
function amResultErrorText(result) {
  const reasonText = amAccountCore && result?.body?.reason ? amAccountCore.refusalText(result.body.reason) : "";
  return reasonText || amErrorText(result?.code, result?.body?.message);
}

function amViewerRole() {
  return String(machtileAuthState.role || "");
}

// options.quiet: a 401 is NOT treated as "session expired" (used by the read-only usage lookup,
// which must never throw the admin out or pop anything up — the page just shows "—").
async function amCallFunction(fnName, payload, options = {}) {
  const baseUrl = String(config.supabaseUrl || "").replace(/\/$/, "");
  const response = await fetch(`${baseUrl}/functions/v1/${fnName}`, {
    method: "POST",
    headers: {
      apikey: config.supabaseAnonKey,
      Authorization: `Bearer ${machtileSupabaseBearerToken()}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });
  if (response.status === 401 && !options.quiet) machtileHandleUnauthorized();
  let body = {};
  try {
    body = await response.json();
  } catch (error) {
    body = {};
  }
  return { ok: response.ok && body.status === "ok", code: body.code || "", body };
}

async function amFetchUsers() {
  const rows = await supabaseFetch("app_users?select=id,name,account,role,is_active,auth_user_id&order=created_at.asc");
  // Display order (self pinned, role order, disabled last) is decided at render time by
  // accountAdminCore.sortAccounts.
  return Array.isArray(rows) ? rows : [];
}

// Server facts per account (never signed in? any records? face enrolments?) from the
// am-list-user-usage Edge Function (read-only). Called when EITHER switch is on
// (accountAdminCore.usageMode): enableAccountDelete → delete buttons/locks;
// enableFaceStatus → 「已登記 N 張／未登記」. A missing/failed function never raises: the
// delete UI stays hidden and the face badge shows 「—」.
async function amFetchUsage() {
  amUsersState.usageNote = "";
  const mode = amAccountCore ? amAccountCore.usageMode(config) : { fetchUsage: false, deleteEnabled: false };
  if (!mode.fetchUsage) return null;
  const failNote = mode.deleteEnabled ? "使用紀錄暫時查不到，先不顯示刪除功能。" : "";
  try {
    const result = await amCallFunction("am-list-user-usage", {}, { quiet: true });
    if (!result.ok || !Array.isArray(result.body?.users)) {
      amUsersState.usageNote = failNote;
      return null;
    }
    const byId = {};
    result.body.users.forEach((row) => {
      if (row && row.appUserId) byId[row.appUserId] = row;
    });
    return byId;
  } catch (error) {
    amUsersState.usageNote = failNote;
    return null;
  }
}

// 所屬課別（車床課／銑床課）：一次讀完畫面上所有帳號（machine_departments_admin_list）。
// 權限、租戶、橋接帳號判斷都在伺服器；讀不到不擋帳號管理，只藏起課別。404＝RPC 還沒部署。
async function amFetchDepartments(users) {
  const ids = [...new Set((users || []).map((user) => user && user.auth_user_id).filter(Boolean))];
  if (!ids.length) return { status: "ready", byId: {} };
  try {
    const rows = await supabaseFetch("rpc/machine_departments_admin_list", {
      method: "POST",
      body: JSON.stringify({ p_auth_user_ids: ids }),
    });
    const byId = {};
    (Array.isArray(rows) ? rows : []).forEach((row) => {
      if (row && row.auth_user_id) byId[row.auth_user_id] = row;
    });
    return { status: "ready", byId };
  } catch (error) {
    const missing = amAccountCore
      ? amAccountCore.departmentErrorInfo(error).missing
      : /^404\b/.test(String(error?.message || ""));
    return { status: missing ? "missing" : "error", byId: {} };
  }
}

function amApplyDepartments(result) {
  amUsersState.deptById = result.byId;
  amUsersState.deptStatus = result.status;
}

async function amInitUsersModule() {
  const root = document.querySelector("[data-am-users-root]");
  if (!root) return;
  // owner 2026-09-30：主管（manager）也可以進來，但只能管作業員（accountAdminCore.accountPermissions；
  // 伺服器 am-* 函式另外強制同一套規則）。
  const canManage = amAccountCore
    ? amAccountCore.canManageAccounts(machtileAuthState.role)
    : machtileAuthState.role === "admin";
  if (!canManage) {
    root.innerHTML = `
      <section class="admin-side-note">
        <strong>需要管理者或主管帳號</strong>
        <p>員工帳號管理開放給廠內管理者（admin）與主管（manager；只能管作業員）。請改用管理者或主管帳號登入。</p>
      </section>
    `;
    return;
  }
  amUsersState.status = "loading";
  try {
    const [users, usageById] = await Promise.all([amFetchUsers(), amFetchUsage()]);
    amUsersState.users = users;
    amUsersState.usageById = usageById;
    amApplyDepartments(await amFetchDepartments(users));
    amUsersState.status = "ready";
  } catch (error) {
    amUsersState.status = "error";
    amUsersState.message = `載入員工清單失敗：${error.message}`;
    amUsersState.messageKind = "error";
  }
  amRenderUsersModule();
}

function amStatusLine() {
  if (!amUsersState.message) return "";
  const tone = amUsersState.messageKind === "error" ? "color:#b42318" : "color:#067647";
  return `<p class="empty-note" style="${tone}" data-am-status>${escapeHtml(amUsersState.message)}</p>`;
}

function amRoleText(user, usage) {
  const group = amAccountCore ? amAccountCore.roleGroup(user, usage) : user.role;
  if (group === "station") return "站別";
  return amRoleLabels[user.role] || user.role;
}

function amRenderUserRow(user, selfId) {
  const usage = amUsersState.usageById ? amUsersState.usageById[user.id] : undefined;
  const isSelf = user.id === selfId;
  const isAdmin = user.role === "admin";
  const active = user.is_active !== false;
  const resetOpen = amUsersState.expandedResetId === user.id;
  const editOpen = amUsersState.expandedEditId === user.id;
  const confirmOpen = amUsersState.confirmStateId === user.id;
  const deleteOpen = amUsersState.deleteOpenId === user.id;
  const auditOpen = amUsersState.auditOpenId === user.id;
  // Who may touch this row (admin: unchanged rules; manager: plain operators only).
  const perm = amAccountCore
    ? amAccountCore.accountPermissions({ role: amViewerRole(), selfId }, user, usage)
    : { canEdit: !isAdmin, canReset: !isAdmin || isSelf, canToggle: !isAdmin && !isSelf, allowDelete: true, allowFace: true, lock: null };
  const { canReset, canEdit, canToggle } = perm;
  const viewerIsAdmin = amViewerRole() === "admin";
  // Delete UI only with enableAccountDelete AND usage loaded (flag off / lookup failed → none, not
  // even the self lock). The face badge has its own switch (enableFaceStatus).
  const mode = amAccountCore ? amAccountCore.usageMode(config) : { deleteEnabled: false, faceStatusEnabled: false };
  const verdict = amAccountCore && perm.allowDelete && mode.deleteEnabled && amUsersState.usageById
    ? amAccountCore.deleteVerdict(user, usage, selfId)
    : { show: false };
  const face = amAccountCore && perm.allowFace
    ? amAccountCore.faceEntry(user, usage, config.faceAdminUrl, { faceStatus: mode.faceStatusEnabled })
    : { show: false };
  const id = escapeHtml(user.id);
  const display = machtileAccountDisplay(user.account) || "-";
  const deptEntry = user.auth_user_id ? amUsersState.deptById[user.auth_user_id] : undefined;
  const deptBadge = amUsersState.deptStatus === "ready" && amAccountCore ? amAccountCore.departmentBadge(deptEntry) : null;
  const rowClass = ["admin-data-row", "am-user-row", active ? "is-active" : "is-inactive", isSelf ? "is-self" : ""]
    .filter(Boolean)
    .join(" ");

  let deleteHtml = "";
  if (verdict.show && verdict.canDelete) {
    deleteHtml = `<button type="button" class="am-delete-button" data-am-delete-open="${id}" title="${escapeHtml(verdict.title)}">${deleteOpen ? "收合" : "🗑 刪除"}</button>`;
  } else if (verdict.show) {
    deleteHtml = `<span class="am-lock" tabindex="0" title="${escapeHtml(verdict.title)}">${escapeHtml(verdict.text)}</span>`;
  } else if (perm.lock) {
    deleteHtml = `<span class="am-lock am-manager-lock" tabindex="0" title="${escapeHtml(perm.lock.title)}">${escapeHtml(perm.lock.text)}</span>`;
  } else if (viewerIsAdmin && isAdmin && !isSelf) {
    deleteHtml = `<span class="empty-note">平台管理</span>`;
  }

  let faceHtml = "";
  if (face.show && face.eligible) {
    const badge = face.badge
      ? `<small class="am-face-badge${face.badgeKind === "none" ? " is-none" : face.badgeKind === "unknown" ? " is-unknown" : ""}" title="${escapeHtml(face.badgeTitle || "")}">${escapeHtml(face.badge)}</small>`
      : "";
    faceHtml = `<span class="am-face"><a class="am-face-link" href="${escapeHtml(face.href)}" target="_blank" rel="noopener" title="開啟登入中心的人臉登記頁並標出這位員工（登記時本人要在場輸入密碼）">📷 人臉登記</a>${badge}</span>`;
  } else if (face.show) {
    faceHtml = `<small class="am-face-note">${escapeHtml(face.note)}</small>`;
  }

  // 系統／站別帳號（owner 2026-09-29：不要停用）：列上寫用途與停用影響；停用要多確認一次。
  const impact = amAccountCore ? amAccountCore.accountImpact(user, usage) : null;
  const guardedStop = Boolean(impact) && active && canToggle;
  const toggleButton = !canToggle ? "" : guardedStop
    ? (confirmOpen
      ? `<button type="button" data-am-toggle-cancel="${id}">取消停用</button>`
      : `<button type="button" data-am-toggle="${id}" data-am-next="false">停用</button>`)
    : `<button type="button" data-am-toggle="${id}" data-am-next="${active ? "false" : "true"}">${confirmOpen ? (active ? "確認停用？" : "確認啟用？") : (active ? "停用" : "啟用")}</button>`;

  return `
    <div class="${rowClass}" data-am-row="${id}">
      <div class="am-user-main">
        <strong>${escapeHtml(user.name || "-")}</strong>${isSelf ? `<span class="am-self-tag">👑 你</span>` : ""}
        <span class="am-user-account">${escapeHtml(display)}</span>
        ${deptBadge ? `<small class="am-dept-badge is-${escapeHtml(deptBadge.kind)}" title="${escapeHtml(deptBadge.title)}" data-am-dept-badge="${id}">${escapeHtml(deptBadge.text)}</small>` : ""}
        ${impact ? `<small class="am-impact">${escapeHtml(impact.purpose)}<span>⚠ ${escapeHtml(impact.impact)}</span></small>` : ""}
      </div>
      <span class="am-user-role">${escapeHtml(amRoleText(user, usage))}</span>
      <span class="am-status ${active ? "is-on" : "is-off"}">${active ? "● 啟用中" : "○ 已停用"}</span>
      <span class="am-user-actions">
        ${canEdit ? `<button type="button" data-am-edit-open="${id}">${editOpen ? "收合" : "編輯"}</button>` : ""}
        ${canReset ? `<button type="button" data-am-reset-open="${id}">${resetOpen ? "收合" : "重設密碼"}</button>` : ""}
        ${toggleButton}
        ${perm.manageable ? `<button type="button" class="am-audit-button" data-am-audit-open="${id}">${auditOpen ? "收合紀錄" : "🕘 修改紀錄"}</button>` : ""}
        ${faceHtml}
        ${deleteHtml}
      </span>
    </div>
    ${auditOpen ? amRenderAuditPanel(user.id) : ""}
    ${guardedStop && confirmOpen ? `
      <div class="admin-data-row am-sub-row am-stop-row" data-am-stop-row="${id}">
        <div class="am-sub-wide">
          <p class="am-delete-warn">確定要停用「${escapeHtml(user.name || display)}」？${escapeHtml(impact.impact)}</p>
          <p class="am-stop-note">${escapeHtml(impact.purpose)}一般不需要停用；真的不用了再停。</p>
        </div>
        <button type="button" class="am-delete-confirm" data-am-toggle="${id}" data-am-next="false" data-am-guard-confirmed="1">我了解影響，確認停用</button>
      </div>
    ` : ""}
    ${editOpen ? `
      <div class="admin-data-row am-sub-row" data-am-edit-row="${id}">
        <label class="admin-field">
          <span>姓名</span>
          <input type="text" value="${escapeHtml(user.name || "")}" data-am-edit-name="${id}">
        </label>
        <label class="admin-field am-sub-wide">
          <span>登入帳號（工號或 Email）</span>
          <input type="text" value="${escapeHtml(machtileAccountDisplay(user.account))}" data-am-edit-email="${id}">
        </label>
        <button type="button" data-am-edit-confirm="${id}">確認修改</button>
      </div>
      ${amRenderDepartmentField(user, deptEntry)}
    ` : ""}
    ${resetOpen ? `
      <div class="admin-data-row am-sub-row" data-am-reset-row="${id}">
        <label class="admin-field am-sub-wide">
          <span>新密碼（至少 8 碼）</span>
          ${machtilePasswordField(`<input type="password" autocomplete="new-password" data-am-reset-input="${id}">`)}
        </label>
        <button type="button" data-am-reset-confirm="${id}">確認重設</button>
      </div>
    ` : ""}
    ${deleteOpen && verdict.canDelete ? `
      <div class="admin-data-row am-sub-row am-delete-row" data-am-delete-row="${id}">
        <div class="am-sub-wide">
          <p class="am-delete-warn">確定要刪除「${escapeHtml(user.name || display)}」？刪除後無法復原。</p>
          <label class="admin-field">
            <span>請輸入帳號名稱「${escapeHtml(display)}」確認</span>
            <input type="text" autocomplete="off" autocapitalize="off" spellcheck="false" data-am-delete-input="${id}">
          </label>
        </div>
        <button type="button" class="am-delete-confirm" data-am-delete-confirm="${id}" disabled>確認刪除</button>
      </div>
    ` : ""}
  `;
}

function amRenderUsersModule() {
  const root = document.querySelector("[data-am-users-root]");
  if (!root) return;
  const selfId = amSelfAppUserId();
  const sorted = amAccountCore
    ? amAccountCore.sortAccounts(amUsersState.users, selfId, amUsersState.usageById || {})
    : { self: null, active: amUsersState.users, special: [], inactive: [] };
  const activeRows = [sorted.self, ...sorted.active]
    .filter(Boolean)
    .map((user) => amRenderUserRow(user, selfId))
    .join("");
  const specialCount = sorted.special.length;
  // Keep the section open while one of its rows is mid-confirmation / being edited.
  const specialOpen = amUsersState.specialOpen || sorted.special.some((user) => [
    amUsersState.confirmStateId, amUsersState.expandedEditId, amUsersState.expandedResetId,
  ].includes(user.id));
  const specialHtml = specialCount ? `
    <button type="button" class="am-inactive-toggle am-special-toggle" data-am-special-toggle aria-expanded="${specialOpen ? "true" : "false"}">
      系統與站別帳號（${specialCount}）${specialOpen ? "▾" : "▸"}
    </button>
    ${specialOpen ? `
      <p class="am-special-note">程式與機台平板共用的登入，不是個人帳號。請不要停用：停用會讓派工同步或機台報工中斷。</p>
      <div class="admin-data-table am-special-table">${sorted.special.map((user) => amRenderUserRow(user, selfId)).join("")}</div>
    ` : ""}
  ` : "";
  const inactiveCount = sorted.inactive.length;
  const inactiveOpen = amUsersState.inactiveOpen;
  const inactiveHtml = inactiveCount ? `
    <button type="button" class="am-inactive-toggle" data-am-inactive-toggle aria-expanded="${inactiveOpen ? "true" : "false"}">
      已停用（${inactiveCount}）${inactiveOpen ? "▾" : "▸"}
    </button>
    ${inactiveOpen ? `<div class="admin-data-table am-inactive-table">${sorted.inactive.map((user) => amRenderUserRow(user, selfId)).join("")}</div>` : ""}
  ` : "";
  const activeCount = amUsersState.users.filter((user) => user.is_active !== false).length;

  root.innerHTML = `
    <section class="admin-table-card am-users-card">
      <div class="admin-table-head">
        <strong>員工帳號</strong>
        <span>${amUsersState.users.length} 個帳號・啟用 ${activeCount}</span>
      </div>
      ${amStatusLine()}
      ${amUsersState.usageNote ? `<p class="empty-note">${escapeHtml(amUsersState.usageNote)}</p>` : ""}
      <div class="admin-data-table">
        ${activeRows || '<p class="empty-note">尚無帳號。</p>'}
      </div>
      ${specialHtml}
      ${inactiveHtml}
    </section>
    <section class="admin-form-card">
      <h3>新增員工帳號</h3>
      <div class="admin-form-grid">
        <label class="admin-field"><span>姓名</span><input type="text" data-am-new-name></label>
        <label class="admin-field"><span>登入帳號（工號或 Email）</span><input type="text" data-am-new-email></label>
        <label class="admin-field"><span>初始密碼（至少 8 碼）</span>${machtilePasswordField('<input type="password" autocomplete="new-password" data-am-new-password>')}</label>
        ${amCreateRoleField()}
      </div>
      <button class="admin-save-button" type="button" data-am-create>建立帳號</button>
      ${amViewerRole() === "manager"
        ? `<p class="empty-note" data-am-manager-note>主管只能新增作業員；新帳號可用系統為 MachTile Cloud（預設）。角色、可用系統、刪除帳號，以及主管／排程／品檢／系統與站別帳號，請找管理者。</p>`
        : `<p class="empty-note">管理者帳號由平台（super admin）建立，不能在此新增。</p>`}
    </section>
  `;
  amBindUsersModuleEvents();
}

// 所屬課別區（在「編輯」展開的表單下面，獨立的「儲存課別」按鈕，不跟姓名／帳號一起送）。
// RPC 未部署（404）或讀取失敗：只留一行說明，其他欄位照常可改。橋接帳號：鎖住不給改。
function amRenderDepartmentField(user, entry) {
  const id = escapeHtml(user.id);
  const status = amUsersState.deptStatus;
  const note = (text, attr = "") => `<p class="am-dept-note"${attr}>${escapeHtml(text)}</p>`;
  let body;
  let action = "";
  if (!amAccountCore || status === "missing") {
    body = note("課別設定尚未開通（伺服器還沒有這個功能），其他欄位照常可改。", " data-am-dept-unavailable");
  } else if (status !== "ready") {
    body = note("課別暫時讀不到，請稍後重新整理再試。", " data-am-dept-unavailable");
  } else if (!user.auth_user_id || !entry) {
    body = note("這個帳號沒有連結登入身分，不能設定課別。", ` data-am-dept-nologin="${id}"`);
  } else if (entry.is_bridge === true) {
    body = note("🔒 橋接／回寫帳號固定兩課，不能修改。", ` data-am-dept-locked="${id}"`);
  } else {
    const checked = amAccountCore.departmentChecked(entry);
    const saving = amUsersState.deptSavingId === user.id;
    const boxes = amAccountCore.DEPARTMENT_CODES.map((code) => `
          <label class="am-dept-check">
            <input type="checkbox" value="${code}" data-am-dept-check="${id}"${checked.includes(code) ? " checked" : ""}${saving ? " disabled" : ""}>
            <span>${escapeHtml(amAccountCore.DEPARTMENT_LABELS[code])}</span>
          </label>`).join("");
    const roleHint = ["admin", "manager", "planner"].includes(String(user.role))
      ? `<small class="am-dept-hint">管理者／主管／排程本來就看得到全部課別；這個設定只在作業員身上生效。</small>`
      : "";
    body = `
        <div class="am-dept-checks" role="group" aria-label="所屬課別">${boxes}</div>
        <small class="am-dept-hint">都不勾＝無課別：作業員在現場看不到任何機台。${entry.configured === false ? "目前尚未設定（預設兩課）。" : ""}</small>
        ${roleHint}`;
    action = `<button type="button" data-am-dept-save="${id}"${saving ? " disabled" : ""}>${saving ? "儲存中…" : "儲存課別"}</button>`;
  }
  return `
      <div class="admin-data-row am-sub-row am-dept-row" data-am-dept-row="${id}">
        <div class="am-sub-wide">
          <span class="am-dept-title">所屬課別（MachTile 機台）</span>
          ${body}
        </div>
        ${action}
      </div>`;
}

// Re-render while keeping what was typed (but not yet saved) in the name/account fields.
function amRenderKeepingEditDraft(id) {
  const root = document.querySelector("[data-am-users-root]");
  const name = root?.querySelector(`[data-am-edit-name="${id}"]`)?.value;
  const email = root?.querySelector(`[data-am-edit-email="${id}"]`)?.value;
  amRenderUsersModule();
  const nameInput = root?.querySelector(`[data-am-edit-name="${id}"]`);
  const emailInput = root?.querySelector(`[data-am-edit-email="${id}"]`);
  if (nameInput && name !== undefined) nameInput.value = name;
  if (emailInput && email !== undefined) emailInput.value = email;
}

async function amSaveDepartments(id) {
  const root = document.querySelector("[data-am-users-root]");
  const user = amUsersState.users.find((row) => row.id === id);
  if (!root || !user || !user.auth_user_id || !amAccountCore || amUsersState.deptSavingId) return;
  const codes = amAccountCore.departmentSelection(
    [...root.querySelectorAll(`[data-am-dept-check="${id}"]`)].filter((box) => box.checked).map((box) => box.value),
  );
  const name = user.name || machtileAccountDisplay(user.account);
  amUsersState.deptSavingId = id;
  amSetMessage("", "");
  amRenderKeepingEditDraft(id);
  try {
    const result = await supabaseFetch("rpc/machine_departments_admin_set", {
      method: "POST",
      body: JSON.stringify({ p_auth_user_id: user.auth_user_id, p_department_codes: codes }),
    });
    const saved = Array.isArray(result?.department_codes) ? result.department_codes : codes;
    amUsersState.deptById[user.auth_user_id] = {
      ...(amUsersState.deptById[user.auth_user_id] || {}),
      auth_user_id: user.auth_user_id,
      department_codes: saved,
      configured: true,
    };
    const text = amAccountCore.departmentText(saved);
    amSetMessage(result?.changed === false
      ? `「${name}」的課別沒有變動（${text}）。`
      : `已儲存「${name}」的課別：${text}。已留下修改紀錄。`, "ok");
    if (amUsersState.auditOpenId === id) amLoadAudit(id);
  } catch (error) {
    if (amAccountCore.departmentErrorInfo(error).missing) amUsersState.deptStatus = "missing";
    amSetMessage(amAccountCore.departmentErrorText(error), "error");
  }
  amUsersState.deptSavingId = "";
  amRenderKeepingEditDraft(id);
}

// 修改紀錄 panel under a row (最近 20 筆). Manager: the server only returns rows the manager wrote.
function amRenderAuditPanel(appUserId) {
  const slot = amUsersState.auditById[appUserId] || { status: "loading" };
  const scopeNote = amViewerRole() === "manager" ? "只顯示你做過的修改。" : "最近 20 筆，新的在上面。";
  let body;
  if (slot.status === "loading") {
    body = `<p class="empty-note">載入修改紀錄中…</p>`;
  } else if (slot.status === "error") {
    body = `<p class="empty-note" style="color:#b42318">修改紀錄暫時讀不到（${escapeHtml(slot.message || "請稍後再試")}）。</p>`;
  } else if (!slot.entries.length) {
    body = `<p class="empty-note">還沒有修改紀錄。</p>`;
  } else {
    body = `<ol class="am-audit-list">${slot.entries.map((entry) => {
      const v = amAccountCore ? amAccountCore.auditEntryView(entry) : { when: entry.at, who: "", what: entry.action, fields: [], warn: false };
      return `<li class="am-audit-item${v.warn ? " is-warn" : ""}">
        <span class="am-audit-when">${escapeHtml(v.when)}</span>
        <span class="am-audit-who">${escapeHtml(v.who)}</span>
        <strong class="am-audit-what">${escapeHtml(v.what)}</strong>
        ${v.fields.length ? `<span class="am-audit-fields">${v.fields.map((f) => escapeHtml(f)).join("<br>")}</span>` : ""}
      </li>`;
    }).join("")}</ol>`;
  }
  return `
    <div class="admin-data-row am-sub-row am-audit-row" data-am-audit-row="${escapeHtml(appUserId)}">
      <div class="am-sub-wide">
        <p class="am-audit-head">🕘 修改紀錄・${escapeHtml(scopeNote)}密碼內容不會被記錄。</p>
        ${body}
      </div>
    </div>
  `;
}

async function amLoadAudit(appUserId) {
  amUsersState.auditById[appUserId] = { status: "loading", entries: [] };
  amRenderUsersModule();
  try {
    const result = await amCallFunction("am-list-user-audit", { appUserId, limit: 20 }, { quiet: true });
    amUsersState.auditById[appUserId] = result.ok && Array.isArray(result.body?.entries)
      ? { status: "ready", entries: result.body.entries }
      : { status: "error", entries: [], message: amResultErrorText(result) };
  } catch (error) {
    amUsersState.auditById[appUserId] = { status: "error", entries: [], message: String(error?.message || error) };
  }
  if (amUsersState.auditOpenId === appUserId) amRenderUsersModule();
}

// Role field of the create form: admin picks from the four creatable roles (unchanged); a manager
// sees a fixed 「作業員」 (the server forces role=operator + systems ["cloud"] anyway).
function amCreateRoleField() {
  const roles = amAccountCore ? amAccountCore.creatableRoles(amViewerRole()) : amCreatableRoles;
  if (amViewerRole() === "manager") {
    return `<label class="admin-field"><span>角色</span><input type="text" value="${escapeHtml(amRoleLabels.operator)}（固定）" disabled data-am-new-role-fixed></label>`;
  }
  return `<label class="admin-field"><span>角色</span>
          <select data-am-new-role>
            ${roles.map((role) => `<option value="${role}">${escapeHtml(amRoleLabels[role])}</option>`).join("")}
          </select>
        </label>`;
}

function amSelfAppUserId() {
  const self = amUsersState.users.find((user) => (user.account || "").toLowerCase() === (machtileAuthState.email || "").toLowerCase());
  return self ? self.id : "";
}

function amSetMessage(message, kind) {
  amUsersState.message = message;
  amUsersState.messageKind = kind;
}

async function amReloadUsers() {
  // Any change may have added a history row: reload the open panel with the list.
  if (amUsersState.auditOpenId) amLoadAudit(amUsersState.auditOpenId);
  try {
    const [users, usageById] = await Promise.all([amFetchUsers(), amFetchUsage()]);
    amUsersState.users = users;
    amUsersState.usageById = usageById;
    amApplyDepartments(await amFetchDepartments(users));
  } catch (error) {
    amSetMessage(`重新載入失敗：${error.message}`, "error");
  }
  amRenderUsersModule();
}

function amBindUsersModuleEvents() {
  const root = document.querySelector("[data-am-users-root]");
  if (!root) return;

  root.querySelector("[data-am-inactive-toggle]")?.addEventListener("click", () => {
    amUsersState.inactiveOpen = !amUsersState.inactiveOpen;
    amRenderUsersModule();
  });

  root.querySelectorAll("[data-am-delete-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const id = button.getAttribute("data-am-delete-open");
      amUsersState.deleteOpenId = amUsersState.deleteOpenId === id ? "" : id;
      amUsersState.expandedEditId = "";
      amUsersState.expandedResetId = "";
      amUsersState.confirmStateId = "";
      amSetMessage("", "");
      amRenderUsersModule();
      root.querySelector(`[data-am-delete-input="${id}"]`)?.focus();
    });
  });

  root.querySelectorAll("[data-am-delete-input]").forEach((input) => {
    input.addEventListener("input", () => {
      const id = input.getAttribute("data-am-delete-input");
      const user = amUsersState.users.find((row) => row.id === id);
      const usage = amUsersState.usageById ? amUsersState.usageById[id] : undefined;
      const confirmButton = root.querySelector(`[data-am-delete-confirm="${id}"]`);
      if (confirmButton) {
        confirmButton.disabled = !(user && amAccountCore && amAccountCore.confirmMatches(user, input.value, usage));
      }
    });
  });

  root.querySelectorAll("[data-am-delete-confirm]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.getAttribute("data-am-delete-confirm");
      const user = amUsersState.users.find((row) => row.id === id);
      const typed = root.querySelector(`[data-am-delete-input="${id}"]`)?.value || "";
      const usage = amUsersState.usageById ? amUsersState.usageById[id] : undefined;
      if (!user || !amAccountCore || !amAccountCore.confirmMatches(user, typed, usage)) {
        amSetMessage(amErrorText("CONFIRM_MISMATCH"), "error");
        amRenderUsersModule();
        return;
      }
      button.disabled = true;
      button.textContent = "刪除中…";
      // The server re-checks every rule (never signed in, no records, not a station, …)
      // before deleting; this page only hides the button.
      const result = await amCallFunction("am-delete-user", { appUserId: id, confirmAccount: typed.trim() });
      amUsersState.deleteOpenId = "";
      const name = user.name || machtileAccountDisplay(user.account);
      if (result.ok) {
        amSetMessage(
          result.body?.code === "USER_DELETED_AUTH_KEPT"
            ? `已刪除帳號「${name}」；登入身分未能一併刪除，已改為永久停用，請通知平台管理員清理。`
            : `已刪除帳號「${name}」。`,
          "ok",
        );
      } else {
        const blockers = Array.isArray(result.body?.blockers) ? result.body.blockers : [];
        const why = blockers.length && amAccountCore
          ? amAccountCore.deleteVerdict(
            user,
            { blockers, deletable: false, reportCount: result.body?.reportCount, usageTotal: result.body?.usageTotal },
            "",
          ).text.replace(/^🔒\s*/, "")
          : "";
        amSetMessage(`${amResultErrorText(result)}${why ? `（${why}）` : ""}`, "error");
      }
      await amReloadUsers();
    });
  });

  root.querySelector("[data-am-create]")?.addEventListener("click", async (event) => {
    const button = event.currentTarget;
    const name = root.querySelector("[data-am-new-name]")?.value.trim() || "";
    const email = machtileAccountToEmail(root.querySelector("[data-am-new-email]")?.value);
    const passwordInput = root.querySelector("[data-am-new-password]");
    const password = passwordInput?.value || "";
    const role = amViewerRole() === "manager" ? "operator" : (root.querySelector("[data-am-new-role]")?.value || "");
    if (!name || !email) {
      amSetMessage("請填姓名與登入帳號。", "error");
      amRenderUsersModule();
      return;
    }
    if (password.length < 8) {
      amSetMessage("初始密碼至少 8 碼。", "error");
      amRenderUsersModule();
      return;
    }
    button.disabled = true;
    button.textContent = "建立中…";
    const result = await amCallFunction("am-create-user", { email, password, name, role });
    if (passwordInput) passwordInput.value = "";
    if (result.ok) {
      amSetMessage(`已建立帳號 ${machtileAccountDisplay(email)}（${amRoleLabels[role] || role}）。`, "ok");
      amUsersState.expandedResetId = "";
      amUsersState.confirmStateId = "";
      await amReloadUsers();
    } else {
      amSetMessage(amResultErrorText(result), "error");
      amRenderUsersModule();
    }
  });

  root.querySelectorAll("[data-am-reset-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const id = button.getAttribute("data-am-reset-open");
      amUsersState.expandedResetId = amUsersState.expandedResetId === id ? "" : id;
      amUsersState.expandedEditId = "";
      amUsersState.confirmStateId = "";
      amSetMessage("", "");
      amRenderUsersModule();
    });
  });

  root.querySelectorAll("[data-am-edit-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const id = button.getAttribute("data-am-edit-open");
      amUsersState.expandedEditId = amUsersState.expandedEditId === id ? "" : id;
      amUsersState.expandedResetId = "";
      amUsersState.confirmStateId = "";
      amSetMessage("", "");
      amRenderUsersModule();
    });
  });

  root.querySelectorAll("[data-am-edit-confirm]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.getAttribute("data-am-edit-confirm");
      const user = amUsersState.users.find((row) => row.id === id);
      const newName = root.querySelector(`[data-am-edit-name="${id}"]`)?.value.trim() || "";
      const newEmail = machtileAccountToEmail(root.querySelector(`[data-am-edit-email="${id}"]`)?.value);
      if (!newName || !newEmail) {
        amSetMessage("請填姓名與登入帳號。", "error");
        amRenderUsersModule();
        return;
      }
      if (user && newName === (user.name || "") && newEmail === (user.account || "").toLowerCase()) {
        amSetMessage("沒有變更任何內容。", "error");
        amRenderUsersModule();
        return;
      }
      button.disabled = true;
      button.textContent = "修改中…";
      const result = await amCallFunction("am-update-user", { appUserId: id, newEmail, newName });
      if (result.ok) {
        amSetMessage(`已更新帳號資料${result.body?.emailChanged ? "；下次請用新 Email 登入" : ""}。`, "ok");
        amUsersState.expandedEditId = "";
        await amReloadUsers();
      } else {
        amSetMessage(amResultErrorText(result), "error");
        amRenderUsersModule();
      }
    });
  });

  root.querySelectorAll("[data-am-dept-save]").forEach((button) => {
    button.addEventListener("click", () => amSaveDepartments(button.getAttribute("data-am-dept-save")));
  });

  root.querySelectorAll("[data-am-reset-confirm]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.getAttribute("data-am-reset-confirm");
      const input = root.querySelector(`[data-am-reset-input="${id}"]`);
      const newPassword = input?.value || "";
      if (newPassword.length < 8) {
        amSetMessage(amErrorText("INVALID_PAYLOAD"), "error");
        amRenderUsersModule();
        return;
      }
      button.disabled = true;
      button.textContent = "重設中…";
      const result = await amCallFunction("am-reset-password", { appUserId: id, newPassword });
      if (input) input.value = "";
      if (result.ok) {
        amSetMessage(amAccountCore ? amAccountCore.resetDoneMessage(result.body) : "密碼已重設。", "ok");
        amUsersState.expandedResetId = "";
        if (amUsersState.auditOpenId === id) amLoadAudit(id);
      } else {
        amSetMessage(amResultErrorText(result), "error");
      }
      amRenderUsersModule();
    });
  });

  root.querySelectorAll("[data-am-audit-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const id = button.getAttribute("data-am-audit-open");
      amUsersState.auditOpenId = amUsersState.auditOpenId === id ? "" : id;
      if (amUsersState.auditOpenId) amLoadAudit(id);
      else amRenderUsersModule();
    });
  });

  root.querySelector("[data-am-special-toggle]")?.addEventListener("click", () => {
    amUsersState.specialOpen = !amUsersState.specialOpen;
    amRenderUsersModule();
  });

  root.querySelectorAll("[data-am-toggle-cancel]").forEach((button) => {
    button.addEventListener("click", () => {
      amUsersState.confirmStateId = "";
      amRenderUsersModule();
    });
  });

  root.querySelectorAll("[data-am-toggle]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.getAttribute("data-am-toggle");
      const nextActive = button.getAttribute("data-am-next") === "true";
      if (amUsersState.confirmStateId !== id) {
        amUsersState.confirmStateId = id;
        amSetMessage("", "");
        amRenderUsersModule();
        return;
      }
      // System / station accounts: only the button inside the impact box may actually disable.
      const target = amUsersState.users.find((row) => row.id === id);
      const targetUsage = amUsersState.usageById ? amUsersState.usageById[id] : undefined;
      if (!nextActive && target && amAccountCore && amAccountCore.accountImpact(target, targetUsage)
        && button.getAttribute("data-am-guard-confirmed") !== "1") {
        return;
      }
      button.disabled = true;
      const result = await amCallFunction("am-set-user-state", { appUserId: id, active: nextActive });
      amUsersState.confirmStateId = "";
      if (result.ok) {
        amSetMessage(nextActive ? "帳號已重新啟用。" : "帳號已停用（無法再登入）。", "ok");
        await amReloadUsers();
      } else {
        amSetMessage(amResultErrorText(result), "error");
        amRenderUsersModule();
      }
    });
  });
}

// ---- Platform admin module (AM4; super-admin Edge Functions) ----
//
// Strict mode + platform_role='super_admin' only. Backed by am-list-tenants /
// am-create-tenant / am-reset-tenant-admin / am-set-platform-role; the same
// amCallFunction chokepoint (session Bearer) and error map are reused.

const amPlatformState = {
  status: "idle",
  tenants: [],
  message: "",
  messageKind: "",
  expandedResetId: "",
  confirmStateId: "",
  confirmRoleAction: "",
};

function renderPlatformModule() {
  if (!machtileStrictMode() || machtileAuthState.platformRole !== "super_admin") {
    return `
      <section class="admin-side-note">
        <strong>需要平台管理員</strong>
        <p>平台管理只開放給 MachTile 平台管理員（super admin）。</p>
      </section>
    `;
  }
  setTimeout(amInitPlatformModule, 0);
  return `<div data-am-platform-root><p class="empty-note">載入租戶清單中…</p></div>`;
}

function amPlatformSetMessage(message, kind) {
  amPlatformState.message = message;
  amPlatformState.messageKind = kind;
}

function amPlatformStatusLine() {
  if (!amPlatformState.message) return "";
  const tone = amPlatformState.messageKind === "error" ? "color:#b42318" : "color:#067647";
  return `<p class="empty-note" style="${tone}" data-am-platform-status>${escapeHtml(amPlatformState.message)}</p>`;
}

async function amInitPlatformModule() {
  const root = document.querySelector("[data-am-platform-root]");
  if (!root) return;
  amPlatformState.status = "loading";
  const result = await amCallFunction("am-list-tenants", {});
  if (result.ok) {
    amPlatformState.tenants = Array.isArray(result.body?.tenants) ? result.body.tenants : [];
    amPlatformState.status = "ready";
  } else {
    amPlatformState.status = "error";
    amPlatformSetMessage(amErrorText(result.code, result.body?.message), "error");
  }
  amRenderPlatformModule();
}

async function amReloadPlatformTenants() {
  const result = await amCallFunction("am-list-tenants", {});
  if (result.ok) {
    amPlatformState.tenants = Array.isArray(result.body?.tenants) ? result.body.tenants : [];
  } else {
    amPlatformSetMessage(amErrorText(result.code, result.body?.message), "error");
  }
  amRenderPlatformModule();
}

function amRenderPlatformModule() {
  const root = document.querySelector("[data-am-platform-root]");
  if (!root) return;
  const selfEmail = (machtileAuthState.email || "").toLowerCase();
  const tenantRows = amPlatformState.tenants.map((tenant) => {
    const admins = Array.isArray(tenant.admins) ? tenant.admins : [];
    const adminRows = admins.map((admin) => {
      const isSelf = (admin.account || "").toLowerCase() === selfEmail;
      const resetOpen = amPlatformState.expandedResetId === admin.id;
      const confirmOpen = amPlatformState.confirmStateId === admin.id;
      return `
        <div class="admin-data-row" data-am-platform-admin-row="${escapeHtml(admin.id)}">
          <strong>${escapeHtml(admin.name || "-")}</strong>
          <span>${escapeHtml(admin.account || "-")}</span>
          <span>管理者${isSelf ? "（自己）" : ""}</span>
          <span>${admin.isActive ? "啟用中" : "已停用"}</span>
          <span>
            <button type="button" data-am-platform-reset-open="${escapeHtml(admin.id)}">${resetOpen ? "收合" : "重設密碼"}</button>
            ${isSelf ? "" : `<button type="button" data-am-platform-toggle="${escapeHtml(admin.id)}" data-am-next="${admin.isActive ? "false" : "true"}">${confirmOpen ? (admin.isActive ? "確認停用？" : "確認啟用？") : (admin.isActive ? "停用" : "啟用")}</button>`}
          </span>
        </div>
        ${resetOpen ? `
          <div class="admin-data-row" data-am-platform-reset-row="${escapeHtml(admin.id)}">
            <label class="admin-field" style="grid-column: 1 / -2;">
              <span>新密碼（至少 8 碼）</span>
              <input type="password" autocomplete="new-password" data-am-platform-reset-input="${escapeHtml(admin.id)}">
            </label>
            <button type="button" data-am-platform-reset-confirm="${escapeHtml(admin.id)}">確認重設</button>
          </div>
        ` : ""}
      `;
    }).join("");
    return `
      <div class="admin-data-row">
        <strong>${escapeHtml(tenant.name || "-")}</strong>
        <span>${tenant.isActive ? "啟用中" : "已停用"}</span>
        <span>${Number(tenant.userCount) || 0} 個帳號</span>
        <span>${admins.length} 位管理者</span>
      </div>
      ${adminRows}
    `;
  }).join("");

  root.innerHTML = `
    <section class="admin-table-card">
      <div class="admin-table-head">
        <strong>租戶清單</strong>
        <span>${amPlatformState.tenants.length} 個租戶</span>
      </div>
      ${amPlatformStatusLine()}
      <div class="admin-data-table">
        ${tenantRows || '<p class="empty-note">尚無租戶。</p>'}
      </div>
    </section>
    <section class="admin-form-card">
      <h3>建立新租戶</h3>
      <div class="admin-form-grid">
        <label class="admin-field"><span>租戶名稱（工廠）</span><input type="text" data-am-tenant-name></label>
        <label class="admin-field"><span>廠區代碼（預設 F1）</span><input type="text" data-am-factory-code placeholder="F1"></label>
        <label class="admin-field"><span>廠區名稱（預設同租戶名）</span><input type="text" data-am-factory-name></label>
        <label class="admin-field"><span>管理者姓名</span><input type="text" data-am-tenant-admin-name></label>
        <label class="admin-field"><span>管理者 Email（登入帳號）</span><input type="email" data-am-tenant-admin-email></label>
        <label class="admin-field"><span>管理者初始密碼（至少 8 碼）</span><input type="password" autocomplete="new-password" data-am-tenant-admin-password></label>
      </div>
      <button class="admin-save-button" type="button" data-am-tenant-create>建立租戶</button>
      <p class="empty-note">會同時建立租戶、預設廠區與該廠的第一位管理者帳號。</p>
    </section>
    <section class="admin-form-card">
      <h3>平台管理員（super admin）</h3>
      <div class="admin-form-grid">
        <label class="admin-field"><span>帳號 Email</span><input type="email" data-am-platform-role-email></label>
      </div>
      <button class="admin-save-button" type="button" data-am-platform-role-set data-am-grant="true">${amPlatformState.confirmRoleAction === "grant" ? "確認授予？" : "授予平台管理員"}</button>
      <button class="admin-save-button" type="button" data-am-platform-role-set data-am-grant="false">${amPlatformState.confirmRoleAction === "revoke" ? "確認撤銷？" : "撤銷平台管理員"}</button>
      <p class="empty-note">平台管理員可建立租戶與管理各廠管理者；不能變更自己的平台角色。</p>
    </section>
  `;
  amBindPlatformModuleEvents();
}

function amBindPlatformModuleEvents() {
  const root = document.querySelector("[data-am-platform-root]");
  if (!root) return;

  root.querySelector("[data-am-tenant-create]")?.addEventListener("click", async (event) => {
    const button = event.currentTarget;
    const tenantName = root.querySelector("[data-am-tenant-name]")?.value.trim() || "";
    const factoryCode = root.querySelector("[data-am-factory-code]")?.value.trim() || "";
    const factoryName = root.querySelector("[data-am-factory-name]")?.value.trim() || "";
    const adminName = root.querySelector("[data-am-tenant-admin-name]")?.value.trim() || "";
    const adminEmail = root.querySelector("[data-am-tenant-admin-email]")?.value.trim() || "";
    const passwordInput = root.querySelector("[data-am-tenant-admin-password]");
    const adminPassword = passwordInput?.value || "";
    if (!tenantName || !adminName || !adminEmail || adminPassword.length < 8) {
      amPlatformSetMessage(amErrorText("INVALID_PAYLOAD"), "error");
      amRenderPlatformModule();
      return;
    }
    button.disabled = true;
    button.textContent = "建立中…";
    const result = await amCallFunction("am-create-tenant", {
      tenantName,
      factoryCode,
      factoryName,
      adminName,
      adminEmail,
      adminPassword,
    });
    if (passwordInput) passwordInput.value = "";
    if (result.ok) {
      amPlatformSetMessage(`已建立租戶 ${tenantName}，管理者 ${adminEmail}。`, "ok");
      amPlatformState.expandedResetId = "";
      amPlatformState.confirmStateId = "";
      await amReloadPlatformTenants();
    } else {
      amPlatformSetMessage(amErrorText(result.code, result.body?.message), "error");
      amRenderPlatformModule();
    }
  });

  root.querySelectorAll("[data-am-platform-reset-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const id = button.getAttribute("data-am-platform-reset-open");
      amPlatformState.expandedResetId = amPlatformState.expandedResetId === id ? "" : id;
      amPlatformState.confirmStateId = "";
      amPlatformSetMessage("", "");
      amRenderPlatformModule();
    });
  });

  root.querySelectorAll("[data-am-platform-reset-confirm]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.getAttribute("data-am-platform-reset-confirm");
      const input = root.querySelector(`[data-am-platform-reset-input="${id}"]`);
      const newPassword = input?.value || "";
      if (newPassword.length < 8) {
        amPlatformSetMessage(amErrorText("INVALID_PAYLOAD"), "error");
        amRenderPlatformModule();
        return;
      }
      button.disabled = true;
      button.textContent = "重設中…";
      const result = await amCallFunction("am-reset-tenant-admin", { appUserId: id, action: "reset_password", newPassword });
      if (input) input.value = "";
      if (result.ok) {
        amPlatformSetMessage("管理者密碼已重設。", "ok");
        amPlatformState.expandedResetId = "";
      } else {
        amPlatformSetMessage(amErrorText(result.code, result.body?.message), "error");
      }
      amRenderPlatformModule();
    });
  });

  root.querySelectorAll("[data-am-platform-toggle]").forEach((button) => {
    button.addEventListener("click", async () => {
      const id = button.getAttribute("data-am-platform-toggle");
      const nextActive = button.getAttribute("data-am-next") === "true";
      if (amPlatformState.confirmStateId !== id) {
        amPlatformState.confirmStateId = id;
        amPlatformSetMessage("", "");
        amRenderPlatformModule();
        return;
      }
      button.disabled = true;
      const result = await amCallFunction("am-reset-tenant-admin", { appUserId: id, action: "set_state", active: nextActive });
      amPlatformState.confirmStateId = "";
      if (result.ok) {
        amPlatformSetMessage(nextActive ? "管理者帳號已重新啟用。" : "管理者帳號已停用（無法再登入）。", "ok");
        await amReloadPlatformTenants();
      } else {
        amPlatformSetMessage(amErrorText(result.code, result.body?.message), "error");
        amRenderPlatformModule();
      }
    });
  });

  root.querySelectorAll("[data-am-platform-role-set]").forEach((button) => {
    button.addEventListener("click", async () => {
      const grant = button.getAttribute("data-am-grant") === "true";
      const action = grant ? "grant" : "revoke";
      const email = root.querySelector("[data-am-platform-role-email]")?.value.trim() || "";
      if (!email) {
        amPlatformSetMessage(amErrorText("INVALID_PAYLOAD"), "error");
        amRenderPlatformModule();
        return;
      }
      if (amPlatformState.confirmRoleAction !== action) {
        amPlatformState.confirmRoleAction = action;
        amPlatformSetMessage("", "");
        const emailInput = root.querySelector("[data-am-platform-role-email]");
        const typed = emailInput ? emailInput.value : "";
        amRenderPlatformModule();
        const rerendered = document.querySelector("[data-am-platform-role-email]");
        if (rerendered) rerendered.value = typed;
        return;
      }
      button.disabled = true;
      const result = await amCallFunction("am-set-platform-role", { email, grant });
      amPlatformState.confirmRoleAction = "";
      if (result.ok) {
        amPlatformSetMessage(grant ? `已授予 ${email} 平台管理員。` : `已撤銷 ${email} 的平台管理員。`, "ok");
      } else {
        amPlatformSetMessage(amErrorText(result.code, result.body?.message), "error");
      }
      amRenderPlatformModule();
    });
  });
}

function renderInviteModule() {
  const invites = [
    ["MT-OP-LATHE", "operator", "車床課", "30 天"],
    ["MT-OP-MILL", "operator", "銑床課", "30 天"],
    ["MT-QA-DEMO", "inspector", "品檢", "30 天"],
    ["MT-MGR-DEMO", "manager", "主管", "30 天"],
  ];
  return renderSimpleAdminList("邀請碼", invites, "生成新邀請碼");
}

function renderVendorModule() {
  const vendors = [
    ["外包熱處理", "外包商", "只能看指派工單", "待啟用"],
    ["I-Reporter", "品檢系統", "品檢與追溯資料", "已規劃"],
    ["油品供應商", "保養協作", "機台保養資訊", "選配"],
  ];
  return renderSimpleAdminList("外部授權", vendors, "新增授權對象");
}

// 公司資料真做（2026-07-13）：strict 模式接 company_profile_upsert；
// 廠區名稱＝頁首品牌來源，存檔後品牌即時刷新。Dev 免登入維持 mock 示範。
function machtileCanManageCompany() {
  return machtileStrictMode() && machtileSessionActive()
    && ["admin", "manager"].includes(machtileAuthState.role);
}

function renderCompanyModule() {
  if (machtileStrictMode() && machtileSessionActive()) {
    if (!machtileCanManageCompany()) {
      return `<p class="admin-module-note">此功能需要管理者或主管權限的正式環境帳號。</p>`;
    }
    return `
      <form id="machtileCompanyForm" class="admin-module-form">
        <label class="admin-field"><span>公司名稱 *</span>
          <input id="machtileCoName" type="text" required></label>
        <label class="admin-field"><span>統一編號（選填）</span>
          <input id="machtileCoTaxId" type="text"></label>
        <label class="admin-field"><span>聯絡人（選填）</span>
          <input id="machtileCoContact" type="text"></label>
        <label class="admin-field"><span>電話（選填）</span>
          <input id="machtileCoPhone" type="text"></label>
        <label class="admin-field"><span>地址（選填）</span>
          <input id="machtileCoAddress" type="text"></label>
        <label class="admin-field"><span>廠區名稱（顯示在每頁左上角）</span>
          <input id="machtileCoFactory" type="text" placeholder="例：主廠區"></label>
        <button class="admin-save-button" type="submit">儲存公司資料</button>
        <p class="admin-module-note">廠區名稱改了之後，頁首品牌立刻跟著換。</p>
      </form>
    `;
  }
  return `
    <section class="admin-form-card">
      <h3>公司與部署設定</h3>
      <div class="admin-form-grid">
        ${adminField("公司名稱", "MachTile Demo Factory")}
        ${adminField("聯絡人", "張家維")}
        ${adminField("電話", "02-0000-0000")}
        ${adminSelect("部署模式", ["cloud_saas", "dedicated_cloud", "on_premise"], "cloud_saas")}
        ${adminField("資料保留天數", "1095", "number")}
        ${adminField("時區", "Asia/Taipei")}
      </div>
      ${adminSaveButton("儲存公司資料")}
    </section>
  `;
}

async function machtileInitCompanyModule() {
  const form = document.getElementById("machtileCompanyForm");
  if (!form) return;
  try {
    const [settings, factories] = await Promise.all([
      supabaseFetch("company_settings?select=company_name,tax_id,contact_name,phone,address&limit=1"),
      supabaseFetch("factories?select=name&is_active=eq.true&order=factory_code&limit=1"),
    ]);
    const row = Array.isArray(settings) && settings[0] ? settings[0] : {};
    document.getElementById("machtileCoName").value = row.company_name || "";
    document.getElementById("machtileCoTaxId").value = row.tax_id || "";
    document.getElementById("machtileCoContact").value = row.contact_name || "";
    document.getElementById("machtileCoPhone").value = row.phone || "";
    document.getElementById("machtileCoAddress").value = row.address || "";
    document.getElementById("machtileCoFactory").value = Array.isArray(factories) && factories[0] ? (factories[0].name || "") : "";
  } catch (error) {
    console.warn("company profile prefill failed", error);
  }
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const button = form.querySelector("button[type=submit]");
    button.disabled = true;
    try {
      const payload = {
        company_name: document.getElementById("machtileCoName").value.trim(),
        tax_id: document.getElementById("machtileCoTaxId").value.trim() || null,
        contact_name: document.getElementById("machtileCoContact").value.trim() || null,
        phone: document.getElementById("machtileCoPhone").value.trim() || null,
        address: document.getElementById("machtileCoAddress").value.trim() || null,
        factory_name: document.getElementById("machtileCoFactory").value.trim() || null,
      };
      await supabaseFetch("rpc/company_profile_upsert", {
        method: "POST",
        body: JSON.stringify({ p_payload: payload }),
      });
      showToast("公司資料已儲存");
      machtileApplyBranding();
    } catch (error) {
      const msg = String(error?.message || error || "");
      showToast(`儲存失敗：${msg.includes("FORBIDDEN") ? "此帳號沒有公司資料權限（需管理者/主管）。" : msg}`);
    } finally {
      button.disabled = false;
    }
  });
}

function renderTemplateModule() {
  const templates = [
    ["鋸料", "material_prep", "可選機台", "非必要品檢"],
    ["CNC 車削", "cnc_lathe", "車床課", "可要求首件"],
    ["CNC 銑削", "cnc_mill", "銑床課", "可要求首件"],
    ["去毛邊", "manual", "人工站", "完成回報"],
    ["品檢", "inspection", "品檢區", "必填結果"],
    ["包裝", "packing", "出貨前", "完成結案"],
  ];
  return renderSimpleAdminList("製程模板", templates, "新增製程模板");
}

// G-code 估時 v2：保留 FANUC/EIA 輕量解析，並透過獨立核心加入各軸速度／加速度、
// 短行程三角速度與長行程梯形速度模型。未設定加速度時明確回退 v1 等速模型。
// 演算法參考 CAMotics 設計思想與 MIT 授權 gcodeEstimator（無程式碼移植）。
// 已知限制：M98 子程式/宏不展開（列警告）、G95 每轉進給以 F×S 近似、天真模型 ±20~30%，
// 之後用加工履歷（H1）校正收斂。
function machtileEstimateGcode(text, params = {}) {
  const configuredLimits = config.gcodeEstimatorLimits || {};
  const rapidRateCap = Number(configuredLimits.rapidRateMmMin) || 40000;
  const maxFeedRateCap = Number(configuredLimits.maxFeedRateMmMin) || 10000;
  const requestedRapidRate = Number(params.rapidRate) || rapidRateCap;
  const requestedMaxFeedRate = Number(params.maxFeedRateMmMin) || maxFeedRateCap;
  const rapidRate = Math.min(requestedRapidRate, rapidRateCap); // mm/min
  const maxFeedRate = Math.min(requestedMaxFeedRate, maxFeedRateCap);
  const toolChangeSec = Number(params.toolChangeSeconds) || 4.5;
  const segmentOverheadSec = 0.04; // 控制器逐段處理時間近似；加減速由 v2 核心負責
  const estimatorCore = globalThis.MachTileGcodeEstimatorCore;
  const motionProfile = estimatorCore?.createMachineProfile({
    rapidRate,
    maxFeedRateMmMin: maxFeedRate,
    accelerationMmSec2: params.accelerationMmSec2,
    axes: params.axes,
  });
  let accelerationAwareSegments = 0;
  const estimateMotion = (distanceMm, requestedRateMmMin, rapid, deltas = {}) => {
    const cappedRateMmMin = Math.min(requestedRateMmMin, rapid ? rapidRate : maxFeedRate);
    if (!estimatorCore || !motionProfile) return (distanceMm / cappedRateMmMin) * 60;
    const estimate = estimatorCore.estimateMotionSeconds({
      distanceMm,
      requestedRateMmMin: cappedRateMmMin,
      rapid,
      deltas,
      profile: motionProfile,
    });
    if (estimate.model === "acceleration-aware") accelerationAwareSegments += 1;
    return estimate.seconds;
  };
  // 車床模式：dialect 'lathe' 或 auto 偵測（G96 恆線速 / G71~G76 車削循環）
  const sourceText = String(text);
  const lathe = params.dialect === "lathe"
    || (params.dialect !== "mill" && /\bG9[69]\b|\bG7[0-6]\s*P|\bG7[126]\s*U/i.test(sourceText));
  const state = {
    x: 0, y: 0, z: 0,
    feed: 0, spindle: 0, css: 0, maxRpm: 4000,
    motion: null, absolute: true, unitScale: 1, feedPerRev: lathe,
  };
  let cuttingSec = 0, rapidSec = 0, dwellSec = 0, toolChanges = 0, segments = 0;
  const warnings = new Set();
  let subCalls = 0, missingFeed = 0;
  if (lathe) warnings.add("車床模式（X 直徑編程、每轉進給）");
  let pendingG71 = null; // 兩行式 G71/G72 第一行的 U(切深)/R(退刀)
  let pendingG76 = null; // 兩行式 G76 第一行的 Q(最小切深)/R(精修)

  const parseLine = (rawLine) => {
    const line = rawLine.replace(/\(.*?\)/g, "").replace(/;.*$/, "").trim().toUpperCase();
    if (!line || line.startsWith("%") || /^O\d/.test(line)) return null;
    const words = line.match(/[A-Z][+-]?\d*\.?\d+/g) || [];
    if (!words.length) return null;
    const value = {};
    const gCodes = [];
    let toolChange = false;
    for (const word of words) {
      const letter = word[0];
      const num = parseFloat(word.slice(1));
      if (letter === "G") gCodes.push(num);
      else if (letter === "M") { if (num === 6) toolChange = true; if (num === 98) subCalls += 1; }
      else value[letter] = num;
    }
    return { value, gCodes, toolChange };
  };

  // 車床轉速：G96 恆線速依直徑換算（受 G50 上限），G97 直接轉速
  const rpmAt = (diameter) => {
    if (state.css > 0) {
      const d = Math.max(Math.abs(diameter), 1);
      return Math.min(state.maxRpm, (1000 * state.css) / (Math.PI * d));
    }
    return state.spindle || 1000;
  };
  const feedRateAt = (diameter) => {
    if (!state.feed) return 0;
    return state.feedPerRev ? state.feed * rpmAt(diameter) : state.feed;
  };

  const lines = sourceText.split(/\r?\n/);
  // N 行號索引（G71/G70/G76 的 P~Q 輪廓段查找）
  const nIndex = new Map();
  lines.forEach((rawLine, idx) => {
    const m = rawLine.trim().toUpperCase().match(/^N(\d+)/);
    if (m) nIndex.set(Number(m[1]), idx);
  });

  // 輪廓段快速模擬（車床 P~Q）：回傳切削路徑長（半徑座標）、最小直徑、Z 範圍
  const simulateContour = (fromN, toN) => {
    const start = nIndex.get(fromN);
    const end = nIndex.get(toN);
    if (start == null || end == null) return null;
    let cx = state.x, cz = state.z;
    let length = 0, minDia = state.x, zMin = state.z, zMax = state.z;
    for (let i = start; i <= end; i++) {
      const parsed = parseLine(lines[i]);
      if (!parsed) continue;
      const nx = parsed.value.X != null ? parsed.value.X * state.unitScale : cx;
      const nz = parsed.value.Z != null ? parsed.value.Z * state.unitScale : cz;
      length += Math.hypot((nx - cx) / 2, nz - cz);
      cx = nx; cz = nz;
      minDia = Math.min(minDia, cx);
      zMin = Math.min(zMin, cz); zMax = Math.max(zMax, cz);
    }
    return { length, minDia, zSpan: Math.max(Math.abs(zMax - zMin), 1) };
  };

  for (const rawLine of lines) {
    const parsed = parseLine(rawLine);
    if (!parsed) continue;
    const { value, gCodes } = parsed;
    const hasToolChange = parsed.toolChange;

    // F/S 先吸收（FANUC 同一行的 F 對本行循環/移動生效；S 依 G50/G96/G97 語境）
    if (value.F != null) state.feed = value.F * state.unitScale;
    if (value.S != null) {
      if (gCodes.includes(50)) state.maxRpm = value.S;
      else if (gCodes.includes(96)) state.css = value.S;
      else if (gCodes.includes(97)) { state.css = 0; state.spindle = value.S; }
      else if (state.css > 0) state.css = value.S;
      else state.spindle = value.S;
    }

    const isLatheCycleLine = lathe && gCodes.some((g) => g === 70 || g === 71 || g === 72 || g === 74 || g === 75 || g === 76);

    for (const g of gCodes) {
      if (g === 0 || g === 1 || g === 2 || g === 3) state.motion = g;
      else if (g === 20) state.unitScale = 25.4;
      else if (g === 21) state.unitScale = 1;
      else if (g === 90) state.absolute = true;
      else if (g === 91) state.absolute = false;
      else if (g === 94 || g === 98) state.feedPerRev = false;
      else if (g === 95 || (g === 99 && lathe)) state.feedPerRev = true;
      else if (g === 96) { if (state.css <= 0) state.css = state.spindle; }
      else if (g === 97) state.css = 0;
      else if (g === 4) {
        // FANUC G04：P 整數＝毫秒、X/P 帶小數＝秒
        const p = value.P; const xDwell = value.X;
        if (xDwell != null) dwellSec += xDwell;
        else if (p != null) dwellSec += Number.isInteger(p) && p > 100 ? p / 1000 : p;
      } else if (lathe && (g === 71 || g === 72)) {
        if (value.P == null) {
          pendingG71 = { depth: Math.abs(value.U || 2) * state.unitScale };
        } else {
          const contour = simulateContour(value.P, value.Q);
          const depthPerPass = pendingG71?.depth || 2;
          if (contour) {
            const finishAllow = Math.abs(value.U || 0) * state.unitScale / 2;
            const stockRadius = Math.max((state.x - contour.minDia) / 2 - finishAllow, depthPerPass);
            const passes = Math.max(1, Math.ceil(stockRadius / depthPerPass));
            const avgDia = (state.x + contour.minDia) / 2;
            const feed = feedRateAt(avgDia);
            const passLen = g === 71 ? contour.zSpan : Math.max((state.x - contour.minDia) / 2, 1);
            if (feed > 0) cuttingSec += passes * estimateMotion(passLen, feed, false, g === 71 ? { z: passLen } : { x: passLen });
            else missingFeed += 1;
            rapidSec += passes * (estimateMotion(passLen, rapidRate, true, g === 71 ? { z: passLen } : { x: passLen }) + 0.2);
            segments += passes;
            warnings.add(`G${g} 粗車循環以 ${passes} 刀近似`);
          } else warnings.add(`G${g} 找不到 P~Q 輪廓段，循環未估`);
          pendingG71 = null;
        }
      } else if (lathe && g === 70) {
        const contour = simulateContour(value.P, value.Q);
        if (contour) {
          const feed = feedRateAt((state.x + contour.minDia) / 2);
          if (feed > 0) { cuttingSec += estimateMotion(contour.length, feed, false); segments += 1; }
          else missingFeed += 1;
        } else warnings.add("G70 找不到 P~Q 輪廓段，精車未估");
      } else if (lathe && g === 76) {
        if (value.X == null) {
          pendingG76 = { minDepth: (value.Q || 100) / 1000 };
        } else {
          const height = (value.P || 0) / 1000; // 第二行 P＝牙深 μm
          const firstDepth = Math.max((value.Q || 350) / 1000, 0.01);
          let passes = height > 0 ? Math.max(1, Math.ceil(Math.pow(height / firstDepth, 2))) : 10;
          passes = Math.min(passes, 60);
          const lead = value.F != null ? value.F * state.unitScale : state.feed;
          const targetZ = value.Z != null ? value.Z * state.unitScale : state.z;
          const zLen = Math.max(Math.abs(targetZ - state.z), 5);
          const rpm = state.css > 0 ? rpmAt(value.X * state.unitScale) : (state.spindle || 500);
          if (lead > 0 && rpm > 0) cuttingSec += passes * estimateMotion(zLen, lead * rpm, false, { z: zLen });
          rapidSec += passes * (estimateMotion(zLen, rapidRate, true, { z: zLen }) + 0.2);
          segments += passes;
          warnings.add(`G76 螺紋循環以 ${passes} 刀近似`);
          pendingG76 = null;
        }
      } else if (lathe && (g === 74 || g === 75)) {
        warnings.add("含 G74/G75 啄式循環，以直接進給近似");
      } else if (!lathe && ((g >= 81 && g <= 89) || g === 73)) {
        // 銑床孔循環近似：進給下到 Z、快速回 R（G83 啄鑽以 1.5 倍近似）
        const r = (value.R ?? state.z) * state.unitScale;
        const zDepth = (value.Z ?? state.z) * state.unitScale;
        const plunge = Math.abs(r - zDepth);
        const feed = feedRateAt(state.x);
        if (feed > 0 && plunge > 0) {
          const factor = g === 83 || g === 73 ? 1.5 : 1;
          cuttingSec += estimateMotion(plunge * factor, feed, false, { z: plunge * factor });
          rapidSec += estimateMotion(plunge, rapidRate, true, { z: plunge });
          segments += 1;
        }
        warnings.add("含孔加工循環（G73/G81~G89），以單次進退刀近似");
      }
    }

    if (hasToolChange) { toolChanges += 1; }

    // 座標移動（G4 的 X/P 是暫停參數；車削循環行/孔循環另行處理；車床 U/W＝增量移動）
    const isDrillCycle = !lathe && gCodes.some((g) => (g >= 81 && g <= 89) || g === 73);
    const latheIncMove = lathe && !isLatheCycleLine && !gCodes.includes(50) && (value.U != null || value.W != null);
    const hasMove = value.X != null || value.Y != null || value.Z != null || latheIncMove;
    if (state.motion != null && hasMove && !gCodes.includes(4) && !isDrillCycle && !isLatheCycleLine && !gCodes.includes(50)) {
      let nx = value.X != null ? (state.absolute ? value.X * state.unitScale : state.x + value.X * state.unitScale) : state.x;
      const ny = value.Y != null ? (state.absolute ? value.Y * state.unitScale : state.y + value.Y * state.unitScale) : state.y;
      let nz = value.Z != null ? (state.absolute ? value.Z * state.unitScale : state.z + value.Z * state.unitScale) : state.z;
      if (lathe && value.U != null && value.X == null) nx = state.x + value.U * state.unitScale;
      if (lathe && value.W != null && value.Z == null) nz = state.z + value.W * state.unitScale;
      // 車床 X 為直徑值：實際刀具位移＝直徑差 ÷ 2
      let dist = lathe
        ? Math.hypot((nx - state.x) / 2, nz - state.z)
        : Math.hypot(nx - state.x, ny - state.y, nz - state.z);
      if (!lathe && (state.motion === 2 || state.motion === 3) && (value.I != null || value.J != null)) {
        // 圓弧長：由圓心 I/J 求夾角
        const cx = state.x + (value.I || 0) * state.unitScale;
        const cy = state.y + (value.J || 0) * state.unitScale;
        const r0 = Math.hypot(state.x - cx, state.y - cy);
        const a0 = Math.atan2(state.y - cy, state.x - cx);
        const a1 = Math.atan2(ny - cy, nx - cx);
        let sweep = state.motion === 2 ? a0 - a1 : a1 - a0;
        while (sweep <= 0) sweep += Math.PI * 2;
        if (r0 > 0) dist = Math.max(dist, sweep * r0);
      }
      if (dist > 0) {
        segments += 1;
        const linearDeltas = state.motion === 2 || state.motion === 3
          ? {}
          : {
              x: lathe ? (nx - state.x) / 2 : nx - state.x,
              y: ny - state.y,
              z: nz - state.z,
            };
        if (state.motion === 0) {
          rapidSec += estimateMotion(dist, rapidRate, true, linearDeltas) + segmentOverheadSec;
        } else {
          const feed = feedRateAt(lathe ? (state.x + nx) / 2 : state.x);
          if (feed > 0) cuttingSec += estimateMotion(dist, feed, false, linearDeltas) + segmentOverheadSec;
          else missingFeed += 1;
        }
      }
      state.x = nx; state.y = ny; state.z = nz;
    }
  }

  if (subCalls) warnings.add(`含 ${subCalls} 次子程式呼叫（M98），估時不含子程式內容`);
  if (missingFeed) warnings.add(`${missingFeed} 段切削缺 F 進給，已略過`);
  if (!estimatorCore) warnings.add("G-code Estimator v2 核心未載入，已回退 v1 等速模型");
  else if (!motionProfile.hasAcceleration) warnings.add("機台尚未設定加速度，快移／切削沿用 v1 等速模型");
  else if (accelerationAwareSegments) warnings.add(`已對 ${accelerationAwareSegments} 段套用加速度模型；連續轉角速度尚未納入，結果偏保守`);
  warnings.add(`速度上限採 ${configuredLimits.reference || "YCM TCV2000A"}：快移 ${rapidRateCap.toLocaleString("en-US")}、切削 ${maxFeedRateCap.toLocaleString("en-US")} mm/min`);
  const totalSec = Math.round(cuttingSec + rapidSec + dwellSec + toolChanges * toolChangeSec);
  return {
    estimatorVersion: "v2",
    motionModel: accelerationAwareSegments ? "acceleration-aware" : "constant-speed",
    accelerationAwareSegments,
    speedLimits: {
      rapidRateMmMin: rapidRate,
      maxFeedRateMmMin: maxFeedRate,
      reference: configuredLimits.reference || "YCM TCV2000A",
    },
    totalSeconds: totalSec,
    cuttingSeconds: Math.round(cuttingSec),
    rapidSeconds: Math.round(rapidSec),
    dwellSeconds: Math.round(dwellSec),
    toolChanges,
    segments,
    warnings: [...warnings],
  };
}

function machtileFormatDuration(seconds) {
  if (seconds == null) return "—";
  const m = Math.floor(seconds / 60);
  const s = Math.round(seconds % 60);
  return m ? `${m} 分 ${s} 秒` : `${s} 秒`;
}

// C CNC 程式版本管理（2026-07-14 夜間 sprint 3/3）：strict 排程以上真做——
// O 檔上傳到 private bucket、cnc_program_version_register 自動編版、行級差異比對。
function machtileTenantIdFromSession() {
  try {
    const token = machtileSupabaseBearerToken();
    const payload = JSON.parse(atob(token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/")));
    return payload?.app_metadata?.tenant_id || config.tenantId || "";
  } catch (error) {
    return config.tenantId || "";
  }
}

async function machtileFetchProgramText(storagePath) {
  const baseUrl = String(config.supabaseUrl || "").replace(/\/$/, "");
  const encodedPath = String(storagePath).split("/").map(encodeURIComponent).join("/");
  const res = await fetch(`${baseUrl}/storage/v1/object/authenticated/machtile-cnc-programs/${encodedPath}`, {
    headers: { apikey: config.supabaseAnonKey, Authorization: `Bearer ${machtileSupabaseBearerToken()}` },
  });
  if (!res.ok) throw new Error(`程式檔讀取失敗（${res.status}）`);
  return await res.text();
}

// 簡單 LCS 行級差異；任一邊超過 3000 行回 null（呼叫端退回只報行數差）。
function machtileLineDiff(oldText, newText) {
  const a = String(oldText).split(/\r?\n/);
  const b = String(newText).split(/\r?\n/);
  if (a.length > 3000 || b.length > 3000) return null;
  const dp = Array.from({ length: a.length + 1 }, () => new Uint16Array(b.length + 1));
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const out = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { out.push({ type: "ctx", line: a[i] }); i++; j++; }
    else if (dp[i + 1][j] >= dp[i][j + 1]) { out.push({ type: "del", line: a[i] }); i++; }
    else { out.push({ type: "add", line: b[j] }); j++; }
  }
  while (i < a.length) { out.push({ type: "del", line: a[i] }); i++; }
  while (j < b.length) { out.push({ type: "add", line: b[j] }); j++; }
  return out;
}

