function machtileSetEstimateTab(tabKey) {
  const selected = ["gcode", "3d", "history"].includes(tabKey) ? tabKey : "gcode";
  document.querySelectorAll("[data-estimate-tab]").forEach((button) => {
    const active = button.dataset.estimateTab === selected;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });
  document.querySelectorAll("[data-estimate-panel]").forEach((panel) => {
    panel.hidden = panel.dataset.estimatePanel !== selected;
  });
}

async function machtileCncLoadPrograms() {
  // cnc_programs↔versions 有兩條 FK（program_id 與 current_version_id），嵌入要指名走 program_id
  return await supabaseFetch("cnc_programs?select=id,part_name,part_no,program_no,process_name,machine_id,current_version_id,cnc_program_versions!program_id(id,version_no,file_name,file_size_bytes,changed_from_version_id,changed_line_count,change_summary,storage_path,uploaded_at,estimated_seconds)&is_active=eq.true&order=updated_at.desc&limit=50");
}

// B 合併：每張程式卡＝版本清單＋這個工件的加工時間表（機台×程式版 vs 最佳）
function machtileCncTimeTable(program, runs, machineNames) {
  const partKeys = new Set([program.part_name, program.part_no].filter(Boolean));
  const groups = new Map();
  (runs || []).forEach((run) => {
    const wo = run.work_orders || {};
    if (!partKeys.has(wo.part_name) && !partKeys.has(wo.part_no)) return;
    if (run.pure_cutting_seconds == null) return;
    const key = `${machineNames.get(String(run.machine_id)) || "未知機台"}｜${run.cnc_program_versions?.version_no || "無程式版"}`;
    const slot = groups.get(key) || { sum: 0, count: 0, lastDate: "" };
    slot.sum += Number(run.pure_cutting_seconds) || 0;
    slot.count += 1;
    if (String(run.run_date) > slot.lastDate) slot.lastDate = String(run.run_date);
    groups.set(key, slot);
  });
  if (!groups.size) return '<p class="admin-module-note">還沒有這個工件的加工時間紀錄（現場報工填單件時間後自動累積）。</p>';
  const best = Math.min(...[...groups.values()].map((g) => g.sum / g.count));
  const rows = [...groups.entries()].map(([key, g]) => {
    const avg = g.sum / g.count;
    const delta = best > 0 ? Math.round(((avg - best) / best) * 100) : 0;
    const slow = delta > 15;
    const [machine, version] = key.split("｜");
    return `<tr class="${slow ? "machtile-history-slow" : ""}"><td>${escapeHtml(machine)}</td><td>${escapeHtml(version)}</td><td>${Math.round(avg)} 秒</td><td>${slow ? `<strong>+${delta}%</strong>` : delta > 0 ? `+${delta}%` : "最佳"}</td><td>${g.count}</td><td>${escapeHtml(g.lastDate)}</td></tr>`;
  }).join("");
  return `
    <div class="machtile-stats-table-wrap">
      <table class="machtile-stats-table">
        <thead><tr><th>機台</th><th>程式版</th><th>平均單件</th><th>vs 最佳</th><th>次數</th><th>最近加工</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `;
}

function machtileCncCalibrationSummary(program, runs, rawEstimateSeconds) {
  const core = globalThis.MachTileGcodeEstimatorCore;
  if (!core?.summarizeCalibration || !program?.id) return null;
  const samples = (Array.isArray(runs) ? runs : [])
    .filter((run) => String(run.program_id || "") === String(program.id))
    .filter((run) => !program.machine_id || String(run.machine_id || "") === String(program.machine_id))
    .map((run) => ({
      actualSeconds: run.pure_cutting_seconds,
      estimatedSeconds: run.cnc_program_versions?.estimated_seconds,
    }));
  return core.summarizeCalibration(samples, {
    rawEstimateSeconds,
    minimumSamples: config.gcodeCalibration?.minimumSamples,
  });
}

const machtileCalibrationState = {
  sampleDecisions: new Map(),
  baselines: new Map(),
  action: null,
  writePending: false,
  refresh: null,
};

function machtileCalibrationCanWrite() {
  return config.enableCalibrationGovernance === true && machtileStrictMode() && machtileSessionActive()
    && state.source === "supabase" && ["admin", "manager"].includes(String(machtileAuthState.role || "").toLowerCase());
}

function machtileCalibrationEventId() {
  return `machtile-ui:calibration:${globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`}`;
}

async function machtileLoadCalibrationGovernance() {
  machtileCalibrationState.sampleDecisions.clear();
  machtileCalibrationState.baselines.clear();
  if (config.enableCalibrationGovernance !== true) return;
  const snapshot = await supabaseFetch("rpc/cnc_calibration_snapshot", { method: "POST", body: JSON.stringify({ p_payload: {} }) });
  (snapshot?.sample_decisions || []).forEach((row) => machtileCalibrationState.sampleDecisions.set(String(row.machining_run_id), row));
  (snapshot?.baselines || []).forEach((row) => machtileCalibrationState.baselines.set(`${row.program_id}|${row.machine_id}`, row));
}

function machtileOpenCalibrationAction(action) {
  if (!machtileCalibrationCanWrite()) { showToast("校正決策需要主管或管理者權限"); return; }
  machtileCalibrationState.action = { ...action, sourceEventId: machtileCalibrationEventId() };
  const baselineAction = action.kind === "baseline";
  $("#calibrationSecondsField").hidden = !baselineAction || action.decisionType === "adopted";
  $("#calibrationSecondsInput").value = baselineAction ? String(action.suggestedSeconds || "") : "";
  $("#calibrationReasonInput").value = "";
  $("#calibrationActionTitle").textContent = action.kind === "sample" ? (action.excluded ? "恢復校正樣本" : "排除校正樣本") : action.decisionType === "adopted" ? "採用校正建議" : "人工修改校正";
  $("#calibrationActionSummary").textContent = baselineAction ? `歷史建議 ${machtileFormatDuration(action.suggestedSeconds)}；有效樣本 ${action.sampleIds.length} 筆` : `加工履歷 ${action.runId}`;
  $("#calibrationActionSubmit").textContent = action.kind === "sample" ? (action.excluded ? "確認恢復" : "確認排除") : "確認並留痕";
  const sheet = $("#calibrationActionSheet"); sheet.classList.add("is-open"); sheet.setAttribute("aria-hidden", "false");
  window.setTimeout(() => $("#calibrationReasonInput")?.focus(), 50);
}

function machtileCloseCalibrationAction() {
  if (machtileCalibrationState.writePending) return;
  $("#calibrationActionSheet")?.classList.remove("is-open");
  $("#calibrationActionSheet")?.setAttribute("aria-hidden", "true");
  machtileCalibrationState.action = null;
}

async function machtileSubmitCalibrationAction() {
  const action = machtileCalibrationState.action;
  if (!action || machtileCalibrationState.writePending) return;
  const reason = $("#calibrationReasonInput").value.trim();
  if (reason.length < 2) { showToast("校正決策原因至少需要 2 個字"); return; }
  const payload = { reason, source_event_id: action.sourceEventId };
  let rpc = "";
  if (action.kind === "sample") {
    rpc = "cnc_calibration_sample_decide";
    payload.machining_run_id = action.runId;
    payload.excluded = !action.excluded;
  } else {
    rpc = "cnc_calibration_baseline_decide";
    Object.assign(payload, {
      program_id: action.programId, machine_id: action.machineId, program_version_id: action.versionId,
      decision_type: action.decisionType, sample_ids: action.sampleIds,
    });
    if (action.decisionType === "modified") {
      const seconds = Math.round(Number($("#calibrationSecondsInput").value));
      if (!Number.isFinite(seconds) || seconds <= 0) { showToast("人工修改秒數必須大於 0"); return; }
      payload.adopted_seconds = seconds;
    }
  }
  machtileCalibrationState.writePending = true;
  $("#calibrationActionSubmit").disabled = true;
  try {
    await supabaseFetch(`rpc/${rpc}`, { method: "POST", body: JSON.stringify({ p_payload: payload }) });
    machtileCalibrationState.writePending = false;
    machtileCloseCalibrationAction();
    await machtileCalibrationState.refresh?.();
    showToast("校正決策已保存並留下稽核紀錄");
  } catch (error) {
    const message = String(error?.message || error || "");
    showToast(message.includes("MINIMUM_SAMPLES_REQUIRED") ? "至少需要 5 筆未排除的有效樣本" : message.includes("FORBIDDEN") ? "此操作需要主管或管理者權限" : `校正決策失敗：${message}`);
  } finally {
    machtileCalibrationState.writePending = false;
    $("#calibrationActionSubmit").disabled = false;
  }
}

function machtileCncCalibrationMarkup(summary) {
  if (!summary || summary.status === "no-samples") {
    return '<span>歷史校正：尚無同程式、同機台且同時具有預估／實際時間的樣本。</span>';
  }
  const factor = Number(summary.correctionFactor).toFixed(2);
  const medianActual = machtileFormatDuration(Math.round(summary.medianActualSeconds));
  if (summary.status === "threshold-not-configured") {
    return `<span>歷史參考：中位實際 ${medianActual}・係數 ×${factor}・${summary.sampleCount} 筆；尚未設定自動校正樣本門檻，未改動原估時。</span>`;
  }
  if (summary.status === "collecting") {
    return `<span>歷史校正累積中：${summary.sampleCount}/${summary.minimumSamples} 筆・目前係數 ×${factor}；未改動原估時。</span>`;
  }
  return `<span>歷史建議：${machtileFormatDuration(Math.round(summary.suggestedSeconds))}（原始 ${machtileFormatDuration(Math.round(summary.rawEstimateSeconds))}・係數 ×${factor}・${summary.sampleCount} 筆）；原始值仍保留。</span>`;
}

function machtileCncEstimateMarkup(estimate, calibration = null) {
  if (!estimate) return "";
  const modelLabel = estimate.motionModel === "acceleration-aware" ? "v2 加速度模型" : "v2／等速回退";
  const warningLine = estimate.warnings?.length
    ? `<br>⚠️ ${estimate.warnings.map((warning) => escapeHtml(warning)).join("；")}`
    : "";
  const calibrationLine = calibration ? `<br>${machtileCncCalibrationMarkup(calibration)}` : "";
  return `⏱ 預估純加工 <strong>${machtileFormatDuration(estimate.totalSeconds)}</strong>（${modelLabel}｜切削 ${machtileFormatDuration(estimate.cuttingSeconds)}｜快移 ${estimate.rapidSeconds} 秒｜暫停 ${estimate.dwellSeconds} 秒｜換刀 ${estimate.toolChanges} 次｜移動 ${estimate.segments} 段）${warningLine}${calibrationLine}`;
}

function machtileCncCalibrationReview(program, runs, machineNames) {
  const core = globalThis.MachTileGcodeEstimatorCore;
  if (!core?.buildCalibrationReview || !program?.id) return null;
  const versions = [...(program.cnc_program_versions || [])]
    .sort((left, right) => String(right.uploaded_at || "").localeCompare(String(left.uploaded_at || "")));
  const currentVersion = versions.find((version) => String(version.id) === String(program.current_version_id)) || versions[0];
  const samples = (Array.isArray(runs) ? runs : []).map((run) => ({
    sampleId: run.id,
    programId: run.program_id,
    machineId: run.machine_id,
    machineLabel: machineNames.get(String(run.machine_id)) || String(run.machine_id || ""),
    programVersionId: run.program_version_id,
    versionLabel: run.cnc_program_versions?.version_no || "未連結程式版",
    runDate: run.run_date || run.created_at,
    source: run.source,
    remark: run.remark,
    actualSeconds: run.pure_cutting_seconds,
    estimatedSeconds: run.cnc_program_versions?.estimated_seconds,
  }));
  return core.buildCalibrationReview(samples, {
    programId: program.id,
    currentMachineId: program.machine_id,
    rawEstimateSeconds: currentVersion?.estimated_seconds,
    minimumSamples: config.gcodeCalibration?.minimumSamples,
    excludedSampleIds: [...machtileCalibrationState.sampleDecisions.entries()].filter(([, decision]) => decision.excluded).map(([runId]) => runId),
  });
}

function machtileCncCalibrationReasonLabel(reason) {
  return ({
    "missing-machine": "缺機台",
    "missing-actual": "缺實際加工秒數",
    "missing-estimate": "缺該程式版原估時",
  })[reason] || "資料不完整";
}

function machtileCncCalibrationReviewMarkup(program, runs, machineNames) {
  const review = machtileCncCalibrationReview(program, runs, machineNames);
  const canWrite = machtileCalibrationCanWrite();
  const versions = [...(program.cnc_program_versions || [])].sort((a, b) => String(b.uploaded_at || "").localeCompare(String(a.uploaded_at || "")));
  const currentVersion = versions.find((version) => String(version.id) === String(program.current_version_id)) || versions[0];
  if (!review) {
    return '<p class="admin-module-note">校正證據核心尚未載入；不顯示推測結果。</p>';
  }
  if (!review.scopedSampleCount) {
    return `
      <section class="machtile-calibration-review" data-calibration-program="${escapeHtml(program.id)}">
        <div class="machtile-calibration-review-head"><strong>校正證據</strong><span>只讀</span></div>
        <p class="admin-module-note">尚無連結到這支程式的加工履歷。先累積帶原估時與實際加工秒數的真實報工。</p>
      </section>
    `;
  }

  const sourceLabels = { manual: "人工", program_upload: "程式上傳", machine_log: "機台紀錄", mes_import: "MES 匯入" };
  const groupMarkup = review.groups.map((group) => {
    const statusLabel = group.ready ? "已達建議門檻" : `累積 ${group.sampleCount}/${group.minimumSamples || "-"}`;
    const suggestion = group.suggestedSeconds
      ? `建議 ${machtileFormatDuration(Math.round(group.suggestedSeconds))}`
      : "目前程式版缺原估時，暫無建議秒數";
    const baseline = machtileCalibrationState.baselines.get(`${program.id}|${group.machineId}`);
    const rows = group.samples.slice(0, 20).map((sample) => `
      <tr class="${sample.excluded ? "is-excluded" : ""}">
        <td>${escapeHtml(sample.runDate || "-")}</td>
        <td>${escapeHtml(sample.versionLabel || "-")}</td>
        <td>${escapeHtml(machtileFormatDuration(Math.round(sample.estimatedSeconds)))}</td>
        <td>${escapeHtml(machtileFormatDuration(Math.round(sample.actualSeconds)))}</td>
        <td>×${escapeHtml(Number(sample.ratio).toFixed(2))}</td>
        <td>${escapeHtml(sourceLabels[sample.source] || sample.source || "-")}${sample.remark ? `<small>${escapeHtml(sample.remark)}</small>` : ""}</td>
        <td>${canWrite ? `<button type="button" data-calibration-sample="${escapeHtml(sample.sampleId)}" data-calibration-excluded="${sample.excluded ? "true" : "false"}">${sample.excluded ? "恢復" : "排除"}</button>` : sample.excluded ? "已排除" : "—"}</td>
      </tr>
    `).join("");
    return `
      <article class="machtile-calibration-machine ${group.isCurrentMachine ? "is-current" : ""}">
        <header>
          <div><strong>${escapeHtml(group.machineLabel)}</strong>${group.isCurrentMachine ? "<span>目前指定機台</span>" : ""}</div>
          <em class="${group.ready ? "is-ready" : ""}">${escapeHtml(statusLabel)}</em>
        </header>
        <div class="machtile-calibration-metrics">
          <span>有效樣本 <b>${escapeHtml(group.sampleCount)}</b></span>
          <span>中位實際 <b>${escapeHtml(machtileFormatDuration(Math.round(group.medianActualSeconds)))}</b></span>
          <span>中位係數 <b>×${escapeHtml(Number(group.correctionFactor).toFixed(2))}</b></span>
          <span>${escapeHtml(suggestion)}</span>
        </div>
        <div class="machtile-stats-table-wrap">
          <table class="machtile-stats-table machtile-calibration-samples">
            <thead><tr><th>加工日</th><th>程式版</th><th>原估時</th><th>實際</th><th>比值</th><th>來源／備註</th><th>樣本</th></tr></thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
        ${baseline ? `<p class="machtile-calibration-active">目前採用：${escapeHtml(machtileFormatDuration(baseline.adopted_seconds))}・${baseline.decision_type === "modified" ? "主管修改" : "採用建議"}・${escapeHtml(baseline.reason)}</p>` : ""}
        ${canWrite && group.ready && currentVersion?.id ? `<div class="machtile-calibration-actions">
          <button type="button" data-calibration-baseline="adopted" data-calibration-program="${escapeHtml(program.id)}" data-calibration-machine="${escapeHtml(group.machineId)}" data-calibration-version="${escapeHtml(currentVersion.id)}" data-calibration-suggested="${escapeHtml(Math.round(group.suggestedSeconds))}" data-calibration-samples="${escapeHtml(group.activeSamples.map((sample) => sample.sampleId).join(","))}">採用建議</button>
          <button type="button" data-calibration-baseline="modified" data-calibration-program="${escapeHtml(program.id)}" data-calibration-machine="${escapeHtml(group.machineId)}" data-calibration-version="${escapeHtml(currentVersion.id)}" data-calibration-suggested="${escapeHtml(Math.round(group.suggestedSeconds))}" data-calibration-samples="${escapeHtml(group.activeSamples.map((sample) => sample.sampleId).join(","))}">人工修改</button>
        </div>` : ""}
      </article>
    `;
  }).join("");

  const rejectedMarkup = review.rejectedSampleCount ? `
    <details class="machtile-calibration-rejected">
      <summary>基本資格不完整 ${escapeHtml(review.rejectedSampleCount)} 筆</summary>
      <ul>${review.rejected.slice(0, 20).map((sample) => `<li><b>${escapeHtml(machtileCncCalibrationReasonLabel(sample.reason))}</b><span>${escapeHtml(sample.runDate || "-")}・${escapeHtml(sample.versionLabel || "-")}・${escapeHtml(sample.machineLabel || "未指定機台")}</span></li>`).join("")}</ul>
    </details>
  ` : "";

  return `
    <section class="machtile-calibration-review" data-calibration-program="${escapeHtml(program.id)}">
      <div class="machtile-calibration-review-head">
        <div><strong>校正證據</strong><small>同程式、同機台分組</small></div>
        <span>${canWrite ? "主管治理" : "只讀"}</span>
      </div>
      ${groupMarkup || '<p class="admin-module-note">目前沒有同時具備機台、原估時與實際加工秒數的有效樣本。</p>'}
      ${rejectedMarkup}
      <p class="machtile-calibration-guard">不會自動套用建議，也不會因數字極端就自動排除；主管每次採用、修改、排除或恢復都必須填原因並留下稽核。</p>
    </section>
  `;
}

function machtileCncRenderList(programs, runs, machineNames) {
  const holder = document.getElementById("machtileCncList");
  if (!holder) return;
  if (!Array.isArray(programs) || !programs.length) {
    holder.innerHTML = '<p class="admin-module-note">還沒有登錄任何 CNC 程式；把第一支 O 檔拖上去就開張。</p>';
    return;
  }
  holder.innerHTML = programs.map((program) => {
    const versions = (program.cnc_program_versions || []).sort((a, b) => (a.uploaded_at < b.uploaded_at ? 1 : -1));
    return `
      <section class="machtile-cnc-program">
        <div class="machtile-cnc-program-head">
          <div class="machtile-cnc-program-title">
            <strong>${escapeHtml(program.part_name)}</strong>
            ${program.program_no ? `<span class="cnc-chip is-progno">${escapeHtml(program.program_no)}</span>` : ""}
          </div>
          <span class="machtile-cnc-count">${versions.length} 版</span>
        </div>
        ${versions.map((version, index) => `
          <div class="machtile-cnc-version ${index === 0 ? "is-latest" : ""}">
            <span class="cnc-ver-badge">${escapeHtml(version.version_no)}</span>
            <div class="cnc-ver-main">
              <strong>${escapeHtml(version.file_name)}</strong>
              <small>${escapeHtml(machtileFormatAuditTime(version.uploaded_at))}${version.change_summary ? `・${escapeHtml(version.change_summary)}` : ""}</small>
            </div>
            <div class="cnc-ver-chips">
              ${index === 0 ? '<span class="cnc-chip is-current">現行版</span>' : ""}
              ${version.estimated_seconds != null ? `<span class="cnc-chip is-est">⏱ ${machtileFormatDuration(version.estimated_seconds)}</span>` : ""}
              ${version.changed_line_count != null ? `<span class="cnc-chip">±${version.changed_line_count} 行</span>` : ""}
            </div>
            ${version.changed_from_version_id ? `<button type="button" data-cnc-diff="${escapeHtml(version.id)}" data-cnc-prev="${escapeHtml(version.changed_from_version_id)}">比對</button>` : '<span class="cnc-first-tag">首版</span>'}
          </div>
        `).join("")}
        <p class="machtile-cnc-time-title">⏱ 加工時間（此工件・實際）</p>
        ${machtileCncTimeTable(program, runs, machineNames)}
        ${machtileCncCalibrationReviewMarkup(program, runs, machineNames)}
      </section>
    `;
  }).join("");
}

const machtileFormalQuoteState = { candidate: null, snapshot: { versions: [], links: [], finals: [] }, workOrders: [], pending: false };

function machtileFormalQuoteEnabled() {
  return config.enableManufacturingQuoteTracking === true && machtileStrictMode() && machtileSessionActive();
}

function machtileFormalQuoteCanApprove() {
  return ["admin", "manager"].includes(machtileAuthState.role);
}

function machtileFormalQuoteEventId(action) {
  return `machtile-ui:quote:${action}:${globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`}`;
}

async function machtileFormalQuoteRpc(name, payload) {
  return supabaseFetch(`rpc/${name}`, { method: "POST", body: JSON.stringify({ p_payload: payload }) });
}

function machtileFormalQuoteMoney(value) {
  return Number(value || 0).toLocaleString("zh-TW", { style: "currency", currency: "TWD", maximumFractionDigits: 0 });
}

function machtileFormalQuoteRender() {
  const holder = document.getElementById("machtileFormalQuoteList");
  if (!holder) return;
  const versions = machtileFormalQuoteState.snapshot.versions || [];
  const links = machtileFormalQuoteState.snapshot.links || [];
  const finals = new Map((machtileFormalQuoteState.snapshot.finals || []).map((item) => [String(item.work_order_id), item]));
  const statusLabels = { draft: "草稿", approved: "已核准", superseded: "已換版", cancelled: "已取消" };
  if (!versions.length) { holder.innerHTML = '<p class="admin-module-note">尚無正式估價；完成上方初估後可建立 V1 草稿。</p>'; return; }
  holder.innerHTML = versions.map((version) => {
    const versionLinks = links.filter((link) => String(link.quote_version_id) === String(version.id));
    const workOptions = machtileFormalQuoteState.workOrders.map((order) => `<option value="${escapeHtml(order.id)}">${escapeHtml(order.work_order_no)}・${escapeHtml(order.part_name)}・${escapeHtml(order.status)}</option>`).join("");
    const linkedRows = versionLinks.map((link) => {
      const final = finals.get(String(link.work_order_id));
      const isComplete = ["completed", "shipped"].includes(String(link.work_order_status));
      return `<article class="formal-quote-link">
        <div><strong>${escapeHtml(link.work_order_no)}</strong><span>${escapeHtml(link.part_name)}・${escapeHtml(link.work_order_status)}</span></div>
        ${final ? `<div class="formal-quote-final"><span>報價 ${machtileFormatScheduleMinutes(final.quoted_total_minutes)} → 實際 ${machtileFormatScheduleMinutes(final.actual_total_minutes)}</span><strong class="${Number(final.variance_pct) > 0 ? "tracking-bad" : "tracking-good"}">${machtileTrackingPercent(Number(final.variance_pct), true)}</strong><small>${escapeHtml(final.reason)}</small></div>` : isComplete && machtileFormalQuoteCanApprove() ? `
          <form data-formal-quote-finalize="${escapeHtml(link.id)}" class="formal-quote-action-form">
            <label><span>實際架機分</span><input name="setup" type="number" min="0" step="0.1" value="0" required></label>
            <label><span>實際品檢分</span><input name="inspection" type="number" min="0" step="0.1" value="0" required></label>
            <label><span>其他時間分</span><input name="other" type="number" min="0" step="0.1" value="0" required></label>
            <label><span>確認原因</span><input name="reason" type="text" required placeholder="完工覆核"></label>
            <button type="submit">確認最終工時</button>
          </form>` : '<small>工單完工後由主管確認最終工時。</small>'}
      </article>`;
    }).join("");
    return `<section class="formal-quote-version">
      <header><div><strong>${escapeHtml(version.quote_no)}・V${version.version_no}</strong><span>${escapeHtml(version.part_name)}${version.part_no ? `・${escapeHtml(version.part_no)}` : ""}</span></div><em class="is-${escapeHtml(version.status)}">${escapeHtml(statusLabels[version.status] || version.status)}</em></header>
      <div class="formal-quote-metrics"><span>${version.quantity} 件</span><span>單件加工 ${machtileFormatScheduleMinutes(version.machining_minutes_per_part)}</span><span>總價 ${machtileFormalQuoteMoney(version.cost_snapshot?.quote_total)}</span><span>${escapeHtml(version.creation_reason)}</span></div>
      ${version.status === "draft" && machtileFormalQuoteCanApprove() ? `<form data-formal-quote-approve="${escapeHtml(version.id)}" class="formal-quote-action-form is-compact"><label><span>核准原因</span><input name="reason" type="text" required placeholder="工程與價格已覆核"></label><button type="submit">主管核准</button></form>` : ""}
      ${version.status === "approved" ? `<form data-formal-quote-link="${escapeHtml(version.id)}" class="formal-quote-action-form is-compact"><label><span>連結工單</span><select name="workOrder" required><option value="">請選擇</option>${workOptions}</select></label><label><span>連結原因</span><input name="reason" type="text" required placeholder="依核准估價開工"></label><button type="submit">連結</button></form>` : ""}
      ${linkedRows ? `<div class="formal-quote-links">${linkedRows}</div>` : ""}
    </section>`;
  }).join("");
}

async function machtileFormalQuoteRefresh() {
  if (!machtileFormalQuoteEnabled()) return;
  const [snapshot, workOrders] = await Promise.all([
    machtileFormalQuoteRpc("manufacturing_quote_tracking_snapshot", {}),
    supabaseFetch("work_orders?select=id,work_order_no,part_name,status&status=not.in.(cancelled)&order=created_at.desc&limit=500"),
  ]);
  machtileFormalQuoteState.snapshot = snapshot || { versions: [], links: [], finals: [] };
  machtileFormalQuoteState.workOrders = Array.isArray(workOrders) ? workOrders : [];
  machtileFormalQuoteRender();
}

function machtileFormalQuoteError(error) {
  const code = String(error?.message || error || "");
  const labels = { FORBIDDEN: "權限不足", REASON_REQUIRED: "原因至少需要 2 個字", APPROVED_QUOTE_REQUIRED: "只能連結已核准的估價版本", WORK_ORDER_NOT_COMPLETE: "工單尚未完工", FINAL_MACHINING_DATA_REQUIRED: "缺少可彙總的實際加工時間", INVALID_QUOTE_INPUT: "估價參數不完整" };
  return labels[Object.keys(labels).find((key) => code.includes(key))] || code;
}

function machtileInit3dQuote() {
  const core = globalThis.MachTileQuote3dCore;
  const form = document.getElementById("machtile3dQuoteForm");
  const drop = document.getElementById("machtile3dDrop");
  const input = document.getElementById("machtile3dFile");
  if (!core || !form || !drop || !input) return;
  let model = null;
  const inspect = async (file) => {
    if (!file) return;
    const result = core.inspectModel({ name: file.name, buffer: await file.arrayBuffer(), text: await file.text() });
    if (!result.ok) { showToast(result.error === "UNSUPPORTED_MODEL_FORMAT" ? "僅支援 STEP、STL、IGES" : "STL 模型無法解析"); return; }
    model = { ...result, name: file.name, size: file.size };
    if (result.geometryAvailable) {
      const bounds = result.bounds;
      [["quote3dStockX", bounds.x], ["quote3dStockY", bounds.y], ["quote3dStockZ", bounds.z]].forEach(([id, value]) => { document.getElementById(id).value = Number(value.toFixed(3)); });
      document.getElementById("machtile3dModelInfo").textContent = `${file.name}・${result.triangleCount.toLocaleString("zh-TW")} 三角面・模型外框 ${bounds.x.toFixed(2)} × ${bounds.y.toFixed(2)} × ${bounds.z.toFixed(2)} mm・體積 ${(result.volumeMm3 / 1000).toFixed(2)} cm³；毛胚欄位已帶模型外框，請自行加入加工餘量。`;
    } else {
      document.getElementById("machtile3dModelInfo").textContent = `${file.name}・${result.warning}`;
    }
  };
  drop.addEventListener("click", () => input.click());
  drop.addEventListener("keydown", (event) => { if (["Enter", " "].includes(event.key)) { event.preventDefault(); input.click(); } });
  input.addEventListener("change", () => inspect(input.files?.[0]));
  drop.addEventListener("dragover", (event) => { event.preventDefault(); drop.classList.add("is-over"); });
  drop.addEventListener("dragleave", () => drop.classList.remove("is-over"));
  drop.addEventListener("drop", (event) => { event.preventDefault(); drop.classList.remove("is-over"); inspect(event.dataTransfer?.files?.[0]); });
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    if (!model) { showToast("請先選擇 STEP、STL 或 IGES 模型"); return; }
    const value = (id) => document.getElementById(id).value;
    const quote = core.calculateQuote({
      quantity: value("quote3dQty"), stockX: value("quote3dStockX"), stockY: value("quote3dStockY"), stockZ: value("quote3dStockZ"),
      materialDensity: value("quote3dDensity"), materialPricePerKg: value("quote3dMaterialRate"), setups: value("quote3dSetups"),
      setupMinutes: value("quote3dSetupMinutes"), machiningMinutes: value("quote3dMachiningMinutes"), machineRate: value("quote3dMachineRate"),
      inspectionMinutes: value("quote3dInspectionMinutes"), inspectionRate: value("quote3dInspectionRate"), extraCost: value("quote3dExtraCost"), marginPct: value("quote3dMargin"),
    });
    if (!quote.ok) { showToast("請確認數量、毛胚、材料、架機、加工費率與毛利率"); return; }
    const money = (amount) => Number(amount).toLocaleString("zh-TW", { style: "currency", currency: "TWD", maximumFractionDigits: 0 });
    const result = document.getElementById("machtile3dQuoteResult");
    result.hidden = false;
    result.innerHTML = `<header><div><span>參數化初估</span><strong>${money(quote.quoteTotal)}</strong></div><em>${quote.quantity} 件・單件 ${money(quote.quotePerPart)}</em></header>
      <dl><div><dt>材料／單件</dt><dd>${money(quote.materialPerPart)}</dd></div><div><dt>架機成本</dt><dd>${money(quote.setupCost)}</dd></div><div><dt>加工／單件</dt><dd>${money(quote.machiningPerPart)}</dd></div><div><dt>品檢／單件</dt><dd>${money(quote.inspectionPerPart)}</dd></div><div><dt>總成本</dt><dd>${money(quote.cost)}</dd></div><div><dt>目標毛利</dt><dd>${money(quote.profit)}（${quote.marginPct}%）</dd></div></dl>
      <p>${escapeHtml(value("quote3dMaterial"))}・毛胚重 ${quote.stockWeightKg.toFixed(3)} kg／件・模型 ${escapeHtml(model.name)}。尚未包含 CAM 刀路驗證，正式報價前需工程覆核。</p>`;
    if (machtileFormalQuoteEnabled()) {
      machtileFormalQuoteState.candidate = {
        model_name: model.name, model_extension: model.extension, model_size_bytes: model.size,
        geometry_summary: model.geometryAvailable ? { bounds: model.bounds, triangle_count: model.triangleCount, volume_mm3: model.volumeMm3 } : { warning: model.warning || "manual geometry" },
        quantity: value("quote3dQty"), material_name: value("quote3dMaterial"), material_density: value("quote3dDensity"),
        material_price_per_kg: value("quote3dMaterialRate"), stock_x_mm: value("quote3dStockX"), stock_y_mm: value("quote3dStockY"), stock_z_mm: value("quote3dStockZ"),
        setup_count: value("quote3dSetups"), setup_minutes: value("quote3dSetupMinutes"), machining_minutes_per_part: value("quote3dMachiningMinutes"),
        machine_rate_per_hour: value("quote3dMachineRate"), inspection_minutes_per_part: value("quote3dInspectionMinutes"), inspection_rate_per_hour: value("quote3dInspectionRate"),
        extra_cost: value("quote3dExtraCost"), margin_pct: value("quote3dMargin"),
      };
      document.getElementById("machtileFormalQuoteSave").hidden = false;
    }
  });
  document.getElementById("formalQuoteSaveBtn")?.addEventListener("click", async () => {
    const candidate = machtileFormalQuoteState.candidate;
    if (!candidate || machtileFormalQuoteState.pending) return;
    const partName = document.getElementById("formalQuotePartName")?.value.trim();
    const reason = document.getElementById("formalQuoteReason")?.value.trim();
    if (!partName || !reason || reason.length < 2) { showToast("請填品名與建立原因"); return; }
    machtileFormalQuoteState.pending = true;
    try {
      await machtileFormalQuoteRpc("manufacturing_quote_version_create", {
        ...candidate, part_name: partName, title: partName,
        part_no: document.getElementById("formalQuotePartNo")?.value.trim(), customer_name: document.getElementById("formalQuoteCustomer")?.value.trim(),
        quote_no: document.getElementById("formalQuoteNo")?.value.trim(), reason, source_event_id: machtileFormalQuoteEventId("create"),
      });
      showToast("正式估價草稿已建立");
      document.getElementById("formalQuoteReason").value = "";
      await machtileFormalQuoteRefresh();
    } catch (error) { showToast(`建立失敗：${machtileFormalQuoteError(error)}`); }
    finally { machtileFormalQuoteState.pending = false; }
  });
  document.getElementById("machtileFormalQuoteList")?.addEventListener("submit", async (event) => {
    const form = event.target.closest("form");
    if (!form || machtileFormalQuoteState.pending) return;
    event.preventDefault();
    const data = new FormData(form);
    machtileFormalQuoteState.pending = true;
    try {
      if (form.dataset.formalQuoteApprove) {
        await machtileFormalQuoteRpc("manufacturing_quote_version_approve", { quote_version_id: form.dataset.formalQuoteApprove, reason: String(data.get("reason") || ""), source_event_id: machtileFormalQuoteEventId("approve") });
        showToast("正式估價已核准");
      } else if (form.dataset.formalQuoteLink) {
        await machtileFormalQuoteRpc("manufacturing_quote_work_order_link", { quote_version_id: form.dataset.formalQuoteLink, work_order_id: String(data.get("workOrder") || ""), reason: String(data.get("reason") || ""), source_event_id: machtileFormalQuoteEventId("link") });
        showToast("估價版本已連結工單");
      } else if (form.dataset.formalQuoteFinalize) {
        await machtileFormalQuoteRpc("manufacturing_quote_work_order_finalize", { link_id: form.dataset.formalQuoteFinalize, actual_setup_minutes: data.get("setup"), actual_inspection_minutes: data.get("inspection"), actual_other_minutes: data.get("other"), reason: String(data.get("reason") || ""), source_event_id: machtileFormalQuoteEventId("finalize") });
        showToast("最終工時已確認並留痕");
      }
      await machtileFormalQuoteRefresh();
      renderReports();
    } catch (error) { showToast(`操作失敗：${machtileFormalQuoteError(error)}`); }
    finally { machtileFormalQuoteState.pending = false; }
  });
  machtileFormalQuoteRefresh().catch((error) => {
    const holder = document.getElementById("machtileFormalQuoteList");
    if (holder) holder.innerHTML = `<p class="admin-module-note">正式估價載入失敗：${escapeHtml(machtileFormalQuoteError(error))}</p>`;
  });
}

async function machtileInitCncModule() {
  const form = document.getElementById("machtileCncForm");
  if (!form) return;
  machtileInit3dQuote();
  let programs = [];
  let runsCache = [];
  const machineNames = new Map();
  const machineParams = new Map();
  const versionById = new Map();
  let pendingFile = null;
  let pendingEstimate = null;
  let pendingPasteText = "";
  let activeSourceMode = "file";
  const refresh = async () => {
    try {
      await machtileLoadCalibrationGovernance();
      const [programRows, runRows] = await Promise.all([
        machtileCncLoadPrograms(),
        supabaseFetch("cnc_machining_runs?select=id,run_date,qty_good,qty_defect,pure_cutting_seconds,machine_id,program_id,program_version_id,source,remark,created_at,work_orders(part_name,part_no),cnc_program_versions(version_no,estimated_seconds)&order=created_at.desc&limit=500"),
      ]);
      programs = programRows;
      runsCache = Array.isArray(runRows) ? runRows : [];
      versionById.clear();
      programs.forEach((program) => (program.cnc_program_versions || []).forEach((version) => versionById.set(version.id, version)));
      const select = document.getElementById("machtileCncProgram");
      if (select) {
        const current = select.value;
        select.innerHTML = `<option value="">＋ 建立新程式</option>` + programs.map((program) => `<option value="${escapeHtml(program.id)}">${escapeHtml(program.part_name)}${program.program_no ? `・${escapeHtml(program.program_no)}` : ""}</option>`).join("");
        select.value = current;
      }
      machtileCncRenderList(programs, runsCache, machineNames);
    } catch (error) {
      const holder = document.getElementById("machtileCncList");
      if (holder) holder.innerHTML = `<p class="admin-module-note">程式清單載入失敗：${escapeHtml(String(error?.message || ""))}</p>`;
    }
  };
  try {
    const machines = await machtileWoMachines();
    const machineSelect = document.getElementById("machtileCncMachine");
    if (machineSelect) {
      machineSelect.innerHTML = `<option value="">不指定</option>` + machines.map((m) => `<option value="${escapeHtml(m.machine_code)}">${escapeHtml(m.machine_code)}</option>`).join("");
    }
    const machineRows = await supabaseFetch("machines?select=id,machine_code,machine_type,rapid_rate_mm_min,tool_change_seconds");
    machineRows.forEach((m) => {
      machineNames.set(String(m.id), m.machine_code);
      const configuredProfile = config.gcodeMachineProfiles?.[m.machine_code] || {};
      machineParams.set(String(m.id), {
        ...configuredProfile,
        rapidRate: Number(m.rapid_rate_mm_min) || configuredProfile.rapidRate,
        toolChangeSeconds: Number(m.tool_change_seconds) || configuredProfile.toolChangeSeconds,
        dialect: /車/.test(m.machine_type || "") || /lathe|turn/i.test(m.machine_type || "") ? "lathe" : "auto",
      });
    });
    const pasteMachineSelect = document.getElementById("machtileCncPasteMachine");
    if (pasteMachineSelect) {
      pasteMachineSelect.innerHTML = `<option value="">保守預設（YCM TCV2000A 上限）</option>`
        + machineRows.map((machine) => `<option value="${escapeHtml(machine.id)}">${escapeHtml(machine.machine_code)}</option>`).join("");
    }
  } catch (error) { /* 機台清單失敗不擋上傳 */ }
  await refresh();

  // C 上傳體驗：拖放/點擊選檔 → 檔名自動辨識程式號＋自動歸屬 → 預覽確認
  const drop = document.getElementById("machtileCncDrop");
  const fileInput = document.getElementById("machtileCncFile");
  const handleFile = async (file, options = {}) => {
    if (!file) return;
    pendingFile = file;
    const text = await file.text();
    const lines = text.split(/\r?\n/).length;
    const stem = file.name.replace(/\.[^.]+$/, "");
    const progGuess = (stem.match(/O\d{3,5}/i) || [stem.split(/[-_\s]/)[0]])[0].toUpperCase();
    const match = programs.find((p) => (p.program_no || "").toUpperCase() === progGuess)
      || programs.find((p) => (p.cnc_program_versions || []).some((v) => v.file_name.replace(/\.[^.]+$/, "").toUpperCase().startsWith(progGuess)));
    const select = document.getElementById("machtileCncProgram");
    select.value = match ? match.id : "";
    document.getElementById("machtileCncNewFields").style.display = match ? "none" : "";
    document.getElementById("machtileCncProgramNo").value = match ? "" : progGuess;
    const nextVersion = match ? `V${(match.cnc_program_versions || []).length + 1}` : "V1";
    // 估時 v2：機台若有部署設定便套用加速度模型；否則明確回退 v1 等速模型。
    const params = options.estimateParams
      || (match?.machine_id && machineParams.get(String(match.machine_id)))
      || { rapidRate: 40000, maxFeedRateMmMin: 10000, toolChangeSeconds: 4.5, dialect: "auto" };
    pendingEstimate = machtileEstimateGcode(text, params);
    if (options.machineCode) {
      const machineSelect = document.getElementById("machtileCncMachine");
      if (machineSelect && [...machineSelect.options].some((option) => option.value === options.machineCode)) {
        machineSelect.value = options.machineCode;
      }
    }
    const calibration = match ? machtileCncCalibrationSummary(match, runsCache, pendingEstimate.totalSeconds) : null;
    const estLine = machtileCncEstimateMarkup(pendingEstimate, calibration);
    document.getElementById("machtileCncFileInfo").innerHTML = (match
      ? `<strong>${escapeHtml(file.name)}</strong>（${lines} 行）→ 偵測到既有程式 <strong>${escapeHtml(match.part_name)}${match.program_no ? `・${escapeHtml(match.program_no)}` : ""}</strong>，將登錄為 <strong>${nextVersion}</strong>`
      : `<strong>${escapeHtml(file.name)}</strong>（${lines} 行）→ 沒有相符的既有程式，將建立<strong>新程式</strong>（程式號 ${escapeHtml(progGuess)}，請填品名）`)
      + `<br>${estLine}`;
    form.hidden = false;
    document.getElementById("machtileCncStatus").textContent = "";
  };
  drop?.addEventListener("click", () => fileInput.click());
  drop?.addEventListener("dragover", (event) => { event.preventDefault(); drop.classList.add("is-over"); });
  drop?.addEventListener("dragleave", () => drop.classList.remove("is-over"));
  drop?.addEventListener("drop", (event) => {
    event.preventDefault();
    drop.classList.remove("is-over");
    handleFile(event.dataTransfer.files?.[0]);
  });
  fileInput?.addEventListener("change", () => handleFile(fileInput.files?.[0]));

  const sourceModeButtons = [...document.querySelectorAll("[data-gcode-source-mode]")];
  const setSourceMode = (mode) => {
    const selected = mode === "paste" ? "paste" : "file";
    if (selected !== activeSourceMode) {
      form.reset();
      form.hidden = true;
      pendingFile = null;
      pendingEstimate = null;
      activeSourceMode = selected;
    }
    sourceModeButtons.forEach((button) => {
      const active = button.dataset.gcodeSourceMode === selected;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-selected", active ? "true" : "false");
    });
    document.querySelectorAll("[data-gcode-source-panel]").forEach((panel) => {
      panel.hidden = panel.dataset.gcodeSourcePanel !== selected;
    });
  };
  machtileCalibrationState.refresh = refresh;
  sourceModeButtons.forEach((button) => button.addEventListener("click", () => setSourceMode(button.dataset.gcodeSourceMode)));

  const pasteInput = document.getElementById("machtileCncPasteInput");
  const pasteMachine = document.getElementById("machtileCncPasteMachine");
  const pasteResult = document.getElementById("machtileCncPasteResult");
  const pasteSaveButton = document.getElementById("machtileCncPasteSaveBtn");
  const invalidatePastedEstimate = () => {
    pendingPasteText = "";
    if (pasteResult) pasteResult.hidden = true;
    if (pasteSaveButton) pasteSaveButton.hidden = true;
  };
  const estimatePastedGcode = () => {
    const text = String(pasteInput?.value || "").trim();
    if (!text) {
      if (pasteResult) {
        pasteResult.innerHTML = "<p>請先貼上 G-code，再按立即估算。</p>";
        pasteResult.hidden = false;
      }
      if (pasteSaveButton) pasteSaveButton.hidden = true;
      pendingPasteText = "";
      return;
    }
    const params = (pasteMachine?.value && machineParams.get(String(pasteMachine.value)))
      || { rapidRate: 40000, maxFeedRateMmMin: 10000, toolChangeSeconds: 4.5, dialect: "auto" };
    const estimate = machtileEstimateGcode(text, params);
    const lineCount = text.split(/\r?\n/).length;
    const noRecognizedMotion = !estimate.segments && !estimate.toolChanges && !estimate.dwellSeconds;
    pendingPasteText = text;
    if (pasteResult) {
      pasteResult.innerHTML = `
        <p>${machtileCncEstimateMarkup(estimate)}</p>
        <p><small>${lineCount} 行・${text.length.toLocaleString("en-US")} 字元・只在此瀏覽器完成估算，尚未保存。</small></p>
        ${noRecognizedMotion ? "<p>⚠️ 沒有辨識到可估算的移動、換刀或暫停，請確認程式是否完整。</p>" : ""}
      `;
      pasteResult.hidden = false;
    }
    if (pasteSaveButton) pasteSaveButton.hidden = false;
  };
  const savePastedGcode = async () => {
    const text = String(pasteInput?.value || "").trim();
    if (!pendingPasteText || text !== pendingPasteText) {
      if (pasteResult) {
        pasteResult.innerHTML = "<p>內容已變更，請重新估算後再另存成程式版本。</p>";
        pasteResult.hidden = false;
      }
      if (pasteSaveButton) pasteSaveButton.hidden = true;
      return;
    }
    const programNo = (text.match(/(?:^|\n)\s*(O\d{3,5})\b/i) || [])[1]?.toUpperCase();
    const stamp = new Date().toISOString().replace(/[-:TZ.]/g, "").slice(0, 14);
    const fileName = programNo ? `${programNo}-paste.nc` : `PASTED-GCODE-${stamp}.nc`;
    const pastedFile = new File([text], fileName, { type: "text/plain" });
    const selectedMachineId = pasteMachine?.value || "";
    await handleFile(pastedFile, {
      estimateParams: selectedMachineId ? machineParams.get(String(selectedMachineId)) : undefined,
      machineCode: selectedMachineId ? machineNames.get(String(selectedMachineId)) : "",
    });
    const summaryInput = document.getElementById("machtileCncSummary");
    if (summaryInput && !summaryInput.value) summaryInput.value = "由直接貼上 G-code 建立";
    form.scrollIntoView({ behavior: "smooth", block: "start" });
  };
  pasteInput?.addEventListener("input", invalidatePastedEstimate);
  pasteMachine?.addEventListener("change", invalidatePastedEstimate);
  document.getElementById("machtileCncPasteEstimateBtn")?.addEventListener("click", estimatePastedGcode);
  document.getElementById("machtileCncPasteClearBtn")?.addEventListener("click", () => {
    if (pasteInput) pasteInput.value = "";
    invalidatePastedEstimate();
    pasteInput?.focus();
  });
  pasteSaveButton?.addEventListener("click", savePastedGcode);

  document.getElementById("machtileCncProgram")?.addEventListener("change", (event) => {
    const isNew = !event.currentTarget.value;
    document.getElementById("machtileCncNewFields").style.display = isNew ? "" : "none";
  });

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const statusEl = document.getElementById("machtileCncStatus");
    const button = form.querySelector("button[type=submit]");
    const file = pendingFile;
    const programId = document.getElementById("machtileCncProgram").value;
    if (!file) return;
    if (!programId && !document.getElementById("machtileCncPartName").value.trim()) {
      statusEl.textContent = "新程式要填品名。";
      return;
    }
    button.disabled = true;
    try {
      statusEl.textContent = "上傳中…";
      const tenantId = machtileTenantIdFromSession();
      if (!tenantId) throw new Error("讀不到廠區識別，請重新登入。");
      const safeName = sanitizeStorageName(file.name);
      const storagePath = `${tenantId}/cnc-programs/${Date.now()}-${safeName}`;
      const uploadResponse = await fetch(storageObjectUrl("machtile-cnc-programs", storagePath), {
        method: "POST",
        headers: {
          apikey: config.supabaseAnonKey,
          Authorization: `Bearer ${machtileSupabaseBearerToken()}`,
          "Content-Type": file.type || "text/plain",
          "x-upsert": "false",
        },
        body: file,
      });
      if (!uploadResponse.ok) throw new Error(`檔案上傳失敗（${uploadResponse.status}）`);

      // 與前版比對算行數差異（比不了就留空，不擋登錄）
      let changedLineCount = null;
      if (programId) {
        const program = programs.find((p) => p.id === programId);
        const prev = program?.current_version_id ? versionById.get(program.current_version_id) : null;
        if (prev?.storage_path) {
          try {
            const [oldText, newText] = [await machtileFetchProgramText(prev.storage_path), await file.text()];
            const diff = machtileLineDiff(oldText, newText);
            if (diff) changedLineCount = diff.filter((d) => d.type !== "ctx").length;
          } catch (error) { /* 差異計算失敗不影響登錄 */ }
        }
      }

      const payload = {
        program_id: programId || null,
        part_name: document.getElementById("machtileCncPartName").value.trim() || null,
        program_no: document.getElementById("machtileCncProgramNo").value.trim() || null,
        machine_code: document.getElementById("machtileCncMachine").value || null,
        file_name: file.name,
        file_hash: await hashFile(file),
        file_size_bytes: file.size,
        storage_path: storagePath,
        changed_line_count: changedLineCount,
        change_summary: document.getElementById("machtileCncSummary").value.trim() || null,
        estimated_seconds: pendingEstimate?.totalSeconds ?? null,
      };
      const result = await supabaseFetch("rpc/cnc_program_version_register", {
        method: "POST",
        body: JSON.stringify({ p_payload: payload }),
      });
      showToast(`已登錄 ${result?.version_no || "新版本"}`);
      form.reset();
      pendingFile = null;
      pendingEstimate = null;
      form.hidden = true;
      await refresh();
    } catch (error) {
      const msg = String(error?.message || error || "");
      statusEl.textContent = msg.includes("DUPLICATE_FILE") ? "這個檔案內容跟已登錄的版本完全一樣，不用重傳。" : `失敗：${msg}`;
    } finally {
      button.disabled = false;
    }
  });

  document.getElementById("machtileCncList")?.addEventListener("click", async (event) => {
    const diffButton = event.target.closest("[data-cnc-diff]");
    if (!diffButton) return;
    const holder = document.getElementById("machtileCncDiff");
    holder.innerHTML = '<p class="admin-module-note">正在比對…</p>';
    try {
      const current = versionById.get(diffButton.dataset.cncDiff);
      const previous = versionById.get(diffButton.dataset.cncPrev);
      if (!current?.storage_path || !previous?.storage_path) throw new Error("找不到檔案路徑");
      const [oldText, newText] = await Promise.all([
        machtileFetchProgramText(previous.storage_path),
        machtileFetchProgramText(current.storage_path),
      ]);
      const diff = machtileLineDiff(oldText, newText);
      if (!diff) {
        holder.innerHTML = '<p class="admin-module-note">檔案超過 3000 行，只能看行數差異，無法逐行比對。</p>';
        return;
      }
      const changed = diff.filter((d) => d.type !== "ctx");
      const rows = diff
        .filter((d, index) => d.type !== "ctx" || (diff[index - 1] && diff[index - 1].type !== "ctx") || (diff[index + 1] && diff[index + 1].type !== "ctx"))
        .slice(0, 400);
      holder.innerHTML = `
        <section class="machtile-cnc-diff">
          <div class="machtile-cnc-program-head">
            <strong>${escapeHtml(previous.version_no)} → ${escapeHtml(current.version_no)}</strong>
            <span>${changed.length} 行差異${rows.length >= 400 ? "（僅顯示前 400 行）" : ""}</span>
          </div>
          <pre>${rows.map((d) => `<span class="diff-${d.type}">${d.type === "add" ? "＋" : d.type === "del" ? "－" : "　"} ${escapeHtml(d.line)}</span>`).join("\n")}</pre>
        </section>
      `;
    } catch (error) {
      holder.innerHTML = `<p class="admin-module-note">比對失敗：${escapeHtml(String(error?.message || ""))}</p>`;
    }
  });
}

