function renderAll() {
  deriveMachines();
  applyDashboardFilterParams();
  selectedOrder = state.workOrders.find((order) => order.id === selectedOrder?.id) || state.workOrders[0] || null;
  if (selectedOrder) setSelectedOrder(selectedOrder);
  $("#dataSourceLabel").textContent = state.source === "supabase"
    ? `Supabase 已連線${state.cardProcessError ? " · " + state.cardProcessError : ""}${machtileDepartmentAccessError ? " · " + machtileDepartmentAccessError : ""}` : "Mock data";
  ensureHmcDashboardEntry();
  renderStats();
  renderFilters();
  renderWorkOrders();
  renderAlerts();
  renderInspectionQueue();
  renderNotificationCenter();
  renderHistory();
  renderReports();
  renderSettings();
  renderSchedule();
}

function applyDashboardFilterParams() {
  const params = new URLSearchParams(window.location.search);
  const department = params.get("department");
  const millingMode = params.get("millingMode");
  if (departmentFilters.includes(department)) activeDepartmentFilter = department;
  if (millingModeFilters.includes(millingMode)) activeMillingModeFilter = millingMode;
}

function switchView(view) {
  const panel = $(`#${view}View`);
  if (!panel) return;
  $$(".view").forEach((item) => item.classList.remove("is-active"));
  panel.classList.add("is-active");
  $$(".nav-item, .mobile-tab").forEach((button) => {
    const also = String(button.dataset.viewAlso || "").split(",");
    button.classList.toggle("active", button.dataset.view === view || also.includes(view));
  });
  // 課別籤全域列：監控與排程共用（DrCoolant 式），其他頁籤收起
  const departmentBar = $("#departmentBar");
  if (departmentBar) departmentBar.hidden = !(view === "dashboard" || view === "schedule");
  // 車床／銑床批次報工：每次進畫面都重讀進度（已報、待回寫、開工時間）
  const batchGroup = machtileBatchCore()?.groupForView(view);
  if (batchGroup) machtileLoadBatchReport(batchGroup.key);
  // 營運分析：每次進畫面讀（2 分鐘內讀過就用上次的）
  if (view === "reports") machtileLoadAnalytics().catch(() => {});
}

function setSelectedOrder(order) {
  selectedOrder = order;
  $("#reportMachine").textContent = order.machine || UNASSIGNED_MACHINE;
  $("#reportPart").textContent = order.part;
  $("#reportWorkNo").textContent = order.id;
  setReportDefaults(order);
}

function openReport(orderId, options = {}) {
  resetReportFileInputs();
  const machineName = options.machine || "";
  // 只帶機台（機台 QR）→ 預設＝卡片目前顯示的那張（這台最近有活動的單），不再是清單裡交期最早的那張
  if (!orderId && machineName) orderId = machtileCardOrderForMachine(machineName)?.id || "";
  activeReportReturnDetailOrderId = options.returnDetailOrderId || "";
  if (machineName && !isReportableMachineName(machineName)) {
    showToast("未排機不產生報工入口，請先指派實際機台");
    return;
  }
  const orderById = machineName
    ? machtileMachineCardOrders().find(item => item.id === orderId && item.machine === machineName && item.offStation !== true
      && (!options.processId || item.processId === options.processId))
    : state.workOrders.find((item) => item.id === orderId);
  if (options.processId && !orderById) {
    showToast("這道工序已不在此機台，請重新整理後再報工");
    return;
  }
  // Off-station orders (old MES moved them off this machine) are not picked for a machine QR/report.
  const orderByMachine = machineName ? machtileCardOrderForMachine(machineName) : null;
  const order = orderById || orderByMachine || (!machineName ? selectedOrder || state.workOrders[0] : null);
  if (order && !isOrderReportable(order)) {
    showToast("這張工單尚未指派機台，不能開啟報工入口");
    return;
  }
  if (order) {
    setSelectedOrder(order);
  } else if (machineName) {
    selectedOrder = null;
    $("#reportMachine").textContent = machineName;
    $("#reportPart").textContent = "尚未指派工單";
    $("#reportWorkNo").textContent = "待指派";
  }
  setReportType(options.reportType || "workStart");
  machtileStationCmdLabelReportTab(order?.machine || machineName);
  if (!order) setReportDefaults(null);
  $("#reportSheet").classList.toggle("route-sheet", Boolean(options.routeMode));
  document.body.classList.toggle("route-mode", Boolean(options.routeMode));
  $("#reportSheet").classList.add("is-open");
  $("#reportSheet").setAttribute("aria-hidden", "false");
  machtileRenderOperatorSection().catch(() => {});   // strict+flag only; no-op otherwise
  ($("#workTotalQty") || $("#completedQty")).focus();
}

function closeReport() {
  const returnDetailOrderId = activeReportReturnDetailOrderId;
  $("#reportSheet").classList.remove("is-open");
  $("#reportSheet").classList.remove("route-sheet");
  document.body.classList.remove("route-mode");
  $("#reportSheet").setAttribute("aria-hidden", "true");
  activeReportReturnDetailOrderId = "";
  if (returnDetailOrderId) openDetail(returnDetailOrderId);
}

function openDetail(orderId, options = {}) {
  const order = state.workOrders.find((item) => item.id === orderId);
  if (!order) return;
  setSelectedOrder(order);
  $("#detailSheet").classList.toggle("route-sheet", Boolean(options.routeMode));
  document.body.classList.toggle("route-mode", Boolean(options.routeMode));
  $("#detailSheet").classList.add("is-open");
  $("#detailSheet").setAttribute("aria-hidden", "false");
  $("#detailContent").innerHTML = '<p class="empty-note">載入工單明細中...</p>';
  hydrateDetail(order);
}

function closeDetail() {
  $("#detailSheet").classList.remove("is-open");
  $("#detailSheet").classList.remove("route-sheet");
  document.body.classList.remove("route-mode");
  $("#detailSheet").setAttribute("aria-hidden", "true");
}

function openNotificationDrawer() {
  $("#notificationDrawer").classList.add("is-open");
  $("#notificationDrawer").setAttribute("aria-hidden", "false");
  $("#openNotificationsBtn").setAttribute("aria-expanded", "true");
}

function closeNotificationDrawer() {
  $("#notificationDrawer").classList.remove("is-open");
  $("#notificationDrawer").setAttribute("aria-hidden", "true");
  $("#openNotificationsBtn").setAttribute("aria-expanded", "false");
}

async function hydrateDetail(order) {
  let processes = [];
  let reports = [];
  let abnormalities = [];

  if (state.source === "supabase" && isUuid(order.workOrderId)) {
    try {
      processes = await supabaseFetch(
        `work_order_processes?select=process_order,process_code,process_name,process_type,status,qty_planned,qty_completed,qty_defect,inspection_required,inspection_status,planned_start_at,planned_end_at,actual_start_at,actual_end_at,remark&work_order_id=eq.${encodeURIComponent(order.workOrderId)}&order=process_order.asc`
      );
      reports = await supabaseFetch(
        `production_reports?select=completed_qty,defect_qty,status_after_report,remark,created_at&work_order_id=eq.${encodeURIComponent(order.workOrderId)}&order=created_at.desc&limit=8`
      );
      abnormalities = await supabaseFetch(
        `abnormal_events?select=event_type,severity,description,status,reported_at,resolution&work_order_id=eq.${encodeURIComponent(order.workOrderId)}&order=reported_at.desc&limit=6`
      );
    } catch (error) {
      console.warn("Detail load failed, using fallback:", error);
    }
  }

  renderDetail(order, {
    processes: processes.length ? processes : fallbackProcesses(order),
    reports: reports.length ? reports : fallbackReports(order),
    abnormalities: abnormalities.length ? abnormalities : fallbackAbnormalities(order),
  });
}

function fallbackProcesses(order) {
  const currentStatus = order.processStatus || "pending";
  const done = Number(order.done || 0);
  const total = Number(order.total || 0);
  return [
    {
      process_order: 1,
      process_name: order.process?.includes("車") ? "鋸料" : "備料",
      process_type: "preparation",
      status: done > 0 ? "completed" : "pending",
      qty_planned: total,
      qty_completed: done > 0 ? total : 0,
      qty_defect: 0,
      inspection_required: false,
      inspection_status: "none",
      planned_end_at: `${order.dueDate} 09:00+08`,
      remark: done > 0 ? "前段已完成" : "待開工",
    },
    {
      process_order: 2,
      process_name: order.process || "CNC 加工",
      process_type: order.process,
      status: currentStatus,
      qty_planned: total,
      qty_completed: done,
      qty_defect: order.risk ? 1 : 0,
      inspection_required: false,
      inspection_status: "none",
      planned_end_at: `${order.dueDate} 15:00+08`,
      remark: riskSuggestion(order),
    },
    {
      process_order: 3,
      process_name: "品檢",
      process_type: "inspection",
      status: currentStatus === "waiting_inspection" ? "waiting_inspection" : done >= total && total > 0 ? "pending" : "pending",
      qty_planned: total,
      qty_completed: 0,
      qty_defect: 0,
      inspection_required: true,
      inspection_status: currentStatus === "waiting_inspection" ? "pending" : "none",
      planned_end_at: `${order.dueDate} 17:00+08`,
      remark: "加工完成後進入品檢",
    },
  ];
}

function fallbackReports(order) {
  if (!order.done) return [];
  const firstQty = Math.max(1, Math.round(order.done / 2));
  return [
    {
      completed_qty: Math.max(0, order.done - firstQty),
      defect_qty: order.risk ? 1 : 0,
      status_after_report: order.processStatus || "running",
      remark: order.risk ? "現場回報進度落後，需主管確認。" : "正常回報。",
      created_at: new Date(Date.now() - 2 * 3600000).toISOString(),
    },
    {
      completed_qty: firstQty,
      defect_qty: 0,
      status_after_report: "running",
      remark: "開始加工後回報。",
      created_at: new Date(Date.now() - 5 * 3600000).toISOString(),
    },
  ];
}

function fallbackAbnormalities(order) {
  if (!alertCategories(order).has("異常") && !alertCategories(order).has("已延誤") && !alertCategories(order).has("可能延誤")) return [];
  return [{
    event_type: alertReason(order),
    severity: primaryAlertStatus(order) === "overdue" ? "critical" : order.risk || "medium",
    description: riskSuggestion(order),
    status: "open",
    reported_at: new Date(Date.now() - 2 * 3600000).toISOString(),
    resolution: "",
  }];
}

function processLabel(status) {
  const labels = {
    pending: "待開工",
    running: "加工中",
    waiting_inspection: "待品檢",
    completed: "已完成",
    skipped: "略過",
    paused: "暫停",
    abnormal: "異常",
  };
  return labels[status] || status || "-";
}

function processClass(status) {
  if (status === "completed") return "risk-green";
  if (status === "running") return "risk-blue";
  if (status === "waiting_inspection" || status === "paused") return "risk-amber";
  if (status === "abnormal") return "risk-red";
  return "risk-gray";
}

function priorityLabel(priority) {
  const labels = { urgent: "急件", high: "高", normal: "一般", low: "低" };
  return labels[priority] || priority || "-";
}

function inspectionLabel(value) {
  const labels = { none: "無", pending: "待檢", pass: "通過", fail: "不通過", skipped: "略過" };
  return labels[value] || value || "-";
}

function renderDetail(order, detail) {
  const statusKey = deriveOrderStatus(order);
  const status = statusMeta[statusKey] || statusMeta.normal;
  const due = dueInfo(order);
  const percent = pct(order);
  const processes = detail.processes || [];
  const reports = detail.reports || [];
  const abnormalities = detail.abnormalities || [];
  const currentProcess = processes.find((process) => ["running", "waiting_inspection", "abnormal", "paused"].includes(process.status)) || processes[0];
  const profile = getProgramProfile(order);
  const delta = cycleDelta(profile);
  const dailyQty = dailyPureCapacity(profile);
  const workDays = estimatedWorkDays(order, profile);
  const fullOrderUrl = workOrderDetailUrl(order.id);
  const reportable = isOrderReportable(order);

  // Header (owner 2026-09-20 「工單明細 UI 優化」): one card instead of two stacked
  // risk-coloured ones. Left = the order (what), right = machine + completion (where /
  // how far). The report buttons sit right under it — that is what people open this
  // sheet for — and the AI callout below keeps its text only.
  $("#detailContent").innerHTML = `
    <section class="detail-head ${status.className}">
      <div class="detail-head-order">
        <div class="detail-head-pills">
          <span class="status-pill">${escapeHtml(status.label)}</span>
          <span class="machine-type-pill">${escapeHtml(machineTypeLabel(order.process))}</span>
        </div>
        <h3>${escapeHtml(order.part)}</h3>
        <p><span class="detail-work-no">${escapeHtml(order.id)}</span> · ${escapeHtml(order.customer)} · 圖號 ${escapeHtml(order.drawing)}</p>
      </div>
      <div class="detail-head-machine">
        <span>機台</span>
        <strong>${escapeHtml(order.machine || "未排機")}</strong>
        <small>${escapeHtml(order.process)}</small>
        <small>${escapeHtml(order.lastReport || "尚未回報")}</small>
      </div>
      <div class="detail-machine-score">
        <span>完成率</span>
        <strong>${percent}%</strong>
        <small>${order.done} / ${order.total} 件</small>
        ${machtileCardProgressNote(order)}
      </div>
      <div class="detail-progress">
        <div class="progress-track" aria-label="工單完成進度 ${percent}%">
          <div class="progress-fill" style="width:${percent}%"></div>
        </div>
      </div>
    </section>

    <div class="detail-action-row detail-action-row-primary">
      ${reportable
        ? `<button type="button" data-open-report="${escapeHtml(order.id)}" data-open-report-type="workStart">首次開工</button>
           <button type="button" data-open-report="${escapeHtml(order.id)}" data-open-report-type="dailyStart">今日開工</button>
           <a class="detail-link-button" data-no-detail href="${escapeHtml(fullOrderUrl)}" target="_blank" rel="noopener">查看完整工單 ↗</a>`
        : `<button type="button" class="disabled-action" disabled>未指派機台</button>
           <span class="detail-link-button disabled-action">無報工 QR</span>
           <a class="detail-link-button" data-no-detail href="${escapeHtml(fullOrderUrl)}" target="_blank" rel="noopener">查看完整工單 ↗</a>`}
    </div>

    <div class="detail-summary-grid">
      <div><span>交期</span><strong>${escapeHtml(due.label)}</strong><small>${escapeHtml(order.dueDate)}</small></div>
      <div><span>目前製程</span><strong>${escapeHtml(order.process)}</strong><small>${escapeHtml(order.machine || "未排機")}</small></div>
      <div><span>優先級</span><strong>${escapeHtml(priorityLabel(order.priority))}</strong><small>${escapeHtml(order.lastReport)}</small></div>
      <div><span>品檢</span><strong>${escapeHtml(inspectionLabel(currentProcess?.inspection_status))}</strong><small>${currentProcess?.inspection_required ? "需要品檢" : "未要求"}</small></div>
    </div>

    ${machtileHmcDetailSection(machtileHmcMachineFor(order.machine))}

    <section class="detail-ai ${status.className}">
      <div class="advice-title"><span></span>MachTile AI 建議</div>
      <p>${escapeHtml(riskSuggestion(order))}</p>
    </section>

    <section class="detail-section program-section">
      <div class="detail-section-title">
        <h3>程式與加工基準</h3>
        <span>${profile.historyYears ? `近 ${profile.historyYears} 年 ${profile.historyRuns} 次` : "尚未建立履歷"}</span>
      </div>
      <div class="program-grid">
        <div class="program-main-card">
          <span>目前 CNC 程式</span>
          <strong>${escapeHtml(profile.programName)}</strong>
          <small>${escapeHtml(profile.programVersion)} · Hash ${escapeHtml(profile.programHash || "-")}</small>
        </div>
        <div>
          <span>上次版本</span>
          <strong>${escapeHtml(profile.previousVersion || "-")}</strong>
          <small>${profile.changedLines === null ? "無歷史版本" : `${profile.changedLines} 行差異`}</small>
        </div>
        <div>
          <span>純加工時間</span>
          <strong>${escapeHtml(formatSeconds(profile.pureCycleSec))}</strong>
          <small>不含上下料</small>
        </div>
        <div>
          <span>標準基準</span>
          <strong>${escapeHtml(formatSeconds(profile.baselineCycleSec))}</strong>
          <small class="${delta !== null && delta > 8 ? "cycle-warn" : ""}">${delta === null ? "待建立" : `${delta > 0 ? "+" : ""}${delta}%`}</small>
        </div>
        <div>
          <span>每日可加工</span>
          <strong>${dailyQty ? `${dailyQty} 件` : "-"}</strong>
          <small>以 8 小時純加工估算</small>
        </div>
        <div>
          <span>預估工期</span>
          <strong>${workDays ? `${workDays} 天` : "-"}</strong>
          <small>未含上下料與等待</small>
        </div>
      </div>
      <p class="program-note">${escapeHtml(profile.toolChanges)}</p>
    </section>

    <section class="detail-section">
      <div class="detail-section-title">
        <h3>製程進度</h3>
        <span>${machtileFlowVisibilityLevel() === "full" ? `${processes.length} 道製程` : "依角色設定"}</span>
      </div>
      ${machtileFlowVisibilityLevel() !== "full" ? '<p class="empty-note" data-flow-detail-restricted>此角色不顯示完整製程路線（由管理者／主管／排程在「製程路線顯示」設定）。</p>' : `<div class="process-timeline">
        ${processes.map((process) => `
          <article class="process-row ${processClass(process.status)}">
            <div class="process-index">${escapeHtml(process.process_order || "-")}</div>
            <div>
              <div class="process-row-head">
                <strong>${escapeHtml(process.process_name)}</strong>
                <span class="status-pill">${escapeHtml(processLabel(process.status))}</span>
              </div>
              <div class="process-meta-grid">
                <span>預計 ${escapeHtml(formatDateTime(process.planned_end_at))}</span>
                <span>完成 ${Number(process.qty_completed || 0)} / ${Number(process.qty_planned || order.total || 0)}</span>
                <span>不良 ${Number(process.qty_defect || 0)}</span>
                <span>${process.inspection_required ? `品檢 ${inspectionLabel(process.inspection_status)}` : "免品檢"}</span>
              </div>
              ${process.remark ? `<small>${escapeHtml(process.remark)}</small>` : ""}
            </div>
          </article>
        `).join("")}
      </div>`}
    </section>

    <div class="detail-two-column">
      <section class="detail-section">
        <div class="detail-section-title">
          <h3>生產回報紀錄</h3>
          <span>${reports.length} 筆</span>
        </div>
        <div class="report-list">
          ${reports.length ? reports.map((report) => `
            <article class="report-row">
              <div>
                <strong>完成 +${Number(report.completed_qty || 0)} · 不良 ${Number(report.defect_qty || 0)}</strong>
                <p>${escapeHtml(report.remark || "無備註")}</p>
              </div>
              <time>${escapeHtml(formatRelativeTime(report.created_at))}</time>
            </article>
          `).join("") : '<p class="empty-note">尚無生產回報紀錄。</p>'}
        </div>
      </section>

      <section class="detail-section">
        <div class="detail-section-title">
          <h3>異常紀錄</h3>
          <span>${abnormalities.length} 筆</span>
        </div>
        <div class="abnormal-list">
          ${abnormalities.length ? abnormalities.map((event) => `
            <article class="abnormal-row ${processClass(event.severity === "critical" ? "abnormal" : "paused")}">
              <div>
                <strong>${escapeHtml(event.event_type || "異常")}</strong>
                <span class="status-pill">${escapeHtml(event.severity || "medium")}</span>
              </div>
              <p>${escapeHtml(event.description || "-")}</p>
              <small>${escapeHtml(formatDateTime(event.reported_at))} · ${escapeHtml(event.status || "open")}</small>
            </article>
          `).join("") : '<p class="empty-note">目前沒有異常紀錄。</p>'}
        </div>
      </section>
    </div>
  `;
}

function showToast(message) {
  const toast = $("#toast");
  toast.textContent = message;
  toast.classList.add("is-visible");
  window.setTimeout(() => toast.classList.remove("is-visible"), 2200);
}

function openAiSupport() {
  $("#aiSupportPanel")?.classList.add("is-open");
  $("#aiSupportPanel")?.setAttribute("aria-hidden", "false");
  $("#aiSupportFab")?.setAttribute("aria-expanded", "true");
  window.setTimeout(() => $("#aiSupportInput")?.focus(), 50);
}

function closeAiSupport() {
  $("#aiSupportPanel")?.classList.remove("is-open");
  $("#aiSupportPanel")?.setAttribute("aria-hidden", "true");
  $("#aiSupportFab")?.setAttribute("aria-expanded", "false");
}

function appendAiSupportMessage(role, text) {
  const messages = $("#aiSupportMessages");
  if (!messages) return;
  const item = document.createElement("div");
  item.className = `ai-message ai-message-${role}`;
  item.innerHTML = `
    <strong>${role === "user" ? "你" : "MachTile AI 客服"}</strong>
    <p>${escapeHtml(text)}</p>
  `;
  messages.appendChild(item);
  messages.scrollTop = messages.scrollHeight;
}

function aiSupportAnswer(question) {
  const q = String(question || "").toLowerCase();
  if (q.includes("相機") || q.includes("拍照") || q.includes("照片")) {
    return "拍照欄位要點「開啟相機拍照」。手機會優先開後鏡頭，拍完按「拍照使用」。如果瀏覽器沒有相機權限，才會退回手機內建拍照/選檔。\n\n首次開工、收工/完工、異常回報的照片是必填；今日開工的機台照片與 CNC 程式檔是選填。";
  }
  if (q.includes("暫停") || q.includes("pause") || q.includes("停工")) {
    return "「暫停加工」用在加工真的中斷時，例如換刀、待料、量測、機台異音、等主管確認。\n\n點下去後輸入原因，系統會把製程狀態標成 paused，並寫一筆暫停回報。正常中午休息不要用暫停，請用「中午報工」。";
  }
  if (q.includes("報工") || q.includes("一天") || q.includes("中午") || q.includes("4:30") || q.includes("下午")) {
    return "建議報工節點是：\n1. 首次開工：工件總數、cycle time、開工照片、首件檢查必填。\n2. 今日開工：目前機台已加工數量必填，機台照片選填。\n3. 中午報工：這次良品 / 這次不良（填這次新做的數量，不是累計），用來判斷是否加班。\n4. 下午 4:30 檢查：只填檢查表與是否異常，不填數量。\n5. 收工/完工：這次良品 / 這次不良（不是累計）、完工照片、是否加班。";
  }
  if (q.includes("qr") || q.includes("掃碼") || q.includes("未排機")) {
    return "QR Code 只給實際機台使用，例如 CNC-01 到 CNC-08。師傅掃機台 QR 會直接進該機台報工頁。\n\n「未排機」只代表工單尚未指派機台，不應該產生 QR，也不能報工。";
  }
  if (q.includes("警報") || q.includes("延誤") || q.includes("加班") || q.includes("風險")) {
    return "警報頁是風險處理中心。可能延誤、已延誤、異常、待品檢、未回報都集中在那裡。\n\n中午報工是判斷要不要加班的關鍵；下午 4:30 檢查是讓主管下班前確認是否要處理。";
  }
  if (q.includes("管理") || q.includes("設定") || q.includes("員工") || q.includes("程式") || q.includes("加工時間")) {
    return "管理頁目前包含機台、員工、邀請碼、供應商授權、公司資料、製程模板、報工規則、CNC 程式管理、加工時間管理、通知規則、串接設定與資料匯出。\n\nCNC 程式管理用來保存程式版次與 hash；加工時間管理用來保存純加工時間、歷史平均與日產能。";
  }
  if (q.includes("supabase") || q.includes("雲") || q.includes("地端") || q.includes("部署")) {
    return "目前 prototype 已支援 Supabase Cloud。正式版可以分成兩種部署：一般 CNC 加工廠走雲端；成品廠或資安要求高的客戶可用 dedicated cloud 或地端 Supabase/Postgres。\n\n同一套前端可以切換資料來源，不會跟未來 SoftNet MES 衝突。";
  }
  if (q.includes("客服") || q.includes("ai") || q.includes("幫助")) {
    return "我是 MachTile 的內建 AI 客服，先用產品規則回答常見問題。下一步可以接 OpenAI API 或 LINE Messaging API，讓我回答廠內 SOP、報工規則、警報處理與客戶導入問題。";
  }
  return "我先用 MachTile 的規則回答：這個問題可能跟報工、機台、警報、管理或部署有關。你可以問得更具體一點，例如「中午報工要填什麼」、「暫停加工怎麼用」、「QR 可以給未排機嗎」或「Supabase 地端怎麼部署」。";
}

function submitAiSupportQuestion(question) {
  const text = String(question || "").trim();
  if (!text) return;
  appendAiSupportMessage("user", text);
  const input = $("#aiSupportInput");
  if (input) input.value = "";
  window.setTimeout(() => appendAiSupportMessage("assistant", aiSupportAnswer(text)), 180);
}

// ---- CNC field-report offline outbox wiring (2026-07-11) ----
// Plan + locks: docs/MACHTILE_CNC_OUTBOX_APPJS_WIRING_PLAN_2026-07-11.md
// (W1=LocalDevGate, W2=EndedAtOnly, W3=SimulatedOffline, W4=MinimalBadge).
// Gated on config.enableOutboxSubmit (default false): flag off = no module
// import, no listeners, submitReport keeps the direct POST byte-path.
let machtileOutboxInstance = null;
let machtileOutboxLoadPromise = null;
let machtileOutboxDriverStarted = false;
// Attachment entries are captured at submit time (the DOM inputs are cleared
// right after submit) and persisted to an IndexedDB file store keyed by
// report_uuid — so an offline report's photos survive an app restart and get
// uploaded when the report finally sends (backlog A, 2026-07-11). Upload is
// best-effort once, then the entry is deleted (T3) — same tolerance as the
// legacy online path.
const machtileOutboxUploadResults = new Map();

function machtileOutboxEnabled() {
  return Boolean(config.enableOutboxSubmit);
}

async function machtileOutboxHandleSent({ report_uuid, report_id }) {
  const fileStore = machtileOutboxInstance?.fileStore;
  let entries = [];
  if (fileStore) {
    try { entries = (await fileStore.get(report_uuid))?.entries || []; } catch { entries = []; }
  }
  let uploaded = 0;
  let failed = 0;
  if (report_id) {
    for (const entry of entries) {
      try {
        await uploadReportFile(report_id, entry);
        uploaded += 1;
      } catch (error) {
        failed += 1;
        console.warn(error);
      }
    }
  }
  if (fileStore && entries.length) {
    try { await fileStore.delete(report_uuid); } catch { /* best-effort */ }
  }
  if (machtileOutboxUploadResults.size < 50) {
    machtileOutboxUploadResults.set(report_uuid, { uploaded, failed });
  }
  machtileUpdateOutboxBadge();
}

async function machtileGetOutbox() {
  if (!machtileOutboxEnabled()) return null;
  if (machtileOutboxInstance) return machtileOutboxInstance;
  if (!machtileOutboxLoadPromise) {
    machtileOutboxLoadPromise = (async () => {
      // ?v= on module URLs: dynamic import obeys the HTTP cache (Pages
      // max-age=600) — without a bust, a tab that loaded an older module
      // earlier keeps composing against it after a deploy. Bump alongside
      // the index.html app.js ?v= stamp on every outbox change.
      const v = "20260711-outbox-trio2";
      const [outboxMod, storeMod, fileStoreMod, senderMod, submitMod] = await Promise.all([
        import(`./outbox/outbox.mjs?v=${v}`),
        import(`./outbox/outbox-store-idb.mjs?v=${v}`),
        import(`./outbox/outbox-file-store-idb.mjs?v=${v}`),
        import(`./outbox/sender-supabase.mjs?v=${v}`),
        import(`./outbox/field-report-submit.mjs?v=${v}`),
      ]);
      const fileStore = fileStoreMod.createIdbFileStore();
      const outbox = outboxMod.createOutbox({
        store: storeMod.createIdbStore(),
        sender: senderMod.createSupabaseFieldReportSender({
          callRpc: senderMod.createPostgrestRpcCall({
            baseUrl: config.supabaseUrl,
            getHeaders: () => supabaseHeaders(),
          }),
        }),
        online: () => navigator.onLine,
        onSent: machtileOutboxHandleSent,
      });
      const submitter = submitMod.createFieldReportSubmitter({ outbox, fileStore });
      machtileOutboxInstance = { outbox, submitter, fileStore };
      machtileOutboxStartDriver(outbox);
      return machtileOutboxInstance;
    })().catch((error) => {
      machtileOutboxLoadPromise = null;
      console.warn("outbox unavailable, falling back to direct submit", error);
      return null;
    });
  }
  return machtileOutboxLoadPromise;
}

function machtileOutboxStartDriver(outbox) {
  if (machtileOutboxDriverStarted) return;
  machtileOutboxDriverStarted = true;
  const flush = () => outbox.flush().then(() => machtileUpdateOutboxBadge()).catch(() => {});
  window.addEventListener("online", flush);
  window.setInterval(() => { if (navigator.onLine) flush(); }, 30000);
  flush(); // startup: resend leftovers from previous sessions (online() guards offline)
}

async function machtileUpdateOutboxBadge() {
  if (!machtileOutboxInstance) return;
  const { outbox } = machtileOutboxInstance;
  let pendingCount = 0;
  let failedCount = 0;
  try {
    pendingCount = (await outbox.pending()).length;
    failedCount = (await outbox.deadLetters()).length;
  } catch {
    return;
  }
  let badge = document.getElementById("machtileOutboxBadge");
  if (pendingCount === 0 && failedCount === 0) {
    // 2026-10-01：cssText 寫死 display:flex，光設 hidden 藏不起來（待送 0 筆後徽章還一直掛著、
    // 壓住手機底部分頁列）。改用 style.display。
    if (badge) { badge.hidden = true; badge.style.display = "none"; }
    return;
  }
  if (!badge) {
    badge = document.createElement("div");
    badge.id = "machtileOutboxBadge";
    badge.style.cssText =
      "position:fixed;left:16px;bottom:16px;z-index:60;display:flex;gap:8px;align-items:center;" +
      "padding:8px 12px;border-radius:10px;background:#1f2937;color:#f9fafb;font-size:13px;" +
      "box-shadow:0 4px 12px rgba(0,0,0,.25);";
    document.body.appendChild(badge);
  }
  badge.hidden = false;
  badge.style.display = "flex";
  // 手機版底部有分頁列（56px）：徽章放在它上面，別擋住「監控」等分頁
  badge.style.bottom = window.matchMedia?.("(max-width: 720px)").matches ? "72px" : "16px";
  const failedText = failedCount
    ? `<button type="button" data-outbox-retry style="border:0;border-radius:8px;padding:4px 8px;background:#dc2626;color:#fff;cursor:pointer;">送失敗 ${failedCount} 筆，點擊重試</button>`
    : "";
  badge.innerHTML = `${pendingCount ? `<span>報工待送 ${pendingCount} 筆</span>` : ""}${failedText}`;
  badge.querySelector("[data-outbox-retry]")?.addEventListener("click", async () => {
    const dead = await outbox.deadLetters();
    for (const item of dead) await outbox.requeue(item.report_uuid);
    outbox.flush().then(() => machtileUpdateOutboxBadge()).catch(() => {});
    machtileUpdateOutboxBadge();
  });
}

async function machtileSubmitReportViaOutbox(box, basePayload, structuredPayload, reportType, operators, filesOverride = null) {
  // ended_at = capture time fixed at enqueue (accurate even if the report is
  // sent hours later); started_at from the rolling ledger (W2=EndedAtOnly
  // superseded 2026-07-11 — the writeback bridge requires both).
  const endedAt = new Date().toISOString();
  // 2026-10-02 review fix: also floor started_at at this process's last report on the SERVER
  // (any device, e.g. a phone batch report). Without it a tablet whose own ledger is older
  // re-claims the batch report's period → the same hours land twice in SFC (CT／每人產值).
  const serverLastAt = await machtileServerLastReportAt(basePayload.process_id);
  const startedAt = machtileTakeStartedAt(basePayload.process_id, endedAt, serverLastAt);
  const payload = {
    ...basePayload,
    ...structuredPayload,
    ended_at: endedAt,
  };
  if (startedAt) payload.started_at = startedAt;
  // filesOverride（開工確認卡的今日開工＝[]）：不去讀報工表單上可能還留著的照片
  const files = Array.isArray(filesOverride) ? filesOverride : config.enableFileUpload ? reportFilesForType(reportType) : [];
  const { report_uuid } = await box.submitter.submit(payload, {
    operators: operators && operators.length ? operators : (basePayload.user_id ? [basePayload.user_id] : []),
    files,
  });
  // submit() already fire-and-forgets a flush; await one more (it joins the
  // in-flight scan) so the toast can tell "written now" from "queued offline".
  await box.outbox.flush().catch(() => {});
  const record = await box.outbox.get(report_uuid).catch(() => null);
  const sentNow = record?.status === "sent";
  const uploadResult = machtileOutboxUploadResults.get(report_uuid) || { uploaded: 0, failed: 0 };
  machtileOutboxUploadResults.delete(report_uuid);
  machtileUpdateOutboxBadge();
  return {
    wroteCloud: true,
    queuedOffline: !sentNow,
    uploaded: uploadResult.uploaded,
    uploadFailed: uploadResult.failed,
    reportUuid: report_uuid || null,
    // 伺服器明確拒絕（dead-letter）：既有報工畫面照舊只看 queuedOffline；開工確認卡用它判「沒存到」
    deadLetter: record?.status === "failed",
    // 已送達時伺服器回的列 id（field_report_upsert 的 report_id）；開工確認卡只在有它時才說「已記錄」
    reportId: sentNow ? (record?.report_id ?? null) : null,
  };
}

// ---- started_at rolling ledger (2026-07-11, TODO_APPJS_STARTED_AT_FOR_CNC_WRITEBACK) ----
// The SoftNet writeback bridge REQUIRES started_at (contract §3: 工時 = out−in;
// rows without it are rejected). Lock=RollingLedger: each report's started_at
// = the previous report/開工 timestamp for the same process (kept per-device in
// localStorage), then the ledger rolls forward to this report's ended_at — so
// periods tile without overlap and their sum equals real elapsed time. Ledger
// miss (first-ever report on this device) → started_at stays null: visible
// bridge reject instead of fabricated hours.
const MACHTILE_STARTED_AT_LEDGER_KEY = "machtile-outbox-started-at";

// serverFloorIso (optional, 2026-10-02): the process's last report end on the server. The
// started_at is the LATEST of {device ledger, server floor} that is not after ended_at — the
// same rule as the batch screen (batchReportCore.resolveStartedAt), so periods reported from
// different devices tile instead of overlapping. Neither known → null, as before.
function machtileTakeStartedAt(processId, endedAtIso, serverFloorIso = null) {
  if (!processId) return null;
  let startedAt = null;
  const floor = (() => {
    const t = serverFloorIso ? Date.parse(serverFloorIso) : NaN;
    return Number.isFinite(t) ? new Date(t).toISOString() : null;
  })();
  try {
    let ledger;
    try { ledger = JSON.parse(localStorage.getItem(MACHTILE_STARTED_AT_LEDGER_KEY) || "{}") || {}; }
    catch { ledger = {}; }
    const prev = ledger[processId];
    // ISO-8601 UTC strings compare lexicographically; guard ended>=started
    // (the RPC raises otherwise, e.g. after a device clock change).
    if (typeof prev === "string" && prev && prev <= endedAtIso) startedAt = prev;
    if (floor && floor <= endedAtIso && (!startedAt || floor > startedAt)) startedAt = floor;
    ledger[processId] = endedAtIso;   // roll forward
    localStorage.setItem(MACHTILE_STARTED_AT_LEDGER_KEY, JSON.stringify(ledger));
  } catch {
    // storage unavailable → only the server floor is known
    if (floor && floor <= endedAtIso) startedAt = floor;
  }
  return startedAt;
}

// Latest report end (ended_at, else created_at) of this process on the server, any device/type.
// Best effort with a short timeout: offline / slow / error → null and the device ledger alone
// decides (the report still queues offline exactly as before).
async function machtileServerLastReportAt(processId, timeoutMs = 2500) {
  if (state.source !== "supabase" || !isUuid(processId)) return null;
  const controller = typeof AbortController === "function" ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
  try {
    const rows = await supabaseFetch(
      `production_reports?select=ended_at,created_at&process_id=eq.${encodeURIComponent(processId)}&order=created_at.desc&limit=50`,
      controller ? { signal: controller.signal } : {},
    );
    let latest = null;
    (Array.isArray(rows) ? rows : []).forEach((row) => {
      const at = row?.ended_at || row?.created_at;
      const t = at ? Date.parse(at) : NaN;
      if (Number.isFinite(t) && (latest === null || t > latest)) latest = t;
    });
    return latest === null ? null : new Date(latest).toISOString();
  } catch (error) {
    return null;
  } finally {
    if (timer) clearTimeout(timer);
  }
}

// ---- operator multi-select (backlog C, 2026-07-11; T2=all active users) ----
// Strict-only + flag-on: the report sheet gains an 操作人員 checklist so one
// station account can credit several people's 每人產值 (operators -> RPC
// operator_ids). dev-nologin never renders it (no session, byte-identical).
let machtileOperatorListCache = null;

async function machtileFetchOperatorList() {
  if (!machtileStrictMode() || !machtileSessionActive()) return [];
  if (machtileOperatorListCache) return machtileOperatorListCache;
  try {
    // legacy_user_id 一起撈：它是「這個人能不能被歸產值」唯一機器可判的準則
    // （回寫 feed 只收有對照的，見 machtile-mini-mes 的 2026-09-02 F-3 migration）。
    const rows = await supabaseFetch("app_users?select=id,name,legacy_user_id&is_active=eq.true&order=name");
    machtileOperatorListCache = Array.isArray(rows) ? rows : [];
  } catch (error) {
    console.warn("operator list lookup failed; falling back to single actor", error);
    machtileOperatorListCache = [];
  }
  return machtileOperatorListCache;
}

// 有 legacy_user_id 才算「歸得了產值的人」。站別/面板帳號（HMC-01 站別…）
// 沒有對照，回寫 feed 也收不了它，所以在 UI 就不當成有效作業員。
function machtileIsMappedOperator(u) {
  return Boolean(String(u?.legacy_user_id ?? "").trim());
}

// Injected before the 備註 field each time the report sheet opens.
//
// ⚠️ 2026-09-02（owner 決策 F-2）：原本是「預設勾選當下登入帳號」。但現場平板
// 是用站別帳號登入的，於是預設就把報工掛在機台身上——實測 8 筆有署名的報工
// 100% 掛在 HMC-01/02 站別上，掛真人的 0 筆。現在改成：只有當登入帳號本身
// 是有對照的真人時才預設勾選；站別帳號不預設勾選，且必須至少選一位有對照的
// 人員才能送出（見 machtileValidateOperatorSelection）。
async function machtileRenderOperatorSection() {
  if (!machtileOutboxEnabled() || !machtileStrictMode() || !machtileSessionActive()) return;
  const form = document.getElementById("reportForm");
  const anchor = form?.querySelector('label[for="reportNote"]');
  if (!form || !anchor) return;
  const actorId = await machtileResolveAppUserId();
  const allUsers = await machtileFetchOperatorList();
  // 只列「有對照工號」的人：沒對照的本來就過不了送出閘門（產值歸不到人），
  // 站別／測試／管理帳號列出來只是讓現場多滑一頁（owner 2026-09-20）。
  const users = allUsers.filter(machtileIsMappedOperator);
  if (!allUsers.length) return;
  let section = document.getElementById("machtileOperatorSection");
  if (!section) {
    section = document.createElement("section");
    section.id = "machtileOperatorSection";
    section.className = "report-section";
    form.insertBefore(section, anchor);
  }
  const actor = allUsers.find((u) => u.id === actorId);
  const actorIsMapped = machtileIsMappedOperator(actor);
  // 提示沿用既有的 .report-section-head span（muted / 12px / 右對齊），
  // 維持原作者「zero styles.css change」的設計。
  section.innerHTML = `
    <div class="report-section-head"><strong>操作人員</strong><span id="machtileOperatorHint"></span></div>
    <div class="checklist-card" id="machtileOperatorList"></div>
  `;
  const list = section.querySelector("#machtileOperatorList");
  users.forEach((u) => {
    const mapped = machtileIsMappedOperator(u);
    const label = document.createElement("label");
    const input = document.createElement("input");
    input.type = "checkbox";
    input.value = u.id;
    input.dataset.mapped = mapped ? "1" : "0";
    // 只有「登入的就是本人、而且有對照」才預設勾選。站別帳號一律不預設。
    input.checked = mapped && u.id === actorId;
    label.appendChild(input);
    label.appendChild(document.createTextNode(` ${u.name || u.id}${mapped ? "" : "（未對照工號）"}`));
    list.appendChild(label);
  });
  const hint = section.querySelector("#machtileOperatorHint");
  if (hint) {
    hint.textContent = !users.length
      ? "還沒有任何人員對照到 SoftNet 工號，請管理者先補上工號對照。"
      : actorIsMapped
        ? "請確認實際操作的人員；可複選。"
        : "此裝置以站別帳號登入，請勾選實際操作的人員（至少一位）才能送出。";
  }
}

// Checked operators from the section. 區段存在時就以勾選為準——**不再**在沒勾
// 任何人時退回登入帳號，那個 fallback 正是報工掛到站別帳號上的第二個來源。
// 區段不存在（dev-nologin、清單查詢失敗）維持原本的單人 fallback 不變。
function machtileSelectedOperators(actorAppUserId) {
  const list = document.getElementById("machtileOperatorList");
  if (list) {
    return Array.from(list.querySelectorAll('input[type="checkbox"]:checked')).map((i) => i.value);
  }
  return actorAppUserId ? [actorAppUserId] : [];
}

// 送出前的閘門：區段有出現時，至少要勾一位「有對照工號」的人員。
// 回傳提示字串代表擋下，回傳 null 代表放行。
// 區段不存在時一律放行（維持 dev-nologin / 查詢失敗時的既有行為）。
function machtileValidateOperatorSelection() {
  const list = document.getElementById("machtileOperatorList");
  if (!list) return null;
  const checked = Array.from(list.querySelectorAll('input[type="checkbox"]:checked'));
  if (!checked.length) return "請勾選實際操作的人員（至少一位）。";
  if (!checked.some((i) => i.dataset.mapped === "1")) {
    return "勾選的人員都還沒對照到 SoftNet 工號，產值會歸不到人。請改選已對照的人員，或請管理者先補上工號對照。";
  }
  return null;
}

// ---- 車床／銑床批次報工（owner 2026-10-01「做批次報工」）----
// 一台一列、只填這次的良品／不良，一次送出＝每台各建一筆報工。決策邏輯在 batchReportCore.js；
// 這裡只有 DOM、讀資料、送出。送出沿用單台報工的 offline outbox（field_report_upsert，report_uuid 冪等）；
// outbox 載不起來時直接呼叫同一支 RPC（同一個 report_uuid，重送也不會變兩筆）。
// 已報＝舊 MES 累計＋待回寫：machtile-mini-mes migration 20261001120000 的 batch_report_progress
// （同一個 SQL 快照判斷哪些 App 報工已經寫進舊 MES，絕不重複計數）。讀不到時顯示「—」，照樣可以報工。
const machtileBatchCore = () => (typeof window === "undefined" ? null : window.MachTileBatchReportCore);
const MACHTILE_BATCH_DRAFT_KEY = "machtile-batch-report-drafts";
const machtileBatchState = {
  group: "lathe",
  // 報工類型分頁（今日開工／中午報工／收工 / 完工）。預設中午報工＝原本的批次行為。
  mode: "noon",
  loading: false,
  submitting: false,
  error: "",
  formError: "",
  progressError: "",
  progressByProcess: new Map(),
  // 機台加工時間（秒／件）：每道工序最新一次填的值（production_reports.cycle_time_seconds）。
  machineTimeByProcess: new Map(),
  users: [],
  actorId: "",
  // 收工：是否加班（單台收工的必填單選，套用到這次送出的每一台）
  overtime: "",
  rows: new Map(),       // machineCode → { processId, good, bad, operatorId, selected, ctMinutes, ctSeconds, error, result }
  stationReportSettings: { status: "unavailable", machines: {}, failReasonCodesByMachine: {}, error: "" },
  stationReportIdentityByProcess: new Map(),
  lastLoadedAt: 0,
};

const machtileStationReportCore = () => (typeof window === "undefined" ? null : window.MachTileStationReportCore);
const machtileStationReportEnabled = () => window.MACHTILE_CONFIG?.enableStationReport === true;
const MACHTILE_STATION_REPORT_RESULT = "智慧報工結果仍待確認；不要重送相同數量。";

async function machtileLoadStationReportSettings(machineCodes) {
  const core = machtileStationReportCore();
  machtileBatchState.stationReportSettings = { status: "unavailable", machines: {}, failReasonCodesByMachine: {}, error: "" };
  if (!machtileStationReportEnabled() || !core || state.source !== "supabase" || !Array.isArray(machineCodes) || !machineCodes.length) return;
  try {
    const client = machtileStationReportCreateClient();
    const allowed = window.MACHTILE_CONFIG.stationReportMachines || [];
    const enabledCodes = machineCodes.filter((code) => allowed.includes(code) || allowed.includes("*"));
    const configs = await Promise.all(enabledCodes.map((code) => client.getGuardConfig(code)));
    const machines = {};
    const failReasonCodesByMachine = {};
    configs.forEach((configRow, index) => {
      const code = String(enabledCodes[index]).trim().toUpperCase();
      if (!core.isGuardConfig(configRow, code)) throw new Error(`invalid guard config for ${code}`);
      // Factory's synced display list is the runtime kill switch. A configured-but-disabled
      // machine must keep the legacy batch-report path and must not render the smart-report UI.
      machines[code] = core.guardConfigReportEnabled(configRow, code);
      failReasonCodesByMachine[code] = configRow.fail_reason_codes;
    });
    machtileBatchState.stationReportSettings = { status: "loaded", machines, failReasonCodesByMachine, error: "" };
  } catch (error) {
    // Until the report RPC/config migration is synchronized, fail closed. Never
    // fall through to production_reports for an enabled report station.
    machtileBatchState.stationReportSettings = { status: "unavailable", machines: {}, failReasonCodesByMachine: {}, error: "智慧報工後端尚未同步；本功能目前關閉。" };
    console.info("station report settings unavailable; feature stays disabled", error?.message || error);
  }
}

async function machtileLoadStationReportIdentity(machineCodes) {
  const core = machtileStationReportCore();
  const identities = new Map();
  machtileBatchState.stationReportIdentityByProcess = identities;
  if (!core || state.source !== "supabase" || machtileBatchState.stationReportSettings.status !== "loaded") return;
  const enabledCodes = (machineCodes || []).filter((code) => core.reportMachineEnabled(machtileBatchState.stationReportSettings.machines, code));
  const processIds = [...new Set(enabledCodes.flatMap((code) => machtileBatchCandidates(code).map((order) => String(order.processId || ""))).filter(isUuid))];
  if (!processIds.length) return;
  try {
    // Separate, optional read after the config gate: old card/list queries never
    // select these columns, so an unapplied bridge migration cannot break them.
    // A missing projection schema leaves the map empty and submit stays blocked.
    const rows = [];
    for (let i = 0; i < processIds.length; i += 80) {
      const chunk = processIds.slice(i, i + 80).map(encodeURIComponent).join(",");
      const result = await supabaseFetch(`work_order_processes?select=id,legacy_index_sn,manufacture_ii_id,simulation_id,work_orders!inner(part_no)&id=in.(${chunk})`);
      if (!Array.isArray(result)) throw new Error("工序舊 MES 識別資料格式不正確");
      rows.push(...result);
    }
    rows.forEach((row) => {
      if (row && isUuid(row.id)) identities.set(String(row.id), {
        legacy_index_sn: row.legacy_index_sn,
        manufacture_ii_id: row.manufacture_ii_id,
        simulation_id: row.simulation_id,
        part_no: row.work_orders?.part_no,
      });
    });
  } catch (error) {
    console.info("station report legacy identity projection unavailable; submit stays blocked", error?.message || error);
  }
}

function machtileRenderStationReportPanel(code, order, row, busy) {
  const core = machtileStationReportCore();
  const settings = machtileBatchState.stationReportSettings;
  if (!core || settings.status !== "loaded" || !core.reportMachineEnabled(settings.machines, code)) return "";
  const flow = machtileStationReportState(row);
  const context = machtileStationReportContext(order, code);
  const route = machtileProcessFlows.get(order?.id);
  const routeLevel = machtileFlowVisibilityLevel();
  const routeSteps = route && window.MachTileProcessFlow?.steps
    ? window.MachTileProcessFlow.steps(route.processes, order?.processId, route.quantity) : [];
  const routePosition = routeSteps.findIndex((step) => step.current);
  const routeCurrent = routePosition >= 0 ? routeSteps[routePosition] : null;
  const routeSummary = routeLevel === "full" && routeSteps.length
    ? `<div class="station-report-route-summary">第 ${routePosition >= 0 ? routePosition + 1 : "?"}／共 ${routeSteps.length} 道・本道累計已報 ${routeCurrent?.done == null ? "無資料" : escapeHtml(routeCurrent.done)}／${route.quantity != null && Number.isFinite(Number(route.quantity)) ? escapeHtml(route.quantity) : "工單量無資料"} 件</div>${machtileProcessFlowMarkup(order, { compact: true, level: routeLevel })}`
    : "";
  const missingContext = machtileStationReportMissingContext(order, code);
  const reasons = settings.failReasonCodesByMachine[code] || [];
  const reasonOptions = ["<option value=\"\">選不良原因</option>", ...reasons.map((reason) =>
    `<option value="${escapeHtml(reason)}"${reason === row.failReasonCode ? " selected" : ""}>${escapeHtml(reason)}</option>`)].join("");
  const result = flow.result ? core.resultCard(flow.result) : null;
  const operatorName = machtileBatchState.users.find((user) => String(user.id) === String(row.operatorId))?.name || row.operatorId || "未選報工人";
  const confirmCard = `<div class="station-report-confirm-card" role="group" aria-label="報工確認資訊">
    <strong>${escapeHtml(machtileBatchMachineLabel(code))}・${escapeHtml(operatorName)}</strong>
    <div>工單尾碼 <b>${escapeHtml(String(order?.id || "").slice(-4))}</b>・${escapeHtml(order?.partNo || context?.expectedPartNo || "")}
      ${escapeHtml(order?.partName || "")}</div>
    <div>第 ${escapeHtml(context?.expectedIndexSn || "?")} 道・${escapeHtml(order?.process || "")}</div>
    <div>本次良 <b>${escapeHtml(row.good || 0)}</b>／不良 <b>${escapeHtml(row.bad || 0)}</b>；目前可報
      <b>${escapeHtml(result?.values?.available ?? "—")}</b></div></div>`;
  let resultHtml = "";
  if (result) {
    const resultTone = result.kind === "applied" || result.kind === "previewed" ? "success"
      : result.kind === "pending" ? "pending" : result.kind === "soft" || result.kind === "preview-soft" ? "warning" : "error";
    const previewValues = result.values && Number.isInteger(result.values.available)
      ? `<div class="station-report-preview-values"><span>目前可報 <strong>${result.values.available}</strong> 件</span>${Number.isInteger(result.values.predicted_ac03_qty) ? `<span>預估先領 <strong>${result.values.predicted_ac03_qty}</strong> 件</span>` : ""}</div>`
      : "";
    const snapshotReady = ["previewed", "preview-soft"].includes(result.kind) && (() => { try { core.buildClientGuardSnapshot(flow.preview); return true; } catch { return false; } })();
    const prevIndex = Number(result.previousIndex);
    const previousStep = ["hard", "preview-blocked"].includes(result.kind) && (result.code || result.guardCode) === "QTY_EXCEEDS_AVAILABLE" && Number.isInteger(prevIndex) && prevIndex > 0
      ? `<a class="station-report-previous-step" href="${escapeHtml(workOrderDetailUrl(order?.id))}">查看製程路線，先報第 ${prevIndex} 道</a>` : "";
    resultHtml = `<div class="station-report-result is-${resultTone}" role="${resultTone === "error" ? "alert" : "status"}"><strong>${escapeHtml(result.title)}</strong><p>${escapeHtml(result.message)}</p>${previewValues}${previousStep}</div>`;
    if (result.kind === "previewed") {
      resultHtml += snapshotReady
        ? `${confirmCard}<div class="station-report-actions"><button type="button" class="primary-action station-report-action" data-station-report-confirm="${escapeHtml(code)}"${busy ? " disabled" : ""}>長按 1 秒確認報工</button><button type="button" class="secondary-action station-report-action" data-station-report-cancel-preview="${escapeHtml(code)}">修改數量並重新預覽</button></div>`
        : `<p class="batch-notice is-error" role="alert">預覽回傳 guard 欄位不完整；已阻擋正式送出。</p>`;
    } else if (result.kind === "preview-soft") {
      resultHtml += snapshotReady
        ? `${confirmCard}<div class="station-report-actions"><button type="button" class="primary-action station-report-action" data-station-report-preview-ack="${escapeHtml(code)}"${busy ? " disabled" : ""}>長按 1 秒確認照送（${escapeHtml(result.guardLabel)}）</button><button type="button" class="secondary-action station-report-action" data-station-report-cancel-preview="${escapeHtml(code)}">修改數量並重新預覽</button></div>`
        : `<p class="batch-notice is-error" role="alert">軟性 guard 預覽資料不完整；已阻擋送出。</p>`;
    } else if (result.kind === "preview-blocked" || result.kind === "preview-invalid") {
      resultHtml += `<p class="batch-notice is-error" role="alert">${escapeHtml(result.guardCode ? `${result.guardLabel}：` : "")}${escapeHtml(result.kind === "preview-invalid" ? "預覽資料不完整；已阻擋正式送出。" : "已阻擋確認送出；可修改數量後重新預覽。")}</p><div class="station-report-actions"><button type="button" class="secondary-action station-report-action" data-station-report-cancel-preview="${escapeHtml(code)}">修改數量並重新預覽</button></div>`;
    } else if (result.kind === "soft") {
      resultHtml += `<div class="station-report-actions"><button type="button" class="primary-action station-report-action" data-station-report-ack="${escapeHtml(code)}"${busy ? " disabled" : ""}>照送（使用新識別碼）</button><button type="button" class="secondary-action station-report-action" data-station-report-cancel="${escapeHtml(code)}">取消</button></div>`;
    }
    if (flow.phase === "blocked" && flow.args) resultHtml += `<button type="button" class="secondary-action station-report-action" data-station-report-reconcile="${escapeHtml(code)}">查詢原報工狀態</button>`;
    if (result.kind === "applied" || result.kind === "applied-late") resultHtml += `<button type="button" class="secondary-action station-report-action" data-station-report-new="${escapeHtml(code)}">下一筆（清空數量）</button>`;
  }
  const noContext = !context;
  const phaseBusy = ["submitting-preview", "waiting-preview", "submitting-report", "waiting-report"].includes(flow.phase);
  const finalApplied = result?.kind === "applied" || result?.kind === "applied-late";
  const formAllowed = !busy && !phaseBusy && flow.phase !== "blocked" && flow.phase !== "previewed" && !finalApplied && !noContext;
  const oldOrderNoteAllowed = !busy && !phaseBusy && result?.kind === "preview-soft" && result.guardCode === "OLD_ORDER_NEWER_OPEN";
  const contextMessage = noContext
    ? `已選工單 ${order?.id || "—"}／機台 ${code}／畫面工序 ${order?.process || "—"}${order?.stationStep ? `（APP 工序序號 ${order.stationStep}）` : ""}。缺少：${missingContext.join("、") || "合約識別資料"}；不會用 APP process_order 代替舊 MES IndexSN。`
    : "送出前會先由套用端唯讀預覽；預覽完成以前不會建立正式報工。";
  return `<section class="station-report-panel" aria-label="${escapeHtml(code)} 智慧報工">
    <div class="station-report-heading"><strong>智慧報工</strong><span>套用端預覽 → 確認</span></div>
    <p class="station-report-hint">${escapeHtml(contextMessage)}</p>
    ${routeSummary}
    ${flow.error ? `<p class="batch-notice is-error" role="alert">${escapeHtml(flow.error)}</p>` : ""}
    <label class="station-report-reason"><span>不良原因（有不良時必選）</span><select data-station-report-reason="${escapeHtml(code)}"${!formAllowed ? " disabled" : ""}>${reasonOptions}</select></label>
    <label class="station-report-note"><span>備註（舊單確認時必填）</span><textarea rows="2" maxlength="500" data-station-report-note="${escapeHtml(code)}"${!formAllowed && !oldOrderNoteAllowed ? " disabled" : ""}>${escapeHtml(row.reportNote || "")}</textarea></label>
    <button type="button" class="secondary-action station-report-action" data-station-report-preview="${escapeHtml(code)}"${!formAllowed || !row.good && !row.bad ? " disabled" : ""}>${flow.phase === "waiting-preview" ? "等待套用端預覽…" : "先預覽，不寫入舊 MES"}</button>
    ${resultHtml}
  </section>`;
}

async function machtileStationReportWait(code, commandUuid, kind) {
  const core = machtileStationReportCore();
  const row = machtileBatchRow(code);
  const flow = machtileStationReportState(row);
  const client = machtileStationReportCreateClient();
  if (!client) throw new Error("智慧報工介面尚未載入。");
  const result = await client.waitForTerminal(commandUuid, { intervalMs: 2000, maxAttempts: 90 });
  flow.result = result;
  flow.phase = core.isTerminal(result)
    ? (kind === "preview" && result.command_type === "report_preview" && result.status === "previewed" ? "previewed" : "finished")
    : `waiting-${kind}`;
  if (kind === "preview") flow.preview = result;
  if (kind === "report") flow.report = result;
  flow.error = core.isTerminal(result) ? "" : "套用結果仍未確認；請勿重送，先查詢原識別碼。";
}

async function machtileStationReportSubmitPreview(code) {
  const core = machtileStationReportCore();
  const order = machtileBatchSelectedOrder(code);
  const row = machtileBatchRow(code);
  const flow = machtileStationReportState(row);
  const context = machtileStationReportContext(order, code);
  if (!core || !context || machtileStationReportFlowBusy(flow)) return;
  const form = { ...context, goodQty: row.good, failQty: row.bad, failReasonCode: row.failReasonCode || null,
    reportNote: row.reportNote || null, acks: [], clientGuardSnapshot: null };
  let args;
  try {
    args = core.buildSubmitArgs(form, crypto.randomUUID(), true, machtileBatchState.stationReportSettings.failReasonCodesByMachine[code] || []);
  } catch (error) {
    flow.error = error.message || "報工資料不完整。";
    machtileRenderBatchReport();
    return;
  }
  flow.args = args;
  flow.phase = "submitting-preview";
  flow.error = "";
  machtileRenderBatchReport();
  try {
    const client = machtileStationReportCreateClient();
    const submitted = await client.submit(args);
    const item = Array.isArray(submitted) ? submitted[0] : submitted;
    flow.preview = item?.command_uuid === args.p_command_uuid ? item : null;
    flow.phase = "waiting-preview";
    if (item && core.isTerminal(item)) {
      flow.result = item;
      flow.phase = item.command_type === "report_preview" && item.status === "previewed" ? "previewed" : "finished";
    }
    else await machtileStationReportWait(code, args.p_command_uuid, "preview");
  } catch (error) {
    flow.phase = "blocked";
    flow.error = error.code === "STATION_REPORT_BACKEND_UNAVAILABLE"
      ? "智慧報工後端尚未同步；未建立正式報工。"
      : `${MACHTILE_STATION_REPORT_RESULT} ${error.message || ""}`;
  }
  machtileRenderBatchReport();
}

async function machtileStationReportSubmitFinal(code) {
  const core = machtileStationReportCore();
  const row = machtileBatchRow(code);
  const flow = machtileStationReportState(row);
  if (!core || machtileStationReportFlowBusy(flow) || !flow.preview) return;
  let snapshot;
  try { snapshot = core.buildClientGuardSnapshot(flow.preview); }
  catch (error) { flow.error = error.message; machtileRenderBatchReport(); return; }
  const context = machtileStationReportContext(machtileBatchSelectedOrder(code), code);
  if (!context) { flow.error = "工序識別資料不完整；已阻擋正式送出。"; machtileRenderBatchReport(); return; }
  let args;
  try {
    args = core.buildSubmitArgs({ ...context, goodQty: row.good, failQty: row.bad, failReasonCode: row.failReasonCode || null,
      reportNote: row.reportNote || null, acks: [], clientGuardSnapshot: snapshot }, crypto.randomUUID(), false,
    machtileBatchState.stationReportSettings.failReasonCodesByMachine[code] || []);
  } catch (error) { flow.error = error.message || "報工資料不完整。"; machtileRenderBatchReport(); return; }
  await machtileStationReportSendFinal(code, args);
}

async function machtileStationReportSendFinal(code, args) {
  const core = machtileStationReportCore();
  const row = machtileBatchRow(code);
  const flow = machtileStationReportState(row);
  flow.args = args;
  flow.phase = "submitting-report";
  flow.error = "";
  machtileRenderBatchReport();
  try {
    const client = machtileStationReportCreateClient();
    const submitted = await client.submit(args);
    const item = Array.isArray(submitted) ? submitted[0] : submitted;
    flow.phase = "waiting-report";
    if (item && core.isTerminal(item)) { flow.result = item; flow.phase = "finished"; flow.report = item; }
    else await machtileStationReportWait(code, args.p_command_uuid, "report");
  } catch (error) {
    flow.phase = "blocked";
    flow.error = error.code === "STATION_REPORT_BACKEND_UNAVAILABLE"
      ? "智慧報工後端尚未同步；未建立正式報工。"
      : `${MACHTILE_STATION_REPORT_RESULT} ${error.message || ""}`;
  }
  machtileRenderBatchReport();
}

async function machtileStationReportRetryAck(code) {
  const core = machtileStationReportCore();
  const row = machtileBatchRow(code);
  const flow = machtileStationReportState(row);
  const result = flow.result;
  if (!core || !flow.args || !result || !core.SOFT_REJECTS.includes(result.reject_code)) return;
  let args;
  try { args = core.retryWithAck({ ...flow.args, p_report_note: row.reportNote || null }, result.reject_code, crypto.randomUUID()); }
  catch (error) { flow.error = error.message; machtileRenderBatchReport(); return; }
  await machtileStationReportSendFinal(code, args);
}

async function machtileStationReportRetryPreviewAck(code) {
  const core = machtileStationReportCore();
  const row = machtileBatchRow(code);
  const flow = machtileStationReportState(row);
  const result = flow.result ? core?.resultCard(flow.result) : null;
  if (!core || !flow.args || !flow.preview || result?.kind !== "preview-soft") return;
  let args;
  try { args = core.retryPreviewWithAck(flow.args, flow.preview, result.guardCode, crypto.randomUUID(), row.reportNote); }
  catch (error) { flow.error = error.message; machtileRenderBatchReport(); return; }
  await machtileStationReportSendFinal(code, args);
}

function machtileStationReportContext(order, machineCode) {
  const core = machtileStationReportCore();
  if (!core || !order?.processId || !order?.id) return null;
  const legacy = machtileBatchState.stationReportIdentityByProcess.get(String(order.processId));
  if (!legacy) return null;
  let identity;
  try { identity = core.legacyIdentityFromProjection(legacy); } catch { return null; }
  const context = {
    machineCode: String(machineCode || "").trim().toUpperCase(),
    expectedOrderNo: String(order.id),
    ...identity,
    expectedPartNo: String(legacy.part_no || "").trim(),
  };
  try {
    // The three legacy identity values come only from factory-bridge fields.
    // APP process_order/stationStep is never substituted.
    core.buildSubmitArgs({ ...context, goodQty: 1, failQty: 0, failReasonCode: null }, "00000000-0000-4000-8000-000000000000", true,
      machtileBatchState.stationReportSettings.failReasonCodesByMachine[String(machineCode || "").toUpperCase()] || []);
    return context;
  } catch {
    return null;
  }
}

function machtileStationReportMissingContext(order, machineCode) {
  const legacy = order?.processId ? machtileBatchState.stationReportIdentityByProcess.get(String(order.processId)) : null;
  const missing = [];
  if (!String(order?.id || "").trim()) missing.push("expected_order_no（舊 MES 工單號）");
  if (!String(machineCode || "").trim()) missing.push("p_machine_code");
  if (!Number.isInteger(legacy?.legacy_index_sn) || legacy.legacy_index_sn < 1) missing.push("legacy_index_sn（舊 MES IndexSN）");
  if (!String(legacy?.part_no || "").trim()) missing.push("part_no（工單投影料號）");
  if (legacy?.manufacture_ii_id != null && (typeof legacy.manufacture_ii_id !== "string" || !legacy.manufacture_ii_id.trim())) missing.push("manufacture_ii_id（舊 MES ManufactureII Id）");
  if (typeof legacy?.simulation_id !== "string" || !legacy.simulation_id.trim() || legacy.simulation_id.length > 20) missing.push("simulation_id（舊 MES SimulationId）");
  return missing;
}

function machtileStationReportState(row) {
  if (!row.stationReport) row.stationReport = { phase: "idle", result: null, args: null, preview: null, error: "" };
  return row.stationReport;
}

function machtileStationReportFlowBusy(flow) {
  return ["submitting-preview", "waiting-preview", "submitting-report", "waiting-report"].includes(flow?.phase);
}

function coreResultWasNotApplied(row) {
  const kind = machtileStationReportCore()?.resultCard(row)?.kind;
  return kind !== "applied" && kind !== "applied-late";
}

async function machtileStationReportReconcile(code) {
  const core = machtileStationReportCore();
  const flow = machtileStationReportState(machtileBatchRow(code));
  const commandUuid = flow.args?.p_command_uuid;
  if (!core || !commandUuid) return;
  flow.error = "正在查詢原報工識別碼…";
  machtileRenderBatchReport();
  try {
    const result = await machtileStationReportCreateClient().read(commandUuid);
    flow.result = result;
    flow.preview = result.command_type === "report_preview" ? result : flow.preview;
    flow.phase = core.isTerminal(result)
      ? (result.command_type === "report_preview" && result.status === "previewed" ? "previewed" : "finished")
      : result.command_type === "report_preview" ? "waiting-preview" : "waiting-report";
    flow.error = core.isTerminal(result) ? "" : "原報工仍在處理；請勿建立第二筆。";
  } catch (error) {
    flow.error = `仍無法確認原報工狀態，請勿重送。${error.message || ""}`;
  }
  machtileRenderBatchReport();
}

function machtileStationReportCancel(code) {
  const flow = machtileStationReportState(machtileBatchRow(code));
  if (machtileStationReportFlowBusy(flow)) return;
  flow.phase = "idle"; flow.result = null; flow.preview = null; flow.args = null; flow.error = "";
  machtileRenderBatchReport();
}

function machtileStationReportNew(code) {
  const row = machtileBatchRow(code);
  const kind = machtileStationReportCore()?.resultCard(row.stationReport?.result)?.kind;
  if (kind !== "applied" && kind !== "applied-late") return;
  row.good = ""; row.bad = ""; row.failReasonCode = ""; row.reportNote = "";
  row.stationReport = { phase: "idle", result: null, args: null, preview: null, error: "" };
  machtileRenderBatchReport();
}

function machtileStationReportCreateClient() {
  const core = machtileStationReportCore();
  return core?.createClient({ request: (path, options) => supabaseFetch(path, options) }) || null;
}

function machtileBatchReadDrafts() {
  try { return JSON.parse(localStorage.getItem(MACHTILE_BATCH_DRAFT_KEY) || "{}") || {}; } catch { return {}; }
}

function machtileBatchWriteDrafts(drafts) {
  try { localStorage.setItem(MACHTILE_BATCH_DRAFT_KEY, JSON.stringify(drafts || {})); } catch { /* storage unavailable */ }
}

function machtileBatchLedgerAt(processId) {
  try {
    const ledger = JSON.parse(localStorage.getItem(MACHTILE_STARTED_AT_LEDGER_KEY) || "{}") || {};
    return typeof ledger[processId] === "string" ? ledger[processId] : null;
  } catch { return null; }
}

// 送出後把這道工序的開工時間 ledger 往前推（跟單台報工同一份），之後單台報工的 started_at 從這次接續。
function machtileBatchRollLedger(processId, endedAtIso) {
  try {
    let ledger;
    try { ledger = JSON.parse(localStorage.getItem(MACHTILE_STARTED_AT_LEDGER_KEY) || "{}") || {}; } catch { ledger = {}; }
    const prev = ledger[processId];
    if (typeof prev !== "string" || prev < endedAtIso) ledger[processId] = endedAtIso;
    localStorage.setItem(MACHTILE_STARTED_AT_LEDGER_KEY, JSON.stringify(ledger));
  } catch { /* storage unavailable */ }
}

function machtileBatchRow(machineCode) {
  let row = machtileBatchState.rows.get(machineCode);
  if (!row) {
    row = { processId: "", good: "", bad: "", operatorId: null, selected: null, ctMinutes: null, ctSeconds: null, failReasonCode: "", reportNote: "", error: "", result: null };
    machtileBatchState.rows.set(machineCode, row);
  }
  return row;
}

function machtileBatchMachineLabel(code) {
  const master = state.machineMasters.find((m) => String(m.code || "").toUpperCase() === code);
  return master?.location ? `${code} ${master.location}` : code;
}

async function machtileBatchFetchUsers() {
  if (state.source !== "supabase") return [];
  try {
    const rows = await supabaseFetch("app_users?select=id,name,legacy_user_id&is_active=eq.true&order=name");
    return Array.isArray(rows) ? rows : [];
  } catch (error) {
    console.warn("batch report: app_users lookup failed", error);
    return [];
  }
}

// 進度＋開工時間來源。batch_report_progress 還沒上線（migration 未套）時，退回只讀
// work_order_processes.actual_start_at＋production_reports 最後一筆時間（開工時間規則照舊，已報顯示「—」）。
async function machtileBatchFetchProgress(processIds) {
  const map = new Map();
  if (state.source !== "supabase" || !processIds.length) return { map, error: "" };
  try {
    const rows = await supabaseFetch("rpc/batch_report_progress", {
      method: "POST",
      body: JSON.stringify({ p_process_ids: processIds, p_pending_since: config.batchReportPendingSince || null }),
    });
    (Array.isArray(rows) ? rows : []).forEach((row) => map.set(String(row.process_id), row));
    return { map, error: "" };
  } catch (error) {
    console.warn("batch_report_progress unavailable; falling back to start-time sources only", error);
  }
  try {
    const ids = processIds.map(encodeURIComponent).join(",");
    const [procs, reports] = await Promise.all([
      supabaseFetch(`work_order_processes?select=id,actual_start_at&id=in.(${ids})`),
      supabaseFetch(`production_reports?select=process_id,ended_at,created_at&process_id=in.(${ids})&order=created_at.desc&limit=1000`),
    ]);
    (Array.isArray(procs) ? procs : []).forEach((p) => map.set(String(p.id), { process_id: p.id, actual_start_at: p.actual_start_at, last_report_at: null, fallback: true }));
    (Array.isArray(reports) ? reports : []).forEach((r) => {
      const entry = map.get(String(r.process_id));
      const at = r.ended_at || r.created_at;
      if (entry && at && (!entry.last_report_at || at > entry.last_report_at)) entry.last_report_at = at;
    });
  } catch (error) {
    console.warn("batch report fallback start-time lookup failed", error);
  }
  return { map, error: "舊 MES 進度暫時讀不到（已報顯示「—」），仍可報工。" };
}

// 機台加工時間（每件秒數）的唯一寫入處＝報工的 cycle_time_seconds（單台「首次開工」的 Cycle time 欄位也是寫這裡；
// 後端 trigger trg_record_cnc_machining_run 會同步記一筆 cnc_machining_runs 並更新 part_process_time_baselines）。
// 這裡讀「這道工序最新一次填的值」：批次每列的預設值，也是 Monitor 卡片「機台加工時間」顯示的值。
// 讀不到（網路／權限）→ 空 Map：批次欄位留白、卡片顯示「未填」，報工照常。
async function machtileFetchMachineTimes(processIds) {
  const core = machtileBatchCore();
  const ids = [...new Set((processIds || []).map(String).filter(isUuid))];
  if (!core || state.source !== "supabase" || !ids.length) return new Map();
  const rows = [];
  for (let i = 0; i < ids.length; i += 80) {
    const chunk = ids.slice(i, i + 80).map(encodeURIComponent).join(",");
    // 審查 L2：最多等 4 秒，讀不到就當沒填（卡片顯示「未填」），不卡住整頁
    const controller = typeof AbortController === "function" ? new AbortController() : null;
    const timer = controller ? setTimeout(() => controller.abort(), 4000) : null;
    try {
      const got = await supabaseFetch(`production_reports?select=process_id,cycle_time_seconds,created_at&process_id=in.(${chunk})&cycle_time_seconds=not.is.null&order=created_at.desc&limit=1000`, controller ? { signal: controller.signal } : {});
      if (Array.isArray(got)) rows.push(...got);
    } catch (error) {
      console.warn("machine time lookup failed", error);
    } finally {
      if (timer) clearTimeout(timer);
    }
  }
  return core.latestMachineTimeByProcess(rows);
}

function machtileBatchCandidates(code) {
  const core = machtileBatchCore();
  return core ? core.candidateOrdersForMachine(machtileMachineCardOrders(), code) : [];
}

function machtileBatchSelectedOrder(code) {
  const candidates = machtileBatchCandidates(code);
  const row = machtileBatchRow(code);
  if (row.processId) {
    const chosen = candidates.find((o) => o.processId === row.processId);
    if (chosen) return chosen;
  }
  // 預設＝卡片目前顯示的那張（這台最近有活動的單）；不在候選清單裡才用候選第一張（原本的規則）
  const cardOrder = machtileCardOrderForMachine(code);
  if (machtileCardActiveCore) return machtileCardActiveCore.defaultCandidate(candidates, cardOrder);
  return candidates[0] || null;
}

async function machtileLoadBatchReport(groupKey) {
  const core = machtileBatchCore();
  const group = core?.groupFor(groupKey);
  if (!group) return;
  machtileBatchState.group = group.key;
  machtileBatchState.stationReportIdentityByProcess = new Map();
  machtileBatchState.loading = true;
  machtileRenderBatchReport();
  try {
    const processIds = [];
    group.machines.forEach((code) => machtileBatchCandidates(code).forEach((o) => processIds.push(o.processId)));
    const uniq = [...new Set(processIds.filter(isUuid))];
    const [actorId, users, progress, machineTimes] = await Promise.all([
      machtileResolveAppUserId(),
      machtileBatchFetchUsers(),
      machtileBatchFetchProgress(uniq),
      machtileFetchMachineTimes(uniq),
      machtileLoadStationReportSettings(group.machines),
    ]);
    await machtileLoadStationReportIdentity(group.machines);
    machtileBatchState.actorId = actorId || "";
    machtileBatchState.users = core.operatorChoices(users);
    machtileBatchState.progressByProcess = progress.map;
    machtileBatchState.progressError = progress.error;
    machineTimes.forEach((v, pid) => machtileBatchState.machineTimeByProcess.set(pid, v.seconds));
    machtileBatchState.error = "";
    machtileBatchState.lastLoadedAt = Date.now();
  } catch (error) {
    machtileBatchState.error = `讀取失敗：${error.message}`;
  } finally {
    machtileBatchState.loading = false;
    machtileRenderBatchReport();
  }
}

function machtileBatchStartInfo(order, endedAtIso, mode) {
  const core = machtileBatchCore();
  const progress = order ? machtileBatchState.progressByProcess.get(String(order.processId)) : null;
  return core.resolveStartedAt({
    serverLastReportAt: progress?.last_report_at || null,
    localLedgerAt: order ? machtileBatchLedgerAt(order.processId) : null,
    actualStartAt: progress?.actual_start_at || null,
    endedAt: endedAtIso,
    // 今日開工跟單台同規則（只看上一筆報工），中午／收工照原本批次規則（沒有報工時可用工序開工時間）
    includeProcessStart: mode !== "dailyStart",
  });
}

function machtileBatchMachineTimeDefault(order) {
  if (!order) return null;
  const sec = machtileBatchState.machineTimeByProcess.get(String(order.processId));
  return Number(sec) > 0 ? Number(sec) : null;
}

function machtileBatchRowModel(code, endedAtIso) {
  const core = machtileBatchCore();
  const mode = machtileBatchState.mode;
  const row = machtileBatchRow(code);
  const order = machtileBatchSelectedOrder(code);
  const operatorId = row.operatorId === null
    ? core.defaultOperatorId(machtileBatchState.users, machtileBatchState.actorId)
    : row.operatorId;
  const start = machtileBatchStartInfo(order, endedAtIso, mode);
  const ctDefault = machtileBatchMachineTimeDefault(order);
  const split = core.splitSeconds(ctDefault);
  return {
    mode,
    machineCode: code,
    order,
    good: row.good,
    bad: row.bad,
    // 今日開工：預設勾「有派工」的機台
    selected: row.selected === null ? Boolean(order) : row.selected === true && Boolean(order),
    ctDefault,
    ctMinutes: row.ctMinutes === null ? split.minutes : row.ctMinutes,
    ctSeconds: row.ctSeconds === null ? split.seconds : row.ctSeconds,
    overtime: machtileBatchState.overtime,
    operatorId,
    operatorMapped: machtileBatchState.users.some((u) => u.id === operatorId),
    startedAt: start.startedAt,
    startedAtSource: start.source,
    startedAtReason: start.reason,
  };
}

const MACHTILE_BATCH_START_SOURCE_LABEL = { lastReport: "上次報工", deviceLedger: "本機上次報工", processStart: "開工" };

function machtileBatchSendableCount(group, nowIso) {
  const core = machtileBatchCore();
  return group.machines.filter((code) => !core.validateRow(machtileBatchRowModel(code, nowIso)).empty).length;
}

function machtileBatchSubmitText(n) {
  const core = machtileBatchCore();
  const meta = core.MODES[machtileBatchState.mode];
  return `${meta.submitLabel}（${n} 台）`;
}

function machtileRenderBatchReport() {
  const core = machtileBatchCore();
  const group = core?.groupFor(machtileBatchState.group);
  const holder = document.querySelector(`[data-batch-root="${machtileBatchState.group}"]`);
  if (!core || !group || !holder) return;
  const mode = machtileBatchState.mode;
  const isStart = mode === "dailyStart";
  const nowIso = new Date().toISOString();
  const demo = state.source !== "supabase";
  const busy = machtileBatchState.submitting;
  const tone = group.key === "mill" ? "is-mill" : "is-lathe";
  const userOptions = (selected) => [
    `<option value="">— 選報工人 —</option>`,
    ...machtileBatchState.users.map((u) => `<option value="${escapeHtml(u.id)}"${u.id === selected ? " selected" : ""}>${escapeHtml(u.name)}</option>`),
  ].join("");
  const rowsHtml = group.machines.map((code) => {
    const model = machtileBatchRowModel(code, nowIso);
    const row = machtileBatchRow(code);
    const candidates = machtileBatchCandidates(code);
    const order = model.order;
    const rawProgress = order ? machtileBatchState.progressByProcess.get(String(order.processId)) || null : null;
    const progress = rawProgress && !rawProgress.fallback ? core.displayProgress(rawProgress) : null;
    const orderCell = !order
      ? `<span class="batch-muted">目前沒有派工</span>`
      : candidates.length > 1
        ? `<select class="batch-order-select" data-batch-order="${code}" aria-label="${code} 工單"${busy ? " disabled" : ""}>${candidates.map((o) => `<option value="${escapeHtml(o.processId)}"${o.processId === order.processId ? " selected" : ""}>${escapeHtml(o.id)}・${escapeHtml(o.process)}</option>`).join("")}</select>`
        : `<strong>${escapeHtml(order.id)}</strong><span>${escapeHtml(order.process)}・${escapeHtml(order.part)}</span>`;
    let doneHtml = `<div class="batch-done-empty"><span class="batch-label">已報</span><span class="batch-muted">—</span></div>`;
    if (order && progress) {
      const pendingText = progress.pendingCount
        ? `<span class="batch-pending${progress.stalePending ? " is-stale" : ""}" title="${progress.stalePending ? "超過 2 小時還沒寫回舊 MES，請通知管理者確認" : "App 已送出、回寫橋還沒寫回舊 MES"}">含待回寫 ${progress.pendingOutput}／${progress.pendingFail}${progress.stalePending ? "（逾 2 小時，請通知管理者）" : ""}</span>`
        : "";
      const legacyText = progress.legacyKnown ? `舊 MES ${progress.legacyOutput}／${progress.legacyFail}` : "舊 MES 尚無結算";
      doneHtml = `
        <div class="batch-stat is-good"><span class="batch-label">已報 良</span><strong>${progress.totalOutput}</strong></div>
        <div class="batch-stat is-bad"><span class="batch-label">不良</span><strong>${progress.totalFail}</strong></div>
        ${order.total ? `<div class="batch-stat"><span class="batch-label">訂</span><strong>${order.total}</strong></div>` : ""}
        <p class="batch-done-meta"><span class="batch-muted">${legacyText}</span>${pendingText}</p>`;
    }
    // 選到「已報良品 ≥ 訂單數量」的單：提醒，不擋報工（owner 2026-10-02）
    const overInfo = order ? machtileOverQtyInfo(order, progress ? progress.totalOutput : undefined) : null;
    const overText = overInfo && machtileCardActiveCore?.overQtyReportWarning ? machtileCardActiveCore.overQtyReportWarning(overInfo) : "";
    const overHtml = overText ? `<p class="batch-overqty" role="note" data-batch-overqty="${code}">${escapeHtml(overText)}</p>` : "";
    let startText = "";
    if (order && isStart) {
      startText = model.startedAt
        ? `上一筆 ${escapeHtml(formatDateTime(model.startedAt))}（${MACHTILE_BATCH_START_SOURCE_LABEL[model.startedAtSource] || ""}）；開工記在按下送出的時間`
        : "第一次在 App 開工：開工記在按下送出的時間";
    } else if (order) {
      startText = model.startedAt
        ? `工時從 ${escapeHtml(formatDateTime(model.startedAt))} 起算（${MACHTILE_BATCH_START_SOURCE_LABEL[model.startedAtSource] || ""}）`
        : `<span class="batch-warn" role="note">${escapeHtml(model.startedAtReason)}</span>`;
    }
    const result = row.result;
    const resultHtml = result
      ? `<p class="batch-result is-${result.status}" role="status">${escapeHtml(result.message)}</p>`
      : row.error ? `<p class="batch-result is-failed" role="alert">${escapeHtml(row.error)}</p>` : "";
    const stationReportHtml = !isStart ? machtileRenderStationReportPanel(code, order, row, busy) : "";
    const stationFlow = machtileStationReportState(row);
    const stationEnabled = !isStart && machtileStationReportCore()?.reportMachineEnabled(machtileBatchState.stationReportSettings.machines, code);
    const stationResultKind = stationFlow.result ? machtileStationReportCore()?.resultCard(stationFlow.result)?.kind : "";
    const stationLocked = stationEnabled && (machtileStationReportFlowBusy(stationFlow) || stationFlow.phase === "previewed" || stationFlow.phase === "blocked" || stationResultKind === "applied" || stationResultKind === "applied-late");
    const disabled = !order || busy || stationLocked ? " disabled" : "";
    const ctHint = model.ctDefault ? `上次 ${escapeHtml(formatSeconds(model.ctDefault))}／件，有變才改` : "還沒填過；有量測再填";
    const inputsHtml = isStart
      ? `
        <div class="batch-inputs is-start">
          <label class="batch-check"><input type="checkbox" data-batch-select="${code}"${model.selected ? " checked" : ""}${disabled}><span>記下今日開工</span></label>
          <label class="batch-operator"><span>報工人</span><select data-batch-operator="${code}"${disabled}>${userOptions(model.operatorId)}</select></label>
        </div>`
      : `
        <div class="batch-inputs">
          <label class="batch-qty is-good"><span>這次良品</span><input type="number" inputmode="numeric" min="0" step="1" data-batch-good="${code}" value="${escapeHtml(row.good)}"${disabled}></label>
          <label class="batch-qty is-bad"><span>這次不良</span><input type="number" inputmode="numeric" min="0" step="1" data-batch-bad="${code}" value="${escapeHtml(row.bad)}"${disabled}></label>
          <div class="batch-ct">
            <span class="batch-ct-label">機台加工時間 <small>選填・${ctHint}</small></span>
            <div class="batch-ct-inputs">
              <input type="number" inputmode="numeric" min="0" step="1" data-batch-ct-min="${code}" value="${escapeHtml(model.ctMinutes)}" aria-label="${code} 機台加工時間 分"${disabled}><span>分</span>
              <input type="number" inputmode="numeric" min="0" max="59" step="1" data-batch-ct-sec="${code}" value="${escapeHtml(model.ctSeconds)}" aria-label="${code} 機台加工時間 秒"${disabled}><span>秒 / 件</span>
            </div>
          </div>
          <label class="batch-operator"><span>報工人</span><select data-batch-operator="${code}"${disabled}>${userOptions(model.operatorId)}</select></label>
        </div>`;
    return `
      <article class="batch-row ${tone}${!order ? " is-idle" : ""}${isStart && model.selected ? " is-selected" : ""}${row.error ? " has-error" : ""}" data-batch-row="${code}">
        <header class="batch-row-head">
          <span class="batch-machine">${escapeHtml(machtileBatchMachineLabel(code))}</span>
          <div class="batch-order">${orderCell}</div>
        </header>
        <div class="batch-done">${doneHtml}</div>
        ${overHtml}
        ${inputsHtml}
        ${startText ? `<p class="batch-start">${startText}</p>` : ""}
        ${resultHtml}
        ${stationReportHtml}
      </article>`;
  }).join("");
  // 有填數字／有勾的台數（能不能送，按下去才逐列檢查並用紅字說明；按鈕不因為某一列有問題就變灰、讓人不知道為什麼）
  const sendable = machtileBatchSendableCount(group, nowIso);
  const modeTabs = core.MODE_ORDER.map((key) => {
    const meta = core.MODES[key];
    const active = key === mode;
    return `<button type="button" role="tab" aria-selected="${active}" class="batch-mode-btn${active ? " is-active" : ""}" data-batch-mode="${key}"${busy ? " disabled" : ""}>${escapeHtml(meta.label)}</button>`;
  }).join("");
  const modeHint = isStart
    ? `勾選要記下<strong>今日開工</strong>的機台（預設勾有派工的），一次送出＝每台各記一筆開工（數量 0）。之後的中午報工、收工，工時從開工這一刻起算。`
    : `只填<strong>這次做的數量</strong>（不是累計）。空白的機台不會送。已報＝舊 MES 累計＋App 已送出、還沒寫回舊 MES 的「待回寫」。機台加工時間有變才改，只改時間不填數量也可以送。`;
  // 2026-10-05 owner：首件檢查只在首次開工做，批次今日開工不再要求勾「當日首件檢查」。
  const modeExtra = mode === "finish"
      ? `<fieldset class="batch-form-radio"><legend>是否加班 <small>必填</small></legend>
          <label><input type="radio" name="batchOvertime-${group.key}" value="none" data-batch-overtime${machtileBatchState.overtime === "none" ? " checked" : ""}${busy ? " disabled" : ""}> 一般下班 17:00</label>
          <label><input type="radio" name="batchOvertime-${group.key}" value="2030" data-batch-overtime${machtileBatchState.overtime === "2030" ? " checked" : ""}${busy ? " disabled" : ""}> 加班收工 20:30</label>
        </fieldset>`
      : "";
  holder.innerHTML = `
    <div class="batch-mode-tabs" role="tablist" aria-label="報工類型">${modeTabs}</div>
    <div class="batch-toolbar">
      <div class="batch-switch" role="tablist" aria-label="切換報工組">
        ${Object.values(core.GROUPS).map((g) => `<button type="button" class="batch-switch-btn${g.key === group.key ? " is-active" : ""}" data-view="${g.view}">${escapeHtml(g.title)}</button>`).join("")}
      </div>
      <label class="batch-apply-all"><span>報工人全部套用</span><select data-batch-operator-all${busy ? " disabled" : ""}>${userOptions("")}</select></label>
      <button type="button" class="secondary-action batch-refresh" data-batch-refresh${machtileBatchState.loading || busy ? " disabled" : ""}>${machtileBatchState.loading ? "讀取中…" : "重新整理"}</button>
    </div>
    ${demo ? `<p class="batch-notice" role="note">示範模式：不會寫入任何資料。</p>` : ""}
    ${machtileBatchState.error ? `<p class="batch-notice is-error" role="alert">${escapeHtml(machtileBatchState.error)}</p>` : ""}
    ${machtileBatchState.progressError ? `<p class="batch-notice" role="note">${escapeHtml(machtileBatchState.progressError)}</p>` : ""}
    ${machtileStationReportEnabled() && !demo && machtileBatchState.stationReportSettings.status !== "loaded" ? `<p class="batch-notice is-error" role="status">${escapeHtml(machtileBatchState.stationReportSettings.error || "智慧報工設定尚未同步；本功能目前關閉。")}</p>` : ""}
    ${!demo && !machtileBatchState.loading && !machtileBatchState.users.length ? `<p class="batch-notice is-error" role="alert">還沒有任何人員對照到舊 MES 工號，請管理者先補上工號對照。</p>` : ""}
    <p class="batch-hint">${modeHint}</p>
    ${modeExtra}
    ${machtileBatchState.formError ? `<p class="batch-notice is-error" role="alert">${escapeHtml(machtileBatchState.formError)}</p>` : ""}
    <div class="batch-rows">${rowsHtml}</div>
    <div class="batch-submit-bar">
      <button type="button" class="primary-action batch-submit" data-batch-submit${busy || !sendable ? " disabled" : ""}>${busy ? "送出中…" : escapeHtml(machtileBatchSubmitText(sendable))}</button>
    </div>`;
}

async function machtileBatchSendOne(box, payload, operators) {
  const uuid = payload.report_uuid;
  if (box) {
    const existing = await box.outbox.get(uuid).catch(() => null);
    if (existing?.status === box.outbox.OUTBOX_STATUS.FAILED) await box.outbox.requeue(uuid);
    if (!existing) await box.submitter.submit(payload, { operators });
    return { direct: false };
  }
  // outbox 不可用：直接打同一支 RPC（同一個 report_uuid → 第二次回 inserted=false，不會變兩筆）
  const { report_uuid: _ignored, ...rest } = payload;
  const res = await supabaseFetch("rpc/field_report_upsert", {
    method: "POST",
    body: JSON.stringify({ p_report_uuid: uuid, p_payload: { ...rest, operators } }),
  });
  return { direct: true, inserted: res?.inserted };
}

// 機台加工時間寫入成功（或已排入待送）後，馬上更新畫面上的值：批次下一次的預設、Monitor 卡片的「機台加工時間」。
function machtileApplyMachineTime(processId, seconds) {
  if (!processId || !(Number(seconds) > 0)) return;
  machtileBatchState.machineTimeByProcess.set(String(processId), Number(seconds));
  [...(state.workOrders || []), ...(state.assignedCardOrders || [])].forEach((order) => {
    if (String(order.processId) === String(processId) && order.machineTimeSource !== "view") {
      order.pureCycleSec = Number(seconds);
      order.machineTimeSource = "report";
    }
  });
}

async function machtileSubmitBatchReport() {
  const core = machtileBatchCore();
  const group = core?.groupFor(machtileBatchState.group);
  if (!core || !group || machtileBatchState.submitting) return;
  const mode = machtileBatchState.mode;
  if (machtileStationReportEnabled() && state.source === "supabase" && mode !== "dailyStart" && machtileBatchState.stationReportSettings.status !== "loaded") {
    machtileBatchState.formError = "無法確認哪些機台已啟用智慧報工；本次未送出任何報工。請重新整理設定後再試。";
    machtileRenderBatchReport();
    showToast("報工設定尚未確認，本次沒有送出。");
    return;
  }
  const meta = core.MODES[mode];
  const endedAt = new Date().toISOString();
  const models = group.machines.map((code) => machtileBatchRowModel(code, endedAt));
  const checks = models.map((m) => ({ model: m, v: core.validateRow(m) }));
  checks.forEach(({ model, v }) => {
    const row = machtileBatchRow(model.machineCode);
    row.error = v.error;
    if (v.error) row.result = null;
  });
  const toSend = checks.filter(({ v }) => v.send);
  const bad = checks.filter(({ v }) => v.error);
  // 整張表單的必填（同單台）：收工要選是否加班（首件檢查已移到首次開工，2026-10-05）
  machtileBatchState.formError = "";
  if (toSend.length && mode === "finish" && !machtileBatchState.overtime) machtileBatchState.formError = "請確認是否加班。";
  if (bad.length || machtileBatchState.formError) {
    machtileRenderBatchReport();
    showToast(machtileBatchState.formError || `有 ${bad.length} 台要先修正（紅字），全部都還沒送出。`);
    return;
  }
  if (!toSend.length) { showToast(mode === "dailyStart" ? "沒有勾選要開工的機台。" : "沒有要送的機台（良品、不良都空白，機台加工時間也沒改）。"); return; }
  if (machtileStationReportEnabled() && mode !== "dailyStart" && machtileBatchState.stationReportSettings.status === "loaded") {
    const enabled = toSend.map(({ model }) => model.machineCode)
      .filter((code) => machtileStationReportCore()?.reportMachineEnabled(machtileBatchState.stationReportSettings.machines, code));
    if (enabled.length) {
      machtileBatchState.formError = `智慧報工已啟用：${enabled.join("、")} 不會走舊批次寫入。請在該機台的智慧報工區先預覽；識別資料未完整時不能送出。`;
      machtileRenderBatchReport();
      showToast("已啟用智慧報工的機台不會回退到舊報工路徑。");
      return;
    }
  }
  const summary = toSend.map(({ model, v }) => {
    if (mode === "dailyStart") return `${model.machineCode} 今日開工`;
    const timeText = v.machineSeconds ? `、機台加工時間 ${formatSeconds(v.machineSeconds)}／件` : "";
    return v.timeOnly ? `${model.machineCode} 只更新機台加工時間 ${formatSeconds(v.machineSeconds)}／件` : `${model.machineCode} 良 ${v.good}／不良 ${v.bad}${timeText}`;
  }).join("\n");
  if (!window.confirm(`${meta.label}：送出 ${toSend.length} 台？\n${summary}`)) return;
  if (state.source !== "supabase") {
    toSend.forEach(({ model }) => {
      const row = machtileBatchRow(model.machineCode);
      row.result = { status: "sent", message: "示範模式：沒有寫入" };
      row.good = ""; row.bad = "";
      if (mode === "dailyStart") row.selected = false;
    });
    machtileRenderBatchReport();
    return;
  }

  machtileBatchState.submitting = true;
  machtileRenderBatchReport();
  const drafts = machtileBatchReadDrafts();
  const actorId = machtileBatchState.actorId || await machtileResolveAppUserId();
  const prepared = toSend.map(({ model }) => {
    const prev = drafts[model.machineCode];
    const id = core.ensureReportUuid(prev, model, () => crypto.randomUUID());
    // 重送同一筆時沿用第一次的時間，payload 才會跟已經進 outbox／伺服器的那筆一致
    const startedAt = id.reused && prev && "startedAt" in prev ? prev.startedAt : model.startedAt;
    const end = id.reused && prev?.endedAt ? prev.endedAt : endedAt;
    drafts[model.machineCode] = { reportUuid: id.reportUuid, fingerprint: id.fingerprint, startedAt, endedAt: end };
    const built = core.buildReportPayload({ row: { ...model, startedAt }, actorAppUserId: actorId, endedAt: end, reportUuid: id.reportUuid, tenantId: model.order.tenantId });
    return { model, built };
  });
  machtileBatchWriteDrafts(drafts);   // 先記下 uuid 再送：送到一半當機／斷線，再按一次還是同一筆

  const box = machtileOutboxEnabled() ? await machtileGetOutbox() : null;
  const results = [];
  for (const item of prepared) {
    const row = machtileBatchRow(item.model.machineCode);
    try {
      const sent = await machtileBatchSendOne(box, item.built.payload, item.built.operators);
      results.push({ item, uuid: item.built.payload.report_uuid, direct: sent.direct, inserted: sent.inserted });
    } catch (error) {
      row.result = { status: "failed", message: `送出失敗：${error.message}（再按一次會重送同一筆，不會變兩筆）` };
      results.push({ item, failed: true });
    }
  }
  if (box) {
    // submit() 每次都會觸發 flush，但進行中的 flush 只掃它開始那一刻的佇列；後面排進去的要再掃一次。
    // 最多掃 3 輪：還沒送掉的（離線、暫時錯誤退避中）留在 outbox，背景會自動重送，畫面標「待送」。
    const ours = new Set(results.filter((r) => !r.failed).map((r) => r.uuid));
    for (let i = 0; i < 3; i += 1) {
      await box.outbox.flush().catch(() => {});
      const left = (await box.outbox.pending().catch(() => [])).filter((x) => ours.has(x.report_uuid) && (x.next_attempt_at == null || x.next_attempt_at <= Date.now()));
      if (!left.length) break;
    }
  }
  for (const r of results) {
    if (r.failed) continue;
    const code = r.item.model.machineCode;
    const row = machtileBatchRow(code);
    const payload = r.item.built.payload;
    let status = "sent";
    let message = r.direct && r.inserted === false ? "已送出（先前已收到，沒有重複）" : "已送出";
    if (box) {
      const record = await box.outbox.get(r.uuid).catch(() => null);
      if (record?.status === box.outbox.OUTBOX_STATUS.FAILED) {
        status = "failed";
        message = `伺服器拒收：${record.last_error || ""}（修正後再按一次）`;
      } else if (record?.status !== box.outbox.OUTBOX_STATUS.SENT) {
        status = "queued";
        message = "已排入待送，連線後自動送出";
      }
    }
    const what = mode === "dailyStart" ? "今日開工"
      : r.item.built.timeOnly ? `機台加工時間 ${formatSeconds(payload.cycle_time_seconds)}／件`
        : `良 ${payload.completed_qty}／不良 ${payload.defect_qty}${payload.cycle_time_seconds ? `、機台加工時間 ${formatSeconds(payload.cycle_time_seconds)}／件` : ""}`;
    row.result = { status, message: status === "failed" ? message : `${message}：${what}` };
    if (status !== "failed") {
      // 只改時間的那筆 ended_at＝上一筆時間，ledger 不會往前推（rollLedger 只往後推）
      machtileBatchRollLedger(r.item.model.order.processId, payload.ended_at);
      if (payload.cycle_time_seconds) machtileApplyMachineTime(payload.process_id, payload.cycle_time_seconds);
      delete drafts[code];
      row.good = "";
      row.bad = "";
      row.ctMinutes = null;
      row.ctSeconds = null;
      if (mode === "dailyStart") row.selected = false;
      row.error = "";
    }
  }
  machtileBatchWriteDrafts(drafts);
  machtileUpdateOutboxBadge();
  // Monitor 卡片的「機台加工時間／每日估算」馬上換成剛填的值（不用等下一次整頁重讀）
  if (results.some((r) => !r.failed && r.item.built.payload.cycle_time_seconds)) {
    try { deriveMachines(); renderWorkOrders(); } catch (error) { console.warn("monitor re-render after machine time failed", error); }
  }
  machtileBatchState.submitting = false;
  const tally = core.summarizeResults(results.map((r) => ({ status: r.failed ? "failed" : machtileBatchRow(r.item.model.machineCode).result?.status })));
  showToast(`${meta.label}：已送出 ${tally.sent}、待送 ${tally.queued}、失敗 ${tally.failed}`);
  await machtileLoadBatchReport(group.key);
}

function machtileHandleBatchClick(event) {
  const previewButton = event.target.closest("[data-station-report-preview]");
  if (previewButton) { machtileStationReportSubmitPreview(previewButton.dataset.stationReportPreview); return true; }
  const confirmButton = event.target.closest("[data-station-report-confirm]");
  if (confirmButton) return true;
  const ackButton = event.target.closest("[data-station-report-ack]");
  if (ackButton) { machtileStationReportRetryAck(ackButton.dataset.stationReportAck); return true; }
  const previewAckButton = event.target.closest("[data-station-report-preview-ack]");
  if (previewAckButton) return true;
  const reconcileButton = event.target.closest("[data-station-report-reconcile]");
  if (reconcileButton) { machtileStationReportReconcile(reconcileButton.dataset.stationReportReconcile); return true; }
  const cancelPreviewButton = event.target.closest("[data-station-report-cancel-preview]");
  if (cancelPreviewButton) { machtileStationReportCancel(cancelPreviewButton.dataset.stationReportCancelPreview); return true; }
  const cancelButton = event.target.closest("[data-station-report-cancel]");
  if (cancelButton) { machtileStationReportCancel(cancelButton.dataset.stationReportCancel); return true; }
  const nextButton = event.target.closest("[data-station-report-new]");
  if (nextButton) { machtileStationReportNew(nextButton.dataset.stationReportNew); return true; }
  if (event.target.closest("[data-batch-submit]")) { machtileSubmitBatchReport(); return true; }
  if (event.target.closest("[data-batch-refresh]")) { machtileLoadBatchReport(machtileBatchState.group); return true; }
  const modeBtn = event.target.closest("[data-batch-mode]");
  if (modeBtn && !machtileBatchState.submitting) {
    const core = machtileBatchCore();
    const next = modeBtn.dataset.batchMode;
    if (core?.MODES[next] && next !== machtileBatchState.mode) {
      // 審查 L1：上一次送出沒確認成功的機台（draft 還在）＝伺服器可能其實已經收到。換分頁再送會是新的
      // report_uuid → 同樣的數量算兩次。所以先擋：預設留在原分頁、請人重按送出（同一筆不會重複）；
      // 真的要換，就把這幾台的數量和待送紀錄一起清掉，不會帶著舊數字去另一個類型。
      const group = core.groupFor(machtileBatchState.group);
      const drafts = machtileBatchReadDrafts();
      const pending = (group?.machines || []).filter((c) => drafts[c]);
      if (pending.length) {
        const ok = window.confirm(`${pending.join("、")} 上一次送出還沒確認成功（伺服器可能已經收到）。\n建議先按「取消」留在這頁、再按一次送出（同一筆不會重複）。\n\n仍要切換？切換會清空這幾台填的數量和待送紀錄。`);
        if (!ok) return true;
        pending.forEach((c) => {
          const row = machtileBatchRow(c);
          row.good = ""; row.bad = ""; row.ctMinutes = null; row.ctSeconds = null;
          delete drafts[c];
        });
        machtileBatchWriteDrafts(drafts);
        showToast(`已清空 ${pending.join("、")} 的數量；如果剛才那筆其實已送到，請到報工紀錄確認，不要再補一次。`);
      }
      machtileBatchState.mode = next;
      machtileBatchState.formError = "";
      machtileBatchState.rows.forEach((row) => { row.error = ""; row.result = null; });
      machtileRenderBatchReport();
    }
    return true;
  }
  return false;
}

function machtileBatchRefreshSubmitButton() {
  const core = machtileBatchCore();
  const group = core?.groupFor(machtileBatchState.group);
  const n = group ? machtileBatchSendableCount(group, new Date().toISOString()) : 0;
  const button = document.querySelector(`[data-batch-root="${machtileBatchState.group}"] [data-batch-submit]`);
  if (button && !machtileBatchState.submitting) { button.textContent = machtileBatchSubmitText(n); button.disabled = !n; }
}

function machtileHandleBatchInput(event) {
  const t = event.target;
  if (!(t instanceof HTMLElement) || !t.closest("[data-batch-root]")) return false;
  if (t.hasAttribute("data-batch-operator-all")) {
    if (event.type !== "change" || !t.value) return true;
    const core = machtileBatchCore();
    core?.groupFor(machtileBatchState.group)?.machines.forEach((c) => { machtileBatchRow(c).operatorId = t.value; });
    machtileRenderBatchReport();
    return true;
  }
  if (t.hasAttribute("data-batch-overtime")) {
    if (t.checked) machtileBatchState.overtime = t.value;
    machtileBatchState.formError = "";
    return true;
  }
  const code = t.dataset.batchGood || t.dataset.batchBad || t.dataset.batchOperator || t.dataset.batchOrder
    || t.dataset.batchSelect || t.dataset.batchCtMin || t.dataset.batchCtSec
    || t.dataset.stationReportReason || t.dataset.stationReportNote;
  if (!code) return false;
  const row = machtileBatchRow(code);
  // 開始填這一列時，把畫面上顯示的那張單固定下來：之後卡片的「目前工單」就算因為新的活動或切換而改變，
  // 這一列也不會偷偷換到別張單（送出的永遠是填數字時看到的那張）。
  if (!row.processId && !t.dataset.batchOrder) {
    const shown = machtileBatchSelectedOrder(code);
    if (shown && shown.processId) row.processId = shown.processId;
  }
  if (t.dataset.batchGood) row.good = t.value;
  if (t.dataset.batchBad) row.bad = t.value;
  if (t.dataset.batchOperator) row.operatorId = t.value;
  if (t.dataset.batchOrder) { row.processId = t.value; row.ctMinutes = null; row.ctSeconds = null; }
  if (t.dataset.batchSelect) row.selected = t.checked;
  if (t.dataset.stationReportReason) row.failReasonCode = t.value;
  if (t.dataset.stationReportNote) row.reportNote = t.value;
  // 改其中一格時，另一格固定成畫面上目前的值（避免另一格還跟著預設值變）
  if (t.dataset.batchCtMin || t.dataset.batchCtSec) {
    const article = t.closest(".batch-row");
    row.ctMinutes = article?.querySelector("[data-batch-ct-min]")?.value ?? "";
    row.ctSeconds = article?.querySelector("[data-batch-ct-sec]")?.value ?? "";
  }
  row.error = "";
  row.result = null;
  const flow = machtileStationReportState(row);
  const guardResult = t.dataset.stationReportNote ? machtileStationReportCore()?.resultCard(flow.result) : null;
  const oldOrderNoteEdit = t.dataset.stationReportNote &&
    (guardResult?.guardCode || guardResult?.code) === "OLD_ORDER_NEWER_OPEN";
  if ((t.dataset.batchGood || t.dataset.batchBad || t.dataset.stationReportReason || t.dataset.stationReportNote && !oldOrderNoteEdit) &&
      ["previewed", "finished"].includes(flow.phase) && coreResultWasNotApplied(flow.result)) {
    flow.phase = "idle"; flow.result = null; flow.preview = null; flow.args = null; flow.error = "";
  }
  if (event.type === "change" && (t.dataset.batchOperator || t.dataset.batchOrder || t.dataset.batchSelect)) {
    machtileRenderBatchReport();
    return true;
  }
  // 打數字時不重畫整頁（游標不會跳走），只更新送出按鈕的台數
  machtileBatchRefreshSubmitButton();
  const article = t.closest(".batch-row");
  article?.classList.remove("has-error");
  article?.querySelector(".batch-result")?.remove();
  return true;
}

let machtileStationReportHoldTimer = null;
function machtileCancelStationReportHold() {
  if (machtileStationReportHoldTimer) clearTimeout(machtileStationReportHoldTimer);
  machtileStationReportHoldTimer = null;
}
document.addEventListener("pointerdown", (event) => {
  const button = event.target.closest?.("[data-station-report-confirm],[data-station-report-preview-ack]");
  if (!button || button.disabled) return;
  machtileCancelStationReportHold();
  machtileStationReportHoldTimer = setTimeout(() => {
    machtileStationReportHoldTimer = null;
    if (!button.isConnected || button.disabled) return;
    if (button.dataset.stationReportConfirm) machtileStationReportSubmitFinal(button.dataset.stationReportConfirm);
    else machtileStationReportRetryPreviewAck(button.dataset.stationReportPreviewAck);
  }, 1000);
});
for (const eventName of ["pointerup", "pointercancel"]) {
  document.addEventListener(eventName, machtileCancelStationReportHold, true);
}
window.addEventListener("blur", machtileCancelStationReportHold);
document.addEventListener("keydown", (event) => {
  if (event.repeat || !["Enter", " "].includes(event.key)) return;
  const button = event.target.closest?.("[data-station-report-confirm],[data-station-report-preview-ack]");
  if (!button || button.disabled) return;
  event.preventDefault();
  machtileCancelStationReportHold();
  machtileStationReportHoldTimer = setTimeout(() => {
    machtileStationReportHoldTimer = null;
    if (!button.isConnected || button.disabled) return;
    if (button.dataset.stationReportConfirm) machtileStationReportSubmitFinal(button.dataset.stationReportConfirm);
    else machtileStationReportRetryPreviewAck(button.dataset.stationReportPreviewAck);
  }, 1000);
});
document.addEventListener("keyup", (event) => {
  if (["Enter", " "].includes(event.key)) machtileCancelStationReportHold();
});
document.addEventListener("input", (event) => { machtileHandleBatchInput(event); });
document.addEventListener("change", (event) => { machtileHandleBatchInput(event); });

// Eager driver start (flag on only): resend leftovers from a previous
// session without waiting for the first new submit of this one.
if (machtileOutboxEnabled()) {
  if (document.readyState === "complete") {
    window.setTimeout(() => { machtileGetOutbox(); }, 0);
  } else {
    window.addEventListener("load", () => { machtileGetOutbox(); });
  }
}

// options（只有開工確認卡的今日開工會帶，owner 2026-10-08；報工畫面照舊不帶＝行為不變）：
//   order＝要報的工單（不動 selectedOrder）、reportPayload＝現成的 report_payload（不讀報工表單）、
//   operators＝報工人（不讀報工表單的人員勾選）、noFiles＝不附任何檔案。
async function submitReport(completed, defects, remark, reportType, options = {}) {
  const order = options.order || selectedOrder;
  if (state.source !== "supabase" || !order?.processId || !isUuid(order.workOrderId)) {
    return { wroteCloud: false, uploaded: 0, uploadFailed: 0 };
  }

  const reportPayload = options.reportPayload || buildReportPayload(reportType);
  const basePayload = {
    // 開工確認卡的今日開工：固定的 report_uuid（重送／補寫都同一個，伺服器去重）；報工畫面不帶＝照舊
    ...(options.reportUuid ? { report_uuid: options.reportUuid } : {}),
    tenant_id: order.tenantId,
    work_order_id: order.workOrderId,
    process_id: order.processId,
    report_date: new Date().toISOString().slice(0, 10),
    completed_qty: completed,
    defect_qty: defects,
    status_after_report: order.processStatus || "running",
    remark,
  };
  const actorAppUserId = await machtileResolveAppUserId();
  if (actorAppUserId) basePayload.user_id = actorAppUserId;
  const structuredPayload = {
    report_type: reportType,
    report_payload: reportPayload,
    work_total_qty: reportPayload.work_total_qty,
    cycle_time_seconds: reportPayload.cycle_time_seconds,
  };
  if (machtileOutboxEnabled()) {
    const box = await machtileGetOutbox();
    // Any outbox init failure falls through to the direct POST — a report
    // must always have a way out.
    if (box) {
      return machtileSubmitReportViaOutbox(
        box, basePayload, structuredPayload, reportType,
        options.operators || machtileSelectedOperators(actorAppUserId),
        options.noFiles ? [] : null
      );
    }
  }
  // seam 待辦 B(a) (2026-07-11): fallback rows carry a report_uuid too, so
  // they still reach the writeback feed (it filters report_uuid IS NOT NULL).
  // Also the key the Jev triage suggestion is stored under (2026-09-24).
  if (!basePayload.report_uuid && globalThis.crypto?.randomUUID) {
    basePayload.report_uuid = crypto.randomUUID();
  }
  let rows;
  if (options.requireStructured) {
    // 開工確認卡的今日開工（2026-10-08 L3 P2）：計數器在 report_type／report_payload 裡，不能退回只有基本欄位的
    // POST（會靜默丟掉數量）。只送一次；回應沒有列 id＝呼叫端當「沒存到」。
    rows = await supabaseFetch("production_reports", {
      method: "POST",
      body: JSON.stringify({ ...basePayload, ...structuredPayload }),
    });
  } else if (useStructuredReportColumns) {
    try {
      rows = await supabaseFetch("production_reports", {
        method: "POST",
        body: JSON.stringify({ ...basePayload, ...structuredPayload }),
      });
    } catch (error) {
      const message = String(error.message || "");
      if (!message.includes("report_type") && !message.includes("report_payload") && !message.includes("cycle_time_seconds")) {
        throw error;
      }
      useStructuredReportColumns = false;
    }
  }
  if (!rows && !options.requireStructured) {
    rows = await supabaseFetch("production_reports", {
      method: "POST",
      body: JSON.stringify(basePayload),
    });
  }
  const reportId = Array.isArray(rows) ? rows[0]?.id : rows?.id;
  const uploadResult = options.noFiles ? { uploaded: 0, failed: 0 } : await uploadReportFiles(reportId, reportType);
  return {
    wroteCloud: true,
    uploaded: uploadResult.uploaded,
    uploadFailed: uploadResult.failed,
    reportUuid: basePayload.report_uuid || null,
    // 伺服器回的那一列 id（沒有＝沒確認寫進去）；報工畫面不看，開工確認卡用它判「已記錄」
    reportId: reportId ?? null,
  };
}

async function submitPauseReport(reason) {
  if (state.source !== "supabase" || !selectedOrder?.processId || !isUuid(selectedOrder.workOrderId)) {
    return { wroteCloud: false, queuedOffline: false };
  }
  const pausePayload = {
    tenant_id: selectedOrder.tenantId,
    work_order_id: selectedOrder.workOrderId,
    process_id: selectedOrder.processId,
    report_date: new Date().toISOString().slice(0, 10),
    completed_qty: 0,
    defect_qty: 0,
    status_after_report: "paused",
    remark: `[暫停加工] ${reason}`,
  };
  const actorAppUserId = await machtileResolveAppUserId();
  if (actorAppUserId) pausePayload.user_id = actorAppUserId;
  // backlog B (2026-07-11): pause goes through the outbox too — RPC accepts
  // status_after_report ('paused' whitelist, migration 202607110005). Pause
  // stays single-actor (whoever pressed it), no operator multi-select.
  if (machtileOutboxEnabled()) {
    const box = await machtileGetOutbox();
    if (box) {
      const pauseEndedAt = new Date().toISOString();
      const pauseStartedAt = machtileTakeStartedAt(selectedOrder.processId, pauseEndedAt);
      const outboxPausePayload = { ...pausePayload, ended_at: pauseEndedAt };
      if (pauseStartedAt) outboxPausePayload.started_at = pauseStartedAt;
      const { report_uuid } = await box.submitter.submit(
        outboxPausePayload,
        { operators: actorAppUserId ? [actorAppUserId] : [] }
      );
      await box.outbox.flush().catch(() => {});
      const record = await box.outbox.get(report_uuid).catch(() => null);
      machtileUpdateOutboxBadge();
      return { wroteCloud: true, queuedOffline: record?.status !== "sent" };
    }
  }
  // seam 待辦 B(a): same report_uuid treatment for the pause fallback
  if (!pausePayload.report_uuid && globalThis.crypto?.randomUUID) {
    pausePayload.report_uuid = crypto.randomUUID();
  }
  await supabaseFetch("production_reports", {
    method: "POST",
    body: JSON.stringify(pausePayload),
  });
  return { wroteCloud: true, queuedOffline: false };
}

async function handlePauseReport() {
  if (!selectedOrder) {
    showToast("此機台尚未指派工單，無法暫停加工。");
    return;
  }
  const reason = window.prompt("請輸入暫停原因，例如：換刀、待料、量測、機台異音");
  if (!reason?.trim()) return;
  try {
    const pauseResult = await submitPauseReport(reason.trim());
    selectedOrder.processStatus = "paused";
    selectedOrder.workStatus = "paused";
    selectedOrder.lastReport = "剛剛";
    closeReport();
    renderAll();
    showToast(
      !pauseResult.wroteCloud ? "已標記暫停加工"
        : pauseResult.queuedOffline ? "已排入待送：暫停加工，連線後自動送出"
        : "已寫入 Supabase：暫停加工"
    );
  } catch (error) {
    showToast(`暫停失敗：${error.message}`);
  }
}

function handleLocalReport(completed, defects, options = {}) {
  if (!selectedOrder) return;
  // 示範模式（不寫雲端）：2026-10-01 起欄位是「這次良品」，一律當增量加上去（與回寫橋一致）。
  if (Number(completed || 0) > 0) {
    selectedOrder.done = Math.min(Number(selectedOrder.total || 0), Number(selectedOrder.done || 0) + completed);
  }
  selectedOrder.lastReport = "剛剛";
  if (defects > 0) {
    selectedOrder.workStatus = "abnormal";
    selectedOrder.processStatus = "abnormal";
    selectedOrder.risk = selectedOrder.risk || "medium";
  }
}

function bindEvents() {
  // 卡片「這台還掛 N 張」展開／收起 → 記住（toggle 不會冒泡，用 capture 收）
  document.addEventListener("toggle", (event) => {
    const box = event.target;
    if (box && box.matches && box.matches("details[data-card-orders]") && box.isConnected) {
      machtileSetCardOrdersOpen(box.dataset.cardOrders, box.open);
    }
  }, true);

  document.addEventListener("click", (event) => {
    if (machtileHandleBatchClick(event)) return;
    const viewButton = event.target.closest("[data-view]");
    if (viewButton) {
      switchView(viewButton.dataset.view);
      return;
    }

    const stationSelectButton = event.target.closest("[data-select-station]");
    if (stationSelectButton) {
      selectStation(stationSelectButton.dataset.selectStation);
      return;
    }

    const departmentButton = event.target.closest("[data-department]");
    if (departmentButton) {
      if (!machtileAvailableDepartments().includes(departmentButton.dataset.department)) return;
      activeDepartmentFilter = departmentButton.dataset.department;
      renderFilters();
      renderWorkOrders();
      renderSchedule();
      return;
    }

    const millingModeButton = event.target.closest("[data-milling-mode]");
    if (millingModeButton) {
      activeMillingModeFilter = millingModeButton.dataset.millingMode;
      renderFilters();
      renderWorkOrders();
      return;
    }

    const todayTile = event.target.closest("[data-today-tile]");
    if (todayTile) {
      machtileToggleTodayFilter(todayTile.dataset.todayTile);
      return;
    }

    if (event.target.closest("[data-today-filter-clear]")) {
      machtileSetTodayFilter(null);
      showToast("已顯示全部機台");
      return;
    }

    const statusButton = event.target.closest("[data-status]");
    if (statusButton) {
      machtileSetTodayFilter(null, { render: false });
      activeStatusFilter = statusButton.dataset.status;
      renderFilters();
      renderStats();
      renderWorkOrders();
      return;
    }

    const statButton = event.target.closest("[data-stat-filter]");
    if (statButton) {
      machtileSetTodayFilter(null, { render: false });
      activeStatusFilter = statButton.dataset.statFilter;
      renderStats();
      renderFilters();
      renderWorkOrders();
      showToast(`已篩選：${activeStatusFilter === "全部狀態" ? "總機台" : activeStatusFilter}`);
      return;
    }

    const alertButton = event.target.closest("[data-alert-filter]");
    if (alertButton) {
      activeAlertFilter = alertButton.dataset.alertFilter;
      renderAlerts();
      return;
    }

    const attentionFilterButton = event.target.closest("[data-attention-filter]");
    if (attentionFilterButton) {
      activeAttentionStatus = attentionFilterButton.dataset.attentionFilter;
      machtileAttentionState.selectedKeys.clear();
      renderAlerts();
      return;
    }

    const attentionSelect = event.target.closest("[data-attention-select]");
    if (attentionSelect) {
      const key = attentionSelect.dataset.attentionSelect;
      if (attentionSelect.checked) machtileAttentionState.selectedKeys.add(key);
      else machtileAttentionState.selectedKeys.delete(key);
      renderAlerts();
      return;
    }

    const attentionOpen = event.target.closest("[data-attention-open]");
    if (attentionOpen) {
      machtileOpenAttentionAction([attentionOpen.dataset.attentionKey], attentionOpen.dataset.attentionOpen);
      return;
    }

    const attentionBatch = event.target.closest("[data-attention-batch]");
    if (attentionBatch) {
      machtileOpenAttentionAction([...machtileAttentionState.selectedKeys], attentionBatch.dataset.attentionBatch);
      return;
    }

    if (event.target.closest("[data-attention-clear]")) {
      machtileAttentionState.selectedKeys.clear();
      renderAlerts();
      return;
    }

    if (event.target.closest("[data-close-attention-action]")) {
      machtileCloseAttentionAction();
      return;
    }

    if (machtileHandleHmcFixedClick(event)) return;

    const hmcPalletButton = event.target.closest("[data-hmc-runtime-pallet]");
    if (hmcPalletButton) {
      machtileOpenHmcRuntimeAction(hmcPalletButton.dataset.hmcRuntimeMachine, hmcPalletButton.dataset.hmcRuntimePallet);
      return;
    }

    const hmcMachineButton = event.target.closest("[data-hmc-runtime-machine-action]");
    if (hmcMachineButton) {
      machtileOpenHmcRuntimeAction(hmcMachineButton.dataset.hmcRuntimeMachineAction, null, hmcMachineButton.dataset.hmcRuntimeEvent);
      return;
    }

    if (event.target.closest("[data-close-hmc-runtime-action]")) {
      machtileCloseHmcRuntimeAction();
      return;
    }

    const historyTabButton = event.target.closest("[data-history-tab]");
    if (historyTabButton) {
      activeHistoryTab = historyTabButton.dataset.historyTab;
      renderHistory();
      return;
    }

    if (event.target.closest("[data-history-export]")) {
      const rows = filteredHistoryRows();
      machtileCsvDownload(
        `machtile-${activeHistoryTab}-${new Date().toISOString().slice(0, 10)}.csv`,
        ["類型", "事件類別", "工單", "品號／工件", "機台", "摘要", "事件時間", "系統寫入時間", "現場操作員", "系統修改人", "修改前／後", "原因", "資料來源"],
        rows.map((row) => [row.category, row.recordType, row.orderId, row.part, row.machine, row.title, row.eventTime, row.writtenAt, row.operator, row.modifier, row.beforeAfter, row.reason, row.source]),
      );
      showToast(`已依目前篩選匯出 ${rows.length} 筆`);
      return;
    }

    if (event.target.closest("#aiSupportFab")) {
      openAiSupport();
      return;
    }

    if (event.target.closest("[data-close-ai-support]")) {
      closeAiSupport();
      return;
    }

    const aiQuestionButton = event.target.closest("[data-ai-question]");
    if (aiQuestionButton) {
      submitAiSupportQuestion(aiQuestionButton.dataset.aiQuestion);
      return;
    }

    const cameraButton = event.target.closest("[data-camera-for]");
    if (cameraButton) {
      openCamera(cameraButton.dataset.cameraFor, cameraButton.dataset.cameraLabel);
      return;
    }

    if (event.target.closest("[data-camera-capture]")) {
      captureCameraPhoto();
      return;
    }

    if (event.target.closest("[data-close-camera]")) {
      closeCamera();
      return;
    }

    if (event.target.closest("[data-pause-report]")) {
      handlePauseReport();
      return;
    }

    const reportTypeButton = event.target.closest("[data-report-type]");
    if (reportTypeButton) {
      setReportType(reportTypeButton.dataset.reportType);
      return;
    }

    const reportButton = event.target.closest("[data-report], [data-open-report]");
    if (reportButton) {
      const reportOrderId = reportButton.dataset.report || reportButton.dataset.openReport || "";
      const reportType = reportButton.dataset.reportType || reportButton.dataset.openReportType || "workStart";
      const fromDetailSheet = Boolean(reportButton.closest("#detailSheet"));
      if (fromDetailSheet) closeDetail();
      openReport(reportOrderId, { reportType, machine: reportButton.dataset.reportMachine || "", processId: reportButton.dataset.reportProcess || "", returnDetailOrderId: fromDetailSheet ? reportOrderId : "" });
      return;
    }

    const machineAdminButton = event.target.closest("[data-machine-admin]");
    if (machineAdminButton) {
      openMachineAdmin(machineAdminButton.dataset.machineAdmin);
      return;
    }

    const estimateTabButton = event.target.closest("[data-estimate-tab]");
    if (estimateTabButton) {
      machtileSetEstimateTab(estimateTabButton.dataset.estimateTab);
      return;
    }

    const calibrationSample = event.target.closest("[data-calibration-sample]");
    if (calibrationSample) {
      machtileOpenCalibrationAction({ kind: "sample", runId: calibrationSample.dataset.calibrationSample, excluded: calibrationSample.dataset.calibrationExcluded === "true" });
      return;
    }

    const calibrationBaseline = event.target.closest("[data-calibration-baseline]");
    if (calibrationBaseline) {
      machtileOpenCalibrationAction({
        kind: "baseline", decisionType: calibrationBaseline.dataset.calibrationBaseline,
        programId: calibrationBaseline.dataset.calibrationProgram, machineId: calibrationBaseline.dataset.calibrationMachine,
        versionId: calibrationBaseline.dataset.calibrationVersion, suggestedSeconds: Number(calibrationBaseline.dataset.calibrationSuggested),
        sampleIds: String(calibrationBaseline.dataset.calibrationSamples || "").split(",").filter(Boolean),
      });
      return;
    }

    if (event.target.closest("[data-close-calibration-action]")) { machtileCloseCalibrationAction(); return; }

    const adminModuleButton = event.target.closest("[data-admin-module]");
    if (adminModuleButton) {
      if (adminModuleButton.dataset.adminModule === "add") machtileMachineEditSeed = null;
      openAdminModule(adminModuleButton.dataset.adminModule);
      return;
    }

    if (event.target.closest("[data-open-admin-drawer]")) {
      machtileToggleAdminDrawer(true);
      return;
    }

    const machineEditButton = event.target.closest("[data-machine-edit]");
    if (machineEditButton) {
      machtileOpenMachineEdit(machineEditButton.dataset.machineEdit);
      return;
    }

    if (event.target.closest("#adminDrawerBtn")) {
      machtileToggleAdminDrawer();
      return;
    }
    if (event.target.closest("#adminDrawerBackdrop")) {
      machtileToggleAdminDrawer(false);
      return;
    }
    const drawerItem = event.target.closest("[data-drawer-module]");
    if (drawerItem) {
      const key = drawerItem.dataset.drawerModule;
      machtileToggleAdminDrawer(false);
      if (key === "__guide") {
        window.location.href = hmcGuideRouteUrl("B01", "day");
        return;
      }
      if (key === "__batchLathe" || key === "__batchMill") {
        switchView(key === "__batchLathe" ? "batchLathe" : "batchMill");
        return;
      }
      if (key === "__history") {
        switchView("history");
        return;
      }
      if (key === "__reports") {
        switchView("reports");
        return;
      }
      if (key === "__tv") {
        machtileEnterTvFromMenu();
        return;
      }
      if (key === "add") machtileMachineEditSeed = null;
      openAdminModule(key);
      return;
    }

    const hmcQrCardLink = event.target.closest(".machine-qr-card");
    if (hmcQrCardLink) {
      const sameTabReportUrl = sameTabReportUrlFromLink(hmcQrCardLink.href);
      if (sameTabReportUrl) {
        event.preventDefault();
        window.location.href = sameTabReportUrl;
        return;
      }
    }

    const scheduleOpenButton = event.target.closest("[data-schedule-open]");
    if (scheduleOpenButton) {
      machtileScheduleExpanded = scheduleOpenButton.dataset.scheduleOpen || "";
      switchView("schedule");
      return;
    }

    // 卡片「這台還掛 N 張」：切換卡片顯示哪一張（只改畫面，不寫資料庫）
    const cardPickButton = event.target.closest("[data-card-pick]");
    if (cardPickButton) {
      machtileSetCardPick(cardPickButton.dataset.cardPick, cardPickButton.dataset.cardPickKey || "");
      return;
    }
    if (event.target.closest("[data-close-card-selection]")) { machtileCloseCardSelection(); return; }
    const cardSelectOpen = event.target.closest("[data-card-select-open]");
    if (cardSelectOpen) { machtileOpenCardSelection(cardSelectOpen.dataset.cardSelectOpen); return; }
    const cardPoolOpen = event.target.closest("[data-card-pool-open]");
    if (cardPoolOpen) { machtileOpenCardSelection(cardPoolOpen.dataset.cardPoolOpen, { poolOnly: true }); return; }
    const cardSelectProcess = event.target.closest("[data-card-select-process]");
    if (cardSelectProcess) {
      machtileCommitCardSelection(cardSelectProcess.dataset.cardSelectMachine, cardSelectProcess.dataset.cardSelectProcess);
      return;
    }

    // 臥式機台沒有工單：卡片「明細」→ 只看這台的交換盤盤況
    const hmcMachineDetail = event.target.closest("[data-hmc-machine-detail]");
    if (hmcMachineDetail) {
      machtileOpenHmcMachineDetail(hmcMachineDetail.dataset.hmcMachineDetail);
      return;
    }

    if (machtileStationCmdHandleClick(event)) return;

    if (event.target.closest("[data-no-detail]")) {
      return;
    }

    const detailButton = event.target.closest("[data-detail]");
    if (detailButton) {
      openDetail(detailButton.dataset.detail);
      return;
    }

    if (event.target.closest("[data-close-report]")) {
      closeReport();
      return;
    }

    if (event.target.closest("[data-close-detail]")) {
      closeDetail();
      return;
    }

    if (event.target.closest("[data-close-machine-admin]")) {
      closeMachineAdmin();
      return;
    }

    if (event.target.closest("[data-close-admin-module]")) {
      closeAdminModule();
      return;
    }

    if (event.target.closest("#openNotificationsBtn")) {
      openNotificationDrawer();
      return;
    }

    if (event.target.closest("#closeNotificationsBtn")) {
      closeNotificationDrawer();
      return;
    }

    if (event.target.id === "notificationDrawer") {
      closeNotificationDrawer();
      return;
    }

    const qcPunchBtn = event.target.closest("[data-qc-punch]");
    if (qcPunchBtn) {
      const row = qcPunchBtn.closest("[data-qc-slot]");
      if (row) {
        if (qcPunchBtn.dataset.qcPunch === "pass") {
          machtileQcPunch(row, "pass").catch((error) => showToast(`品檢記錄失敗：${String(error?.message || error || "")}`));
        } else {
          const noteBox = row.querySelector(".machtile-qc-note");
          noteBox.hidden = false;
          noteBox.querySelector("input").focus();
        }
      }
      return;
    }
    const qcConfirmBtn = event.target.closest("[data-qc-punch-confirm]");
    if (qcConfirmBtn) {
      const row = qcConfirmBtn.closest("[data-qc-slot]");
      const input = row.querySelector(".machtile-qc-note input");
      if (!input.value.trim()) {
        showToast("異常原因必填");
        return;
      }
      machtileQcPunch(row, "fail", input.value.trim()).catch((error) => showToast(`品檢記錄失敗：${String(error?.message || error || "")}`));
      return;
    }
    const qcRedoBtn = event.target.closest("[data-qc-redo]");
    if (qcRedoBtn) {
      machtileQcEditSet.add(`${qcRedoBtn.dataset.qcRedo}|${qcRedoBtn.dataset.qcMachine}`);
      machtileRenderQcBoard().catch(() => {});
      return;
    }

    const actionButton = event.target.closest("[data-alert-action]");
    if (actionButton) {
      const action = actionButton.dataset.alertAction;
      const orderId = actionButton.dataset.alertOrder || "";
      if (action === "查看工單" && orderId) { openDetail(orderId); return; }
      if (action === "調排程") {
        const order = state.workOrders.find((item) => item.id === orderId);
        machtileScheduleExpanded = order?.machine || "";
        switchView("schedule");
        return;
      }
      showToast(`${action}${orderId ? `：${orderId}` : ""}`);
      return;
    }

    const adminSaveButton = event.target.closest("[data-admin-save]");
    if (adminSaveButton) {
      showToast(`${adminSaveButton.dataset.adminSave}已建立草稿`);
    }
  });

  $("#attentionActionForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    machtileSubmitAttentionAction().catch((error) => showToast(String(error?.message || error || "待處理案件更新失敗")));
  });

  $("#hmcRuntimeEventSelect")?.addEventListener("change", machtileHmcRuntimeUpdateActionNote);
  $("#hmcRuntimeSuggestedUse")?.addEventListener("click", () => {
    const select = $("#hmcRuntimeEventSelect");
    const suggestedEvent = machtileHmcRuntimeState.action?.suggestedEvent || "";
    if (!select || !suggestedEvent) return;
    select.value = suggestedEvent;
    const otherEvents = $("#hmcRuntimeOtherEvents");
    if (otherEvents) otherEvents.open = false;
    machtileHmcRuntimeUpdateActionNote();
  });
  $("#hmcRuntimeActionForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    machtileSubmitHmcRuntimeAction().catch((error) => showToast(machtileHmcRuntimeErrorMessage(error)));
  });
  $("#calibrationActionForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    machtileSubmitCalibrationAction();
  });

  $$(".stepper button").forEach((button) => {
    button.addEventListener("click", () => {
      const input = $(`#${button.dataset.step}`);
      const value = Math.max(0, Number(input.value || 0) + Number(button.dataset.delta));
      input.value = value;
      updateNoonAdvice();
    });
  });

  ["workTotalQty", "cycleMinutes", "cycleSeconds", "completedQty"].forEach((id) => {
    const input = $(`#${id}`);
    if (!input) return;
    input.addEventListener("input", () => {
      if (id === "cycleMinutes" || id === "cycleSeconds") reportCycleTouched = true;
      updateReportEstimate();
      updateNoonAdvice();
    });
  });

  ["startPhoto", "machinePhoto", "finishPhoto", "abnormalPhoto"].forEach((id) => {
    const input = $(`#${id}`);
    if (!input) return;
    input.addEventListener("change", () => {
      if (input.files?.length) capturedCameraFiles.delete(id);
      updateCameraStatus(id);
    });
  });

  $("#aiSupportForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    submitAiSupportQuestion($("#aiSupportInput")?.value);
  });

  $("#reportForm").addEventListener("submit", async (event) => {
    event.preventDefault();
    if (!selectedOrder) {
      showToast("此機台尚未指派工單，請先由主管排入工單。");
      return;
    }
    const validationMessage = validateReportForm(activeReportType);
    if (validationMessage) {
      showToast(validationMessage);
      return;
    }
    // F-2（2026-09-02）：站別帳號登入時，沒選到有對照的真人就不讓送出——
    // 否則產值會掛在機台上，而且回寫 feed 也會把整筆擋下（F-3=A）。
    const operatorMessage = machtileValidateOperatorSelection();
    if (operatorMessage) {
      showToast(operatorMessage);
      return;
    }
    // 開了「開工／停工」的機台（owner 2026-10-08「先修」）：同一道今天已有排入待送的今日開工 → 不送第二筆
    // 送出前重讀伺服器今天的報工：已有今日開工 → 擋（L3 複審）
    if (activeReportType === "dailyStart" && selectedOrder.processId && machtileStationCmdActiveFor(selectedOrder.machine)) {
      const already = await machtileDailyStartExistsToday(selectedOrder.processId);
      if (already === "server") {
        showToast(machtileStationCmdCore.DAILY_START_ALREADY_TEXT);
        return;
      }
      if (already === "unknown") {   // 讀不到伺服器 → 不能確定今天沒有，不送
        showToast(machtileStationCmdCore.DAILY_START_UNREADABLE_TEXT);
        return;
      }
      if (already === "outbox" || already === "pending") {
        const queued = already === "pending" ? { qty: machtileDailyStartQueueFor(selectedOrder.processId)?.snap.qty }
          : await machtileOutboxPendingDailyStart(selectedOrder.processId);
        showToast(machtileStationCmdCore.dailyStartBlockedText(queued?.qty));
        return;
      }
    }
    const meta = reportTypeMeta[activeReportType] || reportTypeMeta.workStart;
    const completed = Number($("#completedQty").value || 0);
    const defects = Number($("#defectQty").value || 0);
    const remark = buildReportRemark(activeReportType, $("#reportNote").value.trim());
    try {
      const result = await submitReport(completed, defects, remark, activeReportType);
      if (!result.wroteCloud) handleLocalReport(meta.needsQty ? completed : 0, defects, meta);
      closeReport();
      renderAll();
      const qtyText = meta.needsQty ? `：良品 ${completed} 件，不良 ${defects} 件` : "";
      const fileText = result.uploaded ? `，附件 ${result.uploaded} 個` : result.uploadFailed ? "，附件待補" : "";
      showToast(
        !result.wroteCloud ? `已送出示範${meta.label}${qtyText}`
          : result.queuedOffline ? `已排入待送${meta.label}${qtyText}，連線後自動送出`
          : `已寫入 Supabase ${meta.label}${qtyText}${fileText}`
      );
      // Suggestion only (owner 2026-09-24): who should look at this, how urgent. Runs after
      // the report is safely written; a failure here changes nothing about the report.
      // Only the uuid is sent: since mini-mes #72 the function reads the stored report itself
      // (and ignores any text sent). A report still queued offline is not in the cloud yet, so
      // asking would only get 404 — skip it.
      if (activeReportType === "abnormal" && result.wroteCloud && !result.queuedOffline && result.reportUuid) {
        machtileJevTriage({ reportUuid: result.reportUuid })
          .then((label) => { if (label) showToast(`AI 建議：${label}`); });
      }
    } catch (error) {
      showToast(`回報失敗：${error.message}`);
    }
  });
}

// ---- Jev triage (2026-09-24) -------------------------------------------------------------
// The tablet never talks to the model: it calls our Edge Function (jev-triage), which holds
// the gateway key, checks the session's tenant, asks Jev the three questions and stores the
// answer under the report's uuid. Off unless config.enableJevTriage is true (the function
// and its secret must be deployed first). Returns the label to show, or "" when unavailable.
function machtileJevTriageEnabled() {
  return config.enableJevTriage === true && machtileStrictMode() && machtileSessionActive();
}

async function machtileJevTriage(payload) {
  if (!machtileJevTriageEnabled()) return "";
  try {
    const { ok, body } = await amCallFunction("jev-triage", payload);
    if (!ok || !body?.label) {
      console.warn("jev-triage unavailable", body?.code || "");
      return "";
    }
    return String(body.label);
  } catch (error) {
    console.warn("jev-triage failed", error);
    return "";
  }
}

// Stored suggestions for the history page: report_uuid → { owner, ownerProb, urgency }.
async function machtileJevSuggestionsByReport() {
  if (!machtileJevTriageEnabled()) return new Map();
  try {
    const rows = await supabaseFetch("abnormal_triage_suggestions?select=report_uuid,owner,owner_prob,urgency,machine_down_prob&order=created_at.desc&limit=200");
    return new Map((Array.isArray(rows) ? rows : []).map((row) => [String(row.report_uuid), row]));
  } catch (error) {
    console.warn("abnormal_triage_suggestions read failed", error);
    return new Map();
  }
}

const machtileJevOwnerLabels = { maintenance: "設備維修", planner: "生管排程", qc: "品管", none: "不用處理" };

function machtileJevChip(row) {
  if (!row) return "";
  const owner = machtileJevOwnerLabels[row.owner] || row.owner || "-";
  const pct = Math.round(Number(row.owner_prob || 0) * 100);
  const urgency = Number(row.urgency || 0);
  const tone = urgency >= 2.5 ? "is-urgent" : urgency >= 1.5 ? "is-soon" : "";
  return `<span class="jev-chip ${tone}" title="AI 建議分流（只是建議，不會自動通知）">AI 建議：${escapeHtml(owner)} ${pct}%・緊急 ${urgency.toFixed(1)}/3</span>`;
}

function formatDuration(ms) {
  const totalSeconds = Math.max(0, Math.floor(ms / 1000));
  const hours = String(Math.floor(totalSeconds / 3600)).padStart(2, "0");
  const minutes = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0");
  const seconds = String(totalSeconds % 60).padStart(2, "0");
  return `${hours}:${minutes}:${seconds}`;
}

function startDemo() {
  const params = new URLSearchParams(window.location.search);
  if (params.get("demo") !== "1") return;

  const durationMinutes = Number(params.get("duration") || 180);
  const durationMs = Math.max(1, durationMinutes) * 60 * 1000;
  const startedAt = Date.now();
  const views = ["dashboard", "alerts", "history", "reports", "settings"];
  let viewIndex = 0;
  let statusFilterIndex = 0;

  demoState = { timers: [], timeouts: [], startedAt, durationMs };
  $("#demoBanner").hidden = false;

  const updateTimer = () => {
    const remaining = durationMs - (Date.now() - startedAt);
    $("#demoTimer").textContent = formatDuration(remaining);
    if (remaining <= 0) stopDemo("自動展示已結束");
  };

  const cycleView = () => {
    viewIndex = (viewIndex + 1) % views.length;
    switchView(views[viewIndex]);
  };

  const cycleFilter = () => {
    statusFilterIndex = (statusFilterIndex + 1) % statusFilters.length;
    switchView("dashboard");
    activeStatusFilter = statusFilters[statusFilterIndex];
    renderStats();
    renderFilters();
    renderWorkOrders();
  };

  updateTimer();
  demoState.timers.push(window.setInterval(updateTimer, 1000));
  demoState.timers.push(window.setInterval(cycleView, 15000));
  demoState.timers.push(window.setInterval(cycleFilter, 22000));
  const pulseReportSheet = () => {
    openReport();
    const timeout = window.setTimeout(closeReport, 5500);
    demoState?.timeouts.push(timeout);
  };

  demoState.timers.push(window.setInterval(pulseReportSheet, 60000));

  $("#stopDemoBtn").addEventListener("click", () => stopDemo("自動展示已停止"), { once: true });
  showToast("自動展示已開始");
}

function stopDemo(reason = "自動展示已停止") {
  if (!demoState) return;
  demoState.timers.forEach((timer) => window.clearInterval(timer));
  demoState.timeouts.forEach((timer) => window.clearTimeout(timer));
  demoState = null;
  $("#demoBanner").hidden = true;
  closeReport();
  showToast(reason);
}

function updateTodayLabel() {
  const now = new Date();
  const weekday = ["日", "一", "二", "三", "四", "五", "六"][now.getDay()];
  $("#todayLabel").textContent = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, "0")}/${String(now.getDate()).padStart(2, "0")} 週${weekday}`;
}

// 每個 route 頁左上角固定品牌列（點擊回首頁）；CSS 只在 *-route-mode 顯示。
function machtileEnsureRouteBrand() {
  if (document.getElementById("machtileRouteBrand")) return;
  const bar = document.createElement("div");
  bar.id = "machtileRouteBrand";
  bar.className = "machtile-route-brand-bar";
  bar.innerHTML = `
    <a class="brand" href="./" aria-label="回首頁">
      <div class="brand-mark" aria-hidden="true"><span></span></div>
      <div>
        <div class="brand-name">MachTile</div>
        <div class="brand-subtitle">製程方塊</div>
      </div>
    </a>
  `;
  document.body.prepend(bar);
}

function applyInitialRoute() {
  ensureP0SafeModeBanner();
  machtileEnsureRouteBrand();
  const params = new URLSearchParams(window.location.search);
  const routePath = currentRoutePath();
  const routeView = params.get("view");

  if (routePath === stationSelectRoutePath()) {
    renderStationSelectRoute();
    return;
  }

  if (routePath === workListRoutePath()) {
    renderWorkListRoute();
    return;
  }

  if (routePath === workDetailRoutePath()) {
    renderWorkDetailRoute();
    return;
  }

  if (routePath === reportWorkRoutePath() || routePath.startsWith(`${reportWorkRoutePath()}/`)) {
    renderReportWorkRoute();
    return;
  }

  if (routePath === hmcWorklistSetupRoutePath() || routePath.startsWith(`${hmcWorklistSetupRoutePath()}/`)) {
    renderHmcWorklistSetupRoute();
    return;
  }

  if (routePath === hmcDailyCheckReviewRoutePath() || routePath.startsWith(`${hmcDailyCheckReviewRoutePath()}/`)) {
    renderHmcDailyCheckReviewRoute();
    return;
  }

  if (routePath === hmcFormalReportsRoutePath() || routePath.startsWith(`${hmcFormalReportsRoutePath()}/`)) {
    renderHmcFormalReportsRoute();
    return;
  }

  if (routePath === hmcFormalReportDraftsRoutePath() || routePath.startsWith(`${hmcFormalReportDraftsRoutePath()}/`)) {
    renderHmcFormalReportDraftsRoute();
    return;
  }

  if (routePath === hmcGuideRoutePath() || routePath.startsWith(`${hmcGuideRoutePath()}/`)) {
    renderHmcGuideRoute();
    return;
  }

  if (routePath === hmcReportRoutePath() || routePath.startsWith(`${hmcReportRoutePath()}/`)) {
    renderHmcReportRoute();
    return;
  }

  if (isWorkOrderDetailRoutePath(routePath)) {
    const orderId = decodeURIComponent(routePath.replace("/work-orders/", ""));
    switchView("dashboard");
    openDetail(orderId, { routeMode: true });
    return;
  }

  if (routePath === "/m/report" || routePath.startsWith("/m/report/")) {
    const machineName = params.get("machine") || "";
    const orderNo = params.get("wo") || "";
    switchView("dashboard");
    if (!isReportableMachineName(machineName)) {
      showToast("未排機沒有報工 QR，請先在工單指派實際機台");
      return;
    }
    openReport(orderNo, { routeMode: true, machine: machineName, reportType: params.get("type") || "dailyStart" });
    return;
  }

  // 現場大螢幕電視頁（owner 2026-10-03）：全螢幕、沒有導覽，見 machtileOpenTvWall
  if (routeView === "tv") {
    machtileOpenTvWall();
    return;
  }

  if (routeView) switchView(routeView);
}

async function init() {
  updateTodayLabel();
  loadMockData();
  bindEvents();

  // Gate P / P2 GlobalLoginGate: in strict mode nothing renders (and no data
  // call fires) before a successful login; the gate resumes init afterwards.
  // Route changes are full page loads, so first try the per-tab persisted
  // session before showing the gate.
  // The gate is pre-rendered in index.html (first paint), so every exit from this block must
  // either hand it to the login/progress renderers or remove it below; an unexpected throw
  // while restoring the session falls back to the login button instead of a stuck cover.
  machtileOauthHandoffResume = machtileFinishSignedInBoot;
  if (machtileStrictMode() && machtileOauthConfigured()) {
    machtileSweepOauthShared();
    machtileInstallOauthHandoffListeners();
  }
  try {
    if (machtileStrictMode() && !machtileSessionActive()) {
      await machtileRestoreSession();
    }
    if (machtileStrictMode() && !machtileSessionActive()) {
      const oauthPendingOrComplete = await machtileTryOauthSignIn();
      if (oauthPendingOrComplete && !machtileSessionActive()) return;
    }
  } catch (error) {
    console.warn("session restore failed", error);
  }
  if (machtileStrictMode() && !machtileSessionActive()) {
    machtileRenderLoginGate();
    return;
  }
  await machtileFinishSignedInBoot();
}

// Everything init() does once a session exists. Also the resume point when the
// installed App takes over a login finished in a Custom Tab (runs at most once).
let machtileSignedInBootDone = false;

async function machtileFinishSignedInBoot() {
  if (machtileSignedInBootDone) return;
  if (!machtileEnforceCentralAccess()) return;
  machtileSignedInBootDone = true;

  machtileRemoveLoginGate();
  machtileEnsureSessionBadge();
  machtileApplyBranding();
  machtileEnsureRefreshTimer();
  await machtileResumeInit();
}

async function machtileResumeInit() {
  if (isP0SafeMode()) {
    ensureP0SafeModeBanner();
    applyInitialRoute();
    return;
  }

  if (isP0RoutePath()) {
    applyInitialRoute();
    return;
  }

  if (isWorkOrderDetailRoutePath()) {
    renderAll();
    applyInitialRoute();
    return;
  }

  if (config.useSupabase && config.supabaseUrl && config.supabaseAnonKey) {
    try {
      await loadFromSupabase();
    } catch (error) {
      if (machtileStrictMode()) {
        machtileClearDepartmentData();
        renderAll();
        showToast(error?.message || "權限或資料讀取失敗，已停用操作");
        return;
      }
      console.warn("Supabase load failed, fallback to mock data:", error);
      loadMockData();
      showToast("Supabase 讀取失敗，已切回示範資料");
    }
  }

  renderAll();
  machtileEnsureHmcRuntimePolling();
  applyInitialRoute();
  startDemo();
}

// ---- Monitor 機台卡片：機台加工時間直接填、今日開工狀態、每日估算（owner 2026-10-02）----
// 1. 點卡片「機台加工時間」→ 小框填分／秒（作業員看機台控制器螢幕上的每件加工時間）→ 儲存＝送一筆 0／0 的報工，
//    只帶 cycle_time_seconds。payload 直接用批次報工的 batchReportCore.buildReportPayload（中午報工類型、只改時間），
//    started_at＝ended_at＝上一筆報工的時間（不推進起算點）、report_uuid 冪等、報工人＝登入者。
// 2. 卡片底部改成這道工序「今天」的狀態：今日已開工 08:05・姓名／今日已收工 17:00／今日尚未開工。
//    資料＝production_reports 今天（台灣時區）的 dailyStart／finish 最新一筆。讀不到 → 原本的顯示。
// 3. 每日估算的上下料時間：cardEstimateCore（實績中位數 ≥ 3 筆，否則車床 60／銑床 180 秒預設）。
// 全部只讀＋前端計算；寫入只有第 1 項（跟批次報工同一支 field_report_upsert）。
const machtileCardEstimateCore = () => (typeof window === "undefined" ? null : window.MachTileCardEstimateCore);
const MACHTILE_CARD_CT_DRAFT_KEY = "machtile-card-machine-time-drafts";
const MACHTILE_CARD_FETCH_TIMEOUT_MS = 4000;
const machtileCardState = {
  statsByKey: new Map(),   // 產品＋工序 → 上下料／實際每件時間樣本
  statsStatus: "idle",     // idle | ok | error（error＝全部用預設值）
  today: new Map(),        // processId → 今天最新一筆 dailyStart／finish
  todayRows: [],           // 今天的 dailyStart／noon／finish 原始列（總覽「今日報工狀態」三格用，見 todayReportStatusCore.js）
  todayLoadedAt: 0,        // 上一次讀到 todayRows 的時間（每分鐘重算時，超過 2 分鐘就重讀同一份查詢）
  todayStatus: "idle",     // idle | ok | error（不是 ok＝卡片底部照原本顯示、總覽三格顯示「—」）
  userNames: new Map(),
  editor: null,            // 開著的小框：{ ref, processId, machineCode, loading, saving, readOnly, notice, error, ctx }
};

// 卡片資料：逐工序在站來源；排程板／提醒中心仍保留原 workOrders view。
function machtileCardOrders() {
  return machtileMachineCardOrders();
}

async function machtileCardFetch(path) {
  const controller = typeof AbortController === "function" ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), MACHTILE_CARD_FETCH_TIMEOUT_MS) : null;
  try {
    return await supabaseFetch(path, controller ? { signal: controller.signal } : {});
  } finally {
    if (timer) clearTimeout(timer);
  }
}

function machtileMachineForOrder(order) {
  const name = String(order?.machine || "").trim();
  if (!name) return null;
  const upper = name.toUpperCase();
  const same = (m) => m && [m.name, m.code].some((v) => String(v || "").trim().toUpperCase() === upper);
  return (state.machines || []).find(same) || (state.machineMasters || []).find(same) || baseMachines.find(same) || { name };
}

function machtileOrderProductKey(order) {
  const core = machtileCardEstimateCore();
  if (!core || !order) return null;
  const drawing = order.drawingNo ?? (order.drawing && order.drawing !== "-" ? order.drawing : "");
  return core.productKey({ drawingNo: drawing, partNo: order.partNo, partName: order.part, processName: order.process });
}

// 這張單用的上下料時間（cardEstimateCore.resolveLoadUnload 的結果）；沒有 core → null（估算退回不含上下料）
function machtileLoadUnloadFor(order) {
  const core = machtileCardEstimateCore();
  if (!core || !order) return null;
  try {
    const kind = core.machineKind(machtileMachineForOrder(order));
    const key = machtileOrderProductKey(order);
    const stats = key ? machtileCardState.statsByKey.get(key) || null : null;
    return core.resolveLoadUnload({ kind, stats });
  } catch (error) {
    console.warn("load/unload estimate failed", error);
    return null;
  }
}

async function machtileLoadCardTodayAndLoadUnload(orders) {
  const core = machtileCardEstimateCore();
  if (!core || state.source !== "supabase") return;
  await Promise.all([machtileLoadCardToday(core), machtileLoadCardLoadUnload(core, Array.isArray(orders) ? orders : [])]);
}

// 今天（台灣日期）的 dailyStart／noon／finish：卡片底部「今日已開工／已收工」與總覽「今日報工狀態」三格共用這一次查詢。
// 下限＝台灣今天 00:00（created_at）；卡片底部只看 dailyStart／finish（todayStatusByProcess 會略過 noon）。
// started_at／completed_qty／defect_qty：認出「只改機台加工時間」的 0／0 noon（不算中午報工，見 todayReportStatusCore）。
function machtileCardTodayPath(core) {
  const since = core.todayStartIso();
  return `production_reports?select=process_id,report_type,created_at,started_at,ended_at,completed_qty,defect_qty,user_id,operator_ids&report_type=in.(dailyStart,noon,finish)&created_at=gte.${encodeURIComponent(since)}&order=created_at.desc&limit=1000`;
}

function machtileApplyCardTodayRows(core, rows) {
  if (!Array.isArray(rows)) throw new Error("production_reports returned no rows array");
  machtileCardState.today = core.todayStatusByProcess(rows);
  machtileCardState.todayRows = rows;
  machtileCardState.todayLoadedAt = Date.now();
  machtileCardState.todayStatus = "ok";
}

async function machtileLoadCardToday(core) {
  try {
    const [rows, users] = await Promise.all([
      machtileCardFetch(machtileCardTodayPath(core)),
      machtileFetchOperatorList(),
    ]);
    machtileApplyCardTodayRows(core, rows);
    machtileCardState.userNames = new Map((Array.isArray(users) ? users : []).map((u) => [String(u.id), u.name || ""]));
  } catch (error) {
    console.warn("today start status unavailable; cards keep the last-report text", error);
    machtileCardState.today = new Map();
    machtileCardState.todayRows = [];
    machtileCardState.todayStatus = "error";
  }
}

async function machtileLoadCardLoadUnload(core, orders) {
  try {
    // 畫面上工單的圖號／品號：v_work_order_cards 沒有 part_no，正式庫幾乎每張單都只有品號（沒有圖號），
    // 不補的話卡片會用品名、報工那邊用品號，對不上。
    const woIds = [...new Set(orders.map((o) => String(o.workOrderId || "")).filter(isUuid))];
    const woById = new Map();
    for (let i = 0; i < woIds.length; i += 80) {
      const chunk = woIds.slice(i, i + 80).map(encodeURIComponent).join(",");
      const rows = await machtileCardFetch(`work_orders?select=id,drawing_no,part_no,part_name&id=in.(${chunk})`);
      (Array.isArray(rows) ? rows : []).forEach((r) => woById.set(String(r.id), r));
    }
    orders.forEach((o) => {
      const wo = woById.get(String(o.workOrderId || ""));
      if (!wo) return;
      o.drawingNo = wo.drawing_no || "";
      o.partNo = wo.part_no || "";
    });
    // 最近的報工（有數量、或有填機台加工時間），連同產品與工序名稱；跨工單累積同一個產品＋工序
    const reports = await machtileCardFetch("production_reports?select=process_id,started_at,ended_at,completed_qty,defect_qty,cycle_time_seconds,created_at,work_order_processes(process_name),work_orders(drawing_no,part_no,part_name)&or=(completed_qty.gt.0,defect_qty.gt.0,cycle_time_seconds.not.is.null)&order=created_at.desc&limit=3000");
    const rows = Array.isArray(reports) ? reports : [];
    const keyByProcess = new Map();
    rows.forEach((r) => {
      if (!r?.process_id || keyByProcess.has(String(r.process_id))) return;
      const wo = r.work_orders || {};
      keyByProcess.set(String(r.process_id), core.productKey({
        drawingNo: wo.drawing_no, partNo: wo.part_no, partName: wo.part_name, processName: r.work_order_processes?.process_name,
      }));
    });
    machtileCardState.statsByKey = core.buildLoadUnloadStats(rows, keyByProcess);
    machtileCardState.statsStatus = "ok";
  } catch (error) {
    console.warn("load/unload calibration unavailable; using defaults", error);
    machtileCardState.statsByKey = new Map();
    machtileCardState.statsStatus = "error";
  }
}

// 卡片底部：今日開工狀態；沒讀到（示範資料、讀取失敗）→ 原本的「最後回報」文字
function machtileCardFooterStatus(order, machine) {
  const fallback = `<span>${escapeHtml(order?.lastReport || machine?.note || "尚未回報")}</span>`;
  const core = machtileCardEstimateCore();
  if (!order || !core || machtileCardState.todayStatus !== "ok" || !order.processId) return fallback;
  try {
    const label = core.todayStatusLabel(machtileCardState.today.get(String(order.processId)), (uid) => machtileCardState.userNames.get(String(uid)) || "");
    const title = order.lastReport ? ` title="最後回報：${escapeHtml(order.lastReport)}"` : "";
    return `<span class="card-today-status is-${escapeHtml(label.tone)}" data-today-status="${escapeHtml(label.tone)}"${title}>${escapeHtml(label.text)}</span>`;
  } catch (error) {
    console.warn("today status label failed", error);
    return fallback;
  }
}

// 能不能在卡片上改機台加工時間：跟卡片「回報」按鈕同一套（有指派機台、不是臥式多盤），而且有工序 id；
// 正式模式要登入中（沒登入看不到頁面，這裡是保險）。
function machtileCardCanEditMachineTime(machine, order) {
  if (!order || !order.processId || !order.workOrderId) return false;
  if (!isReportableMachineName(machine?.name) || !isOrderReportable(order) || isHmcMachine(machine)) return false;
  if (machtileStrictMode() && !machtileSessionActive()) return false;
  return true;
}

function machtileCardCycleGrid(machine, order, profile, delta, dailyQty) {
  const core = machtileCardEstimateCore();
  const has = Number(profile?.pureCycleSec) > 0;
  const editable = machtileCardCanEditMachineTime(machine, order);
  const machineCode = String(machine?.code || machine?.name || "");
  const timeInner = `
            <span>機台加工時間</span>
            <strong>${has ? `${escapeHtml(formatSeconds(profile.pureCycleSec))}<small> / 件</small>` : "未填"}</strong>
            ${editable ? `<small class="cycle-edit-hint">${has ? "點這裡修改" : "點這裡填"}</small>` : ""}`;
  const timeCell = editable
    ? `<div class="cycle-machine-time is-editable${has ? "" : " is-missing"}" role="button" tabindex="0" data-no-detail data-card-ct-edit="${escapeHtml(String(order.processId))}" data-card-ct-machine="${escapeHtml(machineCode)}" aria-label="${escapeHtml(machineCode)} 機台加工時間：${has ? escapeHtml(formatSeconds(profile.pureCycleSec)) : "未填"}，點一下填寫">${timeInner}
          </div>`
    : `<div class="cycle-machine-time${has ? "" : " is-missing"}">${timeInner}
          </div>`;
  const lu = profile?.loadUnload || null;
  const actualDaily = core && lu?.actualPerPieceSec ? core.actualDailyEstimate(lu.actualPerPieceSec) : null;
  const luText = core && lu ? core.loadUnloadLabel(lu) : "";
  return `
        <div class="cycle-mini-grid">
          ${timeCell}
          <div>
            <span>基準差異</span>
            <strong class="${delta !== null && delta > 8 ? "cycle-warn" : ""}">${delta === null ? "-" : `${delta > 0 ? "+" : ""}${delta}%`}</strong>
          </div>
          <div class="cycle-daily-estimate">
            <span>每日估算</span>
            <strong>${dailyQty ? `${dailyQty} 件` : "-"}</strong>
            ${luText ? `<small class="cycle-load-unload" data-lu-source="${escapeHtml(lu.source)}">${escapeHtml(luText)}</small>` : ""}
            ${actualDaily ? `<small class="cycle-actual-daily" data-actual-samples="${lu.actualSamples}">實際約 ${actualDaily} 個／天</small>` : ""}
          </div>
        </div>`;
}

// ---- 小框 ----
function machtileCardCtSheet() {
  let sheet = document.getElementById("cardMachineTimeSheet");
  if (sheet) return sheet;
  sheet = document.createElement("div");
  sheet.id = "cardMachineTimeSheet";
  sheet.className = "sheet card-ct-sheet";
  sheet.setAttribute("aria-hidden", "true");
  sheet.innerHTML = `
    <div class="sheet-backdrop" data-card-ct-close></div>
    <section class="sheet-panel card-ct-panel" role="dialog" aria-modal="true" aria-labelledby="cardCtTitle">
      <div class="sheet-header">
        <div><p class="eyebrow" id="cardCtEyebrow"></p><h2 id="cardCtTitle">機台加工時間</h2></div>
        <button class="icon-button" type="button" data-card-ct-close aria-label="關閉">×</button>
      </div>
      <form id="cardCtForm" class="card-ct-form" novalidate></form>
    </section>`;
  document.body.appendChild(sheet);
  sheet.addEventListener("click", (event) => {
    if (event.target.closest("[data-card-ct-close]")) machtileCloseCardMachineTime();
  });
  // 改了數字就把上一次的紅字拿掉（例：「時間跟目前一樣」）
  sheet.querySelector("#cardCtForm").addEventListener("input", () => {
    if (machtileCardState.editor) machtileCardState.editor.error = "";
    sheet.querySelector("[data-card-ct-error]")?.remove();
  });
  sheet.querySelector("#cardCtForm").addEventListener("submit", (event) => {
    event.preventDefault();
    machtileSaveCardMachineTime();
  });
  return sheet;
}

function machtileRenderCardCtSheet() {
  const ed = machtileCardState.editor;
  const sheet = machtileCardCtSheet();
  if (!ed) return;
  const order = ed.order;
  sheet.querySelector("#cardCtEyebrow").textContent = `${ed.machineCode} · ${order?.id || ""}${order?.process ? ` · ${order.process}` : ""}`;
  const form = sheet.querySelector("#cardCtForm");
  const current = Number(order?.pureCycleSec) > 0 ? `${formatSeconds(order.pureCycleSec)} / 件` : "未填";
  const disabled = ed.loading || ed.saving || ed.readOnly ? " disabled" : "";
  form.innerHTML = `
    <p class="card-ct-help">看<strong>機台控制器螢幕</strong>上的每件加工時間，填分和秒。</p>
    <p class="card-ct-current">目前：<strong>${escapeHtml(current)}</strong></p>
    <div class="card-ct-inputs">
      <label><input id="cardCtMinutes" type="number" inputmode="numeric" min="0" step="1" value="${escapeHtml(ed.minutes)}" aria-label="分"${disabled}><span>分</span></label>
      <label><input id="cardCtSeconds" type="number" inputmode="numeric" min="0" max="59" step="1" value="${escapeHtml(ed.seconds)}" aria-label="秒"${disabled}><span>秒 / 件</span></label>
    </div>
    <p class="card-ct-operator" data-card-ct-operator>${ed.loading ? "讀取中…" : `報工人：${escapeHtml(ed.actorName || "（登入者）")}（只記錄機台時間，不寫回舊 MES）`}</p>
    ${ed.notice ? `<p class="card-ct-notice" data-card-ct-notice>${escapeHtml(ed.notice)}</p>` : ""}
    ${ed.error ? `<p class="card-ct-error" role="alert" data-card-ct-error>${escapeHtml(ed.error)}</p>` : ""}
    <div class="card-ct-actions">
      <button type="button" class="secondary-button" data-card-ct-close>取消</button>
      <button type="submit" class="primary-submit" data-card-ct-save${disabled}>${ed.saving ? "儲存中…" : "儲存"}</button>
    </div>`;
}

function machtileCloseCardMachineTime() {
  const sheet = document.getElementById("cardMachineTimeSheet");
  if (sheet) {
    sheet.classList.remove("is-open");
    sheet.setAttribute("aria-hidden", "true");
  }
  if (!machtileCardState.editor?.saving) machtileCardState.editor = null;
}

async function machtileOpenCardMachineTime(processId, machineCode) {
  const order = machtileCardOrders().find((o) => String(o.processId) === String(processId)) || null;
  const machine = machtileMachineForOrder(order) || { name: machineCode };
  if (!order || !machtileCardCanEditMachineTime(machine, order)) {
    showToast("這張單目前不能在卡片上填機台加工時間。");
    return;
  }
  const bcore = machtileBatchCore();
  const split = bcore ? bcore.splitSeconds(order.pureCycleSec) : { minutes: "", seconds: "" };
  const ed = {
    processId: String(processId), machineCode: String(machineCode || machine.code || machine.name || ""), order,
    minutes: split.minutes, seconds: split.seconds, loading: state.source === "supabase", saving: false,
    readOnly: false, notice: "", error: "", actorId: "", actorName: "", operatorMapped: false, progress: null,
  };
  machtileCardState.editor = ed;
  const sheet = machtileCardCtSheet();
  machtileRenderCardCtSheet();
  sheet.classList.add("is-open");
  sheet.setAttribute("aria-hidden", "false");
  if (state.source !== "supabase") {
    ed.notice = "示範資料：儲存只改畫面，不會寫入。";
    machtileRenderCardCtSheet();
    return;
  }
  try {
    const [actorId, users, progress] = await Promise.all([
      machtileResolveAppUserId(),
      machtileBatchFetchUsers(),
      machtileBatchFetchProgress([ed.processId]),
    ]);
    if (machtileCardState.editor !== ed) return;
    const choices = bcore ? bcore.operatorChoices(users) : [];
    ed.actorId = actorId || "";
    ed.actorName = machtileAuthState.appUserName || choices.find((u) => u.id === ed.actorId)?.name || "";
    ed.operatorMapped = choices.some((u) => u.id === ed.actorId);
    ed.progress = progress.map.get(ed.processId) || null;
    if (!ed.actorId) {
      ed.readOnly = true;
      ed.notice = "登入帳號沒有對應到啟用中的使用者，不能填。請聯絡管理者。";
    }
    // 沒有舊 MES 工號對照也可以填：這個小框只送 0／0（只帶 cycle_time_seconds），回寫橋不會寫回舊 MES
    // （SKIP_ZERO），所以不需要工號；報工人＝登入者本人（user_id、operators 都是 app_users.id，不捏造工號）。
  } catch (error) {
    if (machtileCardState.editor !== ed) return;
    ed.readOnly = true;
    ed.error = `讀取失敗：${error.message}`;
  }
  ed.loading = false;
  machtileRenderCardCtSheet();
  document.getElementById("cardCtMinutes")?.focus();
}

function machtileCardCtReadDrafts() {
  try { return JSON.parse(localStorage.getItem(MACHTILE_CARD_CT_DRAFT_KEY) || "{}") || {}; } catch { return {}; }
}

function machtileCardCtWriteDrafts(drafts) {
  try { localStorage.setItem(MACHTILE_CARD_CT_DRAFT_KEY, JSON.stringify(drafts || {})); } catch { /* storage unavailable */ }
}

function machtileCardCtAfterSaved(processId, seconds) {
  machtileApplyMachineTime(processId, seconds);
  try { deriveMachines(); renderWorkOrders(); } catch (error) { console.warn("monitor re-render after card machine time failed", error); }
}

async function machtileSaveCardMachineTime() {
  const ed = machtileCardState.editor;
  const bcore = machtileBatchCore();
  if (!ed || !bcore || ed.loading || ed.saving || ed.readOnly) return;
  ed.minutes = document.getElementById("cardCtMinutes")?.value ?? "";
  ed.seconds = document.getElementById("cardCtSeconds")?.value ?? "";
  ed.error = "";
  const order = ed.order;
  const ctDefault = Number(order.pureCycleSec) > 0 ? Math.round(Number(order.pureCycleSec)) : null;
  const parsed = bcore.parseMachineTime(ed.minutes, ed.seconds);
  if (parsed.error || parsed.seconds === null) {
    ed.error = parsed.error || "請填機台加工時間（分、秒）";
    machtileRenderCardCtSheet();
    return;
  }
  if (state.source !== "supabase") {
    machtileCloseCardMachineTime();
    machtileCardCtAfterSaved(order.processId, parsed.seconds);
    showToast(`示範模式：沒有寫入（機台加工時間 ${formatSeconds(parsed.seconds)}／件）`);
    return;
  }
  const endedAt = new Date().toISOString();
  // 起算點跟批次報工「中午報工」同一套規則（上一筆報工 → 本機 ledger → 工序開工）；只改時間時 ended_at＝started_at
  const start = bcore.resolveStartedAt({
    serverLastReportAt: ed.progress?.last_report_at || null,
    localLedgerAt: machtileBatchLedgerAt(order.processId),
    actualStartAt: ed.progress?.actual_start_at || null,
    endedAt,
  });
  const model = {
    mode: "noon",
    machineCode: ed.machineCode,
    order,
    good: "",
    bad: "",
    ctDefault,
    ctMinutes: ed.minutes,
    ctSeconds: ed.seconds,
    overtime: "",
    operatorId: ed.actorId,
    operatorMapped: ed.operatorMapped,
    allowUnmappedTimeOnly: true,
    startedAt: start.startedAt,
    startedAtReason: start.startedAt ? "" : "這張單在 App 上還沒有開工或報工紀錄，請先送「今日開工」再填時間。",
  };
  const v = bcore.validateRow(model);
  if (v.empty) { ed.error = "時間跟目前一樣，不用儲存。"; machtileRenderCardCtSheet(); return; }
  if (!v.send || !v.timeOnly) { ed.error = v.error || "不能儲存"; machtileRenderCardCtSheet(); return; }

  ed.saving = true;
  machtileRenderCardCtSheet();
  const drafts = machtileCardCtReadDrafts();
  const prev = drafts[ed.processId];
  const id = bcore.ensureReportUuid(prev, model, () => crypto.randomUUID());
  // 重送同一筆時沿用第一次的時間，payload 才會跟已經進 outbox／伺服器的那筆一致（同批次）
  const startedAt = id.reused && prev && "startedAt" in prev ? prev.startedAt : model.startedAt;
  const end = id.reused && prev?.endedAt ? prev.endedAt : endedAt;
  drafts[ed.processId] = { reportUuid: id.reportUuid, fingerprint: id.fingerprint, startedAt, endedAt: end };
  machtileCardCtWriteDrafts(drafts);
  let status = "sent";
  let message = "";
  try {
    const built = bcore.buildReportPayload({ row: { ...model, startedAt }, actorAppUserId: ed.actorId, endedAt: end, reportUuid: id.reportUuid, tenantId: order.tenantId });
    const box = machtileOutboxEnabled() ? await machtileGetOutbox() : null;
    await machtileBatchSendOne(box, built.payload, built.operators);
    if (box) {
      for (let i = 0; i < 3; i += 1) {
        await box.outbox.flush().catch(() => {});
        const left = (await box.outbox.pending().catch(() => [])).filter((x) => x.report_uuid === id.reportUuid && (x.next_attempt_at == null || x.next_attempt_at <= Date.now()));
        if (!left.length) break;
      }
      const record = await box.outbox.get(id.reportUuid).catch(() => null);
      if (record?.status === box.outbox.OUTBOX_STATUS.FAILED) { status = "failed"; message = `伺服器拒收：${record.last_error || ""}`; }
      else if (record?.status !== box.outbox.OUTBOX_STATUS.SENT) status = "queued";
    }
    if (status !== "failed") {
      delete drafts[ed.processId];
      machtileCardCtWriteDrafts(drafts);
      machtileBatchRollLedger(order.processId, built.payload.ended_at);
      machtileUpdateOutboxBadge();
      ed.saving = false;
      machtileCloseCardMachineTime();
      machtileCardCtAfterSaved(order.processId, built.payload.cycle_time_seconds);
      showToast(`${ed.machineCode} 機台加工時間 ${formatSeconds(built.payload.cycle_time_seconds)}／件${status === "queued" ? "：已排入待送，連線後自動送出" : "：已儲存"}`);
      return;
    }
  } catch (error) {
    status = "failed";
    message = `送出失敗：${error.message}`;
  }
  ed.saving = false;
  ed.error = `${message}（再按一次會重送同一筆，不會變兩筆）`;
  machtileRenderCardCtSheet();
}

function machtileHandleCardCtTrigger(event) {
  const trigger = event.target.closest?.("[data-card-ct-edit]");
  if (!trigger) return;
  if (event.type === "keydown" && event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  machtileOpenCardMachineTime(trigger.dataset.cardCtEdit, trigger.dataset.cardCtMachine);
}

document.addEventListener("click", machtileHandleCardCtTrigger);
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && document.getElementById("cardMachineTimeSheet")?.classList.contains("is-open")) {
    machtileCloseCardMachineTime();
    return;
  }
  machtileHandleCardCtTrigger(event);
});

// ---- Monitor 總覽「今日報工狀態」三格（owner 2026-10-02 拍板）----
// 今日未開工／今日未報工／未收工（可能加班）。判斷規則在 todayReportStatusCore.js（台灣時間，不看瀏覽器時區）。
// 資料＝卡片底部「今日已開工／已收工」同一次查詢（machtileCardState.todayRows），不另外打 API；
// 每分鐘重算一次（跨過 08:30／13:00／17:15／20:45 自動切換），順便每 2 分鐘重讀那同一份查詢（不然整天開著的畫面看不到新的報工）。
// 只改畫面，不寫資料庫。點格子＝卡片牆只顯示那幾台；再點一次或按「顯示全部」恢復。選擇記在 localStorage（讀寫都包 try/catch）。
const machtileTodayReportCore = () => (typeof window === "undefined" ? null : window.MachTileTodayReportCore);
const MACHTILE_TODAY_FILTER_KEY = "machtile-monitor-today-filter";
const MACHTILE_TODAY_TICK_MS = 60 * 1000;
const MACHTILE_TODAY_REFETCH_MS = 2 * 60 * 1000;
let machtileTodayFilter = machtileReadTodayFilter();
let machtileTodayTickTimer = null;
let machtileTodayRefetching = false;

function machtileReadTodayFilter() {
  try {
    const value = localStorage.getItem(MACHTILE_TODAY_FILTER_KEY);
    return ["notStarted", "unreported", "overtime"].includes(value) ? value : null;
  } catch {
    return null;
  }
}

function machtileWriteTodayFilter(value) {
  try {
    if (value) localStorage.setItem(MACHTILE_TODAY_FILTER_KEY, value);
    else localStorage.removeItem(MACHTILE_TODAY_FILTER_KEY);
  } catch { /* storage unavailable */ }
}

// 現在的三格；讀不到今日報工（示範資料、讀取失敗、還沒載入）→ null（三格顯示「—」）
function machtileTodaySummary() {
  const core = machtileTodayReportCore();
  if (!core || machtileCardState.todayStatus !== "ok") return null;
  try {
    const machines = managedMachineList().map((machine) => {
      const orders = [machine.order, ...(Array.isArray(machine.cardOrders) ? machine.cardOrders.map((item) => item?.order) : [])].filter(Boolean);
      return {
        key: machine.name,
        hasOrder: Boolean(machine.order) && !machine.isUnassignedBucket,
        processIds: [...new Set(orders.map((order) => String(order.processId || "")).filter(Boolean))],
      };
    });
    return core.summarize({ machines, reports: machtileCardState.todayRows, nowMs: Date.now() });
  } catch (error) {
    console.warn("today report summary failed", error);
    return null;
  }
}

// 篩選中、而且那一格這個時段有在計算 → 那幾台的名稱；否則 null（不篩）
function machtileTodayActiveFilterKeys(summary) {
  if (!machtileTodayFilter) return null;
  const s = summary === undefined ? machtileTodaySummary() : summary;
  const tile = s ? s[machtileTodayFilter] : null;
  if (!tile || !tile.active) return null;
  return new Set(tile.keys);
}

function machtileTodayTilesMarkup() {
  const core = machtileTodayReportCore();
  if (!core) return "";
  const summary = machtileTodaySummary();
  const filterOn = Boolean(machtileTodayActiveFilterKeys(summary));
  return core.KINDS.map((kind) => {
    const tile = summary ? summary[kind] : null;
    const active = Boolean(tile?.active);
    const tone = tile ? tile.tone : "na";
    const value = active ? `${tile.count}<small> 台</small>` : "—";
    const hint = tile ? tile.hint : "讀不到今日報工";
    const pressed = filterOn && machtileTodayFilter === kind;
    const label = core.LABEL[kind];
    const aria = active ? `${label} ${tile.count} 台${pressed ? "，篩選中，再點一次顯示全部" : "，點一下只看這幾台"}` : `${label}：${hint}`;
    const title = active && tile.keys.length ? `${hint}：${tile.keys.join("、")}` : hint;
    return `
    <button class="stat-card stat-button today-tile is-${escapeHtml(tone)}${pressed ? " active is-filtering" : ""}" type="button" data-today-tile="${escapeHtml(kind)}" data-today-tone="${escapeHtml(tone)}" data-today-count="${active ? tile.count : ""}" aria-pressed="${pressed ? "true" : "false"}" aria-label="${escapeHtml(aria)}" title="${escapeHtml(title)}">
      <span class="stat-label">${escapeHtml(label)}</span>
      <strong class="stat-value">${value}</strong>
      <small class="today-tile-hint">${pressed ? "篩選中・再點一次恢復" : escapeHtml(hint)}</small>
    </button>`;
  }).join("");
}

function machtileRenderTodayFilterBar() {
  const bar = document.getElementById("todayFilterBar");
  if (!bar) return;
  const core = machtileTodayReportCore();
  const summary = machtileTodayFilter ? machtileTodaySummary() : null;
  const keys = machtileTodayActiveFilterKeys(summary);
  if (!core || !keys) {
    bar.hidden = true;
    bar.innerHTML = "";
    delete bar.dataset.todayFilter;
    return;
  }
  const tile = summary[machtileTodayFilter];
  bar.hidden = false;
  bar.className = `today-filter-bar is-${tile.tone}`;
  bar.dataset.todayFilter = machtileTodayFilter;
  bar.innerHTML = `
    <span class="today-filter-text"><strong>篩選中：${escapeHtml(core.LABEL[machtileTodayFilter])} ${tile.count} 台</strong>${tile.keys.length ? `<span class="today-filter-keys">${escapeHtml(tile.keys.join("、"))}</span>` : ""}<span class="today-filter-note">台灣時間 ${escapeHtml(summary.phase.time)}・不分課別／狀態</span></span>
    <button type="button" class="today-filter-clear" data-today-filter-clear>顯示全部</button>`;
}

function machtileSetTodayFilter(kind, { render = true } = {}) {
  machtileTodayFilter = kind || null;
  machtileWriteTodayFilter(machtileTodayFilter);
  if (!render) return;
  renderStats();
  renderFilters();
  renderWorkOrders();
}

function machtileToggleTodayFilter(kind) {
  const core = machtileTodayReportCore();
  if (!core || !core.KINDS.includes(kind)) return;
  if (machtileTodayFilter === kind && machtileTodayActiveFilterKeys()) {
    machtileSetTodayFilter(null);
    showToast("已顯示全部機台");
    return;
  }
  const summary = machtileTodaySummary();
  const tile = summary ? summary[kind] : null;
  if (!tile || !tile.active) {
    showToast(`${core.LABEL[kind]}：${tile ? tile.hint : "讀不到今日報工"}`);
    return;
  }
  machtileSetTodayFilter(kind);
  showToast(`已篩選：${core.LABEL[kind]} ${tile.count} 台`);
}

// 每分鐘：重算三格（時段切換）；篩選中的那一格這個時段不再計算 → 自動恢復全部；超過 2 分鐘沒讀就重讀今天的報工。
async function machtileTodayTick() {
  const core = machtileTodayReportCore();
  if (!core || !document.getElementById("statsGrid")) return;
  const ecore = machtileCardEstimateCore();
  if (ecore && state.source === "supabase" && machtileCardState.todayStatus === "ok" && !document.hidden && !machtileTodayRefetching
    && Date.now() - (machtileCardState.todayLoadedAt || 0) >= MACHTILE_TODAY_REFETCH_MS - 5000) { // 容許計時器誤差：每 2 次重算重讀一次
    machtileTodayRefetching = true;
    try {
      machtileApplyCardTodayRows(ecore, await machtileCardFetch(machtileCardTodayPath(ecore)));
    } catch (error) {
      console.warn("today reports refresh failed; keeping the last result", error);
    } finally {
      machtileTodayRefetching = false;
    }
  }
  if (machtileTodayFilter && machtileCardState.todayStatus === "ok") {
    const summary = machtileTodaySummary();
    if (summary && !summary[machtileTodayFilter]?.active) machtileSetTodayFilter(null, { render: false });
  }
  try {
    renderStats();
    renderWorkOrders();
  } catch (error) {
    console.warn("today tiles re-render failed", error);
  }
}

function machtileStartTodayTick() {
  if (machtileTodayTickTimer || typeof window === "undefined" || typeof window.setInterval !== "function") return;
  machtileTodayTickTimer = window.setInterval(machtileTodayTick, MACHTILE_TODAY_TICK_MS);
}

// ---- 現場大螢幕電視頁（?view=tv，owner 2026-10-03 拍板）----
// 掛在廠區電視上給作業員看（3～5 公尺外）。全螢幕、沒有側欄／導覽，純邏輯在 tvWallCore.js。
// 資料口徑全部跟 Monitor 卡片同一套：目前工單（cardActiveOrderCore 挑單）、已報（batchReportCore.cardProgress）、
// 上方三格（todayReportStatusCore，machtileTodaySummary 同一個函式）。
// 每 60 秒自動重讀（只讀：v_work_order_cards、v_machine_management_cards、work_order_processes 佇列、
// rpc/batch_report_progress（唯讀 RPC）、今天的 production_reports、app_users、legacy_station_progress）；0 次寫入。
// 讀取失敗：畫面保留上一次成功的內容，角落顯示「資料更新失敗，最後更新 HH:MM」，下一輪自動再試。
const machtileTvCore = () => (typeof window === "undefined" ? null : window.MachTileTvWallCore);
const MACHTILE_TV_LOAD_TIMEOUT_MS = 30 * 1000;
const MACHTILE_TV_CLOCK_MS = 5 * 1000;
const machtileTvState = {
  open: false,
  model: null,        // 上一次成功的畫面資料（讀取失敗也不清掉）
  lastOkAt: 0,
  failed: false,
  failReason: "",
  demo: false,
  loading: false,
  generation: 0,
  refreshTimer: null,
  clockTimer: null,
};

function machtileTvMachineInputs() {
  const byCode = new Map();
  (state.machines || []).forEach((machine) => {
    if (!machine || machine.isUnassignedBucket) return;
    const code = String(machine.code || machine.name || "").trim().toUpperCase();
    if (!code || byCode.has(code)) return;
    const order = machine.order || null;
    const orders = [order, ...(Array.isArray(machine.cardOrders) ? machine.cardOrders.map((item) => item?.order) : [])].filter(Boolean);
    byCode.set(code, {
      code,
      key: machine.name,
      alias: machine.location || "",
      found: true,
      order: order ? { id: order.id, part: order.part, process: order.process, done: order.done, total: order.total, dueDate: order.dueDate } : null,
      processIds: [...new Set(orders.map((o) => String(o.processId || "")).filter(Boolean))],
    });
  });
  return byCode;
}

function machtileTvBuildModel() {
  const core = machtileTvCore();
  if (!core) return null;
  deriveMachines();
  const todayOk = machtileCardState.todayStatus === "ok";
  const model = core.buildModel({
    machinesByCode: machtileTvMachineInputs(),
    summary: todayOk ? machtileTodaySummary() : null,
    todayMap: todayOk ? machtileCardState.today : null,
    nowMs: Date.now(),
  });
  if (machtileStrictMode()) {
    const permitted = new Set(machtileTvMachineInputs().keys());
    model.lines = model.lines.map(line => ({...line, machines: line.machines.filter(cell => permitted.has(cell.code))}))
      .filter(line => line.machines.length > 0);
  }
  return model;
}

// 只讀重新載入（loadFromSupabase 的子集合：電視用不到的排程合約、產能日曆、提醒中心、HMC 盤況、上下料統計不讀）
async function machtileTvFetchAll() {
  await machtileLoadDepartmentAccess({ readOnly: true, force: true });
  const ecore = machtileCardEstimateCore();
  if (!ecore) throw new Error("卡片元件沒有載入");
  const controller = typeof AbortController === "function" ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), MACHTILE_TV_LOAD_TIMEOUT_MS) : null;
  let rows;
  try {
    rows = await supabaseFetch("v_work_order_cards?select=*&order=due_date.asc,work_order_no.asc", controller ? { signal: controller.signal } : {});
  } finally {
    if (timer) clearTimeout(timer);
  }
  if (!Array.isArray(rows) || (!machtileStrictMode() && rows.length === 0)) throw new Error("工單資料是空的");
  let masters = null;
  try {
    masters = await supabaseFetch("v_machine_management_cards?select=*&order=display_order.asc,machine_code.asc");
  } catch (error) {
    if (machtileStrictMode()) {
      machtileClearDepartmentData();
      throw new Error("機台清單讀取失敗");
    }
    console.warn("tv: machine masters unavailable; keeping the last ones", error);
  }
  state.workOrders = rows.map(normalizeOrder);
  if (machtileStrictMode() && !Array.isArray(masters)) {
    machtileClearDepartmentData();
    throw new Error("機台清單讀取失敗");
  }
  if (Array.isArray(masters)) state.machineMasters = masters.map(normalizeMachineMaster)
    .filter(machine => !machtileStrictMode() || machtileDepartmentAccess?.all_departments
      || machtileAvailableDepartments().includes(normalizedMachineDepartment(machine)));
  state.source = "supabase";
  await machtileLoadScheduleQueue();
  await machtileLoadAssignedCardProcesses();
  await machtileLoadCardLegacyProgress();
  await machtileLoadCardToday(ecore);
  await machtileLoadCardActivity();
  if (machtileCardState.todayStatus !== "ok") throw new Error("今日報工讀取失敗");
}

function machtileTvWithTimeout(promise, ms) {
  let timer = null;
  return Promise.race([
    promise,
    new Promise((_, reject) => { timer = setTimeout(() => reject(new Error("讀取逾時")), ms); }),
  ]).finally(() => { if (timer) clearTimeout(timer); });
}

async function machtileTvReload() {
  if (!machtileTvState.open || machtileTvState.loading) return;
  const generation = ++machtileTvState.generation;
  machtileTvState.loading = true;
  try {
    if (!(config.useSupabase && config.supabaseUrl && config.supabaseAnonKey)) {
      // 示範模式（Dev、無後端）：照樣顯示，但畫面標「示範資料」
      machtileTvState.demo = true;
      machtileTvState.model = machtileTvBuildModel();
      machtileTvState.lastOkAt = Date.now();
      machtileTvState.failed = false;
      return;
    }
    if (machtileStrictMode() && !machtileSessionActive()) throw new Error("登入已過期，請重新登入");
    await machtileTvWithTimeout(machtileTvFetchAll(), MACHTILE_TV_LOAD_TIMEOUT_MS + 15000);
    if (generation !== machtileTvState.generation) return;
    const model = machtileTvBuildModel();
    if (!model) throw new Error("電視頁元件沒有載入");
    machtileTvState.model = model;
    machtileTvState.lastOkAt = Date.now();
    machtileTvState.failed = false;
    machtileTvState.failReason = "";
    machtileTvState.demo = false;
  } catch (error) {
    if (generation !== machtileTvState.generation) return;
    if (machtileStrictMode()) machtileTvState.model = null;
    console.warn("tv refresh failed", error);
    machtileTvState.failed = true;
    machtileTvState.failReason = machtileStrictMode() && !machtileSessionActive() ? "登入已過期，請重新登入" : String(error?.message || error || "").slice(0, 80);
  } finally {
    if (generation === machtileTvState.generation) machtileTvState.loading = false;
    machtileRenderTvWall();
  }
}

function machtileTvTileHtml(tile) {
  const sub = tile.active && tile.count > 0 && tile.keys.length ? tile.keys.join("、") : tile.hint;
  return `
    <div class="tv-tile is-${escapeHtml(tile.tone)}" data-tv-tile="${escapeHtml(tile.kind)}" data-tv-tone="${escapeHtml(tile.tone)}" data-tv-count="${tile.active ? tile.count : ""}">
      <span class="tv-tile-label">${escapeHtml(tile.label)}</span>
      <b class="tv-tile-value">${escapeHtml(tile.value)}${tile.active ? "<small>台</small>" : ""}</b>
      <em class="tv-tile-sub">${escapeHtml(sub)}</em>
    </div>`;
}

function machtileTvCellHtml(cell) {
  const tags = cell.tags.map((tag) => `<span class="tv-tag is-${escapeHtml(tag.kind)}" data-tv-tag="${escapeHtml(tag.kind)}">${escapeHtml(tag.label)}</span>`).join("");
  const head = `<div class="tv-cell-head"><b class="tv-code">${escapeHtml(cell.code)}</b>${cell.alias ? `<span class="tv-alias">${escapeHtml(cell.alias)}</span>` : ""}</div>`;
  if (!cell.hasOrder) {
    return `
      <article class="tv-cell is-idle${cell.severity ? ` sev-${escapeHtml(cell.severity)}` : ""}" data-tv-machine="${escapeHtml(cell.code)}" data-tv-severity="${escapeHtml(cell.severity)}">
        ${head}
        <p class="tv-part is-empty">${cell.found ? "無工單" : "沒有這台機台的資料"}</p>
        <p class="tv-today is-${escapeHtml(cell.today.tone)}" data-tv-today="${escapeHtml(cell.today.tone)}">${cell.today.tone === "idle" ? "" : escapeHtml(cell.today.text)}</p>
        ${tags ? `<div class="tv-tags">${tags}</div>` : ""}
      </article>`;
  }
  const qty = cell.total
    ? `<b class="tv-done">${escapeHtml(cell.done)}</b><span class="tv-total">/ ${escapeHtml(cell.total)}</span><em class="tv-pct">${escapeHtml(cell.percent)}%</em>`
    : `<b class="tv-done">${escapeHtml(cell.done)}</b><span class="tv-total">/ 未填數量</span>`;
  return `
    <article class="tv-cell${cell.severity ? ` sev-${escapeHtml(cell.severity)}` : ""}" data-tv-machine="${escapeHtml(cell.code)}" data-tv-severity="${escapeHtml(cell.severity)}">
      ${head}
      <p class="tv-part" title="${escapeHtml(cell.part)}">${escapeHtml(cell.part)}</p>
      <p class="tv-sub">${escapeHtml(cell.orderNo)}${cell.process ? `・${escapeHtml(cell.process)}` : ""}</p>
      <div class="tv-qty" data-tv-qty="${escapeHtml(cell.done)}/${escapeHtml(cell.total)}">${qty}${cell.fullNote ? `<span class="tv-fullnote">${escapeHtml(cell.fullNote)}</span>` : ""}</div>
      <div class="tv-bar${cell.full && cell.over > 0 ? " is-over" : ""}" aria-hidden="true"><i style="width:${Math.max(0, Math.min(100, Number(cell.bar) || 0))}%"></i></div>
      <p class="tv-today is-${escapeHtml(cell.today.tone)}" data-tv-today="${escapeHtml(cell.today.tone)}">${escapeHtml(cell.today.text)}</p>
      <div class="tv-tags">${tags}</div>
    </article>`;
}

function machtileRenderTvWall() {
  const holder = document.getElementById("tvWall");
  const core = machtileTvCore();
  if (!holder || !core) return;
  const st = machtileTvState;
  const model = st.model;
  const clock = core.clockParts(Date.now());
  const stateName = st.failed ? "error" : !model ? "loading" : st.demo ? "demo" : "ok";
  holder.dataset.tvState = stateName;
  holder.dataset.tvUpdated = core.hhmm(st.lastOkAt);
  const alert = st.failed
    ? `<div class="tv-alert" role="alert" data-tv-alert><strong>${escapeHtml(core.failureText(st.lastOkAt))}</strong>${st.failReason ? `<small>${escapeHtml(st.failReason)}・60 秒後自動再試</small>` : "<small>60 秒後自動再試</small>"}</div>`
    : "";
  const tiles = (model ? model.tiles : core.headerTiles(null)).map(machtileTvTileHtml).join("");
  const body = model
    ? model.lines.map((line) => `
      <section class="tv-line" data-tv-line="${escapeHtml(line.key)}" aria-label="${escapeHtml(line.title)}">
        <h2 class="tv-line-title">${escapeHtml(line.title)}</h2>
        <div class="tv-grid" style="--tv-cols:${line.machines.length}">${line.machines.map(machtileTvCellHtml).join("")}</div>
      </section>`).join("")
    : `<section class="tv-empty" data-tv-empty><p>${st.failed ? "資料讀取失敗，60 秒後自動重試。" : "正在讀取資料…"}</p></section>`;
  holder.innerHTML = `
    <header class="tv-top">
      <div class="tv-clock"><b data-tv-clock>${escapeHtml(clock.time)}</b><span data-tv-date>${escapeHtml(`${clock.date} ${clock.weekday}`)}</span></div>
      <div class="tv-tiles">${tiles}</div>
    </header>
    ${body}
    <footer class="tv-foot">
      <span data-tv-updated>${st.lastOkAt ? `資料更新 ${escapeHtml(core.hhmm(st.lastOkAt))}` : "尚未取得資料"}・每 60 秒自動更新・台灣時間${st.demo ? "・<b class=\"tv-demo\">示範資料</b>" : ""}</span>
      <a class="tv-exit" href="./">離開電視頁</a>
    </footer>
    ${alert}`;
}

function machtileTvTickClock() {
  const core = machtileTvCore();
  const el = document.querySelector("#tvWall [data-tv-clock]");
  if (!core || !el) return;
  const clock = core.clockParts(Date.now());
  el.textContent = clock.time;
  const date = document.querySelector("#tvWall [data-tv-date]");
  if (date) date.textContent = `${clock.date} ${clock.weekday}`;
}

function machtileOpenTvWall() {
  const core = machtileTvCore();
  if (!core) { showToast("電視頁元件沒有載入，請重新整理"); return; }
  machtileToggleAdminDrawer(false);
  let holder = document.getElementById("tvWall");
  if (!holder) {
    holder = document.createElement("div");
    holder.id = "tvWall";
    holder.className = "tv-wall";
    holder.setAttribute("aria-label", "現場電視");
    document.body.appendChild(holder);
  }
  document.body.classList.add("tv-mode");
  document.title = "現場電視・MachTile";
  const st = machtileTvState;
  st.open = true;
  // 開機剛讀過的真資料直接用（不再多讀一次）；示範資料模式照樣顯示；其餘（開機讀取失敗退回示範資料）→ 馬上重讀，不拿示範資料冒充
  const backend = Boolean(config.useSupabase && config.supabaseUrl && config.supabaseAnonKey);
  if (!st.model && state.source === "supabase" && machtileCardState.todayStatus === "ok") {
    st.model = machtileTvBuildModel();
    st.lastOkAt = machtileCardState.todayLoadedAt || Date.now();
  } else if (!st.model && !backend) {
    st.demo = true;
    st.model = machtileTvBuildModel();
    st.lastOkAt = Date.now();
  }
  machtileRenderTvWall();
  if (!st.model) machtileTvReload().catch(() => {});
  if (!st.refreshTimer) st.refreshTimer = window.setInterval(() => { machtileTvReload().catch(() => {}); }, core.REFRESH_MS);
  if (!st.clockTimer) st.clockTimer = window.setInterval(machtileTvTickClock, MACHTILE_TV_CLOCK_MS);
}

// 選單「現場電視」：同一個分頁切到電視頁，網址改成 ?view=tv（電視可以直接把這個網址設成首頁）
function machtileEnterTvFromMenu() {
  try {
    const url = new URL(window.location.href);
    url.search = "";
    url.hash = "";
    url.searchParams.set("view", "tv");
    window.history.pushState(null, "", url.toString());
  } catch { /* 網址改不了也照樣開 */ }
  machtileOpenTvWall();
}

// 電視頁按瀏覽器「上一頁」→ 重新載入回到一般畫面
window.addEventListener("popstate", () => {
  if (!machtileTvState.open) return;
  if (new URLSearchParams(window.location.search).get("view") !== "tv") window.location.reload();
});

machtileStartTodayTick();

init();
